IF OBJECT_ID('[dbo].[PRC_010_CARGA_VW_CLIENTE_PAINEL]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[PRC_010_CARGA_VW_CLIENTE_PAINEL];
GO
CREATE      PROCEDURE [dbo].PRC_010_CARGA_VW_CLIENTE_PAINEL as
--
---------------------------------------------------------------------------------------------------


---------------------------------------------------------------------------------------------------
--		Extratação dos PRODUTOS
---------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS #PRODUTO

SELECT 
		'PREVIDENCIA' AS DES_SEGMENTO,
		COD_PRODUTO_KIPREV AS COD_PRODUTO,
		DES_MODALIDADE,
		NULL AS NOME_BU

INTO	#PRODUTO

FROM	DMDB11.DBO.DM_008_PRODUTO PR WITH (NOLOCK)

UNION ALL
SELECT 'PRESTAMISTA' AS DES_SEGMENTO,
		COD_PRODUTO AS COD_PRODUTO,
		NULL AS DES_MODALIDADE,
		DES_LINHA_PROD AS NOME_BU
FROM	DMDB42.DBO.DM_DIM_PRODUTO WITH (NOLOCK)

UNION ALL
SELECT	DISTINCT 
		'VIDA' AS DES_SEGMENTO,
		A.COD_PRODUTO AS COD_PRODUTO,
		NULL AS DES_MODALIDADE,
		A.NOM_SEGMENTO_BP AS NOME_BU
FROM	DMDB05.DBO.DM_052_PRODUTO A WITH (NOLOCK) 

---------------------------------------------------------------------------------------------------
--		Extratação dos Clientes VIDA e Prestamista (PF/PJ) e Previdência (PF) 
---------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS #BASE

select	
		/* Dados Clientes */
		A.NOM_SEGMENTO,
		A.DES_PESSOA,
		A.COD_TIPO_PESSOA,
		A.NUM_CPF_CNPJ,
		A.DES_CBO,
		A.DES_CNAE,
		A.DTA_NASCIMENTO,
		cast(FLOOR(DATEDIFF(DAY, A.DTA_NASCIMENTO, GETDATE()) / 365.25) as integer)  AS NUM_IDADE,
		A.VLR_RENDA_INDIVIDUAL,
		A.VLR_FATURAMENTO_ANUAL,
		A.VLR_FATURAMENTO_RENDA_BIRO,
		A.COD_UF,
		case
			when A.COD_UF in ('GO','DF','MS','MT') then 'CENTRO-OESTE'
			when A.COD_UF in ('BA','MA','PE','PI','SE','AL','CE','RN','PB') then 'NORDESTE'
			when A.COD_UF in ('TO','RO','PA','RR','AC','AM','AP') then 'NORTE'
			when A.COD_UF in ('MG','ES','RJ') then 'SUDESTE'
			when A.COD_UF in ('PR','SC','RS') then 'SUL'
			when A.COD_UF in ('SP') then 'SAO PAULO'
			else 'SEM INFORMACAO'
		end as REGIAO,
		A.IND_GENERO,
		A.DES_ESTADO_CIVIL,
		A.IND_PEP,
		A.IND_PERMITE_CONTATO_EMAIL,
		A.IND_PERMITE_CONTATO_TELEFONE,
		A.IND_PERMITE_CONTATO_WHATSAPP,
		A.IND_RECEBER_OFERTAS_CAIXA_SEG,
		A.IND_RECEBER_OFERTAS_PARCEIROS,
		A.IND_NAO_PERTURBE_LGPD,
		A.IND_RECEBER_PESQUISAS,
		A.DES_CATEG_SEGMENTACAO as SEGMENTACAO_CVP,
		
		/* Dados Contratos */
		B.NUM_CERTIFICADO,
		B.COD_PRODUTO,
		B.COD_STATUS_CONTRATO,
		B.COD_AGENCIA,
		B.DTA_INICIO_VIGENCIA,
		B.DTA_FIM_VIGENCIA,
		B.DTA_ENCERRAMENTO,
		case
			when B.COD_STATUS_CONTRATO = 'I' and B.DTA_ENCERRAMENTO is not null then B.DTA_ENCERRAMENTO
			when B.COD_STATUS_CONTRATO = 'I' and B.DTA_ENCERRAMENTO is null and B.DTA_FIM_VIGENCIA <= getdate() then B.DTA_FIM_VIGENCIA
			else NULL
		end as DTA_ENCERRAMENTO_2,
		B.VLR_IS,
		B.VLR_PREMIO,
		B.VLR_PMBAC,
		B.VLR_PMBAC_EMP,
		B.DES_MOTIVO_CANCEL,
		B.DES_CANAL_VENDA,
		B.DES_CANAL_VENDA_COMERCIAL,
		B.IND_PERIODICIDADE_COBRANCA,
		B.DES_FORMA_PAGAMENTO,
		B.IND_MULTIFUNDO

INTO	#BASE   --21.093.328  2:46

from	DMDB41..DM_CLIENTES_CONTRATOS_CVP A WITH ( NOLOCK )

join	DMDB41..DM_CONTRATOS_CVP B WITH ( NOLOCK )
on		A.NOM_SEGMENTO		= B.NOM_SEGMENTO 
and		A.NUM_CERTIFICADO	= B.NUM_CERTIFICADO

where	A.DES_PESSOA = 'SEGURADO TITULAR'
and	(	B.COD_STATUS_CONTRATO = 'A'
or		(COALESCE(B.DTA_ENCERRAMENTO, B.DTA_FIM_VIGENCIA )>= dateadd(month, -25, dateadd(day, 1, eomonth(getdate())))))

---------------------------------------------------------------------------------------------------
--		Extratação dos Clientes Previdência (PJ)
---------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS #PREV_PJ

select	
		/* Dados Clientes */
		A.NOM_SEGMENTO,
		A.DES_PESSOA,
		A.COD_TIPO_PESSOA,
		A.NUM_CPF_CNPJ,
		A.DES_CBO,
		A.DES_CNAE,
		A.DTA_NASCIMENTO,
		cast(FLOOR(DATEDIFF(DAY, A
GO
 
IF OBJECT_ID('[dbo].[PRC_020_CARGA_TB_VW_CLIENTE_CROSS_AGRUPADO]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[PRC_020_CARGA_TB_VW_CLIENTE_CROSS_AGRUPADO];
GO
CREATE      PROCEDURE [dbo].PRC_020_CARGA_TB_VW_CLIENTE_CROSS_AGRUPADO as

---------------------------------------------------------------------------------------------------
--

--
---------------------------------------------------------------------------------------------------
--		AUTOR	:	William	Koloda	/ SILVIO J®
--		DATA	:	02/02/2022 - Criação	
---------------------------------------------------------------------------------------------------


---------------------------------------------------------------------------------------------------
--		BASE VIDA 
---------------------------------------------------------------------------------------------------

DROP TABLE IF EXISTS #BASE_VIDA --AS (

select distinct	
		'VIDA' as NOM_SEGMENTO
		,A.COD_TIPO_PESSOA
		,A.NUM_CPF_CNPJ
		,'S' as FLAG_VIDA

INTO	#BASE_VIDA

from	DMDB41..DM_CLIENTES_CONTRATOS_CVP A WITH ( NOLOCK ) 

join	DMDB41..DM_CONTRATOS_CVP B  WITH ( NOLOCK INDEX = IDX_DM_CONTRATOS_CVP_CERTIF_SEGMTO) 
on		A.NOM_SEGMENTO = B.NOM_SEGMENTO 
and		A.NUM_CERTIFICADO = B.NUM_CERTIFICADO
where	A.NOM_SEGMENTO = 'VIDA'
and		A.DES_PESSOA = 'SEGURADO TITULAR'
and		B.COD_STATUS_CONTRATO = 'A'

---------------------------------------------------------------------------------------------------
--		BASE PRESTA
---------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS #BASE_PRES	

select distinct
		'PRESTAMISTA' as NOM_SEGMENTO
		,A.COD_TIPO_PESSOA
		,A.NUM_CPF_CNPJ
		,'S' as FLAG_PRES

INTO	#BASE_PRES

from	DMDB41..DM_CLIENTES_CONTRATOS_CVP A WITH ( NOLOCK ) 

join	DMDB41..DM_CONTRATOS_CVP B  WITH ( NOLOCK INDEX = IDX_DM_CONTRATOS_CVP_CERTIF_SEGMTO ) 
on		A.NOM_SEGMENTO = B.NOM_SEGMENTO 
and		A.NUM_CERTIFICADO = B.NUM_CERTIFICADO

where	A.NOM_SEGMENTO = 'PRESTAMISTA'
and		A.DES_PESSOA = 'SEGURADO TITULAR'
and		B.COD_STATUS_CONTRATO = 'A'

---------------------------------------------------------------------------------------------------
--		BASE PREVI
---------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS #BASE_PREV_F	--AS	(
select distinct
		'PREVIDENCIA' as NOM_SEGMENTO
		,A.COD_TIPO_PESSOA
		,A.NUM_CPF_CNPJ
		,'S' as FLAG_PREV
INTO	#BASE_PREV_F

from	DMDB41..DM_CLIENTES_CONTRATOS_CVP A WITH ( NOLOCK )

join	DMDB41..DM_CONTRATOS_CVP B  WITH ( NOLOCK INDEX= IDX_DM_CONTRATOS_CVP_CERTIF_SEGMTO) 
on		A.NOM_SEGMENTO = B.NOM_SEGMENTO 
and		A.NUM_CERTIFICADO = B.NUM_CERTIFICADO

where	A.NOM_SEGMENTO = 'PREVIDENCIA'
and		A.DES_PESSOA = 'SEGURADO TITULAR'
and		B.COD_STATUS_CONTRATO = 'A'

---------------------------------------------------------------------------------------------------
--		BASE PREVI
---------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS #BASE_PREV_J	--AS	(
select distinct
		'PREVIDENCIA' as NOM_SEGMENTO
		,A.COD_TIPO_PESSOA
		,A.NUM_CPF_CNPJ
		,'S' as FLAG_PREV

INTO	#BASE_PREV_J

from	DMDB41..DM_CLIENTES_CONTRATOS_CVP A WITH ( NOLOCK ) 

join	DMDB41..DM_CONTRATOS_CVP B  WITH ( NOLOCK ) 
on		A.NOM_SEGMENTO = B.NOM_SEGMENTO 
and		A.NUM_CERTIFICADO = B.NUM_CONTRATO_PAI

where	A.NOM_SEGMENTO = 'PREVIDENCIA'
and		A.DES_PESSOA = 'SEGURADO TITULAR'
and		B.COD_STATUS_CONTRATO = 'A'

---------------------------------------------------------------------------------------------------
--		BASE PREVI
---------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS #BASE_PREV	--AS	(
select	A.*
INTO	#BASE_PREV

from	(	select * from #BASE_PREV_F
			union all
			select * from #BASE_PREV_J
		) A


---------------------------------------------------------------------------------------------------
--		BASE CLIENTE
---------------------------------------------------------------------------------------------------
DROP TABLE
GO
 
