SELECT	W.SEGMENTO	,
		W.DTA_PROPOSTA,
		W.DTA_PAGAMENTO,
		W.COD_MATRICULA,
		W.COD_AGENCIA_VENDA,
		W.COD_AGENCIA_FUNCIONARIO,
		W.COD_TIPO_PESSOA,
		W.DES_PRODUTO,
		W.DES_STATUS_PROPOSTA,
		W.COD_FORMA_PGTO,
		W.DES_FORMA_PGTO,
		W.TIPO_PAGAMENTO,
		W.DES_CANAL_VENDA,
		W.DES_OPERACAO_CREDITO,
		W.GRUPO_LINHA_CREDITO,
		COUNT(1)				AS	QTD_VENDA,
		SUM(CASE	WHEN FL_PAGO = 'S' 
					THEN 1 
					ELSE 0
					END )		AS	QTD_PAGO,

		R.IND_ROADMAP,
		R.DES_ROADMAP ,
		R.DES_GRUPO_ROADMAP,
		W.DES_ORIGEM_CONTRATO,

		W.COD_AGENCIA_REGRA_DIGITAL,
		W.NOME_AGENCIA_REGRA_DIGITAL,

		SUM(VLR_VENDA)			AS	VLR_VENDA,
		SUM(VLR_VENDA_PAGO)		AS	VLR_VENDA_PAGO,
		SUM(VLR_IS)				AS	VLR_IS,

		CURRENT_TIMESTAMP		AS	DTH_ATUALIZACAO

INTO	DMDB41.DBO.TB_VENDA_PRESTAMISTA_CONSOLIDADA

FROM	DMDB41.DBO.TB_VW_VENDA_PRESTAMISTA  W WITH (NOLOCK)

LEFT JOIN [WORK_GEPLAC].[dbo].[AUX_ESTRUTURA_COMERCIAL] E (NOLOCK)
ON			COALESCE(W.COD_AGENCIA_FUNCIONARIO,W.COD_AGENCIA_VENDA)	=	E.COD_AGENCIA 

LEFT JOIN [WORK_GEPLAC].[dbo].[AUX_ESTRUTURA_COMERCIAL] EA (NOLOCK)
ON			W.COD_AGENCIA_VENDA	=	EA.COD_AGENCIA 

LEFT JOIN [WORK_GEPLAC].[dbo].[AUX_CANAL_VENDA] C (NOLOCK)
ON			W.DES_CANAL_VENDA = C.DES_CANAL_ORIGEM

LEFT JOIN [WORK_GEPLAC].[DBO].[AUX_ROADMAP_PRESTAMISTA] R (NOLOCK)
ON			ISNULL(R.DES_GRUPO_CANAL,'')		=	CASE WHEN ISNULL(R.DES_GRUPO_CANAL,'')			<> '' THEN C.DES_GRUPO_CANAL		END--ELSE ''	END
AND			ISNULL(R.TIPO_PESSOA,'')			=	CASE WHEN ISNULL(R.TIPO_PESSOA,'')				<> '' THEN W.COD_TIPO_PESSOA		ELSE ''	END
AND			ISNULL(R.TIPO_REDE,'')				=	CASE WHEN ISNULL(R.TIPO_REDE,'')				<> '' THEN ISNULL(E.TIPO_REDE,EA.TIPO_REDE)	ELSE ''	END
AND			ISNULL(R.DES_GERENCIA_COMERCIAL,'') =	CASE WHEN ISNULL(R.DES_GERENCIA_COMERCIAL,'')	<> '' THEN ISNULL(E.DES_GERENCIA_COMERCIAL,EA.DES_GERENCIA_COMERCIAL) ELSE '' END
AND 		ISNULL(R.GRUPO_LINHA_CREDITO,'')	=	CASE WHEN ISNULL(R.GRUPO_LINHA_CREDITO,'')		<> '' THEN W.GRUPO_LINHA_CREDITO			ELSE ''	END

GROUP BY 
		W.SEGMENTO,
		W.DTA_PROPOSTA,
		W.DTA_PAGAMENTO,
		W.COD_MATRICULA,
		W.COD_AGENCIA_VENDA,
		W.COD_AGENCIA_FUNCIONARIO,
		W.COD_TIPO_PESSOA,
		W.DES_PRODUTO,
		W.COD_FORMA_PGTO,
		W.DES_FORMA_PGTO,
		W.TIPO_PAGAMENTO,
		W.DES_STATUS_PROPOSTA,
		W.DES_CANAL_VENDA,
		W.DES_OPERACAO_CREDITO,
		W.GRUPO_LINHA_CREDITO,
		W.DES_ORIGEM_CONTRATO,
		R.IND_ROADMAP,
		R.DES_ROADMAP ,
		R.DES_GRUPO_ROADMAP,
		W.COD_AGENCIA_REGRA_DIGITAL,
		W.NOME_AGENCIA_REGRA_DIGITAL 
		
----------------------------------------------------------------------------------------------
--		FIM DO PROCESSO
---------------------------------------------------------------------------------------------------

GO
 
