IF OBJECT_ID('[dbo].[PRC_200_TB_KIPREV_PORTABILIDADE_RECENTE]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[PRC_200_TB_KIPREV_PORTABILIDADE_RECENTE];
GO
	CREATE 	PROCEDURE [dbo].[PRC_200_TB_KIPREV_PORTABILIDADE_RECENTE] AS	
----------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS #PORTA

SELECT  distinct 
		NUM_CPF_CNPJ
		,NOM_SEGURADO
		,NUM_CERTIFICADO 
		,DES_TIP_PORTABILIDADE
		,NUM_PORTABILIDADE
		,COD_AGENCIA_VENDA
		,COD_MATRICULA_INDICADOR
		,DTA_SOLICITACAO
		,DTA_LIBERACAO
		,DTA_EFETIVACAO
		,STA_PORTABILIDADE
		,NOM_ENTIDADE_CEDENTE
		,DES_TIPO_ENTIDADE
		,DES_TRIBUTACAO
		,NOM_PLANO_CEDENTE
		,VLR_TOTAL_SOLICITADO
		,VLR_MOVIMENTO

INTO	#PORTA

FROM   OPENQUERY(KIPRD,'
WITH 
CPF_CNPJ AS (
SELECT	PF.COD_PER_FISICA AS COD_PERSONA,
		ID.NUM_ID AS NUM_CPF_CNPJ,
		''PF'' AS	COD_TIPO_PESSOA,
		PRIMER_NOMBRE AS NOM_SEGURADO
FROM	KIPREV.PERSONAS_FISICAS PF 
JOIN	KIPREV.ID_PERSONAS ID 
ON		ID.COD_PERSONA = PF.COD_PER_FISICA
WHERE	ID.COD_TIPO_ID = ''1''

UNION

SELECT	PJ.COD_PER_JURIDICA AS COD_PERSONA,
		ID.NUM_ID AS NUM_CPF_CNPJ ,
		''PJ'' AS	COD_TIPO_PESSOA,
		RAZON_SOCIAL AS NOM_SEGURADO
FROM	KIPREV.PERSONAS_JURIDICAS PJ 
JOIN	KIPREV.ID_PERSONAS ID 
ON		ID.COD_PERSONA = PJ.COD_PER_JURIDICA
WHERE	ID.COD_TIPO_ID = ''5'')	  

--		RELATORIO FINAL
SELECT	DISTINCT  
		SUBSTR(CPF.NUM_CPF_CNPJ,1,20)  AS NUM_CPF_CNPJ
		,SUBSTR(CPF.NOM_SEGURADO,1,100)  AS NOM_SEGURADO
		,PORTAB.COD_CUENTA AS NUM_CERTIFICADO 
		,CASE WHEN TIP_PORTABILIDADE = ''T'' THEN ''TOTAL'' ELSE ''PARCIAL'' END AS DES_TIP_PORTABILIDADE
		,PORTAB.NUM_PORTABILIDADE AS NUM_PORTABILIDADE
		,COD_OFICINA AS COD_AGENCIA_VENDA
		,SUBSTR(A.COD_AGENTE_VENDA,1,10)	AS	COD_MATRICULA_INDICADOR
		,CAST(PORTAB.DATA_SOLICITACAO AS DATE) AS DTA_SOLICITACAO
		,CAST(PORTAB.DATA_LIBERACAO AS DATE)   AS DTA_LIBERACAO
		,CAST(PORTAB.DATA_EFETIVACAO AS DATE) AS DTA_EFETIVACAO
		,CAST(PORTAB.DATA_CANCELAMENTO AS DATE) AS  DTA_CANCELAMENTO
--		,SUBSTR(PS.DES_STATUS,1,20)	AS STA_PORTABILIDADE

		,CASE	WHEN SUBSTR(PS.DES_STATUS,1,20) = ''A Aplicar Histórico''		THEN ''EFETIVADO''
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''A Efetivar''				THEN ''EFETIVADO''
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''A Efetivar sem Hist.''	THEN ''EFETIVADO''
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Aprovada''				THEN ''EM ANDAMENTO''	
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Devolvida''				THEN ''EM ANDAMENTO''	
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Cancelada''				THEN ''CANCELADA''	
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Efetivada''				THEN ''EFETIVADO''
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Efetivada sem Hist.''		THEN ''EFETIVADO''
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Em Preenchimento''		THEN ''EM ANDAMENTO''	
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Em processamento''		THEN ''EM ANDAMENTO''	
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Em Processamento''		THEN ''EM ANDAMENTO''	
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Pendente''				THEN ''EM ANDAMENTO''	
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Estornada''				THEN ''CANCELADA''
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Exclusão Solicitada''		THEN ''CANCELADA''
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Liberada para Cedent''	THEN ''EM ANDAMENTO''
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Recusada''				THEN ''CANCELADA''	
				WHEN SUBSTR(PS.DES_STATUS,1,20) = ''Solicitada''				THEN ''EM ANDAMENTO''
				ELSE SUBSTR(PS.DES_STATUS,1,20)
				END					AS STA_PORTABILIDADE

		,PJ.RAZON_SOCIAL     AS NOM_ENTIDADE_CEDENTE

		,CASE	WHEN ENTS.TIPO_ENTE = 2 THEN ''ABERTA''
				WHEN ENTS.TIPO_ENTE = 5 THEN ''FECHADA''
				ELSE ''OUTROS''
				END AS DES_TIPO_ENTIDADE

		,CASE	WHEN PORTAB.EXT_TIP_TRIBUTACAO = ''P'' THEN       ''TRIBUTACAO PROGRESSIVA''
				WHEN PORTAB.EXT_TIP_TRIBUTACAO = ''R'' THEN ''TRIBUTACAO REGRESSIVA ''
				ELSE PORTAB.EXT_TIP_TRIBUTACAO
				END AS DES_TRIBUTACAO

		,PORTAB.EXT_NOME_PLANO		AS	NOM_PLANO_CEDENTE
		,PORTAB.TOT_SOLICITADO		AS	VLR_TOTAL_SOLICITADO
--		,CASE	WHEN PORTAB.TIP_STATUS = ''PRTE'' 
		,PORTAB.VLR_PORTADO			AS	VLR_MOVIMENTO

FROM
GO
 
IF OBJECT_ID('[dbo].[PRC_210_TB_KIPREV_VENDA_INTERNA_RECENTE]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[PRC_210_TB_KIPREV_VENDA_INTERNA_RECENTE];
GO
CREATE PROCEDURE [dbo].[PRC_210_TB_KIPREV_VENDA_INTERNA_RECENTE]	AS	
----------------------------------------------------------------------------------------------------
--		select top 8 * from  DMDB41..TB_KIPREV_VENDA_INTERNA_RECENTE
----------------------------------------------------------------------------------------------------
--	SELECT CONVERT(VARCHAR(10),DATEADD(DAY,-30,convert(DATE,GETDATE())) ,111)
--	TO_CHAR(SYSDATE - 30, 'YYYY-MM-DD') 
----------------------------------------------------------------------------------------------------

DROP TABLE IF EXISTS #KIP

SELECT  DISTINCT 
		'VENDA INTERNA'						AS	MOVIMENTO,
		CAST(K.DTA_VENDA AS DATE)			AS	DTA_VENDA,
		CAST(K.DTH_VENDA AS DATETIME)		AS	DTH_VENDA,
		K.NUM_CPF_CNPJ,
		CAST(K.NUM_PROPOSTA AS BIGINT)		AS	NUM_PROPOSTA,
		K.NUM_CERTIFICADO,
		k.COD_PRODUCTO AS COD_PRODUTO,
		K.NOM_PRODUTO,
		CASE WHEN K.DES_FORMA_PGTO = 'Débito em conta' then 'DC' ELSE 'FC' END AS DES_FORMA_PGTO,
		K.IND_PAGO,

		K.COD_AGENCIA,  
		K.MATRICULA_INDICADOR,
		K.NOM_INDICADOR,
		K.COD_AGENCIA_INDICADOR,

		K.NOSSO_NUMERO						AS	NOSSO_NUMERO_KIPREV,
		K.NUM_COBRANCA,
		K.NUMERO_DEPOSITO					AS  NUM_DEPOSITO,
		CAST(K.DTA_PAGAMENTO AS DATE)		AS  DTA_PGTO_KIPREV,
		CAST(K.DTA_BAIXA AS DATE)			AS	DTA_BAIXA_KIPREV,
		CONVERT(MONEY,ISNULL(K.VLR_GERADO,0))AS	VLR_GERADO,
		CONVERT(MONEY,ISNULL(K.VLR_PAGO,0)) AS	VLR_PGTO_KIPREV		
		

INTO	#KIP
		
FROM   OPENQUERY(KIPRD,
				'SELECT FC.COD_CUENTA	AS NUM_CERTIFICADO
						,ES.FEC_SOLICITUD AS DTA_VENDA
						,ES.FEC_SOLICITUD AS DTH_VENDA
						,I.NUM_ID AS NUM_CPF_CNPJ 
						,ES.NUM_FORMULARIO AS NUM_PROPOSTA 
						,FC.COD_PRODUCTO
						,PR.DESCRIPCION AS NOM_PRODUTO
						,PB.TIPO	AS DES_FORMA_PGTO
						,CASE WHEN FCC.APORTE_ESPERADO IS NULL THEN ''N'' ELSE ''S'' END  IND_PAGO

						,ES.COD_OFICINA AS COD_AGENCIA  
						,ES.COD_AGENTE_VENDA AS MATRICULA_INDICADOR
						,FUNC.NM_FUNC AS NOM_INDICADOR
						,FUNC.CD_UNIDADE AS COD_AGENCIA_INDICADOR


						,PB.FECHA_DEPOSITO AS DTA_PAGAMENTO  --DATA DE DEPOSITO NO KIPREV.
						,PB.DATA_BAIXA AS DTA_BAIXA

						,(	SELECT	CAST(SUM(CS1.APORTE_ESPERADO) AS DECIMAL(12,2))
							FROM	KIPREV.AF_CONTRIB_X_SOLIC CS1
							WHERE	CS1.NUM_FORMULARIO	= ABS.NUM_FORMULARIO
							AND		CS1.COD_PRODUTO		= ABS.COD_PRODUTO) AS VLR_GERADO

						,PB.VALOR_COB AS VLR_PAGO
						,0 AS VLR_SAP 
						,PB.NOSSO_NUMERO
						,PB.NUM_COBRANCA
						,PB.NUMERO_DEPOSITO

				FROM KIPREV.AF_ENCA_SOLICITUD ES

				LEFT JOIN  KIPREV.AF_ID_X_SOLIC I 
				ON I.COD_EMPRESA    = ES.COD_EMPRESA
				AND I.NUM_FORMULARIO = ES.NUM_FORMULARIO
				AND I.COD_TIPO_ID    = ''1''

				INNER JOIN  KIPREV.AF_BENEFICIOS_X_SOLICITACAO ABS 
				ON ABS.COD_EMPRESA    = ES.COD_EMPRESA
				AND ABS.NUM_FORMULARIO = ES.NUM_FORMULARIO

				INNER  JOIN KIPREV.FO_CUENTAS FC 
				ON	FC.COD_EMPRESA = ES.COD_EMPRESA
				AND FC.COD_CUENTA = ES.COD_CUENTA    

				LEFT JOIN  KIPREV.FO_CONTRIB_X_CONTA FCC 
				ON FCC.COD_CUENTA = FC.COD_CUENTA 
				AND SUBSTR(FCC.COD_CONTRIB,1,2) = ''CO''
 
				LEFT JOIN KIPREV.FO_CONTRIBUICOES H 
				ON FCC.COD_CONTRIB = H.COD_CONTRIB

				LEFT JOIN KPVCUST04.INT_045_FUNCIONARIOS_CEF_DETA func 
				ON CONCAT(func.matr_func,func.dv_matr_func) = ES.COD_AGENTE_VENDA

				LEFT JOIN KIPREV.FO_PRODUCTOS PR
				ON	FC.COD_PRODUCTO		=	PR.COD_PRODUCTO

				LEFT JOIN 
				(
				SELECT RC.PRIMEIRA_COBRANCA,
					   RCD.COD_CUENTA,
					   RCD.NUM_APORTE,
					   RC.VALOR_COB,
					   RC.DATA_EMISSAO,
					   RC.DATA_BAIXA,
					   RC.DATA_VENCIMENTO,
					   RC.TIP_BAIXA,
					   RDP.DATA_PREVISTA_CREDITO,
					   RDP.FECHA_DEPOSITO,
					   RDP.TIPO	,
					   RC.NUM_COBRANCA,
					   RC.NOSSO_NUMERO,
					   RDP.NUMERO_DEPOSITO
				  FROM KIPREV.RE_COBRANCA_DETA RCD
				 JOIN  KIPREV.RE_COBRANCA RC ON RCD.NUM_COBRANCA = RC.NUM_COBRANCA
				                            AND RCD.COD_EMPRESA = RC.COD_EMPRESA
			
GO
 
IF OBJECT_ID('[dbo].[PRC_220_TB_KIPREV_VENDA_RECENTE]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[PRC_220_TB_KIPREV_VENDA_RECENTE];
GO

CREATE PROCEDURE [dbo].[PRC_220_TB_KIPREV_VENDA_RECENTE]	AS	
----------------------------------------------------------------------------------------------------
--		select top 8 * from DMDB41..TB_KIPREV_VENDA_RECENTE
----------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS #KIP

SELECT  DISTINCT 
		'VENDA'				AS	MOVIMENTO,
		NUM_PROPOSTA,
		NUM_CERTIFICADO,
		NUM_CPF_CNPJ,
		DTA_VENDA,
		COD_PRODUTO,
        NOM_PRODUTO,
		COD_FORMA_PGTO,
		COD_AGENCIA,
        NUM_MATRICULA_INDICADOR,
        NOM_INDICADOR,
		COD_AGENCIA_INDICADOR,
		NOSSO_NUMERO,
		NUM_COBRANCA,
		NUM_DEPOSITO,
		VALOR_COB,
		DATA_BAIXA,
		DATA_PREVISTA_CREDITO,
		FECHA_DEPOSITO,
		VALOR_BAIXADO_CON,
		CASE	WHEN COD_STATUS = 'A' THEN 'Ativa'
				WHEN COD_STATUS = 'B' THEN 'Em Benefício'
				WHEN COD_STATUS = 'C' THEN 'Cancelada'
				WHEN COD_STATUS = 'D' THEN 'Desligado'
				WHEN COD_STATUS = 'E' THEN 'Encerrada'
				WHEN COD_STATUS = 'N' THEN 'Pendente'
				WHEN COD_STATUS = 'P' THEN 'Pré-Conta'
				WHEN COD_STATUS = 'R' THEN 'Em Trâmite'
				WHEN COD_STATUS = 'S' THEN 'Sinistro'
				WHEN COD_STATUS = 'T' THEN 'Migração de Taxa'
				WHEN COD_STATUS = 'U' THEN 'Ativa com Cobrança Suspensa'
				WHEN COD_STATUS = 'X' THEN 'Não exibir SOL'
				ELSE 'NAO ENCONTRADO'
				END		AS DES_STA_PROP_KIPREV

INTO	#KIP

FROM   OPENQUERY(KIPRD,
	'SELECT DISTINCT 
			FC.NUM_FORMULARIO	AS	NUM_PROPOSTA,
			RCD.COD_CUENTA		AS	NUM_CERTIFICADO,
			I.NUM_ID AS NUM_CPF_CNPJ,
			FC.FEC_APERTURA     AS  DTA_VENDA,
			PR.COD_PRODUCTO     AS COD_PRODUTO,
            PR.DESCRIPCION      AS NOM_PRODUTO,
			CASE WHEN RC.LINHA_DIGITAVEL IS NOT NULL THEN ''FC'' ELSE ''DC'' END AS COD_FORMA_PGTO,
			ES.COD_OFICINA AS COD_AGENCIA,
            ES.COD_AGENTE_VENDA AS NUM_MATRICULA_INDICADOR,
			FUNC.NM_FUNC AS NOM_INDICADOR,
            FUNC.CD_UNIDADE AS COD_AGENCIA_INDICADOR,
			RC.NOSSO_NUMERO,
			RC.NUM_COBRANCA,
		    RDP.NUMERO_DEPOSITO AS NUM_DEPOSITO,
			RC.VALOR_COB,
			RC.DATA_BAIXA,
			RDP.DATA_PREVISTA_CREDITO,
			RDP.FECHA_DEPOSITO,
			fc.EST_CUENTA  AS COD_STATUS,
			SUM(RSFCH.VALOR_BAIXADO_CON) VALOR_BAIXADO_CON

	FROM	KIPREV.RE_COBRANCA_DETA RCD 

	JOIN	KIPREV.RE_COBRANCA RC  
	ON		RCD.NUM_COBRANCA = RC.NUM_COBRANCA
	AND		RCD.COD_EMPRESA = RC.COD_EMPRESA

	JOIN    KIPREV.RE_DEPOSITOS_PLANILLA RDP  
	ON		RC.NUM_COBRANCA = RDP.NUM_COBRANCA

	JOIN    KIPREV.FO_CUENTAS FC  
	ON		RCD.COD_CUENTA = FC.COD_CUENTA

	JOIN    KIPREV.AF_ENCA_SOLICITUD ES 
	ON      FC.NUM_FORMULARIO   = ES.NUM_FORMULARIO
    AND     FC.COD_EMPRESA	= ES.COD_EMPRESA

	LEFT JOIN KPVCUST04.INT_045_FUNCIONARIOS_CEF_DETA FUNC
	ON     CONCAT(FUNC.matr_func,FUNC.dv_matr_func) = ES.COD_AGENTE_VENDA

	LEFT JOIN  KIPREV.AF_ID_X_SOLIC I
	ON   I.COD_EMPRESA    = ES.COD_EMPRESA
    AND  I.NUM_FORMULARIO = ES.NUM_FORMULARIO
    AND  I.COD_TIPO_ID    = ''1''

	JOIN    KIPREV.FO_PRODUCTOS PR
    ON      PR.COD_PRODUCTO = FC.COD_PRODUCTO

	JOIN    KIPREV.RE_FATURAS_DETA RFD 
	ON		RCD.NUM_FATURA = RFD.NUM_FATURA
	AND		RCD.COD_EMPRESA = RFD.COD_EMPRESA
	AND		RCD.COD_CUENTA = RFD.COD_CUENTA
    
	INNER JOIN	(	SELECT	FCH_S.COD_CUENTA,
							FCH_S.COD_CONTRIB,
							FCH_S.VALOR_BAIXADO_CON

					FROM    KIPREV.FO_CONTRIB_HIST FCH_S 

					WHERE  FCH_S.NUM_PARCELA = 1
					AND    FCH_S.STATUS_CON IN (''BP'',''BT'',''DV'')
					AND    FCH_S.COD_CONTRIB IN (''CREE1'',''CRIS1'',''CREG1'',''CREP1'',''CPPP1'',''CRES1'',''CPPPS'',''ADEM1'',''ADPA1'',''CPLP1'',''ADSE1'',''CPLPS'',
												--CONTRIBUIÇÕES DE RISCO PM
												''PCEM1'',''PCMO1'',''PCPA1'',''PCSE1'',''PECE1'',''PECJ1'',''PECP1'',''PECS1'',''PEME1'',''PEMN1'',''PEMP1'',''PEMS1'',''PEPE1'',''PEPZ1'',''PEPP1'',
												''PEPS1'',''RINE1'',''RINV1'',''RINP1'',''RINS1'',''GRAV1'',
												--CONTRIBUIÇÕES DE SOBREVIDA PU
												''CREG9'',''CREE9'',''CREE6'',''CREP9'',''CREP6'',''CR
GO
 
IF OBJECT_ID('[dbo].[PRC_230_CARGA_TB_ESTRUTURA_UNIDADE_DIM]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[PRC_230_CARGA_TB_ESTRUTURA_UNIDADE_DIM];
GO

----------------------------------------------------------------------------------------------------
		CREATE 	PROCEDURE [dbo].PRC_230_CARGA_TB_ESTRUTURA_UNIDADE_DIM AS	
----------------------------------------------------------------------------------------------------
--		ROTINA DE FUNDAMENTADOR :

--			1.	Carregar as tabelas vindas da CEF e GEPLAC atraves do DataStage
--			2.  Carregar a tabela final nesta proc, chamada pelo ultimo job do DataStage

----------------------------------------------------------------------------------------------------


----------------------------------------------------------------------------------------------------
WITH DETALHES_SEV AS (

SELECT  AG.TP_UNIDADE,
        AG.NU_UNIDADE           AS COD_AGENCIA,
        AG.NO_UNIDADE           AS NOM_AGENCIA,
        AG.NU_PORTE             AS COD_PORTE_AGENCIA,
    
        AG.UN_SEV               AS COD_SEV,
        SEV.NO_UNIDADE          AS NOM_SEV,
        SEV.NU_PORTE            AS COD_PORTE_SEV,
        AG.UN_SR                AS COD_SR,
        SR.NO_UNIDADE           AS NOM_SR,
        SR.NU_PORTE             AS COD_PORTE_SR,
        AG.UN_SURV              AS COD_SURV,
        SURV.NO_UNIDADE         AS NOM_SURV,
        AG.UN_SEP               AS COD_SEP,
        SEP.NO_UNIDADE          AS NOM_SEP,
        AG.UN_SEH               AS COD_SEH,
        SEH.NO_UNIDADE          AS NOM_SEH,
        AG.UN_SN                AS COD_SN,
        SN.NO_UNIDADE           AS NOM_SN,
        AG.UN_VP                AS COD_VP,
        VP.NO_UNIDADE           AS NOM_VP,

        COALESCE(AC.DES_TIPO_REDE,SV.DES_TIPO_REDE)                              AS DES_TIPO_REDE,
        COALESCE(SV.COD_CARTEIRA,AC.COD_CARTEIRA)                                AS COD_CARTEIRA,
        CAR.NOM_CARTEIRA,
        COALESCE(CGA.NUM_MATRICULA_CONSULTOR, CG.NUM_MATRICULA_CONSULTOR)        AS NUM_MATRICULA_CONSULTOR,
        COALESCE(CGA.NOM_CONSULTOR,CG.NOM_CONSULTOR)                             AS NOM_CONSULTOR,
        COALESCE(CGA.DES_EMAIL_CONSULTOR, CG.DES_EMAIL_CONSULTOR)                AS DES_EMAIL_CONSULTOR,
        COALESCE(CGA.NOM_SUB_GERENCIA_CONSULTOR , CG.NOM_SUB_GERENCIA_CONSULTOR) AS NOM_SUB_GERENCIA,

        GG.NOM_GERENCIA ,
        GG.NOM_GERENTE,
        GG.DES_EMAIL_GERENTE, 
        GG.NOM_COORDENADOR ,
        GG.DES_EMAIL_COORDENADOR,
        
        EN.ENDERECO             AS  NOM_ENDERECO_AGENCIA,
        EN.BAIRRO               AS  NOM_BAIRRO_AGENCIA,
        EN.NOME_MUNIC           AS  NOM_CIDADE_AGENCIA,
        EN.UF                   AS  COD_UF_AGENCIA,
        EN.CEP + EN.CEP_COMPL   AS  COD_CEP_AGENCIA,
        EN.TELEFONE_AGENCIA     AS  NUM_FONE_AGENCIA,

        ECO.MATR_FUNC           AS  NUM_MATRICULA_RESPONSAVEL_AGENCIA,
        ECO.NOM_FUNC            AS  NOM_RESPONSAVEL_AGENCIA,
        ECO.NUM_CPF             AS  NUM_CPF_RESPONSAVEL_AGENCIA

FROM    DMDB47.dbo.TB_CEF_UNIDADE_CAIXA         AG      WITH(NOLOCK)

LEFT JOIN   DMDB47.dbo.TB_CEF_UNIDADE_CAIXA     SEV     WITH(NOLOCK) 
ON   SEV.NU_UNIDADE = AG.UN_SEV

LEFT JOIN   DMDB47.dbo.TB_CEF_UNIDADE_CAIXA     SR      WITH(NOLOCK) 
ON   SR.NU_UNIDADE = AG.UN_SR

LEFT JOIN   DMDB47.dbo.TB_CEF_UNIDADE_CAIXA     SURV    WITH(NOLOCK) 
ON   SURV.NU_UNIDADE = AG.UN_SURV

LEFT JOIN   DMDB47.dbo.TB_CEF_UNIDADE_CAIXA     SEP     WITH(NOLOCK) 
ON   SEP.NU_UNIDADE = AG.UN_SEP

LEFT JOIN   DMDB47.dbo.TB_CEF_UNIDADE_CAIXA     SEH     WITH(NOLOCK) 
ON   SEH.NU_UNIDADE = AG.UN_SEH

LEFT JOIN   DMDB47.dbo.TB_CEF_UNIDADE_CAIXA     SN      WITH(NOLOCK) 
ON   SN.NU_UNIDADE = AG.UN_SN

LEFT JOIN   DMDB47.dbo.TB_CEF_UNIDADE_CAIXA     VP      WITH(NOLOCK) 
ON   VP.NU_UNIDADE = AG.UN_VP

-----------------------------

LEFT JOIN   WORK_GEPLAC..TB_SEV_CARTEIRA        SV      WITH(NOLOCK)    --  DMDB47.dbo.TB_SEV_CONSULTOR SV WITH(NOLOCK) 
ON  SV.NUM_SEV  = AG.UN_SEV

LEFT JOIN   WORK_GEPLAC..TB_AG_CARTEIRA        
GO
 
