IF OBJECT_ID('[dbo].[PRC_500_INDICADOR_ESCOLA_NEGOCIO]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[PRC_500_INDICADOR_ESCOLA_NEGOCIO];
GO
CREATE PROCEDURE [dbo].[PRC_500_INDICADOR_ESCOLA_NEGOCIO] AS

SELECT CONVERT(VARCHAR(50),B.NOM_FUNC)			NOM_FUNC
	,CONVERT(VARCHAR(40),B.DES_FUNCAO)		DES_FUNCAO --RITM0076073 13/04/26
	,CONVERT(VARCHAR(50),B.EMAIL_CONTATO)		EMAIL_CONTATO
	,CONVERT(VARCHAR(11),B.NUM_CPF)			NUM_CPF
	,CONVERT(INT,B.MATR_FUNC)					MATR_FUNC 
	,CONVERT(SMALLINT,B.DV_MATR_FUNC)			DV_MATR_FUNC
	,CONVERT(SMALLINT,B.DDD_LOTACAO)			DDD_LOTACAO
	,CONVERT(INT,B.TELEFONE_LOTACAO)			TELEFONE_LOTACAO
	,CONVERT(SMALLINT,B.COD_UNIDADE)			COD_UNIDADE
	,CONVERT(VARCHAR(35),REPLACE(B.NOM_UNIDADE,',','-'))  NOM_UNIDADE
	,CONVERT(VARCHAR(50),REPLACE(B.NOM_SEV,',','-'))  NOM_SEV
	,CONVERT(VARCHAR(50),REPLACE(B.NOM_SR,',','-'))  NOM_SR
	,CONVERT(VARCHAR(2),B.COD_UF)				COD_UF
	,CONVERT(VARCHAR(100),B.EMAIL_CONSULTOR)	EMAIL_CONSULTOR  
	,CONVERT(NVARCHAR(100),B.SUB_GERENCIA)	SUB_GERENCIA
	,CONVERT(VARCHAR(21),B.DES_TIPO_REDE)	DES_TIPO_REDE
	,CONVERT(VARCHAR(15),B.REGIAO)	REGIAO
	,CONVERT(VARCHAR(50),B.DES_CLASSIFICACAO)	DES_CLASSIFICACAO
	,CONVERT(VARCHAR(50),ISNULL(B.NOM_CONSULTOR,''))			NOM_CONSULTOR
FROM (
select
	 ECO.NOM_FUNC			NOM_FUNC
	,CASE WHEN ECO.DES_FUNCAO IS NULL OR ECO.DES_FUNCAO = '' THEN 'SEM FUNCAO' ELSE ECO.DES_FUNCAO END		DES_FUNCAO --RITM0076073 13/04/26
	,ECO.EMAIL_CONTATO		EMAIL_CONTATO
	,ECO.NUM_CPF			NUM_CPF
	,ECO.MATR_FUNC					MATR_FUNC 
	,ECO.DV_MATR_FUNC			DV_MATR_FUNC
	,ECO.DDD_LOTACAO			DDD_LOTACAO
	,ECO.TELEFONE_LOTACAO			TELEFONE_LOTACAO
	,TDV.COD_UNIDADE			COD_UNIDADE
	,REPLACE(ECO.NOM_UNIDADE,',','-')  NOM_UNIDADE
	,REPLACE(TDV.NOM_SEV,',','-')  NOM_SEV
	,REPLACE(TDV.NOM_SR,',','-')  NOM_SR
	,TDV.COD_UF				COD_UF
	,ENAR.EMAIL_CONSULTOR	EMAIL_CONSULTOR  
	,ENAR.SUB_GERENCIA	SUB_GERENCIA
	,ENAR.DES_TIPO_REDE	DES_TIPO_REDE

	,CASE	WHEN	ENAR.REGIAO_AG  = 'SÃO PAULO' THEN 'SAO PAULO'
									ELSE	ENAR.REGIAO_AG
									END	REGIAO

	,CASE	WHEN	TDV.DES_CLASSIFICACAO  = 'SEM CLASSIFICAÃÃO' THEN 'SEM CLASSIFICAO'
									ELSE	TDV.DES_CLASSIFICACAO
									END	DES_CLASSIFICACAO

	,ISNULL(ENAR.NOM_CONSULTOR,'') NOM_CONSULTOR
	,ROW_NUMBER() OVER (PARTITION BY ECO.NUM_CPF ORDER BY (ECO.MATR_FUNC) DESC) AS RN

FROM	DMDB41.dbo.DM_TDV_CLASSIF_INDICADOR ( nolock )  TDV 

JOIN	DMDB41.dbo.DM_ECONOMIARIO  ( nolock )  ECO
ON		SUBSTRING(CONVERT(VARCHAR(7),REPLACE(REPLACE(TDV.COD_MATRICULA,'-',''), 'C', ''),7),1,6)  = ECO.MATR_FUNC

LEFT JOIN DMDB41.[dbo].TB_ESTRUTURA_HIST ENAR
ON		ENAR.NU_UNIDADE	=	TDV.COD_UNIDADE
AND		ENAR.ANOMES		=	TDV.ANOMES

WHERE	TDV.ANOMES		=	(SELECT MAX(ANOMES) FROM DMDB41.dbo.DM_TDV_CLASSIF_INDICADOR)
AND		SIT_FUNC	IN ( 1, 3) 
) B
WHERE B.RN = 1 --RETIRAR CPFs DUPLICADOS ENVIADOS PELA CAIXA
GO
 
IF OBJECT_ID('[dbo].[PRC_501_PARCEIRO_ESCOLA_NEGOCIO]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[PRC_501_PARCEIRO_ESCOLA_NEGOCIO];
GO
create		PROCEDURE [dbo].[PRC_501_PARCEIRO_ESCOLA_NEGOCIO] AS

SELECT	P.*
