IF OBJECT_ID('[dbo].[PRC_520_GEFIN_BENEFICIO]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[PRC_520_GEFIN_BENEFICIO];
GO

-- ==================================================================================================================================================
--
--          PROCEDURE   :   SSCPREV_INS_010_ACON_DCD
--
--          AUTHOR      :	SILVIO J® 
--          CREATE DATE :   01/10/2025
--          DESCRIPTION :	CARREGA OS RESGATES (SOBREVIDA)


CREATE PROCEDURE [dbo].PRC_520_GEFIN_BENEFICIO 

AS


---------------------------------------------------------------------------------------------------
--		RITM0035913 - Extração de dados beneficios
---------------------------------------------------------------------------------------------------
--		Área do solicitante: DIRFI_CVP GEFIS_CVP
---------------------------------------------------------------------------------------------------
--		28/08/2025	:	J®	-	CRIAÇÃO  

--		processo usado para nos casos de manuais pontuais

---------------------------------------------------------------------------------------------------
/*

select * from SB_T_202101_BENEFICIO_CERTIFICADO

*/

DROP TABLE IF EXISTS #BASE1
 
SELECT	*
INTO	#BASE1
FROM	OPENQUERY(KIPRD,'
SELECT ''BENEFICIO'' TIPO_PAGAMENTO,
		SOL.CPF_CNPJ_FAVORECIDO CPF,
		CUE.COD_CUENTA AS APOLICE,
		TO_CHAR(ADD_MONTHS(SYSDATE, -2), ''YYYY'')  AS ANO,
		TO_CHAR(ADD_MONTHS(SYSDATE, -2), ''MM'')  AS MES,
		SPR.DESCRIPCION MODALIDADE, 
		CASE    WHEN TO_CHAR(BM.DATA_VENCIMENTO_ORIGINAL, ''YYYY'') < TO_CHAR(TIT.DATA_PGTO, ''YYYY'') THEN ''REGRESSIVA''
				WHEN BTC.E_RISCO = ''S'' THEN ''PROGRESSIVA''
				WHEN CUE.OPCAO_TRIBUTACAO_IRRF = ''TP'' THEN ''PROGRESSIVA''
				WHEN CUE.OPCAO_TRIBUTACAO_IRRF = ''TR'' THEN ''REGRESSIVA''
				ELSE CUE.OPCAO_TRIBUTACAO_IRRF
		END OPCAO_TRIBUTACAO_IRRF,
		ROUND(TO_NUMBER(SUM(BPP.MONTO)), 2) VLR_BRUTO, 
		ROUND(SUM(NVL(IR.VALOR_TOTAL_BASE_CALCULO, 0)), 2) VLR_BASE_IRRF, 
		ROUND(SUM(ABS(BM2.MONTO)), 2) VLR_IR, 
		ROUND(SUM(NVL(PA.VALOR_ISENCAO, 0)), 2) VLR_PENSAO_ALIM, 
		SOL.DATA_PGTO DATA_PAGAMENTO,

		CASE	WHEN FLOOR(MONTHS_BETWEEN(SOL.DATA_PGTO, PF.FEC_NACIMIENTO) / 12) >= 65 
				THEN ''S''
				ELSE ''N''
				END		MAIOR_65_ANOS, 

		CASE	WHEN ISE.DATA_INICIO_ISENCAO IS NOT NULL 
				THEN ''S''
				ELSE ''N''
				END  MOLESTIA_GRAVE, 

        CASE     WHEN NVL(H.TIPO_MOVTO, P.TIPO_MOVTO) = ''RV'' 
				THEN ''S''
				WHEN NVL(H.TIPO_MOVTO, P.TIPO_MOVTO) = ''AV'' 
				AND  BM.FEC_MOVIMTO >= PBAR.DATA_INI_CALCULO 
				THEN           ''S''
				ELSE         ''N''
				END RRA, 
       TO_CHAR(PBAR.DATA_INI_CALCULO, ''YYYY'') ANO_RRA

FROM KIPREV.BA_CPG_SOLICITACOES SOL

JOIN KIPREV.BA_CPG_TITULOS TIT
ON SOL.COD_EMPRESA = TIT.COD_EMPRESA
AND SOL.NUM_MOVTO_CP = TIT.NUM_MOVTO_CP

JOIN KIPREV.PERSONAS_FISICAS PF
ON PF.COD_PER_FISICA = SOL.COD_PERSONA

LEFT JOIN KIPREV.PA_PESSOAS_X_ISENCOES_DOENCAS ISE
ON ISE.COD_PERSONA = SOL.COD_PERSONA
AND SOL.DATA_PGTO BETWEEN ISE.DATA_INICIO_ISENCAO 
AND ISE.DATA_FIM_ISENCAO

JOIN KIPREV.BE_MOVIMIENTOS BM
ON SOL.COD_EMPRESA = BM.COD_EMPRESA
AND BM.NUM_SOLICITUD = SUBSTR(SOL.NUM_DOCUMENTO_ORIGEM, 1, 8)
AND BM.NUM_MOVIMTO = SUBSTR(SOL.NUM_DOCUMENTO_ORIGEM, 9, 8)

JOIN KIPREV.BE_MOVIMIENTOS BM2
ON BM2.COD_EMPRESA = BM.COD_EMPRESA
AND BM2.NUM_SOLICITUD = BM.NUM_SOLICITUD
AND BM2.COD_PESSOA_BENEFICIARIO = BM.COD_PESSOA_BENEFICIARIO
AND BM2.COD_TIPO_PLAN_PAGO = BM.COD_TIPO_PLAN_PAGO
AND BM2.NUM_PARCELA = BM.NUM_PARCELA

JOIN KIPREV.PA_BASE_CALCULO_IR IR
ON IR.COD_EMPRESA = BM2.COD_EMPRESA
AND IR.ID_BASE_CALCULO = BM2.ID_BASE_CALCULO
AND BM2.COD_AFECTACION =
    KIPREV.PARAM.PARAMETRO_X_EMPRESA(IR.COD_EMPRESA,
                                    ''VARIACAO_IRRF'',
                                    ''BE'')

LEFT JOIN KIPREV.PA_BASE_CALC_OUTRAS_ISENCOES PA
ON IR.COD_EMPRESA = PA.COD_EMPRESA
AND IR.ID_BASE_CALCULO = PA.ID_BASE_CALCULO
AND PA.COD_TIP_ISENCAO_DEDUCAO = 6

JOIN KIPREV.BE_BENEFICIOS BEN
ON BEN.COD_EMPRESA = BM.COD_EMPRESA
AND BEN.COD_PLAN = BM.COD_PLAN
AN
GO
 
IF OBJECT_ID('[dbo].[PRC_530_ENVIA_RESGATES_REINF]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[PRC_530_ENVIA_RESGATES_REINF];
GO


---------------------------------------------------------------------------------------------------
--		RITM0035913 - Extração de dados 
---------------------------------------------------------------------------------------------------
--		Para que possamos estar validando mensalmente a REINF com o KIPREV, preciso que seja 
--		disponibilizado os arquivos mensais de resgate e benefício. 
--		o relatorio deve ser emitido mensalmente com todas as informações constantes nos anexos. 

--		Área do solicitante: DIRFI_CVP GEFIS_CVP
---------------------------------------------------------------------------------------------------
--		28/08/2025	:	J®	-	CRIAÇÃO 
---------------------------------------------------------------------------------------------------

CREATE	PROCEDURE [dbo].[PRC_530_ENVIA_RESGATES_REINF] 

AS

----------------------------------------------------------------------------------------------------
--		AIC +  VENDA INTERNA KIPREV (COM PGTO) + RAJADA +  SAP
----------------------------------------------------------------------------------------------------

DROP TABLE IF EXISTS #BASE1
 
SELECT	*
INTO	#BASE1
FROM	OPENQUERY(KIPRD,
'SELECT ''RESGATE PAGAR PARA'' TIPO_PAGAMENTO, -- 1
       I.CPF, -- 2
       TO_CHAR(ADD_MONTHS(SYSDATE, -1), ''YYYY'')  AS ANO, -- 3
       I.MODALIDADE, -- 4
       I.OPCAO_TRIBUTACAO_IRRF, -- 5
       I.VLR_SAIDA_BRT, -- 6
       I.VLR_SAIDA_LIQ, -- 7
       I.VLR_BASE_IRRF, -- 8
       I.VLR_IRRF, -- 9
	   I.DATA_PAGAMENTO
  FROM (SELECT  ID.NUM_ID CPF,
                SUM(CALC.VLR_SAIDA_BRT) VLR_SAIDA_BRT,
                SUM(CALC.VLR_SAIDA_LIQ) VLR_SAIDA_LIQ,
                SUM(CALC.VLR_BASE_IRRF) VLR_BASE_IRRF,
                SUM(CALC.VLR_IRRF) VLR_IRRF,
                MOD.DESCRIPCION MODALIDADE,
                RS.OPCAO_TRIBUTACAO_IRRF, -- US 30515 - TASK 30518
				TO_CHAR(TRUNC(NVL(TIT.DATA_PGTO_EFETIVO, TIT.DATA_PGTO)), ''YYYY-MM-DD'') DATA_PAGAMENTO
          FROM KIPREV.BA_CPG_SOLICITACOES SOL
          JOIN KIPREV.BA_CPG_TITULOS TIT
            ON SOL.COD_EMPRESA = TIT.COD_EMPRESA
           AND SOL.NUM_MOVTO_CP = TIT.NUM_MOVTO_CP
          JOIN KIPREV.PA_STATUS ST
            ON ST.COD_STATUS = TIT.STATUS
           AND ST.TIP_STATUS = TIT.TIP_STATUS
          JOIN KIPREV.FO_DETALHE_CALCULO CALC
            ON CALC.COD_EMPRESA = SOL.COD_EMPRESA
           AND CALC.NUM_RESGATE = SOL.NUM_DOCUMENTO_ORIGEM
          JOIN KIPREV.FO_CUENTAS CUE
            ON CUE.COD_EMPRESA = SOL.COD_EMPRESA
           AND CUE.COD_CUENTA = SOL.COD_CUENTA
          JOIN KIPREV.ID_PERSONAS ID
            ON ID.COD_PERSONA = CUE.COD_CLIENTE
           AND ID.COD_TIPO_ID = ''1''
           AND ID.COD_PESSOA_TITULAR IS NULL
          JOIN KIPREV.FO_PRODUCTOS PROD
            ON PROD.COD_EMPRESA = CUE.COD_EMPRESA
           AND PROD.COD_PRODUCTO = CUE.COD_PRODUCTO
          JOIN KIPREV.SUBCAT_PRODUCTOS MOD
            ON MOD.COD_CAT_PRODUCTO = PROD.COD_CAT_PRODUTO
           AND MOD.COD_SUBCAT_PRODUCTO = PROD.COD_SUBCAT_PRODUTO
          JOIN KIPREV.FO_RESG_SOLIC RS
            ON RS.COD_EMPRESA = SOL.COD_EMPRESA
           AND RS.NUM_RESGATE = SOL.NUM_DOCUMENTO_ORIGEM
         WHERE SOL.COD_EMPRESA = ''500''
           AND SOL.COD_OPER = ''4'' -- PAGAMENTO DE RESGATE
           AND SOL.STATUS = ''3'' -- STATUS PAGO
           AND ID.NUM_ID <> NVL(SOL.CPF_CNPJ_FAVORECIDO, SOL.NUM_ID) -- SOMENTE PAGAR PARA
		 AND TO_CHAR(NVL(TIT.DATA_PGTO_EFETIVO, TIT.DATA_PGTO),''YYYYMM'') =  TO_CHAR(ADD_MONTHS(SYSDATE, -1), ''YYYYMM'')
         GROUP BY ID.NUM_ID,
                   MOD.DESCRIPCION,
                   RS.OPCAO_TRIBUTACAO_IRRF, -- US 30515 - TASK 30518
                  TO_CHAR(TRUNC(NVL(TIT.DATA_PGTO_EFETIVO, TIT.DATA_PGTO)), ''YYYY-MM-DD'') 
        ) I

') B

-------------------------------------------------------------------------------------------------
