-- ==================================================================================================================================================

CREATE	PROCEDURE [dbo].[PRC_CRT_010_ALERTA_SEGMENTACAO]

AS	
	  
-----------------------------------------------------------------------------------------------------------------------------------------------------

DECLARE		@DESTINATARIOS		            VARCHAR(MAX)
            ,@ASSUNTO			            VARCHAR(MAX)
            ,@TXT_EMAIL			            VARCHAR(MAX)
			,@ALERTA						VARCHAR(6)

-----------------------------------------------------------------------------------------------------------------------------------------------------
-----       FND	-	MOVIMENTAÇÃO DE CLIENTES
-----------------------------------------------------------------------------------------------------------------------------------------------------
IF			OBJECT_ID('TEMPDB..##MOV_CAUSA')		IS NOT	NULL 
			DROP TABLE	##MOV_CAUSA

SELECT	
		DES_SEGMENTO
		,CASE	WHEN	S.DES_SEGMENTO	=	'    ' 
				THEN	'Segmento em branco'
			    WHEN	SUBSTRING(S.DES_SEGMENTO,1,2) NOT IN (	'GV', 'GC', 'GR', 'FX', 'EE', 'ES', 'EF', 'EX',
																'MD', 'UD', 'EC', 'LC', 'IV', 'PD', 'PU', 'PG', 
																'PP', 'ID', 'IU', 'IG', 'IP', 'PO', 'PN', 'PM') 
				THEN	'Código desconhecido' 
				ELSE	NULL 
				END		AS	 TIPO_INCONSISTENCIA,

		NOM_ARQUIVO,
		COUNT(DISTINCT S.NUM_CPF) AS QTDE

INTO	##MOV_CAUSA
-- select top 8 *
FROM	[DMDB41].[DBO].DM_ARQ_SEGMENTACAO_CLIENTE S WITH(NOLOCK)

WHERE	S.DTA_ARQUIVO = (	SELECT MAX(S2.DTA_ARQUIVO) 
							FROM [DMDB41].[DBO].DM_ARQ_SEGMENTACAO_CLIENTE S2 WITH(NOLOCK))
		AND  (	S.DES_SEGMENTO = '    '
		Or	SUBSTRING(S.DES_SEGMENTO,1,2) NOT IN (	'GV', 'GC', 'GR', 'FX', 'EE', 'ES', 'EF', 'EX', 'MD', 'UD', 'EC', 
													'LC', 'IV', 'PD', 'PU', 'PG', 'PP', 'ID', 'IU', 'IG', 'IP', 'PO', 
													'PN', 'PM'))
GROUP BY DES_SEGMENTO
		,CASE	WHEN	S.DES_SEGMENTO	=	'    ' 
				THEN	'Segmento em branco'
			    WHEN	SUBSTRING(S.DES_SEGMENTO,1,2) NOT IN (	'GV', 'GC', 'GR', 'FX', 'EE', 'ES', 'EF', 'EX',
																'MD', 'UD', 'EC', 'LC', 'IV', 'PD', 'PU', 'PG', 
																'PP', 'ID', 'IU', 'IG', 'IP', 'PO', 'PN', 'PM') 
				THEN	'Código desconhecido' 
				ELSE	NULL 
				END
		,NOM_ARQUIVO
-----------------------------------------------------------------------------------------------------------------------------------------------------
--          AVALIA A EMISSÃO DO E_MAIL
-----------------------------------------------------------------------------------------------------------------------------------------------------

IF EXISTS (	SELECT		1                
			FROM        ##MOV_CAUSA		)

BEGIN 
			SET			@ALERTA			=	'High'

			SET         @DESTINATARIOS	=	'rane.neto@caixavidaeprevidencia.com.br;
											tamiris.sampaio@caixavidaeprevidencia.com.br;
											adenyson.santos@caixavidaeprevidencia.com.br;
											italo.pereira.externo@caixavidaeprevidencia.com.br'

			SET         @ASSUNTO        =   'CLIENTE: INCONSISTÊNCIAS NA SEGMENTAÇÃO EM ' + CONVERT(VARCHAR(10),getdate(),103) 

			SET         @TXT_EMAIL		=	'<p> Prezados</p>'
										+	'<p> </p>'
										+	'<p> Segue o relatório das inconsistências na segmentação de clientes</p>'
										+	'<p> </p>'
										+	'<p> Rotina : PRC_CRT_010_ALERTA_SEGMENTACAO</p>'
										+	'<p> </p>'

										----------------------------------------------------------------------------------------------------------------------------------
										--	Cambria

										+	'<html>'
				
GO
 
