 CREATE       PROCEDURE [dbo].[PRC_CRT_010_TOTAL_VENDA]  AS

-----------------------------------------------------------------------------------------------------------------------------------------------------
--          AVALIA A EMISSÃO DO E_MAIL
-----------------------------------------------------------------------------------------------------------------------------------------------------

-------------------------------------------------------------------------------------------
--		VIDA
-------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS #VIDA
DROP TABLE IF EXISTS #VIDA_MEDIA
DROP TABLE IF EXISTS #ALL

SELECT  
		'2.	VIDA                 ' AS SEGMENTO,
		B.DTA_PROX_DATA_UTIL AS DTA_VENDA,
		COUNT(*) QTDE,
		SUM(V.VLR_VENDA) VLR_VENDA
INTO	#VIDA
FROM	DMDB41..TB_VENDA_VIDA_CONSOLIDADA V (NOLOCK)
LEFT JOIN DMDB42..DM_DIM_TEMPO B
ON		V.DTA_PROPOSTA = B.DTA_DATA
WHERE	B.DTA_DATA	BETWEEN		CONVERT(DATE,DATEADD(D,-30,GETDATE()))
						AND		CONVERT(DATE,GETDATE())
GROUP BY 
		B.DTA_PROX_DATA_UTIL 

SELECT  
		SEGMENTO,
		AVG(QTDE) QTDE_MEDIA,
		CONVERT(NUMERIC(18,2),AVG(VLR_VENDA)) VLR_VENDA_MEDIA
into	#VIDA_MEDIA
FROM	#VIDA
GROUP BY 
		SEGMENTO

SELECT	TOP 3
		V.SEGMENTO,
		DTA_VENDA,
		VLR_VENDA,
		M.VLR_VENDA_MEDIA,
		QTDE,
		M.QTDE_MEDIA,
		PCT= REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR,CONVERT(MONEY, (convert(decimal(7,4),cast(VLR_VENDA as float)/ CAST(VLR_VENDA_MEDIA as float)* 100))),1),',', 'x') ,'.', ','),'x', '.') 
INTO	#ALL
FROM	#VIDA V
,		#VIDA_MEDIA M
ORDER BY V.DTA_VENDA desc 

