		,F.MOVIMENTO
		,SUM(F.VLR_GERADO	)									VLR_GERADO
		,SUM(F.VLR_PGTO_RAJADA	)								VLR_PGTO_RAJADA
		,SUM(F.VLR_PGTO_MJUNMOV	)								VLR_PGTO_MJUNMOV
		,SUM(F.VLR_PGTO_SAP		)								VLR_PGTO_SAP
		,SUM(F.VLR_PGTO_banco	)								VLR_PGTO_BANCO
		,SUM(F.VLR_PGTO_KIPREV	)								VLR_PGTO_KIPREV

		, SUM(CASE	WHEN ISNULL(F.VLR_PGTO_RAJADA,0) > 0	THEN ISNULL(F.VLR_PGTO_RAJADA,0)
					WHEN ISNULL(F.VLR_PGTO_MJUNMOV,0) > 0	THEN ISNULL(F.VLR_PGTO_MJUNMOV,0)
					WHEN ISNULL(F.VLR_PGTO_SAP,0) > 0		THEN ISNULL(F.VLR_PGTO_SAP,0)
					WHEN ISNULL(F.VLR_PGTO_banco,0) > 0		THEN ISNULL(F.VLR_PGTO_banco,0)
					WHEN ISNULL(F.VLR_PGTO_KIPREV,0) > 0	THEN ISNULL(F.VLR_PGTO_KIPREV,0)
					END )										VLR_PAGO

		,SUM(ISNULL(F.VLR_EMIS_BC,0) )	VLR_EMIS_BC
		,SUM(ISNULL(F.VLR_EMIS_SSC,0) )	VLR_EMIS_SSC
		,COUNT(*)	QTDE

INTO	##MOV  

FROM	DMDB41..SB_VENDA_FUNDAMENTADOR 	 F
GROUP BY F.MOVIMENTO
		,F.DTA_VENDA

