DECLARE @DTA_DIA_UTIL_ANTERIOR DATE  

SELECT	@DTA_DIA_UTIL_ANTERIOR = DTA_DIA_UTIL_ANTERIOR 
FROM	DMDB41..DM_DIM_TEMPO 
WHERE	DTA_DATA	=	CONVERT(DATE,GETDATE()) --DATEADD(DAY, -2,CONVERT(DATE,GETDATE()))

-----------------------------------------------------------------------------------------------------------------------------------------------------
