DROP TABLE	IF EXISTS ##VENDA			

SELECT		CASE WHEN MOVIMENTO = 'AIC' THEN 'VENDA AIC' ELSE 'VENDA INTERNA' END AS MOVIMENTO,
			DTA_VENDA		AS	DTA_MOVIMENTO,
			SUM(VLR_GERADO) AS	VLR_GERADO,
			SUM(VLR_PAGO)	AS	VLR_PAGO,
			SUM(VLR_SAP)	AS	VLR_SAP

INTO		##VENDA
FROM (
      SELECT *
      FROM   DMDB41..VW_VENDA_PREV
      WHERE DTA_VENDA =  @DTA_DIA_UTIL_ANTERIOR--'2024-10-08'
) B
GROUP BY b.MOVIMENTO,B.DTA_VENDA

