SELECT		MOVIMENTO	,--				=	'APORTE ',
			RS.DTA_APORTE				AS	DTA_MOVIMENTO,
			SUM(RS.VLR_GERADO_KIPREV)	AS	VLR_GERADO,
			SUM(VLR_PAGO_KIPREV)		AS	VLR_PAGO,
			SUM(VLR_SAP)				AS	VLR_SAP

