      SELECT MOVIMENTO	=	'APORTE ', *
      FROM DMDB41..VW_APORTE_PREV A WITH(NOLOCK)
      WHERE DTA_APORTE =  @DTA_DIA_UTIL_ANTERIOR
) RS
GROUP BY rs.MOVIMENTO,RS.DTA_APORTE

