	CREATE	PROCEDURE [dbo].[PRC_CRT_017_ALERTA_VENDA_APORTE_VALOR_ALTO] AS	
	  
-- exec  PRC_CRT_017_ALERTA_VENDA_APORTE_VALOR_ALTO 
-----------------------------------------------------------------------------------------------------------------------------------------------------

--	Podemos incluir matrícula e nome do vendedor, nome da agência, sev e sr?

-----------------------------------------------------------------------------------------------------------------------------------------------------
-----       FND	-	MOVIMENTAÇÃO DE CLIENTES
-----------------------------------------------------------------------------------------------------------------------------------------------------
DROP TABLE	IF EXISTS #VENDA			

SELECT		
		MOVIMENTO		=	'VENDA '
		,DTA_VENDA		AS	DTA_VENDA
		,NUM_PROPOSTA
	--	,IND_PAGO
		,CONVERT(DATE,DTA_PAGAMENTO) DTA_PAGAMENTO
		,MATRICULA_INDICADOR
		,NOM_INDICADOR
		,V.COD_AGENCIA 
		,A.NOM_AGENCIA
		,A.NOM_SEV
		,A.NOM_SR
		,CASE	WHEN DES_FORMA_PGTO = 'Ficha de Compensação' 
				THEN 'FC' 
				ELSE 'DC' 
				END		AS DES_FORMA_PGTO			
		,VLR_GERADO
		,VLR_PAGO

INTO	#VENDA

FROM	DMDB41..VW_VENDA_PREV	V ( nolock) 
LEFT JOIN DMDB41.[dbo].[DM_AGENCIA] A (NOLOCK)
ON		V.COD_AGENCIA	=	A.COD_AGENCIA

WHERE	DTA_VENDA	>	DATEADD(DAY,-10,GETDATE())
AND		VLR_GERADO	>	1000000

UNION  

SELECT	MOVIMENTO			=	'APORTE '
		,DTA_APORTE			AS	DTA_VENDA
		,NUM_PROPOSTA
		--,CASE	WHEN STA_COBRANCA IN ( 'BT' ) 
		--		THEN 'S' 
		--		ELSE 'N' 
		--		END		AS	IND_PAGO
		,CONVERT(DATE,DTA_PAGAMENTO) DTA_PAGAMENTO
		,MATRICULA_INDICADOR
		,NOM_INDICADOR
		,V.COD_AGENCIA 
		,A.NOM_AGENCIA
		,A.NOM_SEV
		,A.NOM_SR
		,CASE WHEN DES_FORMA_PGTO = 'Ficha de Compensação' THEN 'FC' ELSE 'DC' END AS DES_FORMA_PGTO
		,VLR_GERADO_KIPREV	AS	VLR_GERADO
		,VLR_SAP			AS	VLR_PAGO

FROM	DMDB41..VW_APORTE_PREV V WITH(NOLOCK)

LEFT JOIN DMDB41.[dbo].[DM_AGENCIA] A (NOLOCK)
ON		V.COD_AGENCIA		=	A.COD_AGENCIA

WHERE	DTA_APORTE			>	DATEADD(DAY,-10,GETDATE())
AND		VLR_GERADO_KIPREV	>	1000000

order by 12 desc 

