--		"Joao Paulo de Almeida" <joao.p.almeida@caixa.gov.br>; 
--		"Joao Victor Berta Vasconcelos" <joao.b.vasconcelos@caixa.gov.br>; 
--		"Luiz Henrique Ferraz Veiga Granja" <luiz.granja@caixa.gov.br>

----------------------------------------------------------------------------------------------------
--		Tipo do movimento (Aporte, Venda nova, Portabilidade, Venda interna, venda manual),
--		CPF do cliente,
--		Data da venda,
--		Unidade da venda,
--		Matricula do vendedor,
--		Valor Gerado,
--		Valor Pago,
--		Data de pagamento -- se não tiver sido pago, data estará vazia
-- 
--		Filtro: Propostas pagas => 18/11 ou geradas => 18/11
-- 
-- 
--		Etapas:
--		Criar uma view com esses dados e filtros (Silvio)
--		Criar a rotina (Mesmo B2B que já enviamos portabilidade)
----------------------------------------------------------------------------------------------------
--SELECT  '1 - AIC +  VENDA INTERNA KIPREV  + APORTE',GETDATE()
----------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS ##1FUND		--- 88024

SELECT	MOVIMENTO,
		B.DTA_VENDA,
		B.DTH_VENDA,
		B.NUM_CPF_CNPJ,
		B.NUM_PROPOSTA,
		B.COD_AGENCIA,
		B.COD_MATRICULA,
		B.NUM_CERTIFICADO,
		B.NOM_PRODUTO,
		B.DES_FORMA_PGTO,
		B.IND_PAGO,
		CONVERT(MONEY,ISNULL(B.VLR_GERADO,0))		VLR_GERADO,
		CONVERT(DATE,B.DTA_PGTO_KIPREV)				DTA_PGTO_KIPREV,
		CONVERT(DATE,B.DTA_BAIXA_KIPREV)			DTA_BAIXA_KIPREV,
		CONVERT(MONEY,ISNULL(B.VLR_PGTO_KIPREV,0))  VLR_PGTO_KIPREV ,
		B.NOSSO_NUMERO_KIPREV,
		B.NUM_COBRANCA									AS	NUM_COBRANCA ,	
		B.NUM_DEPOSITO									AS	NUM_DEPOSITO ,
		B.DTA_PAGAMENTO_MJUNMOV							AS  DTA_PGTO_MJUNMOV_AIC,
		B.DTA_PAGAMENTO_RAJADA							AS	DTA_PGTO_RAJADA_AIC							

INTO	##1FUND   

FROM (	SELECT	DISTINCT 
				'VENDA AIC'										AS	MOVIMENTO, 
				CONVERT(DATE,A.DT_VENDA)						AS	DTA_VENDA,
				A.DT_VENDA										AS  DTH_VENDA,
				CONVERT(NUMERIC(20),A.COD_CPF_CNPJ)				AS	NUM_CPF_CNPJ,
				CONVERT(BIGINT,REPLACE(A.COD_PROPOSTA,'-',''))	AS	NUM_PROPOSTA,
				K.NUM_CERTIFICADO								AS  NUM_CERTIFICADO,
				A.COD_AGENCIA,
				A.COD_MATRICULA,
				CAST(P.PRODUCTNAME AS VARCHAR(50))	COLLATE SQL_LATIN1_GENERAL_CP1_CI_AS  AS  NOM_PRODUTO,
				CASE	WHEN K.NOSSO_NUMERO IS NULL THEN 'DC' ELSE 'FC' END AS	DES_FORMA_PGTO,
				NULL											AS	IND_PAGO,
				CONVERT(MONEY,ISNULL(A.IPTPREMIOVALOR,0)) / 100 AS	VLR_GERADO ,
				CONVERT(DATE,K.FECHA_DEPOSITO)					AS  DTA_PGTO_KIPREV,
				CONVERT(DATE,K.DATA_BAIXA)						AS	DTA_BAIXA_KIPREV,
				CONVERT(MONEY,K.VALOR_BAIXADO_CON)				AS	VLR_PGTO_KIPREV,
				K.NOSSO_NUMERO									AS	NOSSO_NUMERO_KIPREV	,	
				K.NUM_COBRANCA									AS	NUM_COBRANCA ,	
				K.NUM_DEPOSITO									AS	NUM_DEPOSITO,
				NULL 		DTA_PAGAMENTO_MJUNMOV,
				NULL		DTA_PAGAMENTO_RAJADA							

				-- select top 8 * 
		FROM	[SQL18\STAGING4].TDDB43.dbo.AIC_VENDA_FINALIZADA_METADADO A

		JOIN	[SQL18\STAGING4].TDDB43.DBO.PRODUCTS AS P 
		ON		A.COD_PRODUTO = P.PRODUCTID

		LEFT JOIN DMDB41..TB_KIPREV_VENDA_RECENTE K WITH(NOLOCK) 
		ON		CONVERT(BIGINT,K.NUM_PROPOSTA)	=	CONVERT(BIGINT,REPLACE(A.COD_PROPOSTA,'-',''))	 

		WHERE	CONVERT(DATE,A.DT_VENDA)		>=	'2024-11-18'
		and		CONVERT(FLOAT,A.IPTPREMIOVALOR)	>	0 
		AND		P.BusinessUnitID				IN	(3) --, 4, 7) --PREV, VIDA, PRESTAMISTA

		UNION

  		SELECT	DISTINCT 
				'VENDA
GO
 
