CREATE    procedure [dbo].[RECEBE_ATUALIZACAO_SALES_FORCE] 
(
@numero_documento varchar(20),
@type_of_customer varchar,
@Name varchar(255),
@trading_name varchar(150),
@person_birthdate varchar(30),
@Born_Datetime__c varchar(30),
@fundation_datetime varchar(30),
@person_email varchar(80),
@email varchar(80),
@phone varchar(40),
@person_mobile_phone varchar(40),
@person_home_phone  varchar(40),
@telefone_celular_empresa varchar(40),
@billing_street varchar(255),
@county varchar(80),
@billing_state	 varchar(80),
@billing_city varchar(40),
@billing_postalcode varchar(20),
@gender varchar(255),
@marital_status varchar(255),
@salary_range varchar(255),
@nationality varchar(255),
@dependents varchar(5),
@children varchar(5),
@education varchar(255),
@job_title varchar(255),
@social_level varchar(255),
@nao_perturbe_lgpd varchar(255),
@receber_ofertas_caixa_seguradora varchar(255),
@receber_ofertas_parceiros varchar(255)
)
AS

declare @cod_pessoa bigint;
declare @fone_ddd smallint;
declare @fone_num bigint;
declare @cel_ddd smallint;
declare @cel_num bigint;
declare @dependentes decimal(5,0);
declare @filhos decimal(5,0);
declare @celLimpo varchar(12);
declare @person_birthdate_d  date;
declare @Born_Datetime__c_d date;
declare @fundation_datetime_d date;


set @dependentes = (select cast(@dependents as decimal));
set @filhos =(select cast(@children as decimal));



if @trading_name ='' 
begin set @trading_name = null
end

if @fundation_datetime =''
begin set @fundation_datetime=null
end

if @salary_range =''
begin set @salary_range=null
end

if @type_of_customer =''
begin set @type_of_customer=null
end

if @phone=''
begin set @phone=null
end
	
if @telefone_celular_empresa=''
begin set @telefone_celular_empresa=null
end

set @person_birthdate_d = TRY_CAST(@person_birthdate AS date);
set @Born_Datetime__c_d = TRY_CAST(@Born_Datetime__c AS date);
set @fundation_datetime_d = TRY_CAST(@fundation_datetime AS date);



set @person_mobile_phone =(select [dbo].[ExtractNumericCharacters](@person_mobile_phone));
set @person_home_phone =(select [dbo].[ExtractNumericCharacters](@person_home_phone));
set @fone_ddd = (select left(trim(@person_home_phone),2));
set @fone_num = (select right(trim(@person_home_phone),8));

set @celLimpo = (select replace(@person_mobile_phone, '-', ''));

set @cel_ddd = (select left(trim(@person_mobile_phone),2));

set @cel_num = (select case when len(trim(@celLimpo)) = 11
				then right(trim(@celLimpo),9)
				else right(trim(@celLimpo),8)
				end as x
				);

set @cod_pessoa = (
select cod_pessoa_unificada 
from DM_CLIENTES_UNIFICADOS_CVP
where NUM_CPF_CNPJ = @numero_documento
and NOM_SEGMENTO = 'SALES FORCE'
);

begin try
--insere ou atualiza pessoa

if @cod_pessoa is not null 
begin
update DM_CLIENTES_UNIFICADOS_CVP
set NOM_SEGMENTO='SALES FORCE',
nom_pessoa=@name,
NOM_FANTASIA=@trading_name,
DTA_NASCIMENTO=@person_birthdate_d,
DTA_ABERTURA=@fundation_datetime_d,
IND_GENERO=@gender,
DES_ESTADO_CIVIL=@marital_status,
VLR_RENDA_INDIVIDUAL=@salary_range,
NACIONALIDADE=@nationality,
DEPENDENTES=@dependentes,
FILHOS=@filhos,
EDUCACAO=@education,
DES_CBO=@job_title,
CLASSE_SOCIAL=@social_level,
NAO_PERTUBE_LGPD=@nao_perturbe_lgpd,
RECEBER_OFERTAS_CAIXA=@receber_ofertas_caixa_seguradora,
RECEBER_OFERTAS_PARCEIROS=@receber_ofertas_parceiros,
DTA_ATUALIZACAO=SYSDATETIME()
WHERE COD_PESSOA_UNIFICADA=@cod_pessoa
end
else 
begin
declare @maior_cod bigint;
set @maior_cod = (select max(cod_pessoa_unificada)+1 from DM_CLIENTES_UNIFICADOS_CVP where NOM_SEGMENTO = 'SALES FORCE');
insert into DM_CLIENTES_UNIFICADOS_CVP
([COD_PESSOA_UNIFICADA],[NOM_SEGMENTO],[COD_PESSOA],[DES_PESSOA],[COD_TIPO_PESSOA],[NUM_CPF_CNPJ],[NOM_PESSOA] ,[NOM_FANTASIA],[NOM_SOCIAL],[COD_CBO]
 ,[DES_CBO] ,[COD_CNAE] ,[DES_CNAE] ,[DTA_NASCIMENTO] ,[DTA_ABERTURA] ,[NUM_IDADE] ,[VLR_RENDA_FAMILIAR] ,[VLR_RENDA_INDIVIDU
GO
 
