IF OBJECT_ID('[dbo].[SP_BUSCA_CLIENTES_AGENCIA_v3]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[SP_BUSCA_CLIENTES_AGENCIA_v3];
GO


CREATE PROCEDURE [dbo].[SP_BUSCA_CLIENTES_AGENCIA_v3]
    @CODIGO INT
AS
BEGIN

DECLARE 
    @COD_AGEN INT = NULL,
    @COD_SEV INT = NULL,
    @COD_SR INT = NULL,
    @COD_SN INT = NULL,
    @COD_VP INT = NULL;

--VP
IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_VP = @CODIGO)
BEGIN 
    SET @COD_VP = @CODIGO;
    SELECT COD_SN, NOM_SN, COUNT( NUM_CPF_CNPJ) AS CountCPF
    FROM DM_CLIENTES_UNIFICADOS_CVP c
	inner join DM_AGENCIA a
	on (c.NUM_AGENCIA_DIGITAL = a.COD_AGENCIA or
	c.NUM_AGENCIA_FISICA = a.COD_AGENCIA or
	c.NUM_AGENCIA_PRIVATE = a.COD_AGENCIA
	)
    WHERE COD_VP = @COD_VP
    GROUP BY COD_SN, NOM_SN;
END 

--SN
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SN = @CODIGO)
BEGIN 
    SET @COD_SN = @CODIGO;
    SELECT COD_SR,nom_sr, COUNT( NUM_CPF_CNPJ) AS CountCPF
    FROM DM_CLIENTES_UNIFICADOS_CVP c
	inner join DM_AGENCIA a
	on (c.NUM_AGENCIA_DIGITAL = a.COD_AGENCIA or
	c.NUM_AGENCIA_FISICA = a.COD_AGENCIA or
	c.NUM_AGENCIA_PRIVATE = a.COD_AGENCIA
	)
    WHERE COD_SN = @COD_SN
    GROUP BY COD_SR, nom_Sr;
END  

--SR
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SR = @CODIGO)
BEGIN 
    SET @COD_SR = @CODIGO;
    
    -- Verifica se todos os registros de SEV para o SR atual são -9
    IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SR = @CODIGO AND COD_SEV <> -9)
    BEGIN
        SELECT COD_SEV,NOM_SEV, COUNT( NUM_CPF_CNPJ) AS CountCPF
        FROM DM_CLIENTES_UNIFICADOS_CVP c
        inner join DM_AGENCIA a
        on (c.NUM_AGENCIA_DIGITAL = a.COD_AGENCIA or
        c.NUM_AGENCIA_FISICA = a.COD_AGENCIA or
        c.NUM_AGENCIA_PRIVATE = a.COD_AGENCIA
        )
        WHERE COD_SR = @COD_SR
        GROUP BY COD_SEV, NOM_SEV;
    END
    ELSE
    BEGIN
        -- Pula direto para a busca por AGENCIA
        SELECT COD_AGENCIA,NOM_AGENCIA, COUNT( NUM_CPF_CNPJ) AS CountCPF
        FROM DM_CLIENTES_UNIFICADOS_CVP c
        inner join DM_AGENCIA a
        on (c.NUM_AGENCIA_DIGITAL = a.COD_AGENCIA or
        c.NUM_AGENCIA_FISICA = a.COD_AGENCIA or
        c.NUM_AGENCIA_PRIVATE = a.COD_AGENCIA
        )
        WHERE COD_SR = @COD_SR
        GROUP BY COD_AGENCIA, NOM_AGENCIA;
    END
END 

--SEV
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SEV = @CODIGO)
BEGIN 
    SET @COD_SEV = @CODIGO;
    SELECT NUM_AGENCIA_FISICA AS COD_AGENCIA, NOM_AGENCIA, COUNT( NUM_CPF_CNPJ) AS CountCPF
    FROM DM_CLIENTES_UNIFICADOS_CVP c
    inner join DM_AGENCIA a
	on (c.NUM_AGENCIA_DIGITAL = a.COD_AGENCIA or
	c.NUM_AGENCIA_FISICA = a.COD_AGENCIA or
	c.NUM_AGENCIA_PRIVATE = a.COD_AGENCIA
	)
    WHERE COD_SEV = @COD_SEV
    GROUP BY NUM_AGENCIA_FISICA,NOM_AGENCIA;
END 

--AGENCIA
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_AGENCIA = @CODIGO)
BEGIN 
    SET @COD_AGEN = @CODIGO;
    SELECT NUM_CPF_CNPJ,NOM_PESSOA
    FROM DM_CLIENTES_UNIFICADOS_CVP
    WHERE NUM_AGENCIA_FISICA = @COD_AGEN OR NUM_AGENCIA_DIGITAL = @COD_AGEN OR NUM_AGENCIA_PRIVATE = @COD_AGEN;
END 
end
GO
 
IF OBJECT_ID('[dbo].[SP_BUSCA_CLIENTES_PU_VENCIDOS_VIDA]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[SP_BUSCA_CLIENTES_PU_VENCIDOS_VIDA];
GO
 
CREATE PROCEDURE [dbo].[SP_BUSCA_CLIENTES_PU_VENCIDOS_VIDA]
    @CODIGO INT
AS
BEGIN
 
DECLARE 
    @COD_AGEN INT = NULL,
    @COD_SEV INT = NULL,
    @COD_SR INT = NULL,
    @COD_SN INT = NULL,
    @COD_VP INT = NULL;
 
--VP
IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_VP = @CODIGO)
BEGIN 
    SET @COD_VP = @CODIGO;
    SELECT COD_SN, NOM_SN, COUNT(c.NumeroContrato) AS QuantidadeContratos, SUM(c.ValorPremio) AS ValorContratos
    FROM VW_CLIENTES_PU_VENCIDO_VIDA c
	inner join DM_AGENCIA a
	on (c.CodAgencia = a.COD_AGENCIA )
    WHERE COD_VP = @COD_VP
    GROUP BY COD_SN, NOM_SN;
END
 
--SN
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SN = @CODIGO)
BEGIN 
    SET @COD_SN = @CODIGO;
    SELECT COD_SR,nom_sr, COUNT(c.NumeroContrato) AS QuantidadeContratos, SUM(c.ValorPremio) AS ValorContratos
    FROM VW_CLIENTES_PU_VENCIDO_VIDA c
	inner join DM_AGENCIA a
	on (c.CodAgencia = a.COD_AGENCIA 
	)
    WHERE COD_SN = @COD_SN
    GROUP BY COD_SR, nom_Sr;
END  
 
--SR
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SR = @CODIGO)
BEGIN 
    SET @COD_SR = @CODIGO;
    -- Verifica se todos os registros de SEV para o SR atual são -9
    IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SR = @CODIGO AND COD_SEV <> -9)
    BEGIN
        SELECT COD_SEV,NOM_SEV, COUNT(c.NumeroContrato) AS QuantidadeContratos, SUM(c.ValorPremio) AS ValorContratos
        FROM VW_CLIENTES_PU_VENCIDO_VIDA c
        inner join DM_AGENCIA a
        on (c.CodAgencia = a.COD_AGENCIA 
        )
        WHERE COD_SR = @COD_SR
        GROUP BY COD_SEV, NOM_SEV;
    END
    ELSE
    BEGIN
        -- Pula direto para a busca por AGENCIA
        SELECT *
        FROM VW_CLIENTES_PU_VENCIDO_VIDA c
        --inner join DM_AGENCIA a
