CREATE PROCEDURE [dbo].[SP_BUSCA_PARCELAS_AGENCIA_v4]
    @CODIGO INT,
	@Segmento VARCHAR (50),
	@PeriodicidadePagamento char (2)= NULL,
	@FormaPagamento varchar(200) = NULL

	

AS
BEGIN

 

DECLARE 
    @COD_AGEN INT = NULL,
    @COD_SEV INT = NULL,
    @COD_SR INT = NULL,
    @COD_SN INT = NULL,
    @COD_VP INT = NULL,
	@DES_SEGMENTO VARCHAR (50) = NULL;
 

--VP
IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_VP = @CODIGO) 
BEGIN 
    SET @COD_VP = @CODIGO
	SET @DES_SEGMENTO = @Segmento
    SELECT COD_SN, NOM_SN, COUNT(numeroContrato) AS QuantidadeInadimplencia, SUM(c.valorProposta) AS ValorInadimplencia
    FROM VW_CLIENTES_INADIMPLENTES_CVP c
	inner join DM_AGENCIA a
	on (c.codAgencia = a.COD_AGENCIA)
    WHERE COD_VP = @COD_VP
	and segmento = @DES_SEGMENTO
	and formaPagamento = isnull(@FormaPagamento,formaPagamento)
	and opcaoPagamento = ISNULL(@PeriodicidadePagamento,opcaoPagamento)
    GROUP BY COD_SN, NOM_SN;
END

 

--SN
 IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SN = @CODIGO) 
BEGIN 
    SET @COD_SN = @CODIGO
	SET @DES_SEGMENTO = @Segmento
    SELECT COD_SR,nom_sr, COUNT(numeroContrato) AS QuantidadeInadimplencia, SUM(c.valorProposta) AS ValorInadimplencia
    FROM VW_CLIENTES_INADIMPLENTES_CVP c
	inner join DM_AGENCIA a
	on (c.codAgencia = a.COD_AGENCIA )
    WHERE COD_SN = @COD_SN
	and segmento = @DES_SEGMENTO
	and formaPagamento = isnull(@FormaPagamento,formaPagamento)
	and opcaoPagamento = ISNULL(@PeriodicidadePagamento,opcaoPagamento)
    GROUP BY COD_SR, nom_Sr;
END  

 

--SR
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SR = @CODIGO) 
BEGIN 
    SET @COD_SR = @CODIGO
	SET @DES_SEGMENTO = @Segmento

    -- Verifica se todos os registros de SEV para o SR atual são -9
    IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SR = @CODIGO AND COD_SEV <> -9)
    BEGIN
        SELECT COD_SEV,NOM_SEV, COUNT(numeroContrato) AS QuantidadeInadimplencia, SUM(c.valorProposta) AS ValorInadimplencia
        FROM VW_CLIENTES_INADIMPLENTES_CVP c
        inner join DM_AGENCIA a
        on (c.codAgencia = a.COD_AGENCIA)
        WHERE COD_SR = @COD_SR
		and segmento = @DES_SEGMENTO
		and formaPagamento = isnull(@FormaPagamento,formaPagamento)
		and opcaoPagamento = ISNULL(@PeriodicidadePagamento,opcaoPagamento)
        GROUP BY COD_SEV, NOM_SEV;
    END
    ELSE
    BEGIN
	SET @COD_AGEN = @CODIGO
	SET @DES_SEGMENTO = @Segmento
        -- Pula direto para a busca por AGENCIA
    SELECT c.*
    FROM VW_CLIENTES_INADIMPLENTES_CVP as c
   WHERE codAgencia = @COD_AGEN
   and segmento = @DES_SEGMENTO
   and formaPagamento = isnull(@FormaPagamento,formaPagamento)
   and opcaoPagamento = ISNULL(@PeriodicidadePagamento,opcaoPagamento)
    END
END

 

--SEV
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SEV = @CODIGO) 
BEGIN 
    SET @COD_SEV = @CODIGO
	SET @DES_SEGMENTO = @Segmento
    SELECT codAgencia AS COD_AGENCIA, NOM_AGENCIA, COUNT(numeroContrato) AS QuantidadeInadimplencia, SUM(c.valorProposta) AS ValorInadimplencia
    FROM VW_CLIENTES_INADIMPLENTES_CVP c
    inner join DM_AGENCIA a
	on (c.codAgencia = a.COD_AGENCIA )
    WHERE COD_SEV = @COD_SEV
	and segmento = @DES_SEGMENTO
	and formaPagamento = isnull(@FormaPagamento,formaPagamento)
	and opcaoPagamento = ISNULL(@PeriodicidadePagamento,opcaoPagamento)
    GROUP BY codAgencia,NOM_AGENCIA;
END

 

--AGENCIA
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_AGENCIA = @CODIGO) 
BEGIN 
    SET @COD_AGEN = @CODIGO
	SET @DES_SEGMENTO = @Segmento;
