	and segmento = @DES_SEGMENTO
	and formaPagamento = isnull(@FormaPagamento,formaPagamento)
	and opcaoPagamento = ISNULL(@PeriodicidadePagamento,opcaoPagamento)
    GROUP BY COD_SR, nom_Sr;
END  

 

--SR
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SR = @CODIGO) 
BEGIN 
    SET @COD_SR = @CODIGO
	SET @DES_SEGMENTO = @Segmento

    -- Verifica se todos os registros de SEV para o SR atual são -9
    IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SR = @CODIGO AND COD_SEV <> -9)
    BEGIN
        SELECT COD_SEV,NOM_SEV, COUNT(QtdParcelasInadimplentes) AS QuantidadeInadimplencia, SUM(c.ValorTotalInadimplencia) AS ValorInadimplencia
        FROM VW_CLIENTES_INADIMPLENTES_CVP c
        inner join DM_AGENCIA a
        on (c.codAgencia = a.COD_AGENCIA)
        WHERE COD_SR = @COD_SR
		and segmento = @DES_SEGMENTO
		and formaPagamento = isnull(@FormaPagamento,formaPagamento)
		and opcaoPagamento = ISNULL(@PeriodicidadePagamento,opcaoPagamento)
        GROUP BY COD_SEV, NOM_SEV;
    END
    ELSE
    BEGIN
	SET @COD_AGEN = @CODIGO
	SET @DES_SEGMENTO = @Segmento
        -- Pula direto para a busca por AGENCIA
    SELECT c.*
    FROM VW_CLIENTES_INADIMPLENTES_CVP as c
   WHERE codAgencia = @COD_AGEN
   and segmento = @DES_SEGMENTO
   and formaPagamento = isnull(@FormaPagamento,formaPagamento)
   and opcaoPagamento = ISNULL(@PeriodicidadePagamento,opcaoPagamento)
    END
END

 

--SEV
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SEV = @CODIGO) 
BEGIN 
    SET @COD_SEV = @CODIGO
	SET @DES_SEGMENTO = @Segmento
    SELECT codAgencia AS COD_AGENCIA, NOM_AGENCIA, COUNT(QtdParcelasInadimplentes) AS QuantidadeInadimplencia, SUM(c.ValorTotalInadimplencia) AS ValorInadimplencia
    FROM VW_CLIENTES_INADIMPLENTES_CVP c
    inner join DM_AGENCIA a
	on (c.codAgencia = a.COD_AGENCIA )
    WHERE COD_SEV = @COD_SEV
	and segmento = @DES_SEGMENTO
	and formaPagamento = isnull(@FormaPagamento,formaPagamento)
	and opcaoPagamento = ISNULL(@PeriodicidadePagamento,opcaoPagamento)
    GROUP BY codAgencia,NOM_AGENCIA;
END

 

--AGENCIA
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_AGENCIA = @CODIGO) 
BEGIN 
    SET @COD_AGEN = @CODIGO
	SET @DES_SEGMENTO = @Segmento;
    SELECT c.*
    FROM VW_CLIENTES_INADIMPLENTES_CVP as c
   WHERE codAgencia = @COD_AGEN
   and segmento = @DES_SEGMENTO
   and formaPagamento = isnull(@FormaPagamento,formaPagamento)
   and opcaoPagamento = ISNULL(@PeriodicidadePagamento,opcaoPagamento)
END 
end

GO
 
