IF OBJECT_ID('[dbo].[sp_etl_job_execution_log]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[sp_etl_job_execution_log];
GO
CREATE PROCEDURE [dbo].[sp_etl_job_execution_log]
(
 @execution_id       VARCHAR(50),
 @project            VARCHAR(100),
 @job_name           VARCHAR(200),
 @pipeline           VARCHAR(200),
 @host               VARCHAR(200),
 @start_time         VARCHAR(30),
 @end_time           VARCHAR(30),
 @duration_seconds   INT,
 @status             VARCHAR(20),
 @log_file           VARCHAR(500),
 @task_id            VARCHAR(200)
)
AS
BEGIN

SET NOCOUNT ON;

DECLARE @start_dt DATETIME2
DECLARE @end_dt   DATETIME2

------------------------------------------------
-- TRATAMENTO DE DATAS
------------------------------------------------

SET @start_dt =
    CASE
        WHEN @start_time IS NULL OR @start_time = '' THEN NULL
        ELSE CAST(@start_time AS DATETIME2)
    END

SET @end_dt =
    CASE
        WHEN @end_time IS NULL OR @end_time = '' OR @end_time = '1900-01-01 00:00:00'
        THEN NULL
        ELSE CAST(@end_time AS DATETIME2)
    END

------------------------------------------------
-- INSERT (START) OU UPDATE (END)
------------------------------------------------

IF NOT EXISTS (
    SELECT 1
    FROM dbo.etl_job_execution
    WHERE execution_id = @execution_id
      AND job_name = @job_name
      AND task_id = @task_id
)
BEGIN

    INSERT INTO dbo.etl_job_execution
    (
        execution_id,
        project,
        job_name,
        pipeline,
        host,
        start_time,
        end_time,
        duration_seconds,
        status,
        log_file,
        task_id,
        created_at,
        updated_at
    )
    VALUES
    (
        @execution_id,
        @project,
        @job_name,
        @pipeline,
        @host,
        @start_dt,
        @end_dt,
        @duration_seconds,
        @status,
        @log_file,
        @task_id,
        GETDATE(),
        GETDATE()
    )

END
ELSE
BEGIN

    UPDATE dbo.etl_job_execution
    SET
        end_time = COALESCE(@end_dt, end_time),

        duration_seconds =
            CASE
                WHEN @end_dt IS NOT NULL
                THEN DATEDIFF(SECOND, start_time, @end_dt)
                ELSE duration_seconds
            END,

        status = @status,
        log_file = @log_file,
        updated_at = GETDATE()

    WHERE execution_id = @execution_id
      AND job_name = @job_name
      AND task_id = @task_id

END

END
GO
 
IF OBJECT_ID('[dbo].[sp_etl_job_lineage_upsert]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[sp_etl_job_lineage_upsert];
GO

/* 3) sp_etl_job_lineage_upsert */
CREATE   PROCEDURE [dbo].[sp_etl_job_lineage_upsert]
(
    @pipeline_name NVARCHAR(200),
    @job_name      NVARCHAR(200),
    @direction     NVARCHAR(30), -- origem | destino | transformacao
    @object_type   NVARCHAR(20),
    @object_name   NVARCHAR(500),

    @stage_name        VARCHAR(200)   = NULL,
    @stage_type_raw    VARCHAR(100)   = NULL,
    @database_name     VARCHAR(200)   = NULL,
    @sql_expression    NVARCHAR(MAX)  = NULL,
    @file_path         VARCHAR(500)   = NULL,
    @dsx_source_file   VARCHAR(500)   = NULL,
    @extracted_at      DATETIME2      = NULL,
    @extraction_method VARCHAR(20)    = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        IF @direction NOT IN ('origem','destino','transformacao')
            RAISERROR ('direction inválido: %s', 16, 1, @direction);

        IF EXISTS (
            SELECT 1
            FROM dbo.etl_job_lineage
            WHERE pipeline_name = @pipeline_name
              AND job_name      = @job_name
              AND direction     = @direction
              AND object_name   = @object_name
        )
        BEGIN
            UPDATE dbo.etl_job_lineage
            SET
                object_type = @object_type,
                stage_name = COALESCE(@stage_name, stage_name),
                stage_type_raw = COALESCE(@stage_type_raw, stage_type_raw),
                database_name = COALESCE(@database_name, database_name),
                sql_expression = COALESCE(@sql_expression, sql_expression),
                file_path = COALESCE(@file_path, file_path),
                dsx_source_file = COALESCE(@dsx_source_file, dsx_source_file),
                extracted_at = COALESCE(@extracted_at, extracted_at),
                extraction_method = COALESCE(@extraction_method, extraction_method),
                updated_at  = SYSDATETIME()
            WHERE pipeline_name = @pipeline_name
              AND job_name      = @job_name
              AND direction     = @direction
              AND object_name   = @object_name;
        END
        ELSE
        BEGIN
            INSERT INTO dbo.etl_job_lineage
            (
                pipeline_name, job_name, direction, object_type, object_name,
                stage_name, stage_type_raw, database_name, sql_expression, file_path,
                dsx_source_file, extracted_at, extraction_method,
                created_at, updated_at
            )
            VALUES
            (
                @pipeline_name, @job_name, @direction, @object_type, @object_name,
                @stage_name, @stage_type_raw, @database_name, @sql_expression, @file_path,
                @dsx_source_file, @extracted_at, @extraction_method,
                SYSDATETIME(), SYSDATETIME()
            );
        END
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage  NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT            = ERROR_SEVERITY();
        RAISERROR (@ErrorMessage, @ErrorSeverity, 1);
    END CATCH
END
GO
 
IF OBJECT_ID('[dbo].[sp_etl_pipeline_delete]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[sp_etl_pipeline_delete];
GO

CREATE PROCEDURE dbo.sp_etl_pipeline_delete
    @pipeline_name VARCHAR(300),
    @deleted_by    VARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM dbo.etl_pipeline WHERE pipeline_name = @pipeline_name)
        THROW 50001, 'Pipeline não encontrado.', 1;

    -- Contar dependências antes de deletar (para log/auditoria)
    DECLARE
        @n_jobs     INT = 0,
        @n_lineage  INT = 0,
        @n_exec     INT = 0;

    SELECT @n_jobs    = COUNT(*) FROM dbo.etl_pipeline_job WHERE pipeline_name = @pipeline_name;
    SELECT @n_lineage = COUNT(*) FROM dbo.etl_job_lineage   WHERE pipeline_name = @pipeline_name;

    -- etl_job_execution usa coluna 'pipeline' (não 'pipeline_name')
    IF OBJECT_ID('dbo.etl_job_execution', 'U') IS NOT NULL
        SELECT @n_exec = COUNT(*)
        FROM   dbo.etl_job_execution
        WHERE  pipeline = @pipeline_name;   -- ← coluna correta

    BEGIN TRANSACTION;
    BEGIN TRY

        -- 1. Lineage
        DELETE FROM dbo.etl_job_lineage
        WHERE pipeline_name = @pipeline_name;

        -- 2. Execuções (coluna 'pipeline')
        IF OBJECT_ID('dbo.etl_job_execution', 'U') IS NOT NULL
            DELETE FROM dbo.etl_job_execution
            WHERE pipeline = @pipeline_name;   -- ← coluna correta

        -- 3. Jobs
        DELETE FROM dbo.etl_pipeline_job
        WHERE pipeline_name = @pipeline_name;

        -- 4. Staging de importação (desvincula sem deletar histórico)
        IF OBJECT_ID('dbo.etl_seq_import', 'U') IS NOT NULL
            UPDATE dbo.etl_seq_import
            SET pipeline_id = NULL
            WHERE pipeline_name_override = @pipeline_name
               OR seq_name               = @pipeline_name;

        -- 5. Pipeline principal (por último)
        DELETE FROM dbo.etl_pipeline
        WHERE pipeline_name = @pipeline_name;

        COMMIT TRANSACTION;

        PRINT 'Pipeline "' + @pipeline_name + '" removido com sucesso. ' +
              'Jobs: '     + CAST(@n_jobs    AS VARCHAR) +
              ' | Lineage: ' + CAST(@n_lineage AS VARCHAR) +
              ' | Execuções: ' + CAST(@n_exec  AS VARCHAR);

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF OBJECT_ID('dbo.etl_seq_import', 'U') IS NOT NULL
            UPDATE dbo.etl_seq_import
            SET obs = LEFT('ERRO delete (L' + CAST(ERROR_LINE() AS VARCHAR) + '): ' + ERROR_MESSAGE(), 1000)
            WHERE pipeline_name_override = @pipeline_name
               OR seq_name               = @pipeline_name;

        THROW;
    END CATCH
END;
GO
 
IF OBJECT_ID('[dbo].[sp_etl_pipeline_job_reorder]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[sp_etl_pipeline_job_reorder];
GO

/*
Objetivo:
  Atualizar SOMENTE a ordem de execução (execution_order) de um job,
  sem tocar em lineage e sem exigir origens/destinos.

Uso esperado pela UI:
  - Reordenar jobs em lote (um UPDATE por job)
*/

CREATE   PROCEDURE [dbo].[sp_etl_pipeline_job_reorder]
(
    @pipeline_name   NVARCHAR(200),
    @job_name        NVARCHAR(200),
    @execution_order INT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        IF NOT EXISTS (
            SELECT 1
            FROM dbo.etl_pipeline_job
            WHERE pipeline_name = @pipeline_name
              AND job_name      = @job_name
        )
        BEGIN
            RAISERROR('Job não encontrado para reorder (pipeline=%s, job=%s)', 16, 1, @pipeline_name, @job_name);
            RETURN;
        END

        UPDATE dbo.etl_pipeline_job
        SET
            execution_order = @execution_order,
            updated_at      = GETDATE()
        WHERE pipeline_name = @pipeline_name
          AND job_name      = @job_name;
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage  NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT            = ERROR_SEVERITY();
        RAISERROR (@ErrorMessage, @ErrorSeverity, 1);
    END CATCH
END
GO
 
IF OBJECT_ID('[dbo].[sp_etl_pipeline_job_upsert]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[sp_etl_pipeline_job_upsert];
GO
CREATE PROCEDURE [dbo].[sp_etl_pipeline_job_upsert]
(
    @pipeline_name   NVARCHAR(200),
    @job_name        NVARCHAR(200),
    @execution_order INT,
    @job_type        NVARCHAR(20),
    @job_command     NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        IF EXISTS (
            SELECT 1 FROM dbo.etl_pipeline_job
            WHERE pipeline_name = @pipeline_name AND job_name = @job_name
        )
        BEGIN
            UPDATE dbo.etl_pipeline_job
            SET
                execution_order = @execution_order,
                job_type        = @job_type,
                job_command     = @job_command,
                updated_at      = GETDATE()
            WHERE pipeline_name = @pipeline_name AND job_name = @job_name
        END
        ELSE
        BEGIN
            INSERT INTO dbo.etl_pipeline_job (
                pipeline_name, job_name, execution_order,
                job_type, job_command, created_at
            )
            VALUES (
                @pipeline_name, @job_name, @execution_order,
                @job_type, @job_command, GETDATE()
            )
        END
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT           = ERROR_SEVERITY();
        RAISERROR (@ErrorMessage, @ErrorSeverity, 1);
    END CATCH
END
GO
 
