/* 2) sp_etl_pipeline_upsert */
CREATE   PROCEDURE [dbo].[sp_etl_pipeline_upsert]
(
    @pipeline_name    NVARCHAR(200),
    @scheduled_time   TIME(0),
    @schedule_type    VARCHAR(20)    = NULL,
    @schedule_hour    TINYINT        = NULL,
    @schedule_minute  TINYINT        = NULL,
    @schedule_dow     TINYINT        = NULL,
    @schedule_dom     TINYINT        = NULL,
    @active           BIT           = 1,
    @envia_msg_inicio BIT           = 1,
    @envia_msg_fim    BIT           = 1,
    @envia_msg_erro   BIT           = 1,
    @dag_criada       BIT           = 0,
    @project_name     NVARCHAR(50),
    @domain           NVARCHAR(100),
    @tags             NVARCHAR(500) = ''
)
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM dbo.etl_pipeline WHERE pipeline_name = @pipeline_name)
    BEGIN
        UPDATE dbo.etl_pipeline
        SET
            scheduled_time   = @scheduled_time,
            schedule_type    = COALESCE(@schedule_type, schedule_type),
            schedule_hour    = COALESCE(@schedule_hour, schedule_hour),
            schedule_minute  = COALESCE(@schedule_minute, schedule_minute),
            schedule_dow     = COALESCE(@schedule_dow, schedule_dow),
            schedule_dom     = COALESCE(@schedule_dom, schedule_dom),
            active           = @active,
            ENVIA_MSG_INICIO = @envia_msg_inicio,
            ENVIA_MSG_FIM    = @envia_msg_fim,
            ENVIA_MSG_ERRO   = @envia_msg_erro,
            DAG_CRIADA       = @dag_criada,
            project_name     = @project_name,
            domain           = @domain,
            tags             = @tags,
            updated_at       = SYSDATETIME()
        WHERE pipeline_name = @pipeline_name;
    END
    ELSE
    BEGIN
        INSERT INTO dbo.etl_pipeline (
            pipeline_name, scheduled_time,
            schedule_type, schedule_hour, schedule_minute, schedule_dow, schedule_dom,
            active, last_execution, created_at, updated_at,
            ENVIA_MSG_INICIO, ENVIA_MSG_FIM, ENVIA_MSG_ERRO, DAG_CRIADA,
            project_name, domain, tags
        )
        VALUES (
            @pipeline_name, @scheduled_time,
            @schedule_type, @schedule_hour, @schedule_minute, @schedule_dow, @schedule_dom,
            @active, NULL, SYSDATETIME(), SYSDATETIME(),
            @envia_msg_inicio, @envia_msg_fim, @envia_msg_erro, @dag_criada,
            @project_name, @domain, @tags
        );
    END
END
GO
 
IF OBJECT_ID('[dbo].[sp_etl_pipelines_pendentes_criar]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[sp_etl_pipelines_pendentes_criar];
GO

/* 3) sp_etl_pipelines_pendentes_criar — inclui schedule_* */
CREATE   PROCEDURE [dbo].[sp_etl_pipelines_pendentes_criar]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        p.pipeline_name,
        p.project_name,
        p.domain,
        p.tags,
        CONVERT(VARCHAR(8), p.scheduled_time, 108) AS scheduled_time,
        p.schedule_type,
        p.schedule_hour,
        p.schedule_minute,
        p.schedule_dow,
        p.schedule_dom,
        p.ENVIA_MSG_INICIO,
        p.ENVIA_MSG_FIM,
        p.ENVIA_MSG_ERRO
    FROM dbo.etl_pipeline p
    WHERE p.DAG_CRIADA = 0
      AND p.active     = 1
    ORDER BY p.project_name, p.domain, p.pipeline_name;

    SELECT
        j.pipeline_name,
        j.job_name,
        j.execution_order,
        j.job_type,
        ISNULL(j.job_command, '') AS job_command
    FROM dbo.etl_pipeline_job j
    INNER JOIN dbo.etl_pipeline p
        ON p.pipeline_name = j.pipeline_name
    WHERE p.DAG_CRIADA = 0
      AND p.active     = 1
    ORDER BY j.pipeline_name, j.execution_order;
END
GO
 
IF OBJECT_ID('[dbo].[sp_etl_seq_import_approve]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[sp_etl_seq_import_approve];
GO

CREATE PROCEDURE dbo.sp_etl_seq_import_approve
    @import_id   INT,
    @reviewed_by VARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM dbo.etl_seq_import WHERE id = @import_id)
        THROW 50001, 'Importação não encontrada.', 1;

    IF NOT EXISTS (
        SELECT 1 FROM dbo.etl_seq_import
        WHERE id = @import_id AND status = 'pendente_aprovacao'
    )
        THROW 50002, 'A importação não está com status pendente_aprovacao.', 1;

    DECLARE
        @pipeline_name   VARCHAR(300),
        @project_name    VARCHAR(100),
        @domain          VARCHAR(100),
        @schedule_type   VARCHAR(20),
        @schedule_hour   TINYINT,
        @schedule_minute TINYINT,
        @schedule_dow    TINYINT,
        @schedule_dom    TINYINT;

    SELECT
        @pipeline_name   = COALESCE(pipeline_name_override, seq_name),
        @project_name    = project_name,
        @domain          = ISNULL(domain, ''),
        @schedule_type   = ISNULL(schedule_type,   'daily'),
        @schedule_hour   = ISNULL(schedule_hour,   6),
        @schedule_minute = ISNULL(schedule_minute, 0),
        @schedule_dow    = schedule_dow,
        @schedule_dom    = schedule_dom
    FROM dbo.etl_seq_import
    WHERE id = @import_id;

    -- Derivar @scheduled_time (HH:MM:SS) — obrigatório em sp_etl_pipeline_upsert
    DECLARE @scheduled_time VARCHAR(8);
    SET @scheduled_time =
        RIGHT('0' + CAST(@schedule_hour   AS VARCHAR(2)), 2) + ':' +
        RIGHT('0' + CAST(@schedule_minute AS VARCHAR(2)), 2) + ':00';

    BEGIN TRANSACTION;
    BEGIN TRY

        -- 1. Criar / atualizar pipeline — usando apenas os parâmetros que sp_etl_pipeline_upsert aceita
        EXEC dbo.sp_etl_pipeline_upsert
            @pipeline_name   = @pipeline_name,
            @scheduled_time  = @scheduled_time,
            @project_name    = @project_name,
            @domain          = @domain,
            @active          = 1,
            @schedule_type   = @schedule_type,
            @schedule_hour   = @schedule_hour,
            @schedule_minute = @schedule_minute,
            @schedule_dow    = @schedule_dow,
            @schedule_dom    = @schedule_dom,
            @envia_msg_inicio = 1,
            @envia_msg_fim    = 1,
            @envia_msg_erro   = 1,
            @tags             = '';

        -- 2. Inserir jobs (somente os não ignorados)
        INSERT INTO dbo.etl_pipeline_job (
            pipeline_name, job_name, execution_order, job_type, job_command,
            created_at, updated_at
        )
        SELECT
            @pipeline_name,
            j.job_name_orq,
            j.execution_order,
            j.job_type,
            j.job_command,
            GETDATE(),
            GETDATE()
        FROM dbo.etl_seq_import_job j
        WHERE j.import_id = @import_id
          AND j.status    <> 'ignorado'
        ORDER BY j.execution_order;

        -- Marcar jobs staging como aprovados
        UPDATE dbo.etl_seq_import_job
        SET status = 'aprovado'
        WHERE import_id = @import_id
          AND status    <> 'ignorado';

        -- 3. Inserir lineage
        INSERT INTO dbo.etl_job_lineage (
            pipeline_name, job_name, direction,
            object_name, object_type, stage_name, stage_type_raw,
            database_name, sql_expression, file_path,
            dsx_source_file, extracted_at, extraction_method,
            created_at, updated_at
        )
        SELECT
            @pipeline_name,
            j.job_name_orq,
            l.direction,
            l.object_name,
            l.object_type,
            l.object_name,
            l.stage_type_raw,
            l.database_name,
            l.sql_expression,
            l.file_path,
            l.dsx_source_file,
            GETDATE(),
            l.extraction_method,
            GETDATE(),
            GETDATE()
        FROM dbo.etl_seq_import_line
GO
 
