CREATE PROCEDURE [dbo].[SP_IDENTIFICA_CODIGO_HIERARQUIA_v1]
    @CODIGO INT
AS
BEGIN

DECLARE 
    @COD_AGEN INT = NULL,
    @COD_SEV INT = NULL,
    @COD_SR INT = NULL,
    @COD_SN INT = NULL,
    @COD_VP INT = NULL;

--VP
IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_VP = @CODIGO)
BEGIN 
    SET @COD_VP = @CODIGO;
    SELECT distinct 'VP' as TIPO, COD_VP, NOM_VP FROM DM_AGENCIA WHERE COD_VP = @CODIGO;
END 

--SN
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SN = @CODIGO)
BEGIN 
    SET @COD_SN = @CODIGO;
    SELECT distinct 'SN' as TIPO, COD_SN, NOM_SN FROM DM_AGENCIA WHERE COD_SN  = @CODIGO;
END  

--SR
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SR = @CODIGO)
BEGIN 
    SET @COD_SR = @CODIGO;
     SELECT distinct 'SR' as TIPO, COD_SR, NOM_SR FROM DM_AGENCIA WHERE COD_SR = @CODIGO;
   
END 

--SEV
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_SEV = @CODIGO)
BEGIN 
    SET @COD_SEV = @CODIGO;
   SELECT distinct 'SEV' as TIPO, COD_SEV, NOM_SEV FROM DM_AGENCIA WHERE COD_SEV = @CODIGO;
END 

--AGENCIA
ELSE IF EXISTS (SELECT 1 FROM DM_AGENCIA WHERE COD_AGENCIA = @CODIGO)
BEGIN 
    SET @COD_AGEN = @CODIGO;
    SELECT distinct 'AGENCIA' as TIPO, COD_AGENCIA, NOM_AGENCIA FROM DM_AGENCIA WHERE COD_AGENCIA = @CODIGO;
END 
end
GO
 
IF OBJECT_ID('[dbo].[SP_OBTER_COMUNICACAO_CPF]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[SP_OBTER_COMUNICACAO_CPF];
