  CREATE   PROCEDURE dbo.SP_OBTER_COMUNICACAO_CPF_3
    @NUM_CPF_CNPJ BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH CTE AS
    (
        SELECT 
              NUM_CPF_CNPJ
            , DTH_ATUALIZACAO AS PROCESSAMENTO
            , NUM_CONTRATO
            , '' AS COD_PRODUTO
            , COD_FORMULARIO
            , DES_ASSUNTO_EMAIL
            , ULTIMO_STATUS = (
                  SELECT MAX(dt)
                  FROM (VALUES (DTH_ENVIO), 
                               (DTH_ABERTURA), 
                               (DTH_CLIQUE), 
                               (DTH_BOUNCE)) AS AllDates(dt)
              )
            , ROW_NUMBER() OVER (
                  PARTITION BY NUM_CPF_CNPJ, NUM_CONTRATO
                  ORDER BY DTH_ATUALIZACAO DESC
              ) AS RN
        FROM DMDB41.dbo.DM_SF_MKT_CLOUD_COMUNICACAO
        WHERE NUM_CPF_CNPJ = @NUM_CPF_CNPJ
    )
    SELECT 
          NUM_CPF_CNPJ
        , PROCESSAMENTO
        , NUM_CONTRATO
        , '' AS COD_PRODUTO
        , COD_FORMULARIO
        , DES_ASSUNTO_EMAIL
        , ULTIMO_STATUS
    FROM CTE
    WHERE RN = 1   -- Mais recente de cada contrato
    ORDER BY PROCESSAMENTO DESC;
END;
GO
 
