CREATE PROCEDURE [dbo].[SP_RECEBE_ATUALIZACAO_APP]
(
    @numero_documento VARCHAR(20),
    @email VARCHAR(80) = NULL,
    @telefone VARCHAR(40) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @cod_pessoa BIGINT;
    DECLARE @ddd SMALLINT;
    DECLARE @numero BIGINT;
    DECLARE @telefone_limpo VARCHAR(20);
    DECLARE @tipo_telefone TINYINT;
    DECLARE @email_anterior VARCHAR(80);
    DECLARE @telefone_anterior VARCHAR(20);

    -- Limpa telefone
    SET @telefone_limpo = (SELECT dbo.ExtractNumericCharacters(@telefone));

    IF LEN(@telefone_limpo) >= 10
    BEGIN
        SET @ddd = LEFT(@telefone_limpo, 2);
        SET @numero = RIGHT(@telefone_limpo, LEN(@telefone_limpo) - 2);
        SET @tipo_telefone = CASE 
                                WHEN LEN(@numero) = 9 THEN 2 
                                ELSE 1 
                             END;
    END

    -- Busca cod_pessoa
    SET @cod_pessoa = (
        SELECT DISTINCT cod_pessoa_unificada
        FROM DM_CLIENTES_UNIFICADOS_CVP
        WHERE NUM_CPF_CNPJ = @numero_documento
    );

    IF @cod_pessoa IS NULL
    BEGIN
        SELECT '1' AS CODIGO, 'Pessoa não encontrada' AS MENSAGEM;
        RETURN;
    END

    -- Coleta valores anteriores para log
    SET @email_anterior = (
        SELECT TOP 1 DES_EMAIL
        FROM DM_CLIENTES_EMAIL_CVP
        WHERE COD_PESSOA_UNIFICADA = @cod_pessoa
          AND SEQ_EMAIL = 100
    );

    SET @telefone_anterior = (
        SELECT TOP 1 CAST(NUM_DDD_TELEFONE AS VARCHAR) + CAST(NUM_TELEFONE AS VARCHAR)
        FROM DM_CLIENTES_TELEFONE_CVP
        WHERE COD_PESSOA_UNIFICADA = @cod_pessoa
          AND SEQ_TELEFONE = 100
          AND TIPO_TELEFONE = @tipo_telefone
    );

    BEGIN TRY
        -- Atualiza ou insere e-mail
        IF @email IS NOT NULL
        BEGIN
            IF EXISTS (
                SELECT 1 FROM DM_CLIENTES_EMAIL_CVP
                WHERE COD_PESSOA_UNIFICADA = @cod_pessoa AND SEQ_EMAIL = 100
            )
            BEGIN
                UPDATE DM_CLIENTES_EMAIL_CVP
                SET DES_EMAIL = @email,
                    DTA_ATUALIZACAO = SYSDATETIME()
                WHERE COD_PESSOA_UNIFICADA = @cod_pessoa AND SEQ_EMAIL = 100;
            END
            ELSE
            BEGIN
                INSERT INTO DM_CLIENTES_EMAIL_CVP
                ([COD_PESSOA_UNIFICADA], [SEQ_EMAIL], [NOM_SEGMENTO], [DES_EMAIL], [DTA_ATUALIZACAO], [DTA_INSERCAO], [DTA_INICIO_VIGENCIA])
                VALUES
                (@cod_pessoa, 100, 'AUTOATENDIMENTO', @email, SYSDATETIME(), SYSDATETIME(), SYSDATETIME());
            END
        END

        -- Atualiza ou insere telefone
        IF @telefone IS NOT NULL AND @numero > 9999
        BEGIN
            IF EXISTS (
                SELECT 1 FROM DM_CLIENTES_TELEFONE_CVP
                WHERE COD_PESSOA_UNIFICADA = @cod_pessoa AND SEQ_TELEFONE = 100 AND TIPO_TELEFONE = @tipo_telefone
            )
            BEGIN
                UPDATE DM_CLIENTES_TELEFONE_CVP
                SET NUM_DDD_TELEFONE = @ddd,
                    NUM_TELEFONE = @numero,
                    DTA_ATUALIZACAO = SYSDATETIME()
                WHERE COD_PESSOA_UNIFICADA = @cod_pessoa 
                  AND SEQ_TELEFONE = 100 
                  AND TIPO_TELEFONE = @tipo_telefone;
            END
            ELSE
            BEGIN
                INSERT INTO DM_CLIENTES_TELEFONE_CVP
                ([COD_PESSOA_UNIFICADA], [TIPO_TELEFONE], [NOM_SEGMENTO], [NUM_DDD_TELEFONE], [NUM_TELEFONE], [DTA_ATUALIZACAO], [DTA_INSERCAO], [DTA_INICIO_VIGENCIA], [SEQ_TELEFONE])
                VALUES
                (@cod_pessoa, @tipo_telefone, 'AUTOATENDIMENTO', @ddd, @numero, SYSDATETIME(), SYSDATETIME(), SYSDATETIME(), 100);
            END
        END

        -- Insere na DM_LOG_SALESFORCE
        INSERT INTO DM_LOG_SALESFORCE
        (
            NOM_SEGMENTO,
            COD_PESSOA,
GO
 
IF OBJECT_ID('[dbo].[usp_ReplicarTabelasPLD_SQL69]', 'P') IS NOT NULL DROP PROCEDURE [dbo].[usp_ReplicarTabelasPLD_SQL69];
GO

-- ================================================================
--  PARTE 1 â€” Criar procedure de replicaÃ§Ã£o
-- ================================================================
CREATE   PROCEDURE dbo.usp_ReplicarTabelasPLD_SQL69
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @inicio DATETIME2 = GETDATE();
    DECLARE @msg    VARCHAR(200);

    -- ============================================================
    --  TB_ALERTAS_PLD_FAT
    --  HistÃ³rico de alertas COAF â€” usada nos critÃ©rios 04 e 06
    -- ============================================================
    IF OBJECT_ID('dbo.TB_ALERTAS_PLD_FAT_LOCAL', 'U') IS NOT NULL
        DROP TABLE dbo.TB_ALERTAS_PLD_FAT_LOCAL;

    SELECT *
    INTO dbo.TB_ALERTAS_PLD_FAT_LOCAL
    FROM OPENQUERY([SQL69\BUCC], 'SELECT * FROM PORTAL_IA.dbo.TB_ALERTAS_PLD_FAT');

    DECLARE @qtd_alertas INT = @@ROWCOUNT;

    CREATE INDEX IX_ALERTAS_PLD_CPF
        ON dbo.TB_ALERTAS_PLD_FAT_LOCAL (CPF_CNPJ);

    CREATE INDEX IX_ALERTAS_PLD_IDT
        ON dbo.TB_ALERTAS_PLD_FAT_LOCAL (IDT_DM_COAF_CVP);

    SET @msg = CONCAT('TB_ALERTAS_PLD_FAT_LOCAL: ', @qtd_alertas, ' linhas â€” OK');
    RAISERROR(@msg, 0, 1) WITH NOWAIT;

    -- ============================================================
    --  TB_MOTOR_PLD_FAT
    --  Resultado do motor de IA (STA_ALERTA) â€” usada no critÃ©rio 04
    -- ============================================================
    IF OBJECT_ID('dbo.TB_MOTOR_PLD_FAT_LOCAL', 'U') IS NOT NULL
        DROP TABLE dbo.TB_MOTOR_PLD_FAT_LOCAL;

    SELECT *
    INTO dbo.TB_MOTOR_PLD_FAT_LOCAL
    FROM OPENQUERY([SQL69\BUCC], 'SELECT * FROM PORTAL_IA.dbo.TB_MOTOR_PLD_FAT');

    DECLARE @qtd_motor INT = @@ROWCOUNT;

    CREATE INDEX IX_MOTOR_PLD_IDT
        ON dbo.TB_MOTOR_PLD_FAT_LOCAL (IDT_DM_COAF_CVP);

    CREATE INDEX IX_MOTOR_PLD_STA
        ON dbo.TB_MOTOR_PLD_FAT_LOCAL (STA_ALERTA);

    SET @msg = CONCAT('TB_MOTOR_PLD_FAT_LOCAL: ', @qtd_motor, ' linhas â€” OK');
    RAISERROR(@msg, 0, 1) WITH NOWAIT;

    -- ============================================================
    --  TB_CIDADE_FRONTEIRA_DIM
    --  DimensÃ£o de cidades fronteiricas â€” usada no critÃ©rio 03
    -- ============================================================
    IF OBJECT_ID('dbo.TB_CIDADE_FRONTEIRA_DIM_LOCAL', 'U') IS NOT NULL
        DROP TABLE dbo.TB_CIDADE_FRONTEIRA_DIM_LOCAL;

    -- NOM_CIDADE e SGL_UF chegam como nvarchar(MAX) com collation Latin1_General_CI_AS
    -- do SQL69 â€” convertidos para varchar com collation do banco local (SQL_Latin1_General_CP1_CI_AS)
    -- para permitir indexaÃ§Ã£o e eliminar conflito de collation nas queries da proc principal.
    SELECT
        IDT_CIDADE_FRONTEIRA,
        CAST(NOM_CIDADE AS VARCHAR(200)) COLLATE SQL_Latin1_General_CP1_CI_AS AS NOM_CIDADE,
        CAST(SGL_UF     AS VARCHAR(2))   COLLATE SQL_Latin1_General_CP1_CI_AS AS SGL_UF,
        IND_FRONTEIRA,
        IND_BIFRONTEIRA,
        IND_MINERADORA
    INTO dbo.TB_CIDADE_FRONTEIRA_DIM_LOCAL
    FROM OPENQUERY([SQL69\BUCC], 'SELECT * FROM PORTAL_IA.dbo.TB_CIDADE_FRONTEIRA_DIM');

    DECLARE @qtd_cidade INT = @@ROWCOUNT;

    CREATE INDEX IX_CIDADE_FRONT_NOM
        ON dbo.TB_CIDADE_FRONTEIRA_DIM_LOCAL (NOM_CIDADE, SGL_UF);

    SET @msg = CONCAT('TB_CIDADE_FRONTEIRA_DIM_LOCAL: ', @qtd_cidade, ' linhas â€” OK');
    RAISERROR(@msg, 0, 1) WITH NOWAIT;

    -- ============================================================
    --  TB_PROFISSAO_RISCO_DIM
    --  CBOs de risco â€” usada no critÃ©rio 10 (ativo quando COD_CBO
    --  for incluÃ­do no feed de alertas do Adriel)
    -- ============================================================
    IF OBJECT_ID('dbo.TB_PROFISSAO_RISCO_DIM_LOCAL', 'U') IS NOT NULL
        DROP TABLE dbo.TB_PROFISSAO_RISCO_DIM_LOCAL;

    SELECT *
    INTO dbo.TB_PROFISSAO_RISCO_DIM_LOCAL
    FROM OPENQUERY([SQL69\BUCC], 'SELECT * FROM PORTAL_IA.dbo.TB_PROFISSAO_RISCO_DIM');

    DECLARE @qtd_profissao INT = @@ROWCOUNT;

    CREATE INDEX IX_PROFISSAO_CBO
      
GO
 
 
