IF OBJECT_ID('[dbo].[_VW_CLIENTES_EMAIL_TELEFONE_CVP]', 'V') IS NOT NULL DROP VIEW [dbo].[_VW_CLIENTES_EMAIL_TELEFONE_CVP];
