CREATE VIEW _VW_CLIENTES_EMAIL_TELEFONE_CVP as 

SELECT C.NOM_PESSOA, E.DES_EMAIL, t.NUM_DDD_TELEFONE ,T.NUM_TELEFONE 
from [dbo].DM_CLIENTES_UNIFICADOS_CVP C 

left join [dbo].[DM_CLIENTES_EMAIL_CVP] E 
on C.COD_PESSOA_UNIFICADA = E.COD_PESSOA_UNIFICADA 
and E.SEQ_EMAIL = (SELECT MAX(SEQ_EMAIL) 
					FROM [DM_CLIENTES_EMAIL_CVP] 
					where COD_PESSOA_UNIFICADA = C.COD_PESSOA_UNIFICADA)
						
left join [dbo].[DM_CLIENTES_TELEFONE_CVP] T 
on C.COD_PESSOA_UNIFICADA = T.COD_PESSOA_UNIFICADA 
and T.SEQ_TELEFONE = (SELECT MAX(SEQ_TELEFONE) 
					  FROM [DM_CLIENTES_TELEFONE_CVP] 
					  where COD_PESSOA_UNIFICADA = C.COD_PESSOA_UNIFICADA 
					  and TIPO_TELEFONE=2)
and t.TIPO_TELEFONE=2
GO
 
IF OBJECT_ID('[dbo].[VW_ACOPLADOS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_ACOPLADOS];
GO


CREATE VIEW [dbo].[VW_ACOPLADOS] as (
select 
	c.NUM_CERTIFICADO as numContrato,
	c.COD_PRODUTO as codigoProduto,
	p.DES_PRODUTO as nomeProduto,
	null as dataInicioVigencia,
	null as dataFimVigencia,
	null as numSorte
from 
 DM_CLIENTES_UNIFICADOS_CVP a WITH (NOLOCK)
 inner join DM_CLIENTES_ENDERECO_CVP e WITH (NOLOCK)
 on a.COD_PESSOA_UNIFICADA = e.COD_PESSOA_UNIFICADA
 and e.SEQ_ENDERECO = (select max(SEQ_ENDERECO) 
						from DM_CLIENTES_ENDERECO_CVP 
						where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)


 inner join DM_CLIENTES_CONTRATOS_CVP b WITH (NOLOCK)
 on a.NUM_CPF_CNPJ=b.NUM_CPF_CNPJ
 inner join DM_CONTRATOS_CVP c WITH (NOLOCK)
 on b.NOM_SEGMENTO = c.NOM_SEGMENTO
 and b.NUM_CERTIFICADO = c.NUM_CERTIFICADO
 inner join VW_PRODUTOS_CVP p WITH (NOLOCK)
 on c.COD_PRODUTO = p.COD_PRODUTO
 and c.NOM_SEGMENTO = p.DES_SEGMENTO
 )
GO
 
