GO







CREATE VIEW [dbo].[VW_APORTE_PREV] AS

------------------------------------------------------------------------------------------
--		PROCEDURE VW_APORTE_PREV
------------------------------------------------------------------------------------------
--
--		Objetivo :	Recupera somente os aportes recentes via tabela gerada pelo 
--					DataStage
--		
------------------------------------------------------------------------------------------
--		24/09/2024	Jr® / Ítalo Naves / Walmir Oliveira		:	V1	-	INCLUSÃO DO CPF		
------------------------------------------------------------------------------------------

SELECT DISTINCT
       CAST(A.DTA_EMISSAO AS DATE) AS DTA_APORTE,
       A.NUM_CPF_CNPJ,
	   A.NUM_CERTIFICADO,
	   A.NOSSO_NUMERO,
	   A.NUM_BOLETO,
	   A.NUM_PROPOSTA,
	   A.NOM_CANAL,
	   A.NUM_SOLICITACAO,
	   A.DTA_PAGAMENTO,
	   A.DTA_BAIXA,
	   A.STA_COBRANCA,
	   SC.DES_SIT_COBRANCA AS DES_SIT_COBRANCA,
       CASE WHEN A.STA_COBRANCA = 'BT' THEN 'S' ELSE 'N' END AS IND_PAGO_KIPREV,
	   CASE	WHEN S.NUM_PROPOSTA IS NULL  then  'N' ELSE 'S' END AS IND_PAGO_SAP,
	   CAST(A.COD_AGENCIA_VENDA AS SMALLINT) AS COD_AGENCIA,
	   A.COD_MATRICULA AS MATRICULA_INDICADOR,
	   IsNull(E.NOM_FUNC, E2.NOM_FUNC) AS NOM_INDICADOR,
	   CAST(IsNull(E.COD_UNIDADE, E2.COD_UNIDADE) AS SMALLINT) AS COD_AGENCIA_INDICADOR,
       A.VLR_APORTE AS VLR_GERADO_KIPREV,
	   CASE WHEN A.STA_COBRANCA = 'BT' THEN A.VLR_APORTE ELSE 0 END AS VLR_PAGO_KIPREV,
	   IsNull(S.VLR_MOVIMENTO,0) AS VLR_SAP	  -- SELECT TOP 8 *  ,

	   ,CASE	WHEN	 A.NUM_BOLETO IS NOT NULL then 'Ficha de Compensação'	ELSE 'Débito em Conta' END DES_FORMA_PGTO                               




FROM TB_KIPREV_APORTE_RECENTE A WITH(NOLOCK)

LEFT JOIN DM_SAP_PAGAMENTO_BAIXADO S WITH(NOLOCK) ON S.NUM_PROPOSTA = A.NUM_PROPOSTA
                                                 AND S.VLR_MOVIMENTO = A.VLR_APORTE
                                                 AND S.DTA_PAGAMENTO >= A.DTA_EMISSAO
LEFT JOIN DM_ECONOMIARIO E WITH(NOLOCK) ON E.MATR_FUNC = A.COD_MATRICULA
                          AND E.SEQ_REGISTRO = (SELECT MAX(E2.SEQ_REGISTRO) FROM DM_ECONOMIARIO E2 WITH(NOLOCK) WHERE E.MATR_FUNC = E2.MATR_FUNC AND E2.SIT_FUNC = '1')
LEFT JOIN DM_ECONOMIARIO E2 WITH(NOLOCK) ON CONCAT(E2.MATR_FUNC,E2.DV_MATR_FUNC) = A.COD_MATRICULA
                          AND E2.SEQ_REGISTRO = (SELECT MAX(E3.SEQ_REGISTRO) FROM DM_ECONOMIARIO E3 WITH(NOLOCK) WHERE E2.MATR_FUNC = E3.MATR_FUNC AND E3.SIT_FUNC = '1')
LEFT JOIN DMDB11..DM_029_SIT_COBRANCA SC WITH(NOLOCK) ON SC.COD_SIT_COBRANCA = A.STA_COBRANCA
WHERE STA_COBRANCA <> 'CC'
GO
 
