CREATE VIEW [dbo].[VW_BENEFICIARIOS] as (
select
	b.NUM_CERTIFICADO as numContrato,
  case when a.NOM_SOCIAL is NOT null then a.NOM_SOCIAL
		else a.NOM_PESSOA end as nomBeneficiario,
	a.NUM_CPF_CNPJ as  numCpfBeneficiario,
	a.DTA_NASCIMENTO as dataHoraNascimentoBeneficiario,
	null as desGrauParentesco,
	null as percentualPartBeneficio,
	null  as beneficiarioAtual
 from 
 DM_CLIENTES_UNIFICADOS_CVP a WITH (NOLOCK)
 inner join DM_CLIENTES_CONTRATOS_CVP b WITH (NOLOCK)
 on a.NUM_CPF_CNPJ=b.NUM_CPF_CNPJ
Where b.DES_PESSOA = 'BENEFICIARIO'
)
GO
 
