 CREATE VIEW [dbo].[VW_BUCC_COE] as (

-- DATA CRIAÇÃO: 09/08/2024
-- AUTOR: ALEXANDRE MANZO
-- FINALIDADE: DISPONIBILIZAR INFORMAÇÕES PARA OS SISTEMA COE
-- CLIENTE RESPONSAVEL: Adriano Marcelo Soares

select  DISTINCT 
		c.NUM_CERTIFICADO as numContrato,
		cast (case  c.NOM_SEGMENTO 
		when 'VIDA' then 'SIAS'
		when 'PREVIDENCIA' then 'KIPREV'
		when 'PRESTAMISTA' then 'SMART' end as varchar (10)) as sistema,--num contrato é sempre o certificiado
		NULL as id,
		cast (Case 
		when c.NOM_SEGMENTO  = 'VIDA' and p.DES_TIPO_SEGMENTO = 'Bilhete + Microsseguro' then 5
		when c.NOM_SEGMENTO =  'VIDA' and p.DES_TIPO_SEGMENTO <> 'Bilhete + Microsseguro' then 1
		when c.NOM_SEGMENTO  = 'PREVIDENCIA' then 11
		when c.NOM_SEGMENTO  = 'PRESTAMISTA' then 3 
		end as varchar (20)
		) as indContrato,
		NULL as indVinculoPrincipal,
		NULL as numRamoEmissor,
		c.NUM_APOLICE as numApolice,
		c.NUM_PROPOSTA as numProposta,
		p.COD_PRODUTO as codProduto,
		case when c.NUM_CERTIFICADO = 82484130001541 then 'CONTRATO_TESTE' else null end as nomePlano,
		case when c.NUM_CERTIFICADO = 82484130001541 then 1 else null end as numAssistencia,
		p.COD_PRODUTO as codProdutoBu,
		p.DES_PRODUTO as nomeProdutoBu,
		case  c.NOM_SEGMENTO 
		when 'VIDA' then 'SIAS'
		when 'PREVIDENCIA' then 'KIPREV'
		when 'PRESTAMISTA' then 'SMART' end as nomeBu,
		concat(b.num_ddd_telefone,b.NUM_TELEFONE) as numTelefone1,
		concat(b.num_ddd_celular,b.NUM_CELULAR) as numTelefone2,
		c.NOM_SEGMENTO as segmento,
		a.NUM_CPF_CNPJ as codCpfCnpj,
		'Contrato' as tipoContrato,
		c.COD_AGENCIA as codAgenciaVenda,
		c.COD_AGENCIA_COBRANCA as codAgenciaCobranca,
		c.DES_CANAL_VENDA as canalVenda,
		case when c.COD_STATUS_CONTRATO = 'A' Then 'Ativo'
		when c.COD_STATUS_CONTRATO = 'I' Then 'Inativo' end as situacaoContrato,
		c.DTA_EMISSAO_PROPOSTA as dataHoraEmissaoProposta,
		c.DTA_EMISSAO_CONTRATO as dataHoraEmissaoContrato,
		p.DES_PRODUTO as nomeProduto,
		c.IND_PERIODICIDADE_COBRANCA as opcaoPagamento,
		c.DES_FORMA_PAGAMENTO as formaPagamento,
		NULL as numParcContratadas,
		NULL as numMatriVendedor,
		NULL as valorIof,
		c.DTA_QUITACAO as dataHoraQuitacao,
		c.DTA_CANCELAMENTO as dataHoraCancelamento,
		NULL as dataHoraDeclinio,
		c.DTA_ASSINATURA as dataHoraAssinatura,
		c.DTA_AVERBACAO as dataHoraAverbacao,
		c.dta_assinatura as dataHoraEfetivacao,
		NULL as dataHoraIniAmortiz,
		NULL as dataHoraRejeicaoProp,
		c.dth_carga_atualizacao as dataHoraAtualizacao,
		c.dth_carga as dataHoraReferencia,
		NULL as dthFechamento,
		case when c.NUM_CERTIFICADO = 82484130001541 then '10/04/2023' else null end as dthAbertura,
		c.DTA_INICIO_VIGENCIA as dataHoraIniVigencia,
		c.DTA_FIM_VIGENCIA as dataHoraFimVigencia,
		NULL as valorBem,
		c.VLR_IS as valorImpSegurada,
		c.DTA_VENDA as dataHoraVenda,
		NULL as itemSegurado,
		c.VLR_PREMIO as valorProposta,
		NULL as valorFranquia,
		c.VLR_PREMIO  as valorPremioBruto,
		CAST(NULL AS VARCHAR(10)) as staContratoLegado,
		NULL as numUltimosDigCartao,
		NULL as dataHoraValidadeCartao,
		NULL as nomeBancoCobranca,
		cc.num_Conta as numContaCobranca,
		NULL as numDiaVencimento,
		NULL as numeroIdlgBu,
		NULL as nomeTitularCartao,
		NULL as desBandeiraCartao,
		cc.cod_Operacao as codOperContaCobranca,
		NULL as valorPrimeiraParc,
		NULL as dataHoraPrimeiraParc,
		NULL as indContratoRenovado,
		NULL as codClasseBonus,
		tit.NOM_PESSOA as nomeTitular,
		tit.NOM_PESSOA  as nomeContato,
		null as prazoComercializacao,
		null as numBilhete,
		null as numItem,
		null as numEndosso,
		c.NUM_CERTIFICADO as numCertificado,
		null as numRisco,
		null as numContratoTerc,
		null as numPlano,
		null as numSerie,
		null as numTitulo,
		null as numModPlano,
		null as codGrupo,
		null as codCota,
		null as numVersao,
		null as numContratoVinc,
		null as codSubgrupo,
		null as numApoliceAnt,
		null as numCertificadoAnt,
		null as numBilheteAnt,
		nu
GO
 
