 create VIEW VW_BUCC_CONTATOS AS 

-- Consulta acesso app
-------------------------------------------------
SELECT	--top 100
		'APP' AS DES_ORIGEM,
		[COD_USUARIO] as NUM_USUARIO_CPF_CNPJ,
		[DTA_ACESSO] AS DTA_ACESSO_ENVIO,
		NULL AS DES_ASSUNTO,
		[DES_OPERACAO] AS DES_OPERACAO,
		NULL AS DES_RESULTADO

FROM	TB_BUCC_ACESSO_APP WITH (NOLOCK)
where	[COD_USUARIO] <> 'AIC'

union all

-- Consulta envios CCM
-------------------------------------------------
SELECT	--top 100 
		'CCM' AS DES_ORIGEM,
		CAST(NUM_CPF_CNPJ AS VARCHAR(14)) as NUM_USUARIO_CPF_CNPJ,
		CAST(DTH_ENVIO AS DATE) AS DTA_ACESSO_ENVIO,
		DES_ASSUNTO AS DES_ASSUNTO,
		DES_SERVICO AS DES_OPERACAO,
		---CASE WHEN DES_TP_OBJ_TRATAMENTO IN ('Entregue','Enviado','Processado','Respondido','SMS Enviado') Then 'S' ELSE 'Entregue'END 
		DES_TP_OBJ_TRATAMENTO AS DES_RESULTADO

FROM	DM_CCM_FOLHETERIA  WITH (NOLOCK)

union all

-- Consulta atendimentos Sales Force
-------------------------------------------------
SELECT	--top 100
		'SALES FORCE' AS DES_ORIGEM,
		CAST(NUM_CPF_CNPJ AS VARCHAR(14)) as NUM_USUARIO_CPF_CNPJ,
		CAST(DTH_ABERTURA AS DATE) DTA_ACESSO_ENVIO,
		DES_CATEGORIA_P1 AS DES_ASSUNTO,
		DES_CATEGORIA_P1 AS DES_OPERACAO,
		DES_RESULTADO AS DES_RESULTADO

FROM	DM_SALESFORCE_ATENDIMENTO WITH (NOLOCK) 
WHERE	NUM_CPF_CNPJ IS NOT NULL
		AND DES_CATEGORIA_P1 IS NOT NULL

GO
 
