CREATE VIEW [dbo].[VW_BUCC_CONTRATO_PESSOA_HML] AS 
(
select	distinct
 
		-- DADOS CERTIFICADO
		S.NOM_SEGMENTO,
		C.NUM_CERTIFICADO,
		 p.COD_TIPO_PESSOA,
		 c.NUM_CONTRATO_CREDITO,
		C.DTA_EMISSAO_CONTRATO,
		c.COD_STATUS_CONTRATO,
		C.DTA_INICIO_VIGENCIA,
		C.DTA_FIM_VIGENCIA,
		A.COD_AGENCIA,
		A.NOM_AGENCIA,
		PR.COD_PRODUTO,
		PR.NOM_PRODUTO,
		----Apolice Especifica
		----
		-- DADOS PESSOA
		pp.NOM_PAPEL_PESSOA,
		P.COD_CPF_CNPJ,
		P.NOM_PESSOA,
		P.NOM_PRIMEIRO_NOME,
		P.DTA_NASCIMENTO,
		P.COD_SEXO

 
from	dmdb44.[dbo].[DM_BUCC_CONTRATO_PESSOA] CP
 
		join dmdb44.[dbo].[DM_BUCC_PESSOA] P
			on P.SUK_PESSOA = CP.SUK_PESSOA
 
		join dmdb44.[dbo].DM_BUCC_CONTRATO as C
			on C.SUK_CONTRATO = CP.SUK_CONTRATO
 
		join dmdb44.[dbo].DM_BUCC_ORIGEM_INFORMACAO as OI
			on OI.SUK_ORIGEM_INFORMACAO = P.SUK_ORIGEM_INFORMACAO
 
		join dmdb44.[dbo].DM_BUCC_PAPEL_PESSOA as PP
			on PP.SUK_PAPEL_PESSOA = CP.SUK_PAPEL_PESSOA
 
		join dmdb44.[dbo].DM_BUCC_AGENCIA as A
			on A.SUK_AGENCIA = C.SUK_AGENCIA
 
		join dmdb44.[dbo].DM_BUCC_SEGMENTO S
			on S.SUK_SEGMENTO = C.SUK_SEGMENTO
 
		join dmdb44.[dbo].DM_BUCC_PRODUTO PR
			on PR.SUK_PRODUTO = C.SUK_PRODUTO
)

GO
 
IF OBJECT_ID('[dbo].[VW_BUCC_CONTRATOS_TITULARES]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_BUCC_CONTRATOS_TITULARES];
