CREATE view [dbo].[VW_BUCC_CONTRATOS_TITULARES] as

Select

	C.NOM_SEGMENTO,
	CL.DES_PESSOA,

	-- DADOS CLIENTE
	---------------------------
	CL.NOM_PESSOA,
	CL.NUM_CPF_CNPJ,
	--CL.COD_TIPO_PESSOA,
	CL.DTA_NASCIMENTO,
	case	when CL.NUM_TELEFONE = -8 or CL.NUM_DDD_TELEFONE = -8 then null
			when CL.NUM_TELEFONE  is null or CL.NUM_DDD_TELEFONE is null then null
			else CONCAT(CL.NUM_DDD_TELEFONE,'-',CL.NUM_TELEFONE) 
	end AS NUM_TELEFONE,

	case	when CL.NUM_CELULAR = -8 or CL.NUM_DDD_CELULAR = -8 then null 
			when CL.NUM_CELULAR is null or CL.NUM_DDD_CELULAR is null then null
			else concat(CL.NUM_DDD_CELULAR,'-',CL.NUM_CELULAR)
	end AS NUM_CELULAR,

	upper(CL.DES_EMAIL) as DES_EMAIL,
	CL.COD_UF,
	upper(CL.NOM_CIDADE) as NOM_CIDADE,

	-- DADOS CONTRATO
	---------------------------
	C.NUM_CERTIFICADO,
	C.COD_PRODUTO,
	C.DTA_EMISSAO_CONTRATO,
	C.DTA_INICIO_VIGENCIA,
	c.DTA_FIM_VIGENCIA,
	VLR_IS,
	C.VLR_PMBAC + VLR_PMBAC_EMP as VLR_RESERVA,
	c.VLR_PREMIO,
	CASE WHEN c.COD_STATUS_CONTRATO = 'A' then 'ATIVO' ELSE 'INATIVO' END AS DES_SITUACAO_CONTRATO,
	P.nom_produto
 
from
	DM_CLIENTES_CONTRATOS_CVP as CL
		left join DM_CONTRATOS_CVP as C
			on CL.NOM_SEGMENTO = C.NOM_SEGMENTO 
			and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO
		left join [VW_PRODUTO_SIMPLIFICADA] as P
			on P.cod_produto = C.cod_produto

where	CL.COD_PESSOA in (1,2,3)
		and CL.ind_Carga <> 'D'
GO
 
