CREATE VIEW [dbo].[VW_BUSCAR_PESSOAS] as (
 select distinct
 trim(cast(null as varchar(20))) as 'indContrato',
 a.NUM_CPF_CNPJ  as  'codCpfCnpj',
 trim(cast(null as varchar(20))) as sistema,
 trim(em.DES_EMAIL) as 'email',
 --trim(cast(tel.TIPO_TELEFONE as varchar(3))) 
 'TELEFONIA CELULAR' as 'tipoTelefone',
 trim(cast(tel.NUM_TELEFONE as varchar(10))) as 'telefone',
 trim(e.NOM_LOGRADOURO) as 'endereco',
 trim(e.NOM_BAIRRO) as 'bairro',
 trim(e.COD_UF) as 'uf',
 REPLACE(REPLACE(TRIM(e.NOM_CIDADE), CHAR(13), ''), CHAR(10), '') as 'cidade',
 trim(cast(e.COD_CEP as varchar(20))) as 'cep',
 case when a.NOM_SOCIAL is null then a.NOM_PESSOA
		else a.NOM_PESSOA end as 'nomePessoa',
 Case When a.COD_TIPO_PESSOA = 'F'THEN 'PESSOA FISICA' 
		When a.COD_TIPO_PESSOA = 'J'THEN 'PESSOA JURIDICA' END as 'tipoPessoa',
 null as 'indVinculoPrincipal',
 null as nomeBancoCobranca,
 null as codAgenciaCobranca,
 null  as numContaCobranca,
 null as codOperContaCobranca,
 NULL as 'percentualPactuacaoContrato',
 NULL as 'situacao',
 cast(a.DTA_NASCIMENTO as varchar(30)) as 'dthNascimento',
 classe_social as classeSocial,
 a.dependentes as dependentes,
 a.DTA_ABERTURA as dataHoraFundacao,
 cast(a.DTA_NASCIMENTO as varchar(30)) as 'dataHoraNascimento',
 cast(a.DES_ESTADO_CIVIL as varchar(40)) as estadoCivil,
 cast(a.filhos as varchar(40)) as filhos,
 cast(a.nacionalidade as varchar(40)) as nacionalidade,
 cast(a.NOM_FANTASIA as varchar(200)) as nomeFantasia,
 null as profissaoDeclarada,
 cast(a.VLR_RENDA_INDIVIDUAL as decimal) as renda,
 Case when a.IND_GENERO = 'F' then 'FEMININO'
	when a.IND_GENERO = 'M' then 'MASCULINO' end as sexo,
 a.educacao as escolaridade,
 NULL as situacaoEmail,
 null as situacaoTelefone,
 null as situacaoEndereco,
 null as ratingEmail,
 null as ratingEndereco,
 null as ratingTelefone,
cast(a.VLR_RENDA_INDIVIDUAL as decimal) as rendaIndividual,
 null as indRendaIndividual,
 null as rendaIndividualOrigem,
 cast(a.VLR_RENDA_FAMILIAR as decimal)as rendaFamiliar,
 null as indRendaFamiliar,
 null as rendaFamiliarOrigem,
 a.cod_CBO as codCbo,
 null as nomeMae,
 null as desComplemento,
concat(fixo.NUM_DDD_TELEFONE,fixo.NUM_TELEFONE)  as telefoneFixo,
null as ratingTelefoneFixo,
null as telefoneFixoOrigem,
null as situacaoTelefoneFixo,
concat(tel.NUM_DDD_TELEFONE,tel.NUM_TELEFONE) as  telefoneCelular,
 null as ratingTelefoneCelular,
 null as telefoneCelularOrigem,
 null  as situacaoTelefoneCelular,
 null as telefoneRural,
 null as ratingTelefoneRural,
 null as telefoneRuralOrigem,
 null as situacaoTelefoneRural,
 null as naturalidade,
 null as codDocRg,
 null as orgaoExpedidorRg,
 null as dataHoraEmissaoDoc,
 null as pessoaId,
 null as funcionario,
 null as numMatricula,
 null as tempoCliente,
 cast(a.IND_PEP as varchar(10)) as pep,
 null as obito,
 null as dataHoraObito,
 null as situacaoCadastral,
 cast(a.IND_NLIST as varchar(10)) as nList,
 a.DES_RISCO_CAIXA as desMotivoNList,
 null as obitoSistemaOrigem,
 null as clienteVip
 from 
DM_CLIENTES_UNIFICADOS_CVP a WITH (NOLOCK)
inner join DM_CLIENTES_ENDERECO_CVP e WITH (NOLOCK)
on a.COD_PESSOA_UNIFICADA = e.COD_PESSOA_UNIFICADA
and e.SEQ_ENDERECO = (select max(SEQ_ENDERECO) 
                        from DM_CLIENTES_ENDERECO_CVP 
                        where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)

 


LEFT join dm_clientes_email_cvp em WITH (NOLOCK)
on a.COD_PESSOA_UNIFICADA = em.COD_PESSOA_UNIFICADA
and em.seq_email = (select max(seq_email) 
                    from dm_clientes_email_cvp 
                    where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)

 

LEFT join DM_CLIENTES_TELEFONE_CVP tel WITH (NOLOCK)
on a.COD_PESSOA_UNIFICADA = tel.COD_PESSOA_UNIFICADA
and TIPO_TELEFONE=2
and tel.SEQ_TELEFONE = (select max(SEQ_TELEFONE)
                        from DM_CLIENTES_TELEFONE_CVP 
                        where COD_PESSOA_UNIFICADA = a.COD_PES
GO
 
IF OBJECT_ID('[dbo].[VW_CANCELAMENTO_PRESTAMISTA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CANCELAMENTO_PRESTAMISTA];
GO

 CREATE   view [dbo].[VW_CANCELAMENTO_PRESTAMISTA] as 
 (


select
        C.NUM_APOLICE
        ,C.NUM_CONTRATO_SEGURO
        ,C.NUM_CONTRATO_TERC
        ,C.NUM_CONTRATO_ANT AS NUM_CONTRATO_TERC_ANT
        ,C.NUM_CERTIFICADO AS NUM_CERTIFICADO_INDIVIDUAL
        ,C.COD_PRODUTO
        ,P.DES_PRODUTO AS NOM_PRODUTO
        ,'CANCELAMENTO ONLINE' AS DES_ORIGEM_CANCELAMENTO
        ,'SOLICITADO' AS DES_FORMA_CANCEL
        ,C.DTA_INI_VIGENCIA AS DTA_INI_VIG
        ,C.DTA_FIM_VIGENCIA AS DTA_FIM_VIG
        ,C.DTA_FIM_VIGENCIA_RENOVADO AS DTH_FIM_VIG_RENOVACAO
        ,CANCEL.DTA_SOLICITACAO AS DTA_SOLICITACAO
        ,cancel.DTA_CANCELAMENTO
        ,cancel.DTA_ENCERRAMENTO
        ,cancel.DTA_RETORNO AS DTA_RETORNO
        ,null AS DTA_ENVIO_SIGPF
        ,C.DES_CONTRATO_RENOVACAO AS DES_CONTRATO_RENOVACAO
        ,c.STA_CONTRATO
        ,'S' AS IND_CANC_ONLINE
        ,'R' AS IND_OPERACAO
        ,null AS NUM_PARCELA
        ,mot.DES_MOT_CANCELAMENTO AS DES_MOTIVO_CANCEL
        ,null AS DES_TP_CANCELAMENTO
        ,null AS DES_STA_MOVIMENTO
        ,C.NUM_CPF_CNPJ AS NUM_CPF_CNPJ_SEGURADO
        ,PES.NOM_RAZ_SOCIAL AS NOM_RAZ_SOCIAL_SEGURADO
        ,c.IND_TP_PESSOA
        ,cancel.COD_USUARIO AS COD_USUARIO
        ,null AS COD_BANCO
        ,null as COD_AGENCIA_BANCO
        ,null as NUM_OPER_CONTA
        ,null as NUM_CONTA
        ,null as NUM_DV_CONTA
        ,C.DTA_QUITACAO
        ,c.VLR_MAX_PREMIO_BRUTO
        ,cancel.DTA_RETORNO as DTA_MAX_PREMIO_RESTITUICAO
        ,cancel.VLR_RESTITUICAO as VLR_MAX_PREMIO_BRUTO_RESTITUICAO
        ,null as DTH_LOG_CONTR_SEGURO
        ,null as DTH_LOG_CONTR_TERC
        ,null as DTH_LOG_ORIGEM_CONTRATO
        ,null as DTH_LOG_CONTR_FINANC
        ,age.NOM_SR
    --    ,age.NOM_FILIAL
        ,C.COD_AGENCIA_VENDA_BU as COD_AGENCIA_VENDA
        ,c.NUM_MATRICULA_VENDEDOR as NUM_MATRICULA_VENDEDOR
        ,C.COD_CANAL_VENDA as COD_CANAL_VENDA
        ,C.NUM_ORI_CONTRATO
        ,CANAL.DES_CANAL_VENDA as DES_SUB_CANAL_VENDA_BU
        ,Origem.DES_ORIGEM_CONTRATO as DES_ORI_CONTRATO
        ,prop.NUM_CONTRATO_SIGPF  
        ,case prop.sta_documento 
            when 'LFE'    then 'LFE - LIBERADO FLUXO DE EXCECAO'
            when 'NNU'    then 'NNU - NAO NECESSITA DE UPLOAD'
            when 'NRU'    then 'NRU - NAO REALIZADO UPLOAD'
            when 'PAR'    then 'PAR - PROPOSTA ANTERIOR A REGRA DE UPLOAD'
            when 'PUE'    then 'PUE - PENDENTE UPLOAD DE PROPOSTA DE EXECAO'
            when 'RUP'    then 'RUP - REALIZOU UPLOAD DE PROPOSTA'
            else 'NÃO INFORMADO'
        end as STA_UPLOAD_PROPOSTA 
		from    DMDB42.dbo.DM_ODS_PRS_CANCEL_U AS CANCEL with (nolock)
        LEFT JOIN DMDB42.dbo.DM_ODS_PRS_CONTRATOS_U AS C with (nolock)
            on CANCEL.NUM_CONTRATO_SEGURO = C.NUM_CONTRATO_SEGURO
        LEFT JOIN DMDB42.dbo.DM_DIM_PRODUTO AS P with (nolock)
            ON P.COD_PRODUTO = C.COD_PRODUTO
        LEFT JOIN DMDB42.dbo.DM_DIM_MOTIVO_CANCELAMENTO AS MOT with (nolock)
            ON MOT.COD_MOT_CANCELAMENTO = CANCEL.COD_MOT_CANCELAMENTO
        --LEFT JOIN DM_ODS_PRS_COBRANCA AS COB with (nolock)
        --    ON COB.SEQ_PLAN_CALCULO = CANCEL.SEQ_PLAN_CALCULO
        left join DMDB42.dbo.DM_ODS_PRS_PESSOAS_U as PES with (nolock)
            on PES.NUM_CPF_CNPJ = C.NUM_CPF_CNPJ
        LEFT JOIN DM_AGENCIA AS age with (nolock)
            ON age.COD_AGENCIA = c.COD_AGENCIA_VENDA_BU
        left join DMDB42.dbo.DM_DIM_CANAL_VENDA as CANAL with (nolock)
            on canal.COD_CANAL_VENDA = c.COD_CANAL_VENDA
        left join DMDB42.dbo.DM_DIM_ORIGEM_CONTRATO Origem with (nolock)
            on C.NUM_ORI_CONTRATO = origem.NUM_ORIGEM_CONTRATO
        left join DMDB42.dbo.DM_ODS_PRS_PROPOSTAS_U prop with (nolock)
            on c.NUM_CONTRATO_TERC = prop.NUM_PROPOSTA_ESTIP  -- FILTROS
WHERE YEAR(cancel.DTA_ENCERRAMENTO) >= (YEAR(GETDATE ()) - 2)


)
GO
 
IF OBJECT_ID('[dbo].[VW_CANCELAMENTO_PREVIDENCIA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CANCELAMENTO_PREVIDENCIA];
GO

CREATE VIEW [dbo].[VW_CANCELAMENTO_PREVIDENCIA]
AS
WITH RESGATE AS (SELECT SUK_CERTIFICADO, IND_RESG_APROVADO AS RESG_APROVADO, 'FOP' AS JUSTIFICATIVA
                                        FROM      DMDB11.dbo.DM_058_RESGATE
                                        WHERE   (COD_JUST_APROV_RESG = 15))
    SELECT DISTINCT 
                      CASE WHEN LEFT(sb.COD_PRODUTO, 1) = '1' THEN pessoa.NOM_PESSOA ELSE pessoa_pj.NOM_PESSOA END AS NOM_PESSOA, CASE WHEN LEFT(sb.COD_PRODUTO, 1) 
                      = '1' THEN pessoa.NUM_CPF_CNPJ ELSE pessoa_pj.NUM_CPF_CNPJ END AS NUM_CPF_CNPJ, sb.CERTIFICADO, CAST(sb.DT_INC_DEVOL AS DATE) AS DTA_SOLICITACAO, CAST(sb.DATA_DEVOLUCAO AS DATE) 
                      AS DATA_DEVOLUCAO, CAST(sb.DATA_PAGAMENTO AS DATE) AS DATA_PAGAMENTO, sb.est_cuenta, sb.DES_STATUS, produto.DES_MODALIDADE, CASE WHEN LEFT(sb.COD_PRODUTO, 1) 
                      = '1' THEN 'PF' ELSE 'PJ' END AS TIPO_PESSOA, sb.STATUS_TITULO, sb.DES_SUB_STATUS, sb.desc_motivo, sb.MATRICULA_RESP, sb.VALOR_NOMINAL AS VALOR_PAGO, COB.VLR_ATUALIZACAO AS VALOR_CORRIGIDO, 
                      agencia_dev.COD_AGENCIA AS COD_AGENCIA_DEVOLUCAO, agencia_dev.NOM_AGENCIA AS NOM_AGENCIA_DEVOLUCAO, agencia_dev.NOM_FILIAL AS NOM_FILIAL_DEVOLUCAO, 
                      agencia_dev.NOM_SR AS NOM_SR_DEVOLUCAO, agencia.COD_AGENCIA AS COD_AGENCIA_VENDA, agencia.NOM_AGENCIA AS NOM_AGENCIA_VENDA, agencia.NOM_FILIAL AS NOM_FILIAL_VENDA, 
                      agencia.NOM_SR AS NOM_SR_VENDA, ind.NOME_ECONOMIARIO, indicador.NUM_MATRICULA AS MATRI_INDI, indicador.NOM_INDICADOR, fundo.COD_FUNDO, fundo.DES_FUNDO, certif.DTA_INICIO_VIGENCIA, 
                      RGT.RESG_APROVADO, RGT.JUSTIFICATIVA
    FROM     DMDB11.dbo.SB_P_201911_DEVOLUCOES_MONITOR AS sb LEFT OUTER JOIN
                      DMDB11.dbo.DM_001_PESSOA AS pessoa ON pessoa.COD_PESSOA = sb.COD_CLIENTE LEFT OUTER JOIN
                      DMDB11.dbo.DM_008_PRODUTO AS produto ON CAST(sb.COD_PRODUTO AS INT) = produto.COD_PRODUTO_KIPREV LEFT OUTER JOIN
                      DMDB11.dbo.DM_012_CERTIFICADO AS certif ON certif.NUM_CERTIFICADO = sb.CERTIFICADO LEFT OUTER JOIN
                      DMDB11.dbo.DM_074_BASE_CARTEIRA AS bc ON certif.SUK_CERTIFICADO = bc.SUK_CERTIFICADO LEFT OUTER JOIN
                      DMDB11.dbo.DM_001_PESSOA AS pessoa_pj ON pessoa_pj.SUK_PESSOA = bc.SUK_PESSOA_PJ LEFT OUTER JOIN
                      DMDB11.dbo.DM_084_FUNDO AS fundo ON fundo.SUK_FUNDO = bc.SUK_FUNDO LEFT OUTER JOIN
                      DMDB11.dbo.DM_025_AGENCIA AS agencia ON agencia.SUK_AGENCIA = bc.SUK_AGENCIA LEFT OUTER JOIN
                      DMDB11.dbo.DM_025_AGENCIA AS agencia_dev ON SUBSTRING(sb.DADOS_BANCARIOS, 6, 5) = agencia_dev.COD_AGENCIA LEFT OUTER JOIN
                      DMDB11.dbo.SB_T_2020_CERTIFICADO_INDICADOR AS ind ON certif.NUM_CERTIFICADO = ind.NUM_CERTIFICADO LEFT OUTER JOIN
                      DMDB11.dbo.DM_011_INDICADOR AS indicador ON ind.COD_AGENTE_VENDA = indicador.NUM_MATRICULA LEFT OUTER JOIN
                      DMDB11.dbo.DM_069_COB_DEVOLUCAO AS COB ON COB.SUK_CERTIFICADO = certif.SUK_CERTIFICADO LEFT OUTER JOIN
                      RESGATE AS RGT ON certif.SUK_CERTIFICADO = RGT.SUK_CERTIFICADO
    WHERE  (sb.DT_INC_DEVOL >= GETDATE() - 1095)
GO
 
IF OBJECT_ID('[dbo].[VW_CANCELAMENTO_VIDA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CANCELAMENTO_VIDA];
GO

create VIEW [dbo].[VW_CANCELAMENTO_VIDA] as (
select
    a12.NOM_OPER_CONTRATO,
    a15.COD_PRODUTO  COD_PRODUTO,
	a16.NOM_SEGMENTO_NEGOCIO  NOM_SEGMENTO_NEGOCIO,
	A18.NUM_APOLICE,
	A15.COD_SUBGRUPO,
	A15.DES_PERIOD_PAGAMENTO_BU,
	A15.COD_RAMO,
	a13.NUM_PROPOSTA  NUM_PROPOSTA,
	a14.COD_CPF_CNPJ  COD_CPF_CNPJ,
	a14.NOM_PESSOA  NOM_PESSOA,
	a13.DTH_QUITACAO AS DTH_QUITACAO,
	a13.VLR_PROPOSTA  VLR_PROPOSTA,
	a13.VLR_IS  VLR_IS,
	a11.DTH_CANCELAMENTO AS DTH_CANCELAMENTO,
	a12.NOM_OPER_CONTRATO AS  MOTIVO,
	agencia.NOM_FILIAL,
	agencia.NOM_SUP_REGIONAL,
	contrato.COD_USUARIO AS ULTIMO_USUARIO
from	dmdb05.dbo.DM_002_CANCELAMENTO	a11
	join	dmdb05.dbo.DM_060_OPERACAO_CONTRATO	a12
	  on 	(a11.SUK_OPER_CONTRATO = a12.SUK_OPER_CONTRATO)
	join	dmdb05.dbo.DM_065_PROPOSTA_VIDA	a13
	  on 	(a11.SUK_PROPOSTA_VIDA = a13.SUK_PROPOSTA_VIDA)
	join	dmdb05.dbo.DM_056_PESSOA	a14
	  on 	(a11.SEQ_PESSOA_SEGURADO = a14.SEQ_PESSOA)
	join	dmdb05.dbo.DM_052_PRODUTO	a15
	  on 	(a11.SUK_PRODUTO = a15.SUK_PRODUTO)
	join	dmdb05.dbo.DM_068_SEGMENTO_PRODUTO	a16
	  on 	(a15.SUK_SEGMENTO_PRODUTO = a16.SUK_SEGMENTO_PRODUTO)
	LEFT JOIN dmdb05.dbo.DM_003_PROPOSTA A17
	  ON	A13.SUK_PROPOSTA_VIDA=A17.SUK_PROPOSTA_VIDA
	LEFT JOIN dmdb05.dbo.DM_054_APOLICE A18
	  ON	A17.SEQ_APOLICE=A18.SEQ_APOLICE
	JOIN	dmdb05.dbo.DM_051_UNID_ORG_AG AS agencia
	  ON	agencia.SUK_UNIDADE_ORG_AG = a11.SUK_AGENCIA_VENDA
	JOIN	dmdb05.dbo.DM_066_CONTRATO_VIDA AS contrato
	  ON	a11.SUK_CONTRATO_VIDA = contrato.SUK_CONTRATO_VIDA
where	year(a11.DTH_CANCELAMENTO) >=  (year(GETDATE ()) - 2))
GO
 
IF OBJECT_ID('[dbo].[VW_CARTEIRA_PREVIDENCIA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CARTEIRA_PREVIDENCIA];
GO
CREATE VIEW [DBO].[VW_CARTEIRA_PREVIDENCIA] AS
--
---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_CARTEIRA_PREVIDENCIA
--
--					SQL14\DMCVP\DMDB41
--
--		OBJETIVO:	EVOLUÇÃO DO CARTEIRA DE VENDAS
--
---------------------------------------------------------------------------------------------------
--		DATA	:	03/02/2023	AUTOR	:	SILVIO J®  -  CRIAÇÃO 
---------------------------------------------------------------------------------------------------
--		select top 80 * from VW_CARTEIRA_PREVIDENCIA order by 1,2,3 
---------------------------------------------------------------------------------------------------

---------------------------------------------------------------------------------------------------
--		1.	RECUPERA VENDAS DO KIPREV 
---------------------------------------------------------------------------------------------------
WITH 	

PREVI AS ( 
SELECT 
		'VENDA     '			AS		MOVIMENTO,
		V.DTA_EMISSAO			AS		DTA_VENDA, -- PROPOSTA,
		CONVERT(VARCHAR(30),V.SUK_CERT_PART)			AS  DOC,
		CONVERT(VARCHAR(6),A.COD_AGENCIA)				AS COD_AGENCIA,
		-------------------------------------------------------------------------------------------
		CONVERT(FLOAT, SUM(V.VLR_CONTR_INICIAL + ISNULL(V.VLR_VENDA,0)))	AS	VLR_PREMIO,
		CONVERT(FLOAT, SUM(V.VLR_CONTR_INICIAL + ISNULL(V.VLR_VENDA,0)))	AS	VLR_VENDA,	
		0  AS	VLR_DEMAIS,	
		0  AS	VLR_PORT_ENTRA,		

	    CONVERT(FLOAT, SUM(CASE WHEN	COB.NAT_COBERTURA = 'RISCO' 
								THEN	V.VLR_VENDA 
								ELSE	0 
								END))	AS VLR_RISCO,

		CONVERT(FLOAT, SUM(CASE WHEN	PR.COD_PRODUTO_KIPREV < 2000   -- EMPRESARIAL
								THEN	0
								ELSE	ISNULL(V.VLR_CONTR_INICIAL,0) + ISNULL(V.VLR_VENDA,0)	
								END))	AS	VLR_PREMIO_PJ ,
		
		CONVERT(FLOAT, SUM(CASE WHEN	SUBSTRING(PR.IND_CONJUGADO,1,1) = 'S'
								THEN	ISNULL(V.VLR_CONTR_INICIAL,0) + ISNULL(V.VLR_VENDA,0)	
								ELSE	0
								END ))	AS	VLR_PREMIO_CONJUGADO,

		CONVERT(FLOAT, SUM(CASE WHEN	C.DES_TIPO_CONTRATACAO	=	'Prev. Sócio'
								THEN	ISNULL(V.VLR_CONTR_INICIAL,0) + ISNULL(V.VLR_VENDA,0)		
								ELSE	0
								END))	AS	VLR_PREMIO_SOCIO,

		CONVERT(FLOAT, SUM(CASE	WHEN	COD_TIPO_CERTIFICADO	=	'I'
								AND		COD_SIT_CERTIFICADO		NOT IN ('P','M')
								AND		COD_PRODUTO_KIPREV		IN	(1191, 1192, 1193, 1194, 1195, 1196, 1197, 1199, 1253,1100)  -- PREV MULHER
								AND		PROP.DTA_EMISSAO		BETWEEN 	'2022-09-16' AND '2023-10-31'
								THEN	V.VLR_VENDA 
								ELSE    0
								END))	AS	VLR_PREV_MULHER,
		0	AS	VLR_RESGATE,			
		0	AS	VLR_PORT_SAIDA,
		0	AS	VLR_RESERVA			
		
FROM	DMDB11..DM_066_VENDA AS V WITH (NOLOCK)

LEFT JOIN DMDB11..DM_012_CERTIFICADO C WITH (NOLOCK )--INDEX = DM012IP)  
ON		C.SUK_CERTIFICADO = V.SUK_CERT_PART

LEFT JOIN DMDB11..DM_040_COB_CONTRIBUICAO COB  WITH (NOLOCK )-- INDEX = DM040IP)
ON		COB.SUK_CONTRIBUICAO = V.SUK_CONTRIBUICAO

LEFT JOIN DMDB11..DM_036_PROPOSTA PROP WITH (NOLOCK )-- INDEX = DM036IP)
ON		PROP.SUK_PROPOSTA = V.SUK_PROPOSTA

LEFT JOIN DMDB11..DM_008_PRODUTO PR  WITH (NOLOCK)
ON		PR.SUK_PRODUTO = V.SUK_PRODUTO

LEFT JOIN DMDB11..DM_025_AGENCIA A  WITH (NOLOCK )-- INDEX = DM025IP)
ON		A.SUK_AGENCIA = V.SUK_AGENCIA

WHERE	ISNULL(C.SUK_CERTIFICADO,0) > 0
AND		CONVERT(VARCHAR(6), V.DTA_EMISSAO, 112)	BETWEEN CONVERT(VARCHAR(6), DATEADD(MONTH,-1,GETDATE()) , 112) 
												AND	 CONVERT(VARCHAR(6), GETDATE(), 112)
GROUP BY 
		V.DTA_EMISSAO,
		CONVERT(VARCHAR(30),V.SUK_CERT_PART),
		CONVERT(VARCHAR(6),A.COD_AGENCIA)		

---------------------------------------------------------------------------------------------------
--		2.	RECUPERA PORTABILIDADE DE ENTRADA
---------------------------------------------------------------------------------------------------
UNION ALL

SELECT   	
		'PORT ENTRA'			AS	MOVIMENTO,
		A.DTA_SOLICITACAO		AS	DTA_VENDA ,		
		CONVERT(VARCHAR(30),A.NUM_PORTABILIDADE) 		AS  DOC,
		CONVERT(VARCHAR(6),G.C
GO
 
IF OBJECT_ID('[dbo].[VW_CARTEIRA_VIDA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CARTEIRA_VIDA];
GO
CREATE VIEW [DBO].[VW_CARTEIRA_VIDA] AS

---------------------------------------------------------------------------------------------------
--		select  * from VW_CARTEIRA_VIDA 
---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_CARTEIRA_VIDA
--
--					SQL14\DMCVP\DMDB41
--
--		OBJETIVO:	COMPARATIVO DOS CANCELAMENTOS X CARTEIRA ATIVA
--
---------------------------------------------------------------------------------------------------
--		DATA	:	03/02/2023	AUTOR	:	SILVIO J®  -  CRIAÇÃO
---------------------------------------------------------------------------------------------------

---------------------------------------------------------------------------------------------------
--		0.	VIDA - DATE
---------------------------------------------------------------------------------------------------
WITH 

TEMPO  AS  ( 
 
SELECT		DISTINCT CONVERT(VARCHAR(6),DTH_DATA,112) ANO_MES
FROM		[DMDB05].[dbo].[DM_050_TEMPO]
WHERE		CONVERT(date,DTH_DATA)  BETWEEN		CONVERT(date, DATEADD(YEAR,-2,GETDATE()) )  
									AND			CONVERT(DATE, GETDATE())
)

---------------------------------------------------------------------------------------------------
--		1. VIDA	RECUPERA VENDAS DO AIC
---------------------------------------------------------------------------------------------------
,CANCEL AS  ( 

SELECT	DISTINCT
		CAN.SUK_PROPOSTA_VIDA						AS	NUM_PROPOSTA,
		CONVERT(VARCHAR(6),DTH_CANCELAMENTO,112) 	AS	ANOMES_CANCELAMENTO,
		A051.NUM_AGENCIA							AS	COD_AGENCIA,

		CONVERT(FLOAT,  VLR_PREMIO_CANCELADO)		AS	VLR_PREMIO_CANCELADO,

		CASE	WHEN	A052.DES_PERIOD_PAGAMENTO IN ( 'Bimestral'  , 'Mensal','Trimestral','Semestral')
				THEN	CONVERT(FLOAT,  VLR_PREMIO_CANCELADO)
				END		AS		VLR_PREMIO_PM,

		CASE	WHEN	A052.DES_PERIOD_PAGAMENTO  IN ( 'Anual'  , 'Unico','? - Não informado')
				THEN	CONVERT(FLOAT,  VLR_PREMIO_CANCELADO)
				END		AS		VLR_PREMIO_PU,

		CASE	WHEN	A052.DES_RAMO_PRODUTO	IN ('Microsseguro','Acidentes Pessoais Coletivo','Acidentes Pessoais Individual','Bilhete AP')
				THEN	CONVERT(FLOAT,  VLR_PREMIO_CANCELADO)
				ELSE	0
				END		AS		VLR_PREMIO_AP,
			 			 			 					
		CASE	WHEN	A003.DTH_DATA			BETWEEN '2022-09-19' AND CONVERT(DATE, GETDATE())
				AND		UPPER(A052.NOM_PRODUTO) NOT IN ('SEGURO ACIDENTES PESSOAIS BEM-ESTAR', 'VIDA EMPRESARIAL', 'VIDA EXCLUSIVO')
				AND		A052.COD_ASSISTENCIA	IN ( 2 ,3 ) 						-- 2	'Mais' 				-- 3	'Especial'
				THEN	CONVERT(FLOAT, VLR_PREMIO_CANCELADO)
				END		AS		VLR_PREMIO_MAIS,

		CASE	WHEN	A052.COD_PRODUTO IN (	9722, 9721 , 9723,	-- Vida da Gente: 
												9732, 9731 , 9733, -- Vida Mulher: 
												9736, 9735 , 9737, -- Vida Mulher Total: 
												9742, 9741 , 9743, -- Vida Multipremiado Super: 
												9746, 9745 , 9747, -- Vida Multipremiado Total: 
												9729 )				--Vida Sênior: 
				AND 	A003.DTH_DATA BETWEEN '2022-09-19'   AND CONVERT(DATE, GETDATE())
				THEN	CONVERT(FLOAT,VLR_PREMIO_CANCELADO)
				ELSE	0
				END		AS		VLR_PREMIO_ASSISTENCIA
 
FROM	DMDB05..DM_002_CANCELAMENTO				CAN		WITH ( NOLOCK )

INNER JOIN DMDB05..DM_003_PROPOSTA				A003	WITH ( NOLOCK )
ON		A003.SUK_PROPOSTA_VIDA		=	CAN.SUK_PROPOSTA_VIDA

INNER JOIN DMDB05..DM_065_PROPOSTA_VIDA			A065	WITH ( NOLOCK ) 
ON		A003.SUK_PROPOSTA_VIDA		=	A065.SUK_PROPOSTA_VIDA

INNER JOIN DMDB05..DM_059_SITUACAO_CONTRATO		A059	WITH ( NOLOCK )
ON		A003.SUK_SITUACAO_CONTRATO	=	A059.SUK_SITUACAO_CONTRATO
AND		A059.NOM_SUB_SITUACAO		=  'Cancelado'

INNER JOIN DMDB05..DM_052_PRODUTO				A052	WITH ( NOLOCK )
ON		A003.SUK_PRODUTO			=	A052.SUK_PRODUTO

INNER JOIN DMDB05..DM_051_UNID_ORG_AG			A051	WITH ( NOLOCK )
