	CREATE VIEW [DBO].[VW_CCA_PRESTAMISTA] AS
---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_CCA_PRESTAMISTA
--
--					SQL14\DMCVP\DMDB42 
--
--		OBJETIVO:	CRIAR BASE DE CONSULTA ENTRE CCA E AS VENDAS DO BI
--
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  Criação
--		DATA	:	23/02/2023	
---------------------------------------------------------------------------------------------------

---------------------------------------------------------------------------------------------------
--		PRESTAMISTA
---------------------------------------------------------------------------------------------------
---------------------------------------------------------------------------------------------------
--		RECUPERA VENDAS DO AIC
---------------------------------------------------------------------------------------------------
WITH

CANCELAMENTOS AS
(			
SELECT	A.NUM_CONTRATO_TERC, 
		A.DES_MOTIVO_CANCEL, 
		A.DTA_CANCELAMENTO

FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS A   WITH ( NOLOCK )
INNER JOIN (SELECT	NUM_CONTRATO_TERC, 
					MAX(STA_MOVIMENTO) AS STA_MOVIMENTO,  
					MAX(DTH_CARGA) AS DTH_CARGA 			
			FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS WITH ( NOLOCK ) 
			WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
			GROUP BY NUM_CONTRATO_TERC) B 
ON		A.NUM_CONTRATO_TERC =	B.NUM_CONTRATO_TERC
AND		A.STA_MOVIMENTO		=	B.STA_MOVIMENTO
AND		A.DTH_CARGA			=	B.DTH_CARGA
WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
) 

---------------------------------------------------------------------------------------------------
--		RECUPERA VENDAS DO PRESTAMISTA ( EXCETO CONSORCIO ) SIAPI SIAPX SIFEC
---------------------------------------------------------------------------------------------------
, PRESTA  AS  ( 

SELECT	DISTINCT 
		A.NUM_PROPOSTA_ESTIP			AS	NUM_PROPOSTA,
		CASE WHEN A.COD_UNO_VENDA = 0 
			 THEN CNT.COD_AGENCIA_VENDA 
			 ELSE A.COD_UNO_VENDA 
		END								AS	COD_AGENCIA,
		COD_CCA							AS	NUM_RESPONSAVEL_DV,

		CONVERT(DATE, A.DTA_PROPOSTA)	AS DTA_PROPOSTA,
		CONVERT(FLOAT, A.VLR_PREMIO)AS	VLR_PREMIO ,
		
		CASE	WHEN LTRIM(RTRIM(UPPER(C.DES_PRODUTO))) IN ( 'PRESTAMISTA VIDA DO PRODUTOR RURAL - PF'	
															,'PRESTAMISTA VIDA DO PRODUTOR RURAL - PJ'	
															,'PRESTAMISTA RURAL PJ'					
															,'PRESTAMISTA RURAL PF'	)				
				THEN CONVERT(FLOAT, A.VLR_PREMIO)
				ELSE 0
				END AS	VLR_PREMIO_RURAL,

		CASE	WHEN LTRIM(RTRIM(UPPER(C.DES_PRODUTO))) IN ( 'PRESTAMISTA CONSÓRCIO AUTO'				
															,'PRESTAMISTA CONSÓRCIO IMOBILIÁRIO'		
															,'PRESTAMISTA CONSÓRCIO IMOBILIÁRIO PJ'	)
				THEN CONVERT(FLOAT, A.VLR_PREMIO)
				ELSE 0
				END AS	VLR_PREMIO_CONSORCIO,

		CASE	WHEN OC.DES_OPERACAO_CREDITO = 'Pronampe'
				THEN CONVERT(FLOAT, A.VLR_PREMIO)
				ELSE 0
				END AS	VLR_PREMIO_PRONAMPE,

		CASE	WHEN OC.DES_OPERACAO_CREDITO = 'Girocaixa FGI'
				THEN CONVERT(FLOAT, A.VLR_PREMIO)
				ELSE 0
				END AS	VLR_PREMIO_FGI,

		CASE	WHEN ( CANC.DES_MOTIVO_CANCEL LIKE '% RISCO%' OR CANC.DES_MOTIVO_CANCEL LIKE 'IDADE + PRAZO%' )
				OR ( DATEDIFF(DAY, A.DTA_PROPOSTA, CANC.DTA_CANCELAMENTO) BETWEEN 0 AND 7 )
				OR ( DES_STATUS_PROPOSTA = 'EM CRITICA' AND A.STA_MOVTO = 'REJ' )
				OR ( DES_STATUS_PROPOSTA IN ('INTEGRADA', 'EM CRITICA') AND A.STA_MOVTO = 'CAN' )
				THEN CONVERT(FLOAT, A.VLR_PREMIO)
				ELSE 0
				END AS	VLR_PREMIO_CANCELADO,

		CASE	WHEN IND_UPLOAD = 'N'
				THEN 0
				ELSE 1
				END AS QTD_UPLOAD

FROM	DMDB42..DM_ODS_PRS_PROPOSTAS_U		A		WITH (NOLOCK)

LEFT JOIN DMDB42..DM_DIM_PRODUTO			C		WITH (NOLOCK)
ON		A.COD_PRODUTO			=	C.COD_PRODUTO

LEFT JOIN DMDB42..DM_ODS_PRS_CONTRATOS_U	CNT		WITH (NOLOCK INDEX = IX_DM_ODS_PRS_CONTRATOS_U_terc)
ON		A.NUM_PROPOSTA_ESTIP	=	CNT.NUM_CONTRATO_TERC
AND		A.COD_PRODUTO			=	CNT.COD_PRODUTO

LEFT JOIN DMDB42..DM_DIM_OPERA
GO
 
