CREATE VIEW [DBO].[VW_CCA_VIDA] AS
---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_CCA_VIDA
--
--					SQL14\DMCVP\DMDB42 
--
--		OBJETIVO:	CRIAR BASE DE CONSULTA ENTRE CCA E AS VENDAS DO BI
--
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  Criação
--		DATA	:	23/02/2023	
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  eliminado o respvendas 76
--		DATA	:	01/03/2023	
---------------------------------------------------------------------------------------------------

---------------------------------------------------------------------------------------------------
--		VIDA
---------------------------------------------------------------------------------------------------
---------------------------------------------------------------------------------------------------
--		RECUPERA VENDAS DO AIC
---------------------------------------------------------------------------------------------------
WITH

VIDA AS  ( 

SELECT	DISTINCT
		COD_PROPOSTA				AS	NUM_PROPOSTA,
		DTA_VENDA					AS	DTA_PROPOSTA,
		CONVERT(INT, A.COD_AGENCIA) AS	COD_AGENCIA,


		CASE WHEN ISNUMERIC(A.NUM_MATRICULA_INDICADOR) = 0 THEN A.COD_PV 
             WHEN ISNUMERIC(A.NUM_MATRICULA_INDICADOR) = 1 AND LEN(CONVERT(INT, A.NUM_MATRICULA_INDICADOR)) < 6 THEN A.COD_PV 
        ELSE A.NUM_MATRICULA_INDICADOR END AS NUM_RESPONSAVEL_DV ,

		A076.NUM_RESPONSAVEL_DV AS NUM_RESPONSAVEL_076, 
		A076.COD_AGENCIA AS COD_AGENCIA_RESP ,
		A076.COD_CPF_CNPJ,
		A076.NOM_RAZAO_SOCIAL,
		CASE WHEN	COD_PERIODICIDADE_PGTO = 'A'      
			 AND	A052.DES_PERIOD_PAGAMENTO = 'Unico'
			 THEN	'Unico'

			 WHEN   COD_PERIODICIDADE_PGTO = 'U'
			 AND	A052.DES_PERIOD_PAGAMENTO = 'Unico'
			 THEN	'Unico'

			 WHEN	ISNULL(COD_PERIODICIDADE_PGTO,'') = ''
			 AND	ISNULL(A052.DES_PERIOD_PAGAMENTO,'') =  ''
			 THEN	'Unico'

			 WHEN	COD_PERIODICIDADE_PGTO = 'U'
			 THEN	'Unico'

			 WHEN	COD_PERIODICIDADE_PGTO = 'A'
			 THEN	'Anual' 

			 WHEN   COD_PERIODICIDADE_PGTO = 'A'
			 AND	A052.DES_PERIOD_PAGAMENTO = 'Anual'
			 THEN	'Anual'
		
			 WHEN   COD_PERIODICIDADE_PGTO = 'M'
			 AND	A052.DES_PERIOD_PAGAMENTO = 'Mensal'
			 THEN	'Mensal'

			 WHEN	COD_PERIODICIDADE_PGTO = 'M'
			 THEN	'Mensal'
			 ELSE	''	

			 END    AS	DES_PERIOD_PAGAMENTO ,  

		CONVERT(FLOAT, A.VLR_PREMIO) AS	VLR_PREMIO_EMITIDO,

		CONVERT(FLOAT,  CASE	WHEN 	A065.NUM_PROPOSTA IS NOT NULL 
								THEN	A.VLR_PREMIO
								WHEN (IIF(CASE	WHEN DTA_VENDA <> CONVERT(DATE, GETDATE()) 
												THEN FLG_PAGO_MJUNMOV 
												ELSE FLG_PAGO_RAJADA 
												END = 'S', A.VLR_PREMIO, 0)) = 0  
								THEN	0
								ELSE	A.VLR_PREMIO	
						END 
				) 					AS VLR_PREMIO_PAGO ,

		CASE  WHEN	(CAN.QT_DIAS_CANCEL IS NULL	AND A059.NOM_SUB_SITUACAO = 'CANCELADO')
			  OR		(CAN.QT_DIAS_CANCEL	<=	7	AND A059.NOM_SUB_SITUACAO = 'CANCELADO' )
			  OR		(A059.NOM_SUB_SITUACAO =	'Risco Excluido' )
			  OR		(A059.NOM_SUB_SITUACAO =	'Falta de Pagamento') 
			  THEN	CONVERT(FLOAT, A.VLR_PREMIO)
			  ELSE	0
			  END	AS	VLR_PREMIO_CANCELADO,

		--	  Acidentes pessoais AP
		CASE  WHEN  A052.DES_RAMO_PRODUTO	IN ('Microsseguro','Acidentes Pessoais Coletivo','Acidentes Pessoais Individual','Bilhete AP')
			  THEN	
					CASE	WHEN 	A065.NUM_PROPOSTA IS NOT NULL 
							THEN	CONVERT(FLOAT, A.VLR_PREMIO)
							WHEN (IIF(CASE	WHEN DTA_VENDA <> CONVERT(DATE, GETDATE()) 
											THEN FLG_PAGO_MJUNMOV 
											ELSE FLG_PAGO_RAJADA 
											END = 'S', A.VLR_PREMIO, 0)) = 0  
							THEN	0
							ELSE	CONVERT(FLOAT, A.VLR_PREMIO)
					END 

			  ELSE	0
			  END	AS	VLR_PREMIO_AP,

		CASE  WHEN  COD_PERIODICIDADE_PGTO = 'M'
			  THEN	
					CASE	WHEN 	A065.NUM_PROPOSTA IS NOT NULL 
								THEN	CONVERT(FLOAT, A.VLR_P
GO
 
IF OBJECT_ID('[dbo].[VW_CELULAR_CONTRATOS_CVP]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CELULAR_CONTRATOS_CVP];
GO

CREATE VIEW [dbo].[VW_CELULAR_CONTRATOS_CVP] as (
 select distinct
 c.NUM_CERTIFICADO as 'numContrato',
 a.NUM_CPF_CNPJ as  'codCpfCnpj',
 trim(cast(null as varchar(20))) as sistema,
 'TELEFONIA CELULAR' as 'tipoTelefone',
 --trim(cast(tel.NUM_TELEFONE as varchar(10))) as 'telefone',
--concat(fixo.NUM_DDD_TELEFONE,fixo.NUM_TELEFONE)  as telefoneFixo,
concat(tel.NUM_DDD_TELEFONE,tel.NUM_TELEFONE) as  contato,
'LEGADO' as situacao,
 null as rating,
 null as dth_referencia,
 null as dth_atualizacao
from 
DM_CLIENTES_UNIFICADOS_CVP a 


LEFT join DM_CLIENTES_TELEFONE_CVP tel
on a.COD_PESSOA_UNIFICADA = tel.COD_PESSOA_UNIFICADA
and TIPO_TELEFONE=2
and tel.SEQ_TELEFONE = (select max(SEQ_TELEFONE)
                        from DM_CLIENTES_TELEFONE_CVP 
                        where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA
                        and TIPO_TELEFONE=2)

 

LEFT join DM_CLIENTES_TELEFONE_CVP fixo
on a.COD_PESSOA_UNIFICADA = fixo.COD_PESSOA_UNIFICADA
and fixo.TIPO_TELEFONE=1
and fixo.SEQ_TELEFONE = (select max(SEQ_TELEFONE)
                        from DM_CLIENTES_TELEFONE_CVP 
                        where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA
                        and TIPO_TELEFONE=1)

 

inner join DM_CLIENTES_CONTRATOS_CVP b
on a.NUM_CPF_CNPJ=b.NUM_CPF_CNPJ
and b.COD_PESSOA = (select min(COD_PESSOA) from DM_CLIENTES_CONTRATOS_CVP 
                     where NUM_CPF_CNPJ=b.NUM_CPF_CNPJ)
inner join DM_CONTRATOS_CVP c
on b.NOM_SEGMENTO = c.NOM_SEGMENTO
and b.NUM_CERTIFICADO = c.NUM_CERTIFICADO
)
GO
 
