p.DES_GRUPO_PERGUNTA as Grupo_Pergunta,
p.DES_QUESTOES as Questao_Pesquisa_Nome_Pergunta,
p.DES_RESPOSTA as Resposta,
p.VLR_NPS as NPS,
a.NUM_CPF_CNPJ as CPF_CNPJ_Cliente,
a.DES_EMAIL_PESQUISA as Endereco_Email_Pesquisa,
p.DES_PESQUISA as Pesquisa_Nome_Questionario,
a.NOM_EMPRESA_NIVEL_2 as Proprietario_2_Nivel_Nome_Empresa,
a.NOM_USUARIO_NIVEL_2 as Proprietario_2_Nivel_Nome_Usuario,
A.COD_ID_PESQUISA_SATISFACAO AS Id_Pesquisa_Satisfacao


from [DMDB41].[dbo].[DM_SALESFORCE_ATENDIMENTO] a
left join [DMDB41].[dbo].[DM_SALESFORCE_PESQUISA_SATISFACAO] p on a.cod_id_atendimento=p.cod_id_atendimento

