IF OBJECT_ID('[dbo].[VW_CENTRAL_SEGUNDO_NIVEL_SOLICITACOES]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CENTRAL_SEGUNDO_NIVEL_SOLICITACOES];
