CREATE VIEW [dbo].[VW_CENTRAL_SEGUNDO_NIVEL_SOLICITACOES]
AS
select  a.NUM_ATENDIMENTO as Numero_Solicitacao,
		a.NUM_PROTOCOLO as Numero_Protocolo,
		format(a.DTH_ABERTURA, 'dd/MM/yyyy HH:mm') as Data_Hora_Abertura,
		format(a.DTH_VENCIMENTO, 'dd/MM/yyyy HH:mm') as Data_Vencimento,
		format(a.DTH_RESOLUCAO, 'dd/MM/yyyy HH:mm') as Data_Hora_Fechamento,
		a.STA_ATENDIMENTO as Status,
		a.DES_FINAL_NIVEL_2 as Fila_2_Nivel,
		a.DES_ASSUNTO as Assunto,
		a.DES_ORIGEM as Canal,
		a.DES_ORIGEM_CONTATO as Origem_Contato,
		a.DES_DIRECIONADOR_ORIGEM as Direcionador,
		a.NOM_PROPRIETARIO_NIVEL_2 as Proprietario_2_Nivel_Nome_Completo,
		a.NUM_CPF_CNPJ as CPF_CNPJ,
		a.DES_SEGMENTO as Segmento,
		case when a.IND_REINCIDENCIA='S' then 'VERDADEIRO'
		ELSE 'FALSO' 
		END Reincidencia,
		case when t.IND_SLA_EXCEDIDO='true' then  'VERDADEIRO'
		ELSE 'FALSO' 
		END SLA_Atingido,
		t.COD_TAREFA as Tarefa_Solicitacao,
		a.DES_PRODUTO_CONTRATO as Produto_Contrato,
		a.COD_PRODUTO as Codigo_Produto,
		a.NUM_CONTRATO as Numero_Contrato,
		a.NOM_UF as Cliente_Estado,
		a.NUM_AGENCIA as Cliente_Agencia,
		format(a.DTA_NASCIMENTO, 'dd/MM/yyyy') as Cliente_Data_Nascimento,
		-- adicionadas em 31/10/2024 POR CONTA DA DEMANDA: SCTASK0005359 - RITM0005729
		a.[DTH_ULTIMA_MODIFICACAO] as Data_Ultima_Modificacao, -- --[Solicitacoes].[Data da ultima modificação] OK
		a.[DTH_ENVIO_NIVEL_2] as Data_Hora_Envio_Nivel_2, -- --[Solicitacoes].[Data e hora enviado ao 2º nivel] OK
		a.[DES_RAZAO_CANCEL_N1] AS Motivo_Cancelamento, -- --[Protocolos].[Motivo do cancelamento]
		A.[NOM_PROPRIETARIO_NIVEL_1] AS Proprietario_1_Nivel_Nome_Completo, --[Solicitacoes].[Proprietário do 1º nível - Nome completo] OK
		A.[NUM_FUNCIONARIO_NIVEL_1] AS Funcionario_1_Nivel_Numero, --[Solicitacoes].[Proprietário do 1º nível - Numero do funcionário] OK
		A.[NUM_FUNCIONARIO_NIVEL_2] AS Funcionario_2_Nivel_Numero, --[Solicitacoes].[Proprietário do 2º nível - Numero do funcionário n2]
		A.[COD_ID_PESQUISA_SATISFACAO] AS Id_Pesquisa_Satisfacao, --[Solicitacoes].[Id da pesquisa de satisfação] OK
		a.[IND_PESQUISA_ENVIADA_CASE] AS Pesquisa_Enviada, --[Solicitacoes].[Pesquisa enviada]  Ok
		a.[IND_PESQUISA_RESPONDIDA_CASE] as Pesquisa_Respondida --[Solicitacoes].[Pesquisa respondida] OK

 FROM [DMDB41].[dbo].[DM_SALESFORCE_ATENDIMENTO] a
	  left join [DMDB41].[dbo].[DM_SALESFORCE_TAREFAS] t on a.NUM_ATENDIMENTO=t.NUM_ATENDIMENTO
		   where DTH_ENVIO_NIVEL_2 is not null
		   and a.DES_SEGMENTO in ('PREV','PREST', 'VIDA')
		   and DES_FINAL_NIVEL_2 in ('GERIS - Portal Caixa Seguradora', 
		   'PREST - Consultoria - Central',
		   'PREST - Backoffice - Central',
		   'PREV - Resgate PF - Central',
		   'CAIXA Seguridade - Reset de Cadastro',
		   'PREV - Consultoria - Central',
		   'VIDA - Consultoria - Central',
		   'Consultoria Mídias Sociais - Central')
GO
 
