t.DES_TAREFA_ as Descricao_tarefa,
t.DES_RESPOSTA_TAREFA_COMPLETA_ as Resposta_Tarefa
FROM [DMDB41].[dbo].[DM_SALESFORCE_ATENDIMENTO] a
	  left join [DMDB41].[dbo].[DM_SALESFORCE_TAREFAS] t on a.NUM_ATENDIMENTO=t.NUM_ATENDIMENTO
where DTH_ENVIO_NIVEL_2 is not null and (DES_FILA_RESPONSAVEL like '%Consultoria%' or DES_FILA_RESPONSAVEL like '%Central%')

)
GO
 
IF OBJECT_ID('[dbo].[VW_CHAT_INTERACOES]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CHAT_INTERACOES];
GO

CREATE VIEW [dbo].[VW_CHAT_INTERACOES]
AS
SELECT FORMAT(DT_CRIACAO, 'dd/MM/yyyy HH:mm') AS Hora_Inicio, FORMAT(DT_ENCERRAMENTO, 'dd/MM/yyyy HH:mm') AS Hora_Termino, NUM_PROTOCOLO AS Numero_Protocolo, TEMPO_ESPERA AS Tempo_Espera_Segundos, 
                  DATEDIFF(SECOND, CAST('00:00:00' AS TIME), DURACAO) AS Duracao_Chat, CASE WHEN [ABANDONADO] = 1 THEN 'Perdidas' ELSE 'Atendidas' END AS Resumo_Chamada, NOME_BOTAO AS Botao_Chat_Nome_Desenvolvedor, 
                  NOM_USUARIO AS Proprietario_Nome_Completo, NOM_PROPRIETARIO AS Proprietario_Nome_Usuario, CANAL AS Protocolo_Canal, NUM_DOCUMENTO as CPF_CNPJ
FROM     dbo.DM_SALESFORCE_CHAT
GO
 
IF OBJECT_ID('[dbo].[VW_CHAT_PESQUISAS_SF]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CHAT_PESQUISAS_SF];
GO
CREATE view [VW_CHAT_PESQUISAS_SF]  AS 
(
SELECT
	 SF_ATEND.NUM_PROTOCOLO 
	,cast(SF_ATEND.[DTH_ABERTURA] as date) as DTA_CRIACAO -- SUBSTITUINDO A DATA DE CRIAÇÃO DA PESQUISA PELA DATA DE ABERTURA
	--,cast(PSATS.DTH_CRIACAO as date) as DTA_CRIACAO
	,SF_ATEND.STA_ATENDIMENTO as STATUS_ATENDIMENTO
	,SF_ATEND.NUM_ATENDIMENTO AS NUM_SOLICITACAO
	,SF_ATEND.DES_PRODUTO_CONTRATO as NOM_PRODUTO
	,SF_ATEND.DES_DIRECIONADOR_ORIGEM as DIRECIONADOR_ORIGEM
	,SF_ATEND.DES_ASSUNTO AS ASSUNTO
	,SF_ATEND.DES_RESULTADO as STATUS
	,SF_ATEND.DES_FILA as DIRECIONADOR
	,SF_ATEND.NOM_CLIENTE
	,SF_ATEND.NUM_CPF_CNPJ
	,SF_ATEND.NOM_CRIADOR 
	,cast(PSATS.DTA_RESPOSTA as date) as DTA_RESPOSTA
	,PSATS.DES_GRUPO_PERGUNTA as GRUPO_PERGUNTA	
	,PSATS.DES_TITULO_QUESTOES as NOME_PERGUNTA
	,PSATS.DES_RESPOSTA  AS RESPOSTA
	,SF_ATEND.DES_SEGMENTO as SEGMENTO
	,PSATS.DES_PESQUISA as NOM_QUESTIONARIO
	,SF_CHAT.CANAL

from [DMDB41].[dbo].[DM_SALESFORCE_PESQUISA_SATISFACAO] as PSATS
	join [DMDB41].[dbo].[DM_SALESFORCE_ATENDIMENTO] as SF_ATEND
		on SF_ATEND.COD_ID_ATENDIMENTO = PSATS.COD_ID_ATENDIMENTO
	join [DMDB41].[dbo].[DM_SALESFORCE_CHAT] as SF_CHAT
		on SF_CHAT.NUM_PROTOCOLO = SF_ATEND.NUM_PROTOCOLO

WHERE SF_CHAT.CANAL like '%Chat%'
--and SF_ATEND.DES_DIRECIONADOR_ORIGEM like '%Chat%'
--and SF_ATEND.DES_FILA  like '%Chat%'
)
GO
 
IF OBJECT_ID('[dbo].[VW_CHAT_TABULACOES]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CHAT_TABULACOES];
GO
CREATE VIEW dbo.VW_CHAT_TABULACOES
AS
SELECT FORMAT(DTH_ABERTURA, 'dd/MM/yyyy hh:mm') AS Data_Hora_Abertura, DES_ORIGEM_CONTATO AS Origem_Contato, DES_DIRECIONADOR_ORIGEM AS Direcionador_Origem, DES_FILA AS Direcionador, DES_ORIGEM AS Canal, 
                  NUM_PROTOCOLO AS Numero_Protocolo, NUM_ATENDIMENTO AS Numero_Solicitacao, DES_CATEGORIA_P1 AS Macroassunto, DES_ASSUNTO AS Assunto, DES_SEGMENTO_PROTOCOLO AS Segmento_Protocolo, 
                  DES_SEGMENTO AS Segmento, STA_ATENDIMENTO AS Status, CASE WHEN [DTH_ENVIO_NIVEL_2] IS NULL THEN 'FALSO' ELSE 'VERDADEIRO' END AS Segundo_Nivel, COD_PRODUTO AS Codigo_Produto, 
                  DES_PRODUTO_CONTRATO AS Produto_Contrato, NOM_CRIADOR_PROTOCOLO AS Protocolo_Criado_Por_Nome_Completo, CASE WHEN [IND_TRANSFERENCIA] = 'N' THEN 'FALSO' ELSE 'VERDADEIRO' END AS Transferencia, 
                  NUM_CPF_CNPJ AS CPF_CNPJ, NOM_USUARIO_NIVEL_1 AS Proprietario_1_Nivel_Numero_Funcionario, NUM_TELEFONE_URA AS Numero_Telefone_URA, NUM_CONTRATO AS Numero_Contrato, 
                  NOM_CRIADOR AS Criado_Por_Nome_Completo, NOM_PROPRIETARIO_NIVEL_1 AS Proprietario_1_Nivel_Nome_Completo, NOM_PROPRIETARIO_NIVEL_2 AS Proprietario_2_Nivel_Nome_Completo, 
                  NUM_FUNCIONARIO_NIVEL_2 AS Proprietario_2_Nivel_Numero_Funcionario, STA_ICON
FROM     dbo.DM_SALESFORCE_ATENDIMENTO
WHERE  (DES_ORIGEM IN ('[Phone]', '[App]', 'Chat', 'WhatsApp')) AND (DES_ORIGEM_CONTATO <> 'Sinistro') AND (DES_CATEGORIA_P1 <> 'Transferir atendimento')
GO
 
IF OBJECT_ID('[dbo].[VW_CLASS_RISCO_RESULT]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CLASS_RISCO_RESULT];
GO


CREATE VIEW [dbo].[VW_CLASS_RISCO_RESULT] AS

----------------------------------------------------------
-- ANALISE BASE UNIFICADA - CLASSIFICACAO RISCO
----------------------------------------------------------

select	getdate() as DTH_CARGA,
		NOM_SEGMENTO,
		DES_PESSOA,
		sum(QTD_SEM_CLASSIFICACAO) as QTD_SEM_CLASSIFICACAO,
		sum(QTD_COM_CLASSIFICACAO) as QTD_COM_CLASSIFICACAO,
		sum(QTD_SEM_CLASSIFICACAO) + sum(QTD_COM_CLASSIFICACAO) AS TOTAL,

		CAST(	cast(sum(QTD_COM_CLASSIFICACAO) as decimal(15,3))
				/ cast(sum(QTD_SEM_CLASSIFICACAO) + sum(QTD_COM_CLASSIFICACAO) as decimal(15,3)) * 100  
		AS decimal(15,3)) AS PCT_COM_CLASSIFICACAO

from (

-- sem classificação -------------------
select	cli.NOM_SEGMENTO, 
		cli.DES_PESSOA,
		count(distinct Cli.NUM_CPF_CNPJ) as QTD_SEM_CLASSIFICACAO,
		0 as QTD_COM_CLASSIFICACAO

from	DM_CLIENTES_CONTRATOS_CVP as CLI
		left join DM_CONTRATOS_CVP as C
			on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
			and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO
where	
		C.COD_STATUS_CONTRATO = 'A'
		and cli.IND_CARGA <> 'D'
		and c.IND_CARGA <> 'D'
		and cli.DES_CLASSIFICACAO_RISCO is null
		and cli.NUM_CPF_CNPJ <> 0 
		and cli.NUM_CPF_CNPJ is not null
		and CLI.NOM_PESSOA <> '' -- desconsidera nome em branco
		and CLI.NOM_PESSOA is not null -- desconsidera nome nulo

group by cli.NOM_SEGMENTO, cli.DES_PESSOA

UNION ALL 

-- com classificacao -------------------
select	cli.NOM_SEGMENTO, 
		cli.DES_PESSOA,
		0 as QTD_SEM_CLASSIFICACAO,
		count(distinct Cli.NUM_CPF_CNPJ) as QTD_COM_CLASSIFICACAO

from	DM_CLIENTES_CONTRATOS_CVP as CLI
		left join DM_CONTRATOS_CVP as C
			on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
			and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO
where	
		C.COD_STATUS_CONTRATO = 'A'
		and cli.IND_CARGA <> 'D'
		and c.IND_CARGA <> 'D'
		and cli.DES_CLASSIFICACAO_RISCO is not null
		and cli.NUM_CPF_CNPJ <> 0 
		and cli.NUM_CPF_CNPJ is not null
		and CLI.NOM_PESSOA <> '' -- desconsidera nome em branco
		and CLI.NOM_PESSOA is not null -- desconsidera nome nulo

group by cli.NOM_SEGMENTO, cli.DES_PESSOA

UNION ALL
-- sem classificação TOTAL -------------------
select	' TOTAL' as NOM_SEGMENTO, 
		'TOTAL'	 AS DES_PESSOA,
		count(distinct Cli.NUM_CPF_CNPJ) as QTD_SEM_CLASSIFICACAO,
		0 as QTD_COM_CLASSIFICACAO

from	DM_CLIENTES_CONTRATOS_CVP as CLI
		left join DM_CONTRATOS_CVP as C
			on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
			and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO
where	
		C.COD_STATUS_CONTRATO = 'A'
		and cli.IND_CARGA <> 'D'
		and c.IND_CARGA <> 'D'
		and cli.DES_CLASSIFICACAO_RISCO is null
		and cli.NUM_CPF_CNPJ <> 0 
		and cli.NUM_CPF_CNPJ is not null
		and CLI.NOM_PESSOA <> '' -- desconsidera nome em branco
		and CLI.NOM_PESSOA is not null -- desconsidera nome nulo

UNION ALL 

-- com classificacao TOTAL -------------------
select	' TOTAL' as NOM_SEGMENTO, 
		'TOTAL'	 AS DES_PESSOA,
		0 as QTD_SEM_CLASSIFICACAO,
		count(distinct Cli.NUM_CPF_CNPJ) as QTD_COM_CLASSIFICACAO

from	DM_CLIENTES_CONTRATOS_CVP as CLI
		left join DM_CONTRATOS_CVP as C
			on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
			and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO
where	
		C.COD_STATUS_CONTRATO = 'A'
		and cli.IND_CARGA <> 'D'
		and c.IND_CARGA <> 'D'
		and cli.DES_CLASSIFICACAO_RISCO is not null
		and cli.NUM_CPF_CNPJ <> 0 
		and cli.NUM_CPF_CNPJ is not null
		and CLI.NOM_PESSOA <> '' -- desconsidera nome em branco
		and CLI.NOM_PESSOA is not null -- desconsidera nome nulo

) as A
group by NOM_SEGMENTO,
		DES_PESSOA
GO
 
IF OBJECT_ID('[dbo].[VW_Cliente_Aporte]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_Cliente_Aporte];
GO
CREATE	VIEW	VW_Cliente_Aporte AS

---------------------------------------------------------------------------------------------------
--		Base inicial com os dados necessarios para geração de Dashboard CA
---------------------------------------------------------------------------------------------------
	   
SELECT	Z.NUM_CPF_CNPJ,
        K.DES_MODALIDADE,
        CONVERT(DATE, SC.DTA_BAIXA) AS DT_PAGAMENTO,
        CONVERT(FLOAT, SUM(CASE WHEN CC.NAT_COBERTURA = 'RENDA' AND SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('ES') THEN SC.VLR_DET_BAIXA ELSE 0 END)) AS VL_PAGO_APORTES
FROM	DMDB11..DM_059_COBRANCA C WITH (NOLOCK)

INNER JOIN DMDB11..DM_040_COB_CONTRIBUICAO CC WITH (NOLOCK)
ON  CC.SUK_CONTRIBUICAO = C.SUK_CONTRIBUICAO
AND NAT_COBERTURA IN ('RENDA', 'RISCO') 
AND SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('RE','ES')

LEFT JOIN DMDB11..DM_046_STA_COBRANCA SC  WITH (NOLOCK)
ON SC.SUK_STA_COBRANCA = C.SUK_STA_COBRANCA
AND SUBSTRING(SC.STA_COBRANCA_DET,1,2) IN ('BP','BT')

LEFT JOIN DMDB11..DM_008_PRODUTO PROD WITH (NOLOCK)
ON C.SUK_PRODUTO = PROD.SUK_PRODUTO

LEFT JOIN DMDB11..DM_012_CERTIFICADO CE WITH (NOLOCK)
ON C.SUK_CERT_PARTICIPANTE = CE.SUK_CERTIFICADO

LEFT JOIN DMDB41..DM_CLIENTES_CONTRATOS_CVP Z WITH (NOLOCK)
ON CE.NUM_CERTIFICADO = Z.NUM_CERTIFICADO 

LEFT JOIN DMDB41..DM_CONTRATOS_CVP X WITH (NOLOCK)
ON CE.NUM_CERTIFICADO = X.NUM_CERTIFICADO AND X.NOM_SEGMENTO = 'PREVIDENCIA'

LEFT JOIN DMDB41..VW_PRODUTOS_CVP K WITH (NOLOCK)
ON X.COD_PRODUTO = K.COD_PRODUTO AND K.DES_SEGMENTO = 'PREVIDENCIA'

WHERE  CONVERT(DATE, SC.DTA_BAIXA) BETWEEN '2022-12-01' AND '2022-12-31'

GROUP BY Z.NUM_CPF_CNPJ, K.DES_MODALIDADE, SC.DTA_BAIXA
--        ORDER BY DT_PAGAMENTO DESC

---------------------------------------------------------------------------------------------------
--	FIM DO PROGRAMA
---------------------------------------------------------------------------------------------------

GO
 
IF OBJECT_ID('[dbo].[VW_Cliente_Aporte_PGBL]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_Cliente_Aporte_PGBL];
GO
		CREATE	VIEW	VW_Cliente_Aporte_PGBL AS

---------------------------------------------------------------------------------------------------
--		Base inicial com os dados necessarios para geração de Dashboard CA
---------------------------------------------------------------------------------------------------

WITH BASE AS  (	select 
				P.NUM_CPF_CNPJ
				,DES_MODALIDADE
				,VLR_RESERVA_PGBL = SUM (	CASE	WHEN DES_MODALIDADE = 'PGBL'
											THEN	cast(B.VLR_RESERVA as decimal(20,2)) + cast(B.VLR_RESERVA_EMP as decimal(20,2)) 
											ELSE	0
											END)
				,VLR_RESERVA_VGBL = SUM (	CASE	WHEN DES_MODALIDADE = 'VGBL'
											THEN	cast(B.VLR_RESERVA as decimal(20,2)) + cast(B.VLR_RESERVA_EMP as decimal(20,2)) 
											ELSE	0
											END)
				,VLR_RESERVA_PVGBL = SUM (	CASE	WHEN DES_MODALIDADE IN ( 'VGBL' ,  'PVGBL')
											THEN	cast(B.VLR_RESERVA as decimal(20,2)) + cast(B.VLR_RESERVA_EMP as decimal(20,2)) 
											ELSE	0
											END)

				FROM	DMDB11.DBO.DM_074_BASE_CARTEIRA B   WITH ( NOLOCK )

				JOIN	DMDB11.DBO.DM_012_CERTIFICADO	C   WITH ( NOLOCK )
				ON		C.SUK_CERTIFICADO = B.SUK_CERTIFICADO

				JOIN	DMDB11.DBO.DM_001_PESSOA		P   WITH ( NOLOCK )
				ON		P.SUK_PESSOA = B.SUK_PESSOA

				JOIN	DMDB11.DBO.DM_008_PRODUTO		PR  WITH ( NOLOCK )
				ON		B.SUK_PRODUTO = PR.SUK_PRODUTO

				where	C.COD_SIT_CERTIFICADO in ('A', 'U')
				AND		DES_MODALIDADE IN ( 'VGBL' ,  'PGBL')
				GROUP BY 
						P.NUM_CPF_CNPJ
						,DES_MODALIDADE
)

---------------------------------------------------------------------------------------------------
--			RECUPERA AS INFORMAÇÕES
---------------------------------------------------------------------------------------------------

SELECT		Z.NUM_CPF_CNPJ,
			K.DES_MODALIDADE,
			CONVERT(DATE, SC.DTA_BAIXA) AS DT_PAGAMENTO,

			CONVERT(FLOAT, SUM(	CASE 
								WHEN YEAR(SC.DTA_BAIXA) = 2021 AND CC.NAT_COBERTURA = 'RENDA' AND SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('ES') 
								THEN SC.VLR_DET_BAIXA 
								ELSE 0 END)) AS VL_PAGO_APORTES_2021 ,

			CONVERT(FLOAT, SUM(	CASE 
								WHEN YEAR(SC.DTA_BAIXA) = 2022 AND CC.NAT_COBERTURA = 'RENDA' AND SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('ES') 
								THEN SC.VLR_DET_BAIXA 
								ELSE 0 END)) AS VL_PAGO_APORTES_2022 ,
			R.VLR_RESERVA_PGBL ,
			R.VLR_RESERVA_VGBL ,
			R.VLR_RESERVA_PVGBL 

FROM		DMDB11..DM_059_COBRANCA C WITH (NOLOCK)

JOIN		DMDB11..DM_040_COB_CONTRIBUICAO CC WITH (NOLOCK)
ON			CC.SUK_CONTRIBUICAO = C.SUK_CONTRIBUICAO
AND			NAT_COBERTURA IN ('RENDA') 
AND			SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('ES')

--AND			NAT_COBERTURA IN ('RENDA', 'RISCO') 
--AND			SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('RE','ES')

INNER JOIN	DMDB11..DM_046_STA_COBRANCA SC  WITH (NOLOCK)
ON			SC.SUK_STA_COBRANCA = C.SUK_STA_COBRANCA
AND			SUBSTRING(SC.STA_COBRANCA_DET,1,2) IN ('BP','BT')

LEFT JOIN	DMDB11..DM_008_PRODUTO PROD WITH (NOLOCK)
ON			C.SUK_PRODUTO = PROD.SUK_PRODUTO

LEFT JOIN	 DMDB11..DM_012_CERTIFICADO CE WITH (NOLOCK)
ON			C.SUK_CERT_PARTICIPANTE = CE.SUK_CERTIFICADO

LEFT JOIN	DMDB41..DM_CLIENTES_CONTRATOS_CVP Z WITH (NOLOCK)
ON			CE.NUM_CERTIFICADO = Z.NUM_CERTIFICADO 

LEFT JOIN	BASE R WITH (NOLOCK)
ON			R.NUM_CPF_CNPJ = Z.NUM_CPF_CNPJ

LEFT JOIN	DMDB41..DM_CONTRATOS_CVP X WITH (NOLOCK)
ON			CE.NUM_CERTIFICADO	=	X.NUM_CERTIFICADO 
AND			X.NOM_SEGMENTO		=	'PREVIDENCIA'

LEFT JOIN	DMDB41..VW_PRODUTOS_CVP K WITH (NOLOCK)
ON			X.COD_PRODUTO		=	K.COD_PRODUTO 
AND			K.DES_SEGMENTO		=	'PREVIDENCIA'
AND			K.DES_MODALIDADE	=	R.DES_MODALIDADE

WHERE	(	(CONVERT(DATE, SC.DTA_BAIXA) BETWEEN '2021-12-01' AND '2021-12-31' )
	OR		(CONVERT(DATE, SC.DTA_BAIXA) BETWEEN '2022-12-01' AND '2022-12-31' ) )

AND			R.VLR_RESERVA_VGBL	=	0 
AND			R.VLR_RESERVA_PGBL	>	10000

GROUP BY	Z.NUM_CPF_CNPJ, 
			K.DES_MODALIDADE, 
			SC.DTA_BAIXA,
			R.VLR_RESERVA_PGBL,
			R.VLR_RESERVA_VGBL,
			R.VLR_RESERVA_PVGBL 

-----------------------------
GO
 
IF OBJECT_ID('[dbo].[VW_Cliente_Aporte_PVGBL]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_Cliente_Aporte_PVGBL];
GO
CREATE	VIEW	VW_Cliente_Aporte_PVGBL AS

---------------------------------------------------------------------------------------------------
--		Base inicial com os dados necessarios para geração de Dashboard CA
---------------------------------------------------------------------------------------------------

WITH BASE AS  (	select 
				P.NUM_CPF_CNPJ
--				,DES_MODALIDADE
				,VLR_RESERVA_PGBL = SUM (	CASE	WHEN DES_MODALIDADE = 'PGBL'
											THEN	cast(B.VLR_RESERVA as decimal(20,2)) + cast(B.VLR_RESERVA_EMP as decimal(20,2)) 
											ELSE	0
											END)
				,VLR_RESERVA_VGBL = SUM (	CASE	WHEN DES_MODALIDADE = 'VGBL'
											THEN	cast(B.VLR_RESERVA as decimal(20,2)) + cast(B.VLR_RESERVA_EMP as decimal(20,2)) 
											ELSE	0
											END)
				,VLR_RESERVA_PVGBL = SUM (	CASE	WHEN DES_MODALIDADE IN ( 'VGBL' ,  'PVGBL')
											THEN	cast(B.VLR_RESERVA as decimal(20,2)) + cast(B.VLR_RESERVA_EMP as decimal(20,2)) 
											ELSE	0
											END)

				FROM	DMDB11.DBO.DM_074_BASE_CARTEIRA B   WITH ( NOLOCK )

				JOIN	DMDB11.DBO.DM_012_CERTIFICADO	C   WITH ( NOLOCK )
				ON		C.SUK_CERTIFICADO = B.SUK_CERTIFICADO

				JOIN	DMDB11.DBO.DM_001_PESSOA		P   WITH ( NOLOCK )
				ON		P.SUK_PESSOA = B.SUK_PESSOA

				JOIN	DMDB11.DBO.DM_008_PRODUTO		PR  WITH ( NOLOCK )
				ON		B.SUK_PRODUTO = PR.SUK_PRODUTO

				where	C.COD_SIT_CERTIFICADO in ('A', 'U')
				AND		DES_MODALIDADE IN ( 'VGBL' ,  'PGBL')
				GROUP BY 
						P.NUM_CPF_CNPJ
	--					,DES_MODALIDADE
)

---------------------------------------------------------------------------------------------------
--			RECUPERA AS INFORMAÇÕES
---------------------------------------------------------------------------------------------------

SELECT		Z.NUM_CPF_CNPJ,
			K.DES_MODALIDADE,
			CONVERT(DATE, SC.DTA_BAIXA) AS DT_PAGAMENTO,

			CONVERT(FLOAT, SUM(	CASE 
								WHEN YEAR(SC.DTA_BAIXA) = 2021 AND CC.NAT_COBERTURA = 'RENDA' AND SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('ES') 
								THEN SC.VLR_DET_BAIXA 
								ELSE 0 END)) AS VL_PAGO_APORTES_2021 ,

			CONVERT(FLOAT, SUM(	CASE 
								WHEN YEAR(SC.DTA_BAIXA) = 2022 AND CC.NAT_COBERTURA = 'RENDA' AND SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('ES') 
								THEN SC.VLR_DET_BAIXA 
								ELSE 0 END)) AS VL_PAGO_APORTES_2022 ,
			R.VLR_RESERVA_PGBL ,
			R.VLR_RESERVA_VGBL ,
			R.VLR_RESERVA_PVGBL 

FROM		DMDB11..DM_059_COBRANCA C WITH (NOLOCK)

JOIN		DMDB11..DM_040_COB_CONTRIBUICAO CC WITH (NOLOCK)
ON			CC.SUK_CONTRIBUICAO = C.SUK_CONTRIBUICAO
AND			NAT_COBERTURA IN ('RENDA') 
AND			SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('ES')

--AND			NAT_COBERTURA IN ('RENDA', 'RISCO') 
--AND			SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('RE','ES')

INNER JOIN	DMDB11..DM_046_STA_COBRANCA SC  WITH (NOLOCK)
ON			SC.SUK_STA_COBRANCA = C.SUK_STA_COBRANCA
AND			SUBSTRING(SC.STA_COBRANCA_DET,1,2) IN ('BP','BT')

LEFT JOIN	DMDB11..DM_008_PRODUTO PROD WITH (NOLOCK)
ON			C.SUK_PRODUTO = PROD.SUK_PRODUTO

LEFT JOIN	 DMDB11..DM_012_CERTIFICADO CE WITH (NOLOCK)
ON			C.SUK_CERT_PARTICIPANTE = CE.SUK_CERTIFICADO

LEFT JOIN	DMDB41..DM_CLIENTES_CONTRATOS_CVP Z WITH (NOLOCK)
ON			CE.NUM_CERTIFICADO = Z.NUM_CERTIFICADO 

LEFT JOIN	BASE R WITH (NOLOCK)
ON			R.NUM_CPF_CNPJ = Z.NUM_CPF_CNPJ

LEFT JOIN	DMDB41..DM_CONTRATOS_CVP X WITH (NOLOCK)
ON			CE.NUM_CERTIFICADO	=	X.NUM_CERTIFICADO 
AND			X.NOM_SEGMENTO		=	'PREVIDENCIA'

LEFT JOIN	DMDB41..VW_PRODUTOS_CVP K WITH (NOLOCK)
ON			X.COD_PRODUTO		=	K.COD_PRODUTO 
AND			K.DES_SEGMENTO		=	'PREVIDENCIA'
--AND			K.DES_MODALIDADE	=	R.DES_MODALIDADE

WHERE	(	(CONVERT(DATE, SC.DTA_BAIXA) BETWEEN '2021-12-01' AND '2021-12-31' )
	OR		(CONVERT(DATE, SC.DTA_BAIXA) BETWEEN '2022-12-01' AND '2022-12-31' ) )

AND			R.VLR_RESERVA_VGBL	>	0 
AND			R.VLR_RESERVA_PGBL	>	0
AND			R.VLR_RESERVA_PVGBL >   10000 

GROUP BY	Z.NUM_CPF_CNPJ, 
			K.DES_MODALIDADE, 
			SC.DTA_BAIXA,
			R.VLR_RESERVA_PGBL,
			R.VLR_RESERVA_VGBL,
			R.VLR_RESERVA_
GO
 
IF OBJECT_ID('[dbo].[VW_Cliente_Aporte_VGBL]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_Cliente_Aporte_VGBL];
GO
CREATE	VIEW	VW_Cliente_Aporte_VGBL AS

---------------------------------------------------------------------------------------------------
--		Base inicial com os dados necessarios para geração de Dashboard CA
---------------------------------------------------------------------------------------------------

WITH BASE AS  (	select 
				P.NUM_CPF_CNPJ
				,DES_MODALIDADE
				,VLR_RESERVA_PGBL = SUM (	CASE	WHEN DES_MODALIDADE = 'PGBL'
											THEN	cast(B.VLR_RESERVA as decimal(20,2)) + cast(B.VLR_RESERVA_EMP as decimal(20,2)) 
											ELSE	0
											END)
				,VLR_RESERVA_VGBL = SUM (	CASE	WHEN DES_MODALIDADE = 'VGBL'
											THEN	cast(B.VLR_RESERVA as decimal(20,2)) + cast(B.VLR_RESERVA_EMP as decimal(20,2)) 
											ELSE	0
											END)
				,VLR_RESERVA_PVGBL = SUM (	CASE	WHEN DES_MODALIDADE IN ( 'VGBL' ,  'PVGBL')
											THEN	cast(B.VLR_RESERVA as decimal(20,2)) + cast(B.VLR_RESERVA_EMP as decimal(20,2)) 
											ELSE	0
											END)

				FROM	DMDB11.DBO.DM_074_BASE_CARTEIRA B   WITH ( NOLOCK )

				JOIN	DMDB11.DBO.DM_012_CERTIFICADO	C   WITH ( NOLOCK )
				ON		C.SUK_CERTIFICADO = B.SUK_CERTIFICADO

				JOIN	DMDB11.DBO.DM_001_PESSOA		P   WITH ( NOLOCK )
				ON		P.SUK_PESSOA = B.SUK_PESSOA

				JOIN	DMDB11.DBO.DM_008_PRODUTO		PR  WITH ( NOLOCK )
				ON		B.SUK_PRODUTO = PR.SUK_PRODUTO

				where	C.COD_SIT_CERTIFICADO in ('A', 'U')
				AND		DES_MODALIDADE IN ( 'VGBL' ,  'PGBL')
				GROUP BY 
						P.NUM_CPF_CNPJ
						,DES_MODALIDADE
)

---------------------------------------------------------------------------------------------------
--			RECUPERA AS INFORMAÇÕES
---------------------------------------------------------------------------------------------------

SELECT		Z.NUM_CPF_CNPJ,
			K.DES_MODALIDADE,
			CONVERT(DATE, SC.DTA_BAIXA) AS DT_PAGAMENTO,

			CONVERT(FLOAT, SUM(	CASE 
								WHEN YEAR(SC.DTA_BAIXA) = 2021 AND CC.NAT_COBERTURA = 'RENDA' AND SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('ES') 
								THEN SC.VLR_DET_BAIXA 
								ELSE 0 END)) AS VL_PAGO_APORTES_2021 ,

			CONVERT(FLOAT, SUM(	CASE 
								WHEN YEAR(SC.DTA_BAIXA) = 2022 AND CC.NAT_COBERTURA = 'RENDA' AND SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('ES') 
								THEN SC.VLR_DET_BAIXA 
								ELSE 0 END)) AS VL_PAGO_APORTES_2022 ,
			R.VLR_RESERVA_PGBL ,
			R.VLR_RESERVA_VGBL ,
			R.VLR_RESERVA_PVGBL 

FROM		DMDB11..DM_059_COBRANCA C WITH (NOLOCK)

JOIN		DMDB11..DM_040_COB_CONTRIBUICAO CC WITH (NOLOCK)
ON			CC.SUK_CONTRIBUICAO = C.SUK_CONTRIBUICAO
AND			NAT_COBERTURA IN ('RENDA') 
AND			SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('ES')

--AND			NAT_COBERTURA IN ('RENDA', 'RISCO') 
--AND			SUBSTRING(CC.TP_CONTRIBUICAO,1,2) IN ('RE','ES')

INNER JOIN	DMDB11..DM_046_STA_COBRANCA SC  WITH (NOLOCK)
ON			SC.SUK_STA_COBRANCA = C.SUK_STA_COBRANCA
AND			SUBSTRING(SC.STA_COBRANCA_DET,1,2) IN ('BP','BT')

LEFT JOIN	DMDB11..DM_008_PRODUTO PROD WITH (NOLOCK)
ON			C.SUK_PRODUTO = PROD.SUK_PRODUTO

LEFT JOIN	 DMDB11..DM_012_CERTIFICADO CE WITH (NOLOCK)
ON			C.SUK_CERT_PARTICIPANTE = CE.SUK_CERTIFICADO

LEFT JOIN	DMDB41..DM_CLIENTES_CONTRATOS_CVP Z WITH (NOLOCK)
ON			CE.NUM_CERTIFICADO = Z.NUM_CERTIFICADO 

LEFT JOIN	BASE R WITH (NOLOCK)
ON			R.NUM_CPF_CNPJ = Z.NUM_CPF_CNPJ

LEFT JOIN	DMDB41..DM_CONTRATOS_CVP X WITH (NOLOCK)
ON			CE.NUM_CERTIFICADO	=	X.NUM_CERTIFICADO 
AND			X.NOM_SEGMENTO		=	'PREVIDENCIA'

LEFT JOIN	DMDB41..VW_PRODUTOS_CVP K WITH (NOLOCK)
ON			X.COD_PRODUTO		=	K.COD_PRODUTO 
AND			K.DES_SEGMENTO		=	'PREVIDENCIA'
AND			K.DES_MODALIDADE	=	R.DES_MODALIDADE

WHERE	(	(CONVERT(DATE, SC.DTA_BAIXA) BETWEEN '2021-12-01' AND '2021-12-31' )
	OR		(CONVERT(DATE, SC.DTA_BAIXA) BETWEEN '2022-12-01' AND '2022-12-31' ) )

AND			R.VLR_RESERVA_PGBL	=	0 
AND			R.VLR_RESERVA_VGBL	>	50000

GROUP BY	Z.NUM_CPF_CNPJ, 
			K.DES_MODALIDADE, 
			SC.DTA_BAIXA,
			R.VLR_RESERVA_PGBL,
			R.VLR_RESERVA_VGBL,
			R.VLR_RESERVA_PVGBL 

-------------------------------
GO
 
IF OBJECT_ID('[dbo].[VW_Cliente_Cross_Agrupado]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_Cliente_Cross_Agrupado];
