CREATE VIEW [dbo].VW_Cliente_Cross_Agrupado AS
---------------------------------------------------------------------------------------------------
--		Base inicial com os dados necessarios para geração de Dashboard CA
---------------------------------------------------------------------------------------------------
SELECT 
		case when DES_CROSS_PRODUTOS LIKE '%VIDA%'
			 then 1 
			 else null 
			 end as VIDA,
		case when DES_CROSS_PRODUTOS LIKE '%PRESTAMISTA%'
			 then 1 
			 else null 
			 end as PRESTAMISTA,
		case when DES_CROSS_PRODUTOS LIKE '%PREVIDENCIA%'
			 then 1 
			 else null 
			 end as PREVIDENCIA,
		count(distinct NUM_CPF_CNPJ) as QTD_CLIENTES
from	DMDB41..[DM_CLIENTE_AGREGADO_CROSS_CVP] WITH ( NOLOCK ) 
where	COD_STATUS_CONTRATO = 'A'
and		DES_CROSS_PRODUTOS is not null
group by DES_CROSS_PRODUTOS

GO
 
