CREATE		VIEW [dbo].[VW_Cliente_Cross_Agrupado_New] AS

---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_Cliente_Cross_Agrupado_New
--
--					SQL14\DMCVP\DMDB41
--
--		OBJETIVO:	Gera Base para realização de Cross de Produtos "Somente contratos Ativos"
--
---------------------------------------------------------------------------------------------------
--		AUTOR	:	William	Koloda	/ SILVIO J®
--		DATA	:	02/02/2022 - Criação	
---------------------------------------------------------------------------------------------------


---------------------------------------------------------------------------------------------------
--		BASE VIDA 
---------------------------------------------------------------------------------------------------

WITH BASE_VIDA AS (

select distinct	
		'VIDA' as NOM_SEGMENTO
		,A.COD_TIPO_PESSOA
		,A.NUM_CPF_CNPJ
		,'S' as FLAG_VIDA
from	DMDB41..DM_CLIENTES_CONTRATOS_CVP A WITH ( NOLOCK ) 
join	DMDB41..DM_CONTRATOS_CVP B  WITH ( NOLOCK ) 
on		A.NOM_SEGMENTO = B.NOM_SEGMENTO 
and		A.NUM_CERTIFICADO = B.NUM_CERTIFICADO
where	A.NOM_SEGMENTO = 'VIDA'
and		A.DES_PESSOA = 'SEGURADO TITULAR'
and		B.COD_STATUS_CONTRATO = 'A'
) ,

---------------------------------------------------------------------------------------------------
--		BASE PRESTA
---------------------------------------------------------------------------------------------------
BASE_PRES	AS	(

select distinct
		'PRESTAMISTA' as NOM_SEGMENTO
		,A.COD_TIPO_PESSOA
		,A.NUM_CPF_CNPJ
		,'S' as FLAG_PRES
from	DMDB41..DM_CLIENTES_CONTRATOS_CVP A WITH ( NOLOCK ) 
join	DMDB41..DM_CONTRATOS_CVP B  WITH ( NOLOCK ) 
on		A.NOM_SEGMENTO = B.NOM_SEGMENTO 
and		A.NUM_CERTIFICADO = B.NUM_CERTIFICADO
where	A.NOM_SEGMENTO = 'PRESTAMISTA'
and		A.DES_PESSOA = 'SEGURADO TITULAR'
and		B.COD_STATUS_CONTRATO = 'A'
) ,

---------------------------------------------------------------------------------------------------
--		BASE PREVI
---------------------------------------------------------------------------------------------------
BASE_PREV_F	AS	(
select distinct
		'PREVIDENCIA' as NOM_SEGMENTO
		,A.COD_TIPO_PESSOA
		,A.NUM_CPF_CNPJ
		,'S' as FLAG_PREV
from	DMDB41..DM_CLIENTES_CONTRATOS_CVP A WITH ( NOLOCK ) 
join	DMDB41..DM_CONTRATOS_CVP B  WITH ( NOLOCK ) 
on		A.NOM_SEGMENTO = B.NOM_SEGMENTO 
and		A.NUM_CERTIFICADO = B.NUM_CERTIFICADO
where	A.NOM_SEGMENTO = 'PREVIDENCIA'
and		A.DES_PESSOA = 'SEGURADO TITULAR'
and		B.COD_STATUS_CONTRATO = 'A'
) ,

---------------------------------------------------------------------------------------------------
--		BASE PREVI
---------------------------------------------------------------------------------------------------
BASE_PREV_J	AS	(
select distinct
		'PREVIDENCIA' as NOM_SEGMENTO
		,A.COD_TIPO_PESSOA
		,A.NUM_CPF_CNPJ
		,'S' as FLAG_PREV
from	DMDB41..DM_CLIENTES_CONTRATOS_CVP A WITH ( NOLOCK ) 
join	DMDB41..DM_CONTRATOS_CVP B  WITH ( NOLOCK ) 
on		A.NOM_SEGMENTO = B.NOM_SEGMENTO 
and		A.NUM_CERTIFICADO = B.NUM_CONTRATO_PAI
where	A.NOM_SEGMENTO = 'PREVIDENCIA'
and		A.DES_PESSOA = 'SEGURADO TITULAR'
and		B.COD_STATUS_CONTRATO = 'A'
),

---------------------------------------------------------------------------------------------------
--		BASE PREVI
---------------------------------------------------------------------------------------------------
BASE_PREV	AS	(
select	A.*
from	(	select * from BASE_PREV_F
			union all
			select * from BASE_PREV_J
		) A
),

---------------------------------------------------------------------------------------------------
--		BASE CLIENTE
---------------------------------------------------------------------------------------------------
BASE_CLIENTES	AS	(
select distinct A.NOM_SEGMENTO, A.NUM_CPF_CNPJ, COD_TIPO_PESSOA
from	(
			select NOM_SEGMENTO, NUM_CPF_CNPJ, COD_TIPO_PESSOA from BASE_PREV

			union all

			select NOM_SEGM
GO
 
