CREATE VIEW [DBO].[VW_CLIENTE_VOLUMETRIA] AS
---------------------------------------------------------------------------------------------------
--		select top 80 * from VW_CLIENTE_VOLUMETRIA 
---------------------------------------------------------------------------------------------------
--
--		DEFINICAO
--
--			2021 e 2022
--			pm e pu
--			pj pf
--
--			Vida_ 
--			Quantidade total de clientes PJ e PF;
--			Quantidade de propostas;
--			Total de venda R$ do produto e os subprodutos (vida da gente, vida mulher etc.)
--			Canal de venda.
--			Ticket médio  
--
--			Prestamista  
--			Quantidade total de clientes PJ e PF;
--			Quantidade de propostas;
--			Total de vendas R$ 
--			subprodutos: Verificar à qual operação de crédito estão vinculados.  
--			(Exemplo: Prestamista no Consorcio, Prestamista Dívida Zero na Op. Crédito Consignado)
--			Canal de venda
--			Ticket médio 
--
--			Previdência  
--			Quantidade total de clientes PJ e PF;
--			Quantidade de propostas;
--			Total de vendas R$
--			subprodutos: 
--			Canal de venda
--			Ticket médio (Considerando o valor médio mensal) 
--			Pagamento Único e Médio)
--			Ticket médio de aporte realizados.
--
--
--
---------------------------------------------------------------------------------------------------
--	
--
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  CRIAÇÃO
--		DATA	:	03/02/2023	
---------------------------------------------------------------------------------------------------

---------------------------------------------------------------------------------------------------
--		RECUPERA VENDAS DO PRESTA AIC
---------------------------------------------------------------------------------------------------
WITH	BASE  AS ( 

--DROP TABLE IF EXISTS ##BASE 

SELECT	DISTINCT 
		'PRESTAMISTA        '				AS	SEGMENTO,
		CONVERT(VARCHAR(20),COD_PROPOSTA)	AS	NUM_PROPOSTA,
		CASE WHEN TIP_PESSOA = 1 
			 THEN 'PF' 
			 ELSE 'PJ' 
		END								AS	COD_TIPO_PESSOA,
		AIC.DTA_VENDA					AS	DTA_PROPOSTA,
		CASE	WHEN P.COD_PRODUTO IN (7761,7762)						    						THEN 'Dívida Zero' 
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA - CAIXA SIM'					THEN 'Caixa Sim'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA - DÍVIDA ZERO'					THEN 'Dívida Zero'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA DIVIDA ZERO - CCA'				THEN 'Dívida Zero'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA CONTA CORRENTE'				THEN 'Conta Corrente'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA VIDA DO PRODUTOR RURAL - PF'	THEN 'Prestamista Rural'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA VIDA DO PRODUTOR RURAL - PJ'	THEN 'Prestamista Rural'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA CAIXA SIM'						THEN 'Caixa Sim'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA CONTA CORRENTE PF'				THEN 'Conta Corrente'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA CONTA CORRENTE PJ'				THEN 'Conta Corrente'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA MICROSSEGURO PF - CAIXA TEM'	THEN 'Microseguro'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA MICROSSEGURO PJ - CAIXA TEM'	THEN 'Microseguro'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA MINISTERIO DO EXERCITO'		THEN 'Prestamista Exercito'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA PJ'							THEN 'Prestamista PJ'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA RURAL PJ'						THEN 'Prestamista Rural'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA RURAL PF'						THEN 'Prestamista Rural'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'SEGURO DIVIDA ZERO'						THEN 'Dívida Zero'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'SEGURO PRESTAMISTA PJ'						THEN 'Prestamista PJ'
				WHEN LTRIM(RTRIM(UPPER(NOM_PRODUTO))) = 'PRESTAMISTA CONSÓRCIO AUTO'				THEN 'Consór
GO
 
