CREATE VIEW [dbo].[VW_CLIENTES_CONTRATOS_CVP] as (

 select
 c.NUM_CERTIFICADO as num_contrato, --num contrato é sempre o certificiado
 a.NUM_CPF_CNPJ,
 p.COD_RAMO,
 p.DES_PRODUTO,
 p.EMPRESA,
 p.NOME_BU,
 case  c.NOM_SEGMENTO 
  when 'VIDA' then 'SIAS'
  when 'PREVIDENCIA' then 'KIPREV'
  when 'PRESTAMISTA' then 'SMART' end as SISTEMA,
 c.NOM_SEGMENTO AS NOME_SEGMENTO,
 c.NOM_SEGMENTO as SEGMENTO,
 c.NUM_CERTIFICADO AS CERTIFICADO01,
 c.NUM_CONTRATO_PAI,
 c.NUM_CONTRATO_FILHO,
 c.NUM_PROPOSTA,
 c.NUM_APOLICE,
 c.NUM_CONTRATO_TERC,
 c.NUM_PLANO,
 c.NUM_TITULO,
 c.NUM_SERIE,
 c.NUM_MOD_PLANO,
 c.COD_PRODUTO,
 c.COD_STATUS_CONTRATO,
 c.NUM_PRAZO_CONTRATO,
 c.COD_AGENCIA,
 c.COD_AGENCIA_COBRANCA,
 c.DTA_INICIO_VIGENCIA,
 c.DTA_FIM_VIGENCIA,
 c.DTA_ENCERRAMENTO,
 c.DTA_QUITACAO as DTH_QUITACAO,
 c.DTA_EMISSAO_PROPOSTA as DTH_EMISSAO_PROPOSTA,
 c.DTA_EMISSAO_CONTRATO as DTH_EMISSAO_CONTRATO,
 c.DTA_VENDA as DTH_VENDA,
 c.DTA_ASSINATURA as DTH_ASSINATURA,
 c.DTA_AVERBACAO as DTH_AVERBACAO,
 c.DTA_CANCELAMENTO as DTH_CANCELAMENTO,
 c.VLR_IS,
 c.VLR_PREMIO,
 c.VLR_PMBAC,
 c.VLR_PMBAC_EMP,
 c.VLR_PMBC,
 c.VLR_CARREGAMENTO_SAIDA,
 c.IND_CONTRATO_RENOVACAO,
 c.DES_SITUACAO,
 c.DES_MOTIVO_CANCEL,
 c.COD_CANAL_VENDA,
 c.DES_CANAL_VENDA,
 c.COD_CANAL_VENDA_COMERCIAL,
 c.DES_CANAL_VENDA_COMERCIAL,
 c.COD_SUBCANAL_VENDA,
 c.DES_SUB_CANAL_VENDA,
 c.IND_PERIODICIDADE_COBRANCA,
 c.DES_FORMA_PAGAMENTO,
 c.NUM_MATRICULA_VENDEDOR,
 c.QTD_VIDAS_SEGURADAS,
 c.IND_MULTIFUNDO,
 c.VLR_PECULIO,
 c.VLR_PENSAO,
 c.VLR_RENDA,
 c.IND_CARGA,
 'Contrato' as TIPO_CONTRATO,
 Null as DES_DIRETORIA,
 Null as Grupo,
 --dados pessoa--
 a.COD_CBO,
 a.DES_CBO,
 a.COD_CNAE,
 a.DES_CNAE,
 a.COD_PESSOA,
 a.COD_SEGMENTO_CAIXA,
 a.COD_TIPO_PESSOA,
 a.DES_ESTADO_CIVIL,
 a.DES_PESSOA,
 a.DES_RISCO_CAIXA,
 a.IND_GENERO,
 a.IND_NLIST,
 a.IND_PEP,
 a.NOM_FANTASIA,
 a.NOM_PESSOA,
 a.NOM_SEGMENTO,
 a.NOM_SOCIAL,
 -- endereço
 e.TIPO_ENDERECO,
 e.COD_CEP,
 e.NOM_LOGRADOURO,
 e.NUM_LOGRADOURO,
 e.DES_COMPL_ENDERECO,
 e.NOM_BAIRRO,
 e.NOM_CIDADE,
 e.COD_UF,
 -- endereço eletronico
 em.DES_EMAIL,
 em.des_facebook,
 em.des_instagram,
 em.DES_REDE_SOCIAL_OUTRO,
 em.IND_PERMITE_CONTATO_EMAIL,
 em.FLAG_NEGATIVO_CCM
 FROM
  DM_CLIENTES_UNIFICADOS_CVP a
 inner join DM_CLIENTES_ENDERECO_CVP e
 on a.COD_PESSOA_UNIFICADA = e.COD_PESSOA_UNIFICADA
 and e.seq_ENDERECO = (select max(seq_ENDERECO) from DM_CLIENTES_ENDERECO_CVP where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)
 LEFT join dm_clientes_email_cvp em
 on a.COD_PESSOA_UNIFICADA = em.COD_PESSOA_UNIFICADA
 and em.seq_email = (select max(seq_email) from dm_clientes_email_cvp where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)
 inner join DM_CLIENTES_CONTRATOS_CVP b
 on a.NUM_CPF_CNPJ=b.NUM_CPF_CNPJ
 AND B.COD_PESSOA = (SELECT MIN(COD_PESSOA) FROM DM_CLIENTES_CONTRATOS_CVP WHERE NUM_CPF_CNPJ = a.NUM_CPF_CNPJ AND NUM_CERTIFICADO = b.NUM_CERTIFICADO)
 inner join DM_CONTRATOS_CVP c
 on b.NOM_SEGMENTO = c.NOM_SEGMENTO
 and b.NUM_CERTIFICADO = c.NUM_CERTIFICADO
 inner join VW_PRODUTOS_CVP p
 on c.COD_PRODUTO_COMPLETO = p.COD_PRODUTO_COMPLETO
 and c.NOM_SEGMENTO = p.DES_SEGMENTO

)
GO
 
IF OBJECT_ID('[dbo].[VW_CLIENTES_CONTRATOS_CVP_A]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CLIENTES_CONTRATOS_CVP_A];
GO
CREATE VIEW [dbo].[VW_CLIENTES_CONTRATOS_CVP_A] as (
select DISTINCT
  c.NUM_CERTIFICADO as numContrato,  -- Número de contrato, que é o mesmo que o número do certificado
  cast (case c.NOM_SEGMENTO
  when 'VIDA' then 'SIAS'
  when 'PREVIDENCIA' then 'KIPREV'
  when 'PRESTAMISTA' then 'SMART' end as varchar (10)) as sistema,  -- Sistema associado com o segmento (VIDA, PREVIDENCIA, PRESTAMISTA)
  NULL as id,  -- ID não especificado (poderia ser usado para identificação única de registros)
  cast (Case
  when c.NOM_SEGMENTO  = 'VIDA' and p.DES_TIPO_SEGMENTO = 'Bilhete + Microsseguro' then 5
  when c.NOM_SEGMENTO =  'VIDA' and p.DES_TIPO_SEGMENTO <> 'Bilhete + Microsseguro' then 1
  when  c.NOM_SEGMENTO =  'VIDA' and p.DES_TIPO_SEGMENTO is null then 1
  when c.NOM_SEGMENTO  = 'PREVIDENCIA' then 11
  when c.NOM_SEGMENTO  = 'PRESTAMISTA' then 3 end as varchar (20)) as indContrato,  -- Índice de contrato baseado no segmento e tipo de segmento
  NULL as indVinculoPrincipal,  -- Indicador de vínculo principal não especificado
  NULL as numRamoEmissor,  -- Número do ramo emissor não especificado
  c.NUM_APOLICE as numApolice,  -- Número da apólice
  c.NUM_PROPOSTA as numProposta,  -- Número da proposta
  p.COD_PRODUTO as codProduto,  -- Código do produto
  case when c.NUM_CERTIFICADO = 82484130001541 then 'CONTRATO_TESTE' else null end as nomePlano,  -- Nome do plano, especificamente para um número de certificado
  case when c.NUM_CERTIFICADO = 82484130001541 then 1 else null end as numAssistencia,  -- Número de assistência, específico para um número de certificado
  p.COD_PRODUTO as codProdutoBu,  -- Código do produto para o BU
  p.DES_PRODUTO as nomeProdutoBu,  -- Nome do produto para o BU
  case c.NOM_SEGMENTO 
  when 'VIDA' then 'SIAS'
  when 'PREVIDENCIA' then 'KIPREV'
  when 'PRESTAMISTA' then 'SMART' end as nomeBu,  -- Nome do BU, novamente associado com o segmento
  concat(b.num_ddd_telefone,b.NUM_TELEFONE) as numTelefone1,  -- Primeiro número de telefone concatenando DDD e telefone
  concat(b.num_ddd_celular,b.NUM_CELULAR) as numTelefone2,  -- Segundo número de telefone (celular) concatenando DDD e celular
  c.NOM_SEGMENTO as segmento,  -- Segmento do contrato
  a.NUM_CPF_CNPJ as codCpfCnpj,  -- Código CPF ou CNPJ
  'Contrato' as tipoContrato,  -- Tipo de registro, fixo como 'Contrato'
  c.COD_AGENCIA as codAgenciaVenda,  -- Código da agência de venda
  c.COD_AGENCIA_COBRANCA as codAgenciaCobranca,  -- Código da agência de cobrança
  c.DES_CANAL_VENDA as canalVenda,  -- Canal de venda
  case when c.COD_STATUS_CONTRATO = 'A' Then 'Ativo'
    when c.COD_STATUS_CONTRATO = 'I' Then 'Inativo' end as situacaoContrato,  -- Situação do contrato baseado em seu status
  c.DTA_EMISSAO_PROPOSTA as dataHoraEmissaoProposta,  -- Data e hora de emissão da proposta
  c.DTA_EMISSAO_CONTRATO as dataHoraEmissaoContrato,  -- Data e hora de emissão do contrato
  p.DES_PRODUTO as nomeProduto,  -- Nome do produto
  c.IND_PERIODICIDADE_COBRANCA as opcaoPagamento,  -- Opção de pagamento ou periodicidade da cobrança
  c.DES_FORMA_PAGAMENTO as formaPagamento,  -- Forma de pagamento
  NULL as numParcContratadas,              -- Número de parcelas contratadas (campo atualmente não utilizado)
  NULL as numMatriVendedor,                -- Número da matrícula do vendedor (campo atualmente não utilizado)
  NULL as valorIof,                        -- Valor do IOF (campo atualmente não utilizado)
  c.DTA_QUITACAO as dataHoraQuitacao,     -- Data e hora da quitação do contrato
  c.DTA_CANCELAMENTO as dataHoraCancelamento, -- Data e hora do cancelamento do contrato
  NULL as dataHoraDeclinio,                -- Data e hora do declínio (campo atualmente não utilizado)
  c.DTA_ASSINATURA as dataHoraAssinatura,  -- Data e hora da assinatura do contrato
  c.DTA_AVERBACAO as dataHoraAverbacao,    -- Data e hora da averbação do contrato
  c.dta_assinatura as dataHoraEfetivacao,  -- Data e hora da efetivação do contrato
 
GO
 
IF OBJECT_ID('[dbo].[VW_CLIENTES_CONTRATOS_CVP_A_P]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CLIENTES_CONTRATOS_CVP_A_P];
GO
CREATE VIEW [dbo].[VW_CLIENTES_CONTRATOS_CVP_A_P] as (

 select
 c.NUM_CERTIFICADO as numContrato,
 a.NUM_CPF_CNPJ as  codCpfCnpj,
  em.DES_EMAIL as email,
 tel.TIPO_TELEFONE as tipoTelefone,
 tel.NUM_TELEFONE as telefone,
  e.NOM_LOGRADOURO as endereco,
  e.NOM_BAIRRO as bairro,
  e.COD_UF as uf,
  e.NOM_CIDADE as cidade,
  e.COD_CEP as cep,
  case when a.NOM_SOCIAL is null then a.NOM_PESSOA
		else a.NOM_PESSOA end as nomePessoa,
  Case When a.COD_TIPO_PESSOA = 'F'THEN 'PESSOA FISICA' 
		When a.COD_TIPO_PESSOA = 'J'THEN 'PESSOA JURIDICA' END as tipoPessoa,
 '' as indVinculoPrincipal,
 --'' as nomeBancoCobranca,
 --'' as codAgenciaCobranca,
 --'' as numContaCobranca,
 --'' as codOperContaCobranca,
 '' as percentualPactuacaoContrato,
 '' as situacao,
 a.DTA_NASCIMENTO as dthNascimento,
  case  c.NOM_SEGMENTO 
  when 'VIDA' then 'SIAS'
  when 'PREVIDENCIA' then 'KIPREV'
  when 'PRESTAMISTA' then 'SMART' end as sistema,--num contrato é sempre o certificiado
 c.NUM_APOLICE as numApolice,
 c.NUM_PROPOSTA as numProposta,
 p.COD_PRODUTO as codProduto,
 '' as codProdutoBu,
 '' as nomeProdutoBu,
 'Contrato' as tipoContrato,
 c.COD_AGENCIA as codAgenciaVenda,
 c.COD_AGENCIA_COBRANCA as codAgenciaCobranca,
 c.DES_CANAL_VENDA as canalVenda,
 case when c.COD_STATUS_CONTRATO = 'A' Then 'Ativo'
		when c.COD_STATUS_CONTRATO = 'I' Then 'Inativo' end as situacaoContrato,
 c.DTA_EMISSAO_PROPOSTA as dataHoraEmissaoProposta,
 c.DTA_EMISSAO_CONTRATO as dataHoraEmissaoContrato,
 p.DES_PRODUTO as nomeProduto,
 c.IND_PERIODICIDADE_COBRANCA as opcaoPagamento,
 c.DES_FORMA_PAGAMENTO as formaPagamento,
 '' as numParcContratadas,
 '' as numMatriVendedor,
 '' as valorIof,
 c.DTA_QUITACAO as dataHoraQuitacao,
 c.DTA_CANCELAMENTO as dataHoraCancelamento,
 '' as dataHoraDeclinio,
 c.DTA_ASSINATURA as dataHoraAssinatura,
 c.DTA_AVERBACAO as dataHoraAverbacao,
 '' as dataHoraEfetivacao,
 '' as dataHoraIniAmortiz,
 '' as dataHoraRejeicaoProp,
 c.DTA_INICIO_VIGENCIA as dataHoraIniVigencia,
 c.DTA_FIM_VIGENCIA as dataHoraFimVigencia,
 '' as valorBem,
 c.VLR_IS as valorImpSegurada,
 c.DTA_VENDA as dataHoraVenda,
 '' as itemSegurado,
 '' as valorProposta,
 '' as valorFranquia,
 c.VLR_PREMIO  as valorPremioBruto,
 '' as staContratoLegado,
 '' as numUltimosDigCartao,
 '' as dataHoraValidadeCartao,
 '' as nomeBancoCobranca,
 '' as numContaCobranca,
 '' as numDiaVencimento,
 '' as numeroIdlgBu,
 '' as nomeTitularCartao,
 '' as desBandeiraCartao
 from 
 DM_CLIENTES_UNIFICADOS_CVP a
 inner join DM_CLIENTES_ENDERECO_CVP e
 on a.COD_PESSOA_UNIFICADA = e.COD_PESSOA_UNIFICADA
 and e.SEQ_ENDERECO = (select max(SEQ_ENDERECO) 
						from DM_CLIENTES_ENDERECO_CVP 
						where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)


 LEFT join dm_clientes_email_cvp em
 on a.COD_PESSOA_UNIFICADA = em.COD_PESSOA_UNIFICADA
 and em.seq_email = (select max(seq_email) 
					from dm_clientes_email_cvp 
					where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)

LEFT join DM_CLIENTES_TELEFONE_CVP tel
 on a.COD_PESSOA_UNIFICADA = tel.COD_PESSOA_UNIFICADA
 and tel.SEQ_TELEFONE = (select max(SEQ_TELEFONE) 
						from DM_CLIENTES_TELEFONE_CVP 
						where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)

 inner join DM_CLIENTES_CONTRATOS_CVP b
 on a.NUM_CPF_CNPJ=b.NUM_CPF_CNPJ
 inner join DM_CONTRATOS_CVP c
 on b.NOM_SEGMENTO = c.NOM_SEGMENTO
 and b.NUM_CERTIFICADO = c.NUM_CERTIFICADO
 inner join VW_PRODUTOS_CVP p
 on c.COD_PRODUTO = p.COD_PRODUTO
 and c.NOM_SEGMENTO = p.DES_SEGMENTO

)
GO
 
IF OBJECT_ID('[dbo].[VW_CLIENTES_CONTRATOS_CVP_A_Z]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CLIENTES_CONTRATOS_CVP_A_Z];
