CREATE VIEW [dbo].[VW_CLIENTES_CONTRATOS_CVP_A_Z] as (
select DISTINCT
  c.NUM_CERTIFICADO as numContrato,  -- Número de contrato, que é o mesmo que o número do certificado
  cast (case c.NOM_SEGMENTO
  when 'VIDA' then 'SIAS'
  when 'PREVIDENCIA' then 'KIPREV'
  when 'PRESTAMISTA' then 'SMART' end as varchar (10)) as sistema,  -- Sistema associado com o segmento (VIDA, PREVIDENCIA, PRESTAMISTA)
  NULL as id,  -- ID não especificado (poderia ser usado para identificação única de registros)
  cast (Case
  when c.NOM_SEGMENTO  = 'VIDA' and p.DES_TIPO_SEGMENTO = 'Bilhete + Microsseguro' then 5
  when c.NOM_SEGMENTO =  'VIDA' and p.DES_TIPO_SEGMENTO <> 'Bilhete + Microsseguro' then 1
  when  c.NOM_SEGMENTO =  'VIDA' and p.DES_TIPO_SEGMENTO is null then 1
  when c.NOM_SEGMENTO  = 'PREVIDENCIA' then 11
  when c.NOM_SEGMENTO  = 'PRESTAMISTA' then 3 end as varchar (20)) as indContrato,  -- Índice de contrato baseado no segmento e tipo de segmento
  NULL as indVinculoPrincipal,  -- Indicador de vínculo principal não especificado
  NULL as numRamoEmissor,  -- Número do ramo emissor não especificado
  c.NUM_APOLICE as numApolice,  -- Número da apólice
  c.NUM_PROPOSTA as numProposta,  -- Número da proposta
  p.COD_PRODUTO as codProduto,  -- Código do produto
  case when c.NUM_CERTIFICADO = 82484130001541 then 'CONTRATO_TESTE' else null end as nomePlano,  -- Nome do plano, especificamente para um número de certificado
  case when c.NUM_CERTIFICADO = 82484130001541 then 1 else null end as numAssistencia,  -- Número de assistência, específico para um número de certificado
  p.COD_PRODUTO as codProdutoBu,  -- Código do produto para o BU
  p.DES_PRODUTO as nomeProdutoBu,  -- Nome do produto para o BU
  case c.NOM_SEGMENTO 
  when 'VIDA' then 'SIAS'
  when 'PREVIDENCIA' then 'KIPREV'
  when 'PRESTAMISTA' then 'SMART' end as nomeBu,  -- Nome do BU, novamente associado com o segmento
  concat(b.num_ddd_telefone,b.NUM_TELEFONE) as numTelefone1,  -- Primeiro número de telefone concatenando DDD e telefone
  concat(b.num_ddd_celular,b.NUM_CELULAR) as numTelefone2,  -- Segundo número de telefone (celular) concatenando DDD e celular
  c.NOM_SEGMENTO as segmento,  -- Segmento do contrato
  a.NUM_CPF_CNPJ as codCpfCnpj,  -- Código CPF ou CNPJ
  'Contrato' as tipoContrato,  -- Tipo de registro, fixo como 'Contrato'
  c.COD_AGENCIA as codAgenciaVenda,  -- Código da agência de venda
  c.COD_AGENCIA_COBRANCA as codAgenciaCobranca,  -- Código da agência de cobrança
  c.DES_CANAL_VENDA as canalVenda,  -- Canal de venda
  case when c.COD_STATUS_CONTRATO = 'A' Then 'Ativo'
    when c.COD_STATUS_CONTRATO = 'I' Then 'Inativo' end as situacaoContrato,  -- Situação do contrato baseado em seu status
  c.DTA_EMISSAO_PROPOSTA as dataHoraEmissaoProposta,  -- Data e hora de emissão da proposta
  c.DTA_EMISSAO_CONTRATO as dataHoraEmissaoContrato,  -- Data e hora de emissão do contrato
  p.DES_PRODUTO as nomeProduto,  -- Nome do produto
  c.IND_PERIODICIDADE_COBRANCA as opcaoPagamento,  -- Opção de pagamento ou periodicidade da cobrança
  c.DES_FORMA_PAGAMENTO as formaPagamento,  -- Forma de pagamento
  NULL as numParcContratadas,              -- Número de parcelas contratadas (campo atualmente não utilizado)
  NULL as numMatriVendedor,                -- Número da matrícula do vendedor (campo atualmente não utilizado)
  NULL as valorIof,                        -- Valor do IOF (campo atualmente não utilizado)
  c.DTA_QUITACAO as dataHoraQuitacao,     -- Data e hora da quitação do contrato
  c.DTA_CANCELAMENTO as dataHoraCancelamento, -- Data e hora do cancelamento do contrato
  NULL as dataHoraDeclinio,                -- Data e hora do declínio (campo atualmente não utilizado)
  c.DTA_ASSINATURA as dataHoraAssinatura,  -- Data e hora da assinatura do contrato
  c.DTA_AVERBACAO as dataHoraAverbacao,    -- Data e hora da averbação do contrato
  c.dta_assinatura as dataHoraEfetivacao,  -- Data e hora da efetivação do contr
GO
 
IF OBJECT_ID('[dbo].[VW_CLIENTES_CONTRATOS_SIMILARIDADE_TERR]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CLIENTES_CONTRATOS_SIMILARIDADE_TERR];
GO



CREATE VIEW [dbo].[VW_CLIENTES_CONTRATOS_SIMILARIDADE_TERR] AS 
WITH CLIENTES_CONTRATOS_SIMILARES AS
(
	SELECT  
		  --DISTINCT 
		  CC.NUM_CPF_CNPJ
		, CC.NOM_SEGMENTO
		, CC.COD_PESSOA
		, CC.DES_PESSOA
		, CC.COD_TIPO_PESSOA
		, CC.NOM_PESSOA
		, CC.NOM_FANTASIA
		, CC.NOM_SOCIAL
		, CC.COD_CBO
		, CC.DES_CBO
		, CC.COD_CNAE
		, CC.DES_CNAE
		, CC.DTA_NASCIMENTO
		, CC.DTA_ABERTURA
		, CC.NUM_IDADE
		, CC.VLR_RENDA_FAMILIAR
		, CC.VLR_RENDA_INDIVIDUAL
		, CC.VLR_FATURAMENTO_ANUAL
		, CC.NOM_LOGRADOURO
		, CC.NUM_LOGRADOURO
		, CC.DES_COMPL_ENDERECO
		, CC.NOM_BAIRRO
		, CC.NOM_CIDADE
		, CC.COD_CEP
		, CC.COD_UF
		, CC.NUM_DDD_TELEFONE
		, CC.NUM_TELEFONE
		, CC.NUM_DDD_CELULAR
		, CC.NUM_CELULAR
		, CC.DES_EMAIL
		, CC.DES_FACEBOOK
		, CC.DES_INSTAGRAM
		, CC.DES_REDE_SOCIAL_OUTRO
		, CC.IND_GENERO
		, CC.DES_ESTADO_CIVIL
		, CC.IND_PEP
		, CC.IND_NLIST
		, CC.IND_PERMITE_CONTATO_EMAIL
		, CC.IND_PERMITE_CONTATO_TELEFONE
		, CC.IND_PERMITE_CONTATO_WHATSAPP
		, CC.NUM_CERTIFICADO
		, CC.COD_SEGMENTO_CAIXA
		, CC.DES_RISCO_CAIXA
		, CC.DES_GRAU_PARENTESCO
		, CC.IND_RECEBER_OFERTAS_CAIXA_SEG
		, CC.IND_RECEBER_OFERTAS_PARCEIROS
		, CC.IND_NAO_PERTURBE_LGPD
		, CC.IND_RECEBER_PESQUISAS
		, CC.IND_RECEBER_EMAIL
		, CC.NUM_SCORE_RISCO
		, CC.COD_CLASSIFICACAO_RISCO
		, CC.DES_CLASSIFICACAO_RISCO
		, CC.IND_ESTRANGEIRO
		, CC.DES_CRITERIO
		, CC.DTH_CLASSIFICACAO_RISCO
		, CC.VLR_FATURAMENTO_RENDA_BIRO
		---
		--, ST.ID
		--, ST.NUM_CPF_CNPJ
		--, ST.NUM_CONTRATO
		, ST.NOM_PESSOA_EMPRESA
		, ST.IND_TP_PESSOA
		, ST.SEGMENTO_PRODUTO
		, ST.NOM_SEGMENTO AS NOM_SEGMENTO2
		, ST.COD_FORNECEDOR
		, ST.NOM_TERR
		, ST.ATIVIDADE
		, ST.REGIAO
		, ST.TITULO
		, ST.FONTE_NOTICIA
		, ST.DTA_NOTICIA
		, ST.DTA_GRAVACAO
		, ST.TIPO_OPERACAO
		, ST.DTA_INI_VIGENCIA
		, ST.DTA_FIM_VIGENCIA
		, ST.PJW
		, ST.FILTRO_PJW
		, ST.DTA_ULTIMO_PROCESSAMENTO
		, ST.ORIGEM_DADOS
	FROM DMDB41.dbo.DM_CLIENTES_CONTRATOS_CVP CC WITH(NOLOCK)
		JOIN DMDB41.dbo.STG_SIMILARIDADE_TERRORISTAS ST WITH(NOLOCK)
			ON CC.NUM_CPF_CNPJ=ST.NUM_CPF_CNPJ
				AND
			cast(CC.NUM_CPF_CNPJ as bigint) > 0 -- FOI TRATADOS OS REGISTROS ('-8','00000000000','00000000000-8') 
				AND
			ST.DTA_ULTIMO_PROCESSAMENTO = (SELECT TOP 1 MAX(DTA_ULTIMO_PROCESSAMENTO) AS DT FROM DMDB41.dbo.STG_SIMILARIDADE_TERRORISTAS WITH(NOLOCK) )
			
			
