CREATE VIEW [dbo].[VW_CLIENTES_EMAIL_TELEFONE_CVP] as 

SELECT c.NUM_CPF_CNPJ, C.NOM_PESSOA, E.DES_EMAIL, t.NUM_DDD_TELEFONE ,T.NUM_TELEFONE
from [dbo].DM_CLIENTES_UNIFICADOS_CVP C 

inner join [dbo].[DM_CLIENTES_EMAIL_CVP] E 
on C.COD_PESSOA_UNIFICADA = E.COD_PESSOA_UNIFICADA 
and E.SEQ_EMAIL = (SELECT MAX(SEQ_EMAIL) 
					FROM [DM_CLIENTES_EMAIL_CVP] EMAIL
					left join DM_CLIENTES_UNIFICADOS_CVP CLI
					on EMAIL.COD_PESSOA_UNIFICADA = CLI.COD_PESSOA_UNIFICADA
					where CLI.NUM_CPF_CNPJ = C.NUM_CPF_CNPJ)						
left join [dbo].[DM_CLIENTES_TELEFONE_CVP] T 
on C.COD_PESSOA_UNIFICADA = T.COD_PESSOA_UNIFICADA 
and T.SEQ_TELEFONE = (SELECT MAX(SEQ_TELEFONE) 
					  FROM [DM_CLIENTES_TELEFONE_CVP] 
					  where COD_PESSOA_UNIFICADA = C.COD_PESSOA_UNIFICADA 
					  and TIPO_TELEFONE=2)
and t.TIPO_TELEFONE=2
GO
 
IF OBJECT_ID('[dbo].[VW_CLIENTES_INADIMPLENTES_CVP]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CLIENTES_INADIMPLENTES_CVP];
GO





CREATE VIEW [dbo].[VW_CLIENTES_INADIMPLENTES_CVP] as 
SELECT DISTINCT
    B.COD_AGENCIA AS codAgencia,
    D.NOM_PESSOA,
    D.NUM_CPF_CNPJ AS codCpfCnpj,
    A.NOM_SEGMENTO AS segmento,
    A.NUM_CERTIFICADO AS numeroContrato,
    E.DES_PRODUTO AS nomeProduto,
   B.IND_PERIODICIDADE_COBRANCA AS opcaoPagamento,
	CASE 
   WHEN A.nom_forma_pagamento LIKE '%DEBITO%' THEN 'Debito em Conta'
   WHEN A.nom_forma_pagamento LIKE '%DÉBITO%' THEN 'Debito em Conta'
   WHEN A.nom_forma_pagamento LIKE '%FICHA%' THEN 'Boleto'
   WHEN A.nom_forma_pagamento LIKE '%Combo%' THEN 'Debito em Conta'
   ELSE A.nom_forma_pagamento END AS formaPagamento,
    A.VLR_PREMIO_PARCELA AS valorProposta,
	A.QTD_COBRANCA AS QtdParcelasInadimplentes,
	A.TOTAL_PARCELAS AS ValorTotalInadimplencia,
    A.ULT_COBRANCA AS dataHoraUltimaCob,
CASE 
    WHEN A.NOM_SEGMENTO = 'PREVIDENCIA' THEN FLOOR(DATEDIFF(MONTH, B.DTA_INICIO_VIGENCIA, GETDATE()))
    WHEN A.NOM_SEGMENTO = 'VIDA' THEN FLOOR(DATEDIFF(MONTH, B.DTA_QUITACAO, GETDATE()))
    ELSE NULL
END AS TempoContrato,
--	FLOOR(DATEDIFF(MONTH, B.DTA_QUITACAO, GETDATE())) AS TempoContrato,
	E.IND_CONJUGADO AS Comunicabilidade
	--CASE 
	--WHEN ben.NOM_PESSOA In ('HERDEIROS LEGAIS') then 'Não'
	--WHEN ben.NOM_PESSOA IS null then 'Não'
	--else 'Sim' end as benficiariosExistentes

FROM DMDB41.dbo.DM_COBRANCA_CVP A
INNER JOIN DM_CONTRATOS_CVP B
    ON A.NUM_CERTIFICADO = B.NUM_CERTIFICADO
    AND B.NOM_SEGMENTO IN ('VIDA', 'PREVIDENCIA')
    AND B.DES_SITUACAO IN ('Ativo', 'Ativa com Cobrança')
INNER JOIN DM_CLIENTES_CONTRATOS_CVP D
    ON B.NUM_CERTIFICADO = D.NUM_CERTIFICADO
    AND D.NOM_SEGMENTO IN ('VIDA', 'PREVIDENCIA')
    AND D.COD_PESSOA = 1
LEFT JOIN VW_PRODUTOS_CVP E
    ON B.COD_PRODUTO_COMPLETO = E.COD_PRODUTO_COMPLETO
INNER JOIN DM_CLIENTES_UNIFICADOS_CVP F
    ON D.NUM_CPF_CNPJ = F.NUM_CPF_CNPJ
--LEFT JOIN DM_BENEFICIARIOS_CONTRATOS_CVP ben
--	ON ben.NUM_CERTIFICADO = A.NUM_CERTIFICADO
--	AND ben.NOM_SEGMENTO = A.NOM_SEGMENTO

WHERE A.NOM_SEGMENTO IN ('VIDA', 'PREVIDENCIA') 
    AND (E.DES_TIPO_SEGMENTO <> 'Bilhete + Microsseguro' OR E.DES_TIPO_SEGMENTO IS NULL)
    AND (A.DES_SIT_COBRANCA IN ('Inadimplente', 'Cancelada por Inadimplencia')
        OR A.DES_SIT_PARCELA IN ('PENDENTE', 'CANCELADO'))
  --  AND A.NUM_CERTIFICADO IN (13690069, 80551110322803)
	--AND A.NUM_CERTIFICADO IN (15538385)
    AND A.INAD_UL_PC = 1
	
GO
 
IF OBJECT_ID('[dbo].[VW_CLIENTES_PU_VENCIDO_VIDA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CLIENTES_PU_VENCIDO_VIDA];
