CREATE VIEW [dbo].[VW_CLIENTES_PU_VENCIDO_VIDA] as 


SELECT		DISTINCT 
			AG.COD_AGENCIA as CodAgencia,
			CLI.NOM_SEGMENTO as Segmento ,
			CLI.NOM_PESSOA as NomeSegurado,
			CLI.NUM_CPF_CNPJ as CodCpfCnpj,
			C.NUM_CERTIFICADO as NumeroContrato,
			--C.DTA_EMISSAO_CONTRATO AS DATA_VENDA,
			C.DTA_INICIO_VIGENCIA as DataHoraInicioVigencia,
			--C.DTA_VENDA AS DATA_VENDA3,
			--C.DTA_QUITACAO AS DATA_VENDA4,
			C.DTA_FIM_VIGENCIA as DataHoraFimVigencia,
			C.IND_PERIODICIDADE_COBRANCA as OpcaoPagamento,
			C.VLR_PREMIO as ValorPremio,
			C.VLR_IS as ValorImportanciaSegurada
			--AG.COD_SEV,
			--AG.COD_SR,
			--AG.COD_SN,
			--AG.COD_VP

FROM		DMDB41.DBO.DM_CLIENTES_CONTRATOS_CVP as CLI WITH(NOLOCK)

			LEFT JOIN DMDB41.DBO.DM_CONTRATOS_CVP as C WITH(NOLOCK)
			ON CLI.NUM_CERTIFICADO = C.NUM_CERTIFICADO
			AND CLI.NOM_SEGMENTO = C.NOM_SEGMENTO

			LEFT JOIN DMDB41.DBO.DM_AGENCIA AS AG WITH(NOLOCK)
			ON C.COD_AGENCIA = AG.COD_AGENCIA

			LEFT JOIN DMDB41.DBO.VW_PRODUTOS_CVP AS PR WITH(NOLOCK)
			ON C.COD_PRODUTO_COMPLETO = PR.COD_PRODUTO_COMPLETO

WHERE		CLI.COD_PESSOA = 1 -- Participante
			AND CLI.NOM_SEGMENTO = 'VIDA'
			AND C.IND_PERIODICIDADE_COBRANCA = 'PU'
			AND YEAR(C.DTA_FIM_VIGENCIA) < YEAR(GETDATE()) + 1 -- Vencido (PREVENTIVO?)
			AND YEAR(C.DTA_FIM_VIGENCIA) >= YEAR(GETDATE()) - 3 -- Últimos 6 meses, últimos 12 meses, último ano (definir se é anterior ou posterior a data atual) – Entender melhor.

			

	
GO
 
