 CREATE view [dbo].[VW_COAF_CVP] AS 
 
SELECT 
	[COD_INFORMACAO]
    ,[DES_INFORMACAO]
    ,[DES_PERIODO]
	,SUBSTRING(DES_PERIODO,8,4) as NUM_ANO_PERIODO
    ,SUBSTRING(DES_PERIODO,1,2) as NUM_MES_PERIODO
	,SUBSTRING(DES_PERIODO,8,4) * 100 + SUBSTRING(DES_PERIODO,1,2) as NUM_ANO_MES_PERIODO
    ,[SEGMENTO]
    ,[ORDEM]
    ,[EMPRESA_SIGLA]
    ,[COD_TIPO_ENVOLVIDO]
    ,[NOME]
    ,[CPF_CNPJ]
    ,[CIDADE]
    ,[UF]
    ,[COD_SERVIDOR_PUBLICO]
    ,[PEP]
    ,[COD_PESSOA_OBRIGADA]
    ,[DT_INICIO_OPERACAO]
    ,[DT_FIM_OPERACAO]
    ,[VALOR_OPERACAO]
    ,[VALOR_IS]
    ,[VALOR_PREMIO]
    ,[QTDE_OPERACOES]
    ,[CODIGO_COAF_1]

	,case [CODIGO_COAF_1]
		when 1203 then 'BENEFICIARIO OUTRO'
		when 1210 then 'SINISTRO FREQUENCIA ANORMAL'
		when 1219 then 'BENEFICIARIO FINAL NAO IDENTIFICADO'
		when 1214 then 'ENTRADA 1 MILHAO'
		when 1202 then 'OPERAÇÕES DISCREPANTES'
		when 1201 then 'OPERAÇÕES INCOMPATIVEIS'
		when 1207 then 'TRANSAÇÕES ATÍPICAS'
		else 'NÃO INFORMADO'
	END AS [DES_CODIGO_COAF_1]

    ,[DESCRICAO_OCORRENCIA]
    ,[TIPO_PESSOA]
    ,[DESCRICAO_GRAU_PARENTESCO_BENEFICIARIO]
    ,[CEP]
    ,[DDD]
    ,[TELEFONE]
    ,[RENDA_INDIVIDUAL]
    ,[RENDA_FAMILIAR]
    ,[PROFISSAO]
    ,[CBO]
    ,[NACIONALIDADE_BRASILEIRA]
    ,[PAIS_ESTRANGEIRO]
    ,[BANCO_AGENCIA]
    ,[COD_ORIGEM_DE_RECURSOS]
    ,[IMPEDIDO]
    ,[NLIST]
    ,[DT_NASCIMENTO]
    ,[DT_ATUALIZACAO_CADASTRAL]
    ,[COD_PRODUTO]
    ,[NOME_PRODUTO]
    ,[COD_BEM_SEGURADO_OPERACAO]
    ,[COD_RAMO]
    ,[NOME_DO_RAMO]
    ,[VALOR_MENSALIDADE]
    ,[NOME_CORRETORA]
    ,[CNPJ_CORRETORA]
    ,[COD_FORMA_PAGAMENTO]
    ,[COD_CANAL_DE_VENDA]
    ,[NUM_SINISTRO]
    ,[NUM_APOLICE]
    ,[NUM_CERTIFICADO]
    ,[NOME_TITULAR]
    ,[CPF_TITULAR]
    ,[TIPO_PESSOA_TITULAR]
    ,[COD_TIPO_TITULAR]
    ,[COD_PESSOA_OBRIGADA_TITULAR]
    ,[COD_SERVIDOR_PUBLICO_TITULAR]
    ,[COD_PEP_TITULAR]
    ,[DT_GERACAO_ALERTA]
    ,[MATRICULAANALISTA]
    ,[DT_FIM_DA_ANALISE]
    ,[COD_CODIGO_COAF_2]
    ,[NUM_LOTE]
    ,[NUM_RECIBO]
    ,[DTA_COMUNICADO]
    ,[COD_MATRICULA_RECIBO]
    ,[DES_CLASSIFICACAO_RISCO]
	,[DES_OBSERVACAO]
	,[IND_CONTRATACAO_POSTERIOR]
	,[DES_MOTIVO_CANCELAMENTO]
	,[DES_MOTIVO_REJEICAO]
	,ISNULL(DTA_COMUNICADO,DT_GERACAO_ALERTA) AS  DTA_REFERENCIA

	,year(DT_GERACAO_ALERTA)*100 + month(DT_GERACAO_ALERTA) as 	NUM_ANO_MES_ALERTA
	,SUBSTRING(DES_PERIODO,8,4) * 100 + SUBSTRING(DES_PERIODO,1,2)   NUM_ANO_MES_OPERACAO
	,case	when COD_INFORMACAO = 3 then YEAR(DTA_COMUNICADO) *100 + MONTH(DTA_COMUNICADO)
			when COD_INFORMACAO = 2 then year(DT_GERACAO_ALERTA)*100 + month(DT_GERACAO_ALERTA)
	end as NUM_ANO_MES_ALERTA_COMUNICADO,


	case	when COD_INFORMACAO = 3 then DTA_COMUNICADO
			when COD_INFORMACAO = 2 then DT_GERACAO_ALERTA
	end as DTA_ALERTA_COMUNICADO

  FROM [dbo].[DM_COAF_CVP]
  where	COD_INFORMACAO in (2,3)


----------------------------------------------


