CREATE view [dbo].[VW_COBRANCA_CVP] as (
select 
b.num_certificado as 'numeroContrato',
  Case c.NOM_SEGMENTO 
  when 'VIDA' then 1
  when 'PREVIDENCIA' then 11
  when 'PRESTAMISTA' then 3 end as indContrato,
num_parcela as numeroParcela,
vlr_premio_parcela as valorParcela,
dth_vencimento as dataHoraVencimentoParcela,
des_sit_parcela as situacaoParcela,
dth_atualizacao as dataHoraAtualizacao,
dth_pagamento as dataHoraPagamento,
cod_idlg as numeroIdlg,
null as dataHoraVigenciaProporcional,
null as statusRenovacao,
nom_forma_pagamento as formaPagamento,
b.cod_agencia as codAgencia,
cod_operacao as codOperacao,
num_conta as numeroConta,
b.num_proposta as numeroProposta,
num_endosso as numEndosso,
id as id,
null as dataHoraReferencia,
null as numeroAviso,
null as descricaoAviso,
null as percentualNormal,
null as percentualDiferenca
from DM_COBRANCA_CVP b WITH (NOLOCK)
 inner join DM_CONTRATOS_CVP c WITH (NOLOCK)
 on b.NOM_SEGMENTO = c.NOM_SEGMENTO
 and b.NUM_CERTIFICADO = c.NUM_CERTIFICADO
)
GO
 
