CREATE view [dbo].[VW_COE_SOLICITACOES] AS 
--------------------------------------------
-- BASE COE 
-- SOLICITACAO X ATIVIDADES
--------------------------------------------


WITH SEGMENTO AS 
(
	-- BUSCA SEGMENTO
	SELECT CT2.[COD_SOL_CONTENC],
			CASE WHEN CT2.QTD_SEGMENTO > 1 THEN 'TODOS' ELSE CT2.NOM_SEGMENTO END AS NOM_SEGMENTO,
			CT2.NOM_SEGMENTO AS NOM_TODOS_SEGMENTOS

	FROM	
	(	-- AGREGA AS SOLICITACOES COM MAIS DE UM SEGMENTO
		select	CT1.[COD_SOL_CONTENC],
				STRING_AGG( CT1.NOM_SEGMENTO,'/') as NOM_SEGMENTO,
				COUNT(CT1.NOM_SEGMENTO) AS QTD_SEGMENTO
		

		FROM	(	-- BUSCA OS SEGMENTOS RELACIONADOS A SOLICITACAO
					SELECT	DISTINCT 
							TB01.[COD_SOL_CONTENC],
							CASE P.NOM_SIGLA_DIRETORIA 
								WHEN 'KIPREV' THEN 'PREVIDENCIA'
								WHEN 'SIAS' THEN 'VIDA'
								WHEN 'SMART' THEN 'PRESTAMISTA'
								else 'SEM SEGMENTO'
							END AS NOM_SEGMENTO
		
					from	[SQL18\STAGING4].[TDDB35].[dbo].OE_001_MA_PROC_SOL_CONTENC AS TB01 WITH(NOLOCK)
							LEFT JOIN [SQL18\STAGING4].[TDDB35].[dbo].[OE_012_MA_PRODUTO] P WITH(NOLOCK)
								on TB01.[COD_SOL_CONTENC] = P.M_SolicitacaoContencioso

					where P.NOM_SIGLA_DIRETORIA is not null
				) CT1

		group by CT1.[COD_SOL_CONTENC]
	) CT2
),
NOM_RESP AS
		    (
			SELECT DISTINCT
			 T3.radNumber AS COD_PROC
			,UPPER(TRIM(T5.fullName)) AS NOM_PESSOA_RESPOSTA
 
			FROM [SQL18\STAGING4].TDDB35.dbo.WORKITEM T1
			INNER JOIN [SQL18\STAGING4].TDDB35.dbo.TASK T2
			ON T2.idTask = T1.idTask
 
			INNER JOIN [SQL18\STAGING4].TDDB35.dbo.WFCASE T3
			ON T3.idCase = T1.idCase
 
			INNER JOIN [SQL18\STAGING4].TDDB35.dbo.CURRENTASSIGNEE T4
			ON T4.idWorkItem = T1.idWorkItem
 
			INNER JOIN [SQL18\STAGING4].TDDB35.dbo.WFUSER T5
			ON T5.idUser = T4.idUser
 
			WHERE T2.tskDisplayName = 'Resposta BU'
			AND T4.Deleted <> 1
			)

-- CONSULTA TODAS AS SOLICITACOES COE
--------------------------------------------
select	DISTINCT

		TB01.[COD_SOL_CONTENC] AS COD_SOLICITACAO
		,TB01.COD_PROC AS DES_SOLICITACAO
		,TB02.NOM_DOCUMENTO AS NUM_PROCESSO_JUDICIAL
		,UPPER(ATIV.DES_STATUS) AS DES_STATUS

		-- DATAS --------------------------------
		,CAST(TB02.DTH_DOCUMENTO AS DATE) AS DTA_RECEBIMENTO -- CONHECIMENTO DA CIA
		,CAST(isnull(TB_CASE.casCreationDate,TB_CASE_CL.casCreationDate) AS DATE) as DTA_CADASTRO -- INSERIDA NO SISTEMA

		,CAST(TB02.DTH_LIMITE_RESPOSTA AS DATE) AS DTA_LIMITE_RESPOSTA
		,cast(atv.DTH_DataResposta as date) AS DTA_FINALIZACAO

		-- PRAZOS --------------------------------
		,TB02.QTD_DIAS_PRAZO

		-- QTDE DIA ATENDIMENTO
		,CASE	WHEN UPPER(ATIV.DES_STATUS) = 'FINALIZADA' THEN DATEDIFF(DAY,CAST(TB_CASE_CL.casCreationDate AS DATE),cast(atv.DTH_DataResposta as date)) 
				WHEN UPPER(ATIV.DES_STATUS) = 'FINALIZADA PELA TRIAGEM' THEN 0
				ELSE DATEDIFF(DAY,CAST(TB_CASE_CL.casCreationDate AS DATE),cast(GETDATE() as date))
		END AS QTD_DIAS_ATENDIMENTO

		-- STATUS DO PRAZO
		,CASE	WHEN UPPER(ATIV.DES_STATUS) = 'FINALIZADA PELA TRIAGEM' THEN 'NO PRAZO'

				WHEN UPPER(ATIV.DES_STATUS) = 'FINALIZADA' AND DATEDIFF(DAY,CAST(TB_CASE_CL.casCreationDate AS DATE),cast(atv.DTH_DataResposta as date)) <= TB02.QTD_DIAS_PRAZO THEN 'NO PRAZO' 
				WHEN UPPER(ATIV.DES_STATUS) <> 'FINALIZADA' AND DATEDIFF(DAY,CAST(TB_CASE_CL.casCreationDate AS DATE),CAST(GETDATE() AS DATE)) <= TB02.QTD_DIAS_PRAZO THEN 'NO PRAZO' 
				ELSE 'FORA DO PRAZO'
		END AS DES_STATUS_PRAZO

		-- VISOES --------------------------------
		,UPPER(USU01.fullName) AS NOM_PESSOA_CADASTRO
		,CASE WHEN ATIV.DES_STATUS = 'EM ANÁLISE' THEN NOM.NOM_PESSOA_RESPOSTA ELSE UPPER(USU02.fullName) END AS NOM_PESSOA_RESPOSTA
		,ori.DES_PA_DESCRICAO AS DES_ORIGEM_SOLICITACAO
		,tp.DES_PA_TP_ACAO_JUD as DES_TIPO_ACAO
		,SEG.NOM_SEGMENTO AS NOM_SEGMENTO
		,SEG.NOM_TODOS_SEGMENTOS

from	[SQL18\STAGING4].[TDDB35].[dbo].OE_001_MA_PROC_SOL_CONTENC AS TB01 WITH(NOLOCK)

		left join SEGMENTO as SEG
			ON SEG.COD_SOL_CO
GO
 
