	CREATE VIEW [DBO].[VW_CONQUISTE_CCA] AS

--		SELECT * FROM VW_CONQUISTE_CCA  ORDER BY 7,1,2  --

--		select anomes , count(*) FROM	[DMDB41].[dbo].[DM_TDV_CLASSIF_PARCEIRO_GECLI] group by anomes select anomes , count(*) FROM	[DMDB41].[dbo].[DM_TDV_CLASSIF_PARCEIRO] group by anomes

---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_CONQUISTE_CCA
--
--					SQL14\DMCVP\DMDB42 
--
--		OBJETIVO:	CRIAR BASE DE CONSULTA ENTRE CCA E AS VENDAS DO BI
--
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  Criação
--		DATA	:	23/02/2023	
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  eliminado o respvendas 76
--		DATA	:	01/03/2023	
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  Incluido nova tabela de TDV e gerar o que tem movimentação e 
--								  não tem nas tabelas TDV
--		DATA	:	01/03/2023	
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  todas tabelas mandatórias
--		DATA	:	01/03/2023	
---------------------------------------------------------------------------------------------------

---------------------------------------------------------------------------------------------------
--		VIDA
---------------------------------------------------------------------------------------------------
---------------------------------------------------------------------------------------------------
--		RECUPERA VENDAS DO AIC
---------------------------------------------------------------------------------------------------
WITH

VIDA AS  ( 

SELECT	DISTINCT
		'VIDA       '				AS	SEGMENTO,
		COD_PROPOSTA				AS	NUM_PROPOSTA,

		CONVERT(VARCHAR(6), DTA_VENDA , 112) AS	DTA_PROPOSTA,
		CONVERT(INT, A.COD_AGENCIA) AS	COD_AGENCIA,

		CASE WHEN	ISNUMERIC(A.NUM_MATRICULA_INDICADOR) = 0 
			 THEN	CONVERT(BIGINT,A.COD_PV)   
             WHEN	ISNUMERIC(A.NUM_MATRICULA_INDICADOR) = 1 AND LEN(CONVERT(INT, A.NUM_MATRICULA_INDICADOR)) < 6 
			 THEN	CONVERT(BIGINT,A.COD_PV)  
       		 ELSE	CONVERT(BIGINT,A.NUM_MATRICULA_INDICADOR)
			 END	AS NUM_RESPONSAVEL_DV ,

		CASE WHEN	COD_PERIODICIDADE_PGTO = 'A'      
			 AND	A052.DES_PERIOD_PAGAMENTO = 'Unico'
			 THEN	'Unico'

			 WHEN   COD_PERIODICIDADE_PGTO = 'U'
			 AND	A052.DES_PERIOD_PAGAMENTO = 'Unico'
			 THEN	'Unico'

			 WHEN	ISNULL(COD_PERIODICIDADE_PGTO,'') = ''
			 AND	ISNULL(A052.DES_PERIOD_PAGAMENTO,'') =  ''
			 THEN	'Unico'

			 WHEN	COD_PERIODICIDADE_PGTO = 'U'
			 THEN	'Unico'

			 WHEN	COD_PERIODICIDADE_PGTO = 'A'
			 THEN	'Anual' 

			 WHEN   COD_PERIODICIDADE_PGTO = 'A'
			 AND	A052.DES_PERIOD_PAGAMENTO = 'Anual'
			 THEN	'Anual'
		
			 WHEN   COD_PERIODICIDADE_PGTO = 'M'
			 AND	A052.DES_PERIOD_PAGAMENTO = 'Mensal'
			 THEN	'Mensal'

			 WHEN	COD_PERIODICIDADE_PGTO = 'M'
			 THEN	'Mensal'
			 ELSE	''	

			 END    AS	DES_PERIOD_PAGAMENTO ,  

		CONVERT(FLOAT, A.VLR_PREMIO) AS	VLR_PREMIO_EMITIDO,

		CONVERT(FLOAT,  CASE	WHEN 	A065.NUM_PROPOSTA IS NOT NULL 
								THEN	A.VLR_PREMIO
								WHEN (IIF(CASE	WHEN DTA_VENDA <> CONVERT(DATE, GETDATE()) 
												THEN FLG_PAGO_MJUNMOV 
												ELSE FLG_PAGO_RAJADA 
												END = 'S', A.VLR_PREMIO, 0)) = 0  
								THEN	0
								ELSE	A.VLR_PREMIO	
						END 
				) 					AS VLR_PREMIO_PAGO ,

		CASE  WHEN	(CAN.QT_DIAS_CANCEL IS NULL	AND A059.NOM_SUB_SITUACAO = 'CANCELADO')
			  OR		(CAN.QT_DIAS_CANCEL	<=	7	AND A059.NOM_SUB_SITUACAO = 'CANCELADO' )
			  OR		(A059.NOM_SUB_SITUACAO =	'Risco Excluido' )
			  OR		(A059.NOM_SUB_SITUACAO =	'Falta de Pagamento') 
			  THEN	CONVERT(FLOAT, A.VLR_PREMIO)
			  ELSE	0
			  END	AS	VLR_PREMIO_CANCELADO

FROM	DMDB41..DM_AIC_PROPOSTA	
GO
 
IF OBJECT_ID('[dbo].[VW_CONQUISTE_CLIENTE_AGENCIA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CONQUISTE_CLIENTE_AGENCIA];
GO
CREATE VIEW [DBO].[VW_CONQUISTE_CLIENTE_AGENCIA] AS

---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_CONQUISTE_CLIENTE_AGENCIA
--
--					SQL14\DMCVP\DMDB41
--
--		OBJETIVO:	ACOMPANHAMENTO DOS CLIENTES POR AGENCIA 
--
---------------------------------------------------------------------------------------------------
--		SELECT TOP 8 * FROM dmdb41..VW_CONQUISTE_CLIENTE_AGENCIA
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  CRIAÇÃO
--		DATA	:	13/02/2023	
---------------------------------------------------------------------------------------------------
WITH	BASE AS (
SELECT
		NOM_SEGMENTO
		,COD_AGENCIA

		,CONVERT(VARCHAR(06),DTA_INICIO_VIGENCIA,112)	AS ANOMES

		,COUNT(DISTINCT(NUM_CPF_CNPJ))					AS	QTD_ENTRADA_CLIENTE
		,COUNT(DISTINCT(NUM_CERTIFICADO))				AS  QTD_ENTRADA_APOLICE

		,SUM(CASE	WHEN	FLAG_NOVO = 'S' OR FLAG_CARTEIRA_NOVO = 'S'
					THEN	1
					ELSE	0
					END)	AS		QTD_ENTRADA_NOVO

		,SUM(CASE	WHEN	FLAG_RENOVACAO = 'S'
					THEN	1
					ELSE	0
					END)	AS		QTD_ENTRADA_RENOVACAO

		,SUM(CASE	WHEN	FLAG_RECUPERACAO = 'S'
					THEN	1
					ELSE	0
					END)	AS		QTD_ENTRADA_RECUPERACAO

		,0	AS		QTD_SAIDA_CLIENTE
		,0  AS		QTD_SAIDA_APOLICE
		,0  AS		QTD_SAIDA_FIM_VIGENCIA
		,0  AS		QTD_SAIDA_INADIMPLENTE
		,0 	AS		QTD_SAIDA_SISTEMICO
		,0  AS		QTD_SAIDA_INSATISFACAO
		,0	AS		QTD_SAIDA_SINISTRO
		,0  AS		QTD_SAIDA_SOLICITADO
		,0	AS		QTD_SAIDA_OUTROS
      	  
FROM	[DMDB41].[dbo].[DM_CLIENTE_AGREGADO_CROSS_CVP]

WHERE	DTA_INICIO_VIGENCIA BETWEEN  CONVERT(DATE,DATEADD(MONTH,-1,GETDATE())) AND  CONVERT(DATE,GETDATE())

GROUP BY NOM_SEGMENTO
		,COD_AGENCIA
		,CONVERT(VARCHAR(06),DTA_INICIO_VIGENCIA,112)  

UNION ALL

SELECT
		NOM_SEGMENTO
		,COD_AGENCIA
		,CONVERT(VARCHAR(06),DTA_ENCERRAMENTO,112)		AS ANOMES

		,0	AS		QTD_ENTRADA_CLIENTE
		,0	AS		QTD_ENTRADA_APOLICE
		,0	AS		QTD_ENTRADA_NOVO
		,0	AS		QTD_ENTRADA_RENOVACAO
		,0  AS		QTD_ENTRADA_RECUPERACAO

		,COUNT(DISTINCT(NUM_CPF_CNPJ))					AS	QTD_SAIDA_CLIENTE
		,COUNT(DISTINCT(NUM_CERTIFICADO))				AS  QTD_SAIDA_APOLICE

		,SUM(CASE	WHEN	DTA_ENCERRAMENTO IS NOT NULL  
					AND		DES_MOTIVO_CANCEL	IN ('Fim do Benefício'
													,'Final de Vigencia'
													,'Final de Vigência - Aguardando retorno do banco'
													,'Final de Vigencia - Bilhete Novo Cancelado'
													,'Final de Vigência - Bilhete novo cancelado'
													,'Final de Vigência - Bilhete novo em crítica'
													,'Final de Vigência - Não foi gerado novo bilhete'
													,'Final de Vigência - Renovado'
													,'Final de Vigência - Restrição na Conta Bancária'
													,'Expirado por término de vigência da apólice'
													,'Por Fim de Diferimento'
													,'Empréstimo quitado'                           
													,'Encerrou o relacionamento com a CAIXA'             
													,'Empresa encerrou as atividades'                    
													,'Empréstimo não averbado')                           
					THEN	1
					ELSE	0
					END )	AS		QTD_SAIDA_FIM_VIGENCIA

		,SUM(CASE	WHEN	DTA_ENCERRAMENTO IS NOT NULL  
					AND		DES_MOTIVO_CANCEL	IN ('Inadimplência'                                     
													,'Cancelamento por falta de pagamento'
													,'De Pagamento'
													,'Falta de pagamento'
													,'Por Inadimplência'
													,'Saldo Negativo')
					THEN	1
					ELSE	0
					END )	AS		QTD_SAIDA_INADIMPLENTE

		,SUM(CASE	WHEN	DTA_ENCERRAMENTO IS NOT NULL  
					AND		DES_MOTIVO_CANCEL	IN ('ACÚMULO RISCO - DESFAVORÁVEL À CONTRATAÇÃO'        
													,'ACÚMULO RISCO - DOCUMENTAÇÃO NÃO RECEBIDA'         
													,'IDADE + PRAZO ACIMA DO LIMITE PERMITIDO'           
													,'MATRIZ DE RISCO - DESFAVORÁVEL À CONTRATAÇÃO'      
													,'MATRIZ DE RISCO - DOCUMENT
GO
 
