CREATE VIEW [DBO].[VW_CONQUISTE_HENCEC] AS

---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_CONQUISTE_HENCEC
--
--					SQL14\DMCVP\DMDB41
--
--		OBJETIVO:	COMPARAÇÃO DO CONQUISTE COM OS DADOS DO RADAR
--
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  CRIAÇÃO
--		DATA	:	03/02/2023	
---------------------------------------------------------------------------------------------------
--		select distinct des_tipo_rede from VW_CONQUISTE_HENCEC
---------------------------------------------------------------------------------------------------
	--			NU ITEM 
	--			------- -----------
	--			84		Previdência PJ		atacado
	--			898		Previdência PF		atacado
	--			82		Previdência			varejo   
	--			765		Previdência

	--			43		Seguro Prestamista	atacado      
	--			899		Prestamista PF		atacado
	--			310		Seguro Prestamista	varejo   

	--			89		Seguro Vida PJ		atacado
	--			68		Seguro de Vida		atacado	
	--			180		Seguro de Vida PM	Venda varejo   
	--			181		Seguro de Vida PU	Venda varejo		
	--			900		Seguro de Vida PM
	--			932		Seguro de Vida PU

---------------------------------------------------------------------------------------------------

---------------------------------------------------------------------------------------------------
--		LE CONQUISTE 
---------------------------------------------------------------------------------------------------
WITH 

CONQUISTE AS (				

SELECT	
		A.AM_REF						AS ANOMES_REF, 
		A.NU_UNIDADE,  
		A.NU_ITEM

FROM	DMDB41..DM_ARQ_CONQUISTE A  WITH  (NOLOCK) 
WHERE	A.AM_REF BETWEEN    CONVERT(VARCHAR(6), DATEADD(MONTH,-1,GETDATE()) , 112) AND   CONVERT(VARCHAR(6), GETDATE(), 112)
and		A.NU_ITEM IN ( 
						89	,		--	Seguro Vida PJ  atacado 
						68	,		--	Seguro de Vida Venda USANDO NO PRIVATE  ???? UTILIZADO NO FILTRO
						180	,		--	Seguro de Vida PM Venda  varejo   ver na venda PM Pa
						181	,		--	Seguro de Vida PU Venda  varejo			PU
						900 ,		--	Seguro de Vida PM
						932 ,		--	Seguro de Vida PU

						43	,		--	Seguro Prestamista      ???? UTILIZADO NO FILTRO  
						899	,		--	Prestamista PF atacado
						310	,		--	Seguro Prestamista   varejo

						765 ,		--	Previdência
						84	,		--	Previdência PJ   atacado
						898	,		--	Previdência PF atacado
						82  )		--  Previdência
						
) ,
---------------------------------------------------------------------------------------------------
--	ESTRUTURA COMERCIAL - UNIDADES
---------------------------------------------------------------------------------------------------
ESTRUTURA AS ( 

SELECT	
		COD_SR, 
		COD_SEV, 
		COD_AGENCIA, 
		'UNIDADE' AS DES_TIPO,  
		DES_TIPO_REDE

FROM	DMDB41..DM_AGENCIA	WITH ( NOLOCK )
WHERE	DES_TIPO_REDE IN ('REDE FISICA','MIDDLE','CORPORATE','PRIVATE','REDE AGRO VAREJO','REDE DIGITAL')

UNION ALL

SELECT	DISTINCT 
		COD_SR,
		COD_SEV, 
		COD_SEV AS COD_AGENCIA, 
		'SEV' AS DES_TIPO, 
		DES_TIPO_REDE
FROM	DMDB41..DM_AGENCIA	WITH ( NOLOCK )
WHERE	DES_TIPO_REDE = 'REDE FISICA'

UNION ALL

SELECT	DISTINCT 
		COD_SR, 
		0 AS COD_SEV, 
		COD_SR AS COD_AGENCIA, 
		'SR' AS DES_TIPO, 
		DES_TIPO_REDE
FROM	DMDB41..DM_AGENCIA	WITH ( NOLOCK )
WHERE	DES_TIPO_REDE IN ('REDE FISICA','MIDDLE','CORPORATE','PRIVATE')

) ,

--------------------------------------------------------------------------------------------------- 
--		CONQUISTE  FINAL 
---------------------------------------------------------------------------------------------------
CONQUISTE_FINAL AS (

SELECT	DISTINCT 
		A.ANOMES_REF,
		DES_TIPO_REDE,
		B.COD_SR, 
		B.COD_SEV, 
		B.COD_AGENCIA,
		A.NU_UNIDADE 

FROM	CONQUISTE A

INNER JOIN ESTRUTURA B
ON		A.NU_UNIDADE = B.COD_AGENCIA
AND		DES_TIPO_REDE in ( 'REDE FISICA' ,'REDE AGRO VAREJO')

WHERE	NU_ITEM IN (82,		--			82	Previdência  varejo  
				
GO
 
IF OBJECT_ID('[dbo].[VW_CONQUISTE_MENSAL]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CONQUISTE_MENSAL];
