CREATE VIEW [dbo].[VW_CONQUISTE_MENSAL] AS

---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_CONQUISTE_MENSAL
--
--					SQL14\DMCVP\DMDB41
--
--		OBJETIVO:	EVOLUÇÃO DO MOVIMENTO REALIZADO DO CONQUISTE
--
--		tipo rede = rede fisica
--		cálculo da nota por item Conquiste: ((realizado/objetivo)/(dias_uteis_decorridos/dias_uteis_mes))*100
--		GAP_TOTAL = VL_REALIZADO_MES - VL_OBJETIVO_MES
--
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  CRIAÇÃO
--		DATA	:	02/12/2022	
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  INCLUSÃO DA DATA DE PROCESSAMENTO
--		DATA	:	08/02/2023	
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  INCLUSÃO DO ACUMULADO
--		DATA	:	01/03/2023	
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  INCLUSÃO DO PESO DA TABELA ITEM
--		DATA	:	23/03/2023	
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  TIRANDO O FILTRO DA DATA
--		DATA	:	12/07/2023	
