---------------------------------------------------------------------------------------------------
--		SELECT count(*) FROM VW_CONQUISTE_MENSAL ORDER BY SEGMENTO  -- 316130
---------------------------------------------------------------------------------------------------
--		CONQUISTE
---------------------------------------------------------------------------------------------------
WITH 

CONQUISTE AS (				

SELECT	A.AM_REF						AS ANOMES_REF, 
		A.NU_UNIDADE, 
		A.NU_ITEM, 
		A.NU_AVALIACAO, 
		A.NU_GRUPO,
		CONVERT(FLOAT, QT_PESO_REAL)	AS PESO,
		CONVERT(FLOAT, VR_OBJETIVO)		AS VL_OBJETIVO,
		CONVERT(FLOAT, A.VR_REALIZADO)	AS VL_REALIZADO,
		CONVERT(FLOAT, A.PC_REALIZADO)  AS PC_REALIZADO, 
		CONVERT(FLOAT, A.PC_ESPE)		AS PC_ESPE, 
		CONVERT(FLOAT, A.PC_ITEM)		AS PC_ITEM,
		GAP_TOTAL = CONVERT(FLOAT, A.VR_REALIZADO) - CONVERT(FLOAT,A.VR_OBJETIVO) ,
		GAP_PROPORCIONAL = CONVERT(FLOAT,A.VR_REALIZADO) - ( CONVERT(FLOAT,A.VR_OBJETIVO ) * (CONVERT(FLOAT, A.PC_ESPE)/100)) ,
		CONVERT(DATE, DATEADD(DAY, -1, A.DTH_ATUALIZACAO)) AS DT_ARQUIVO 
FROM	DMDB41..DM_ARQ_CONQUISTE A  WITH  (NOLOCK) 
WHERE	A.AM_REF <= CONVERT(VARCHAR(6), GETDATE(), 112)
)

---------------------------------------------------------------------------------------------------
--		INCLUI OS ITENS
---------------------------------------------------------------------------------------------------
,CONQUISTE_1 AS (

SELECT	A.ANOMES_REF, 
		A.NU_UNIDADE, 
		A.NU_ITEM, 
		A.NU_AVALIACAO, 
		A.NU_GRUPO, 
		B.NO_ITEM, 
		A.PESO, 
		CONVERT(FLOAT, B.QT_PE) AS PESO_ITEM,
		A.VL_OBJETIVO, 
		A.VL_REALIZADO, 
		A.PC_REALIZADO, 
		A.PC_ESPE, 
		A.PC_ITEM,
		A.GAP_TOTAL,
		A.GAP_PROPORCIONAL,
		A.DT_ARQUIVO
FROM	CONQUISTE A
left 	JOIN DMDB41..DM_ARQ_CONQUISTE_ITEM B   WITH  (NOLOCK) 
ON		A.NU_ITEM		=	B.NU_ITEM
AND		A.NU_AVALIACAO	=	B.NU_AVALIACAO
AND		A.NU_GRUPO		=	B.NU_GRUPO
AND		A.ANOMES_REF	=	B.AM_REF
), 

---------------------------------------------------------------------------------------------------
--		APURA A EVOLUÇÃO ENTRE OS MESES
---------------------------------------------------------------------------------------------------
CONQUISTE_2 AS (

SELECT	A.ANOMES_REF, 
		A.NU_UNIDADE,
		A.NU_ITEM, 
		A.NO_ITEM, 
		CASE WHEN A.PESO_ITEM = 0 THEN A.PESO ELSE A.PESO_ITEM END AS PESO,
GO
 
