CREATE VIEW [dbo].[VW_CONQUISTE_TOTAL] AS

---------------------------------------------------------------------------------
--	
--		VIEW	:	VW_CONQUISTE_TOTAL
--
--					SQL14\DMCVP\DMDB41
--
--		OBJETIVO:	EVOLUÇÃO DO MOVIMENTO REALIZADO DO CONQUISTE
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®  -  CRIAÇÃO
--		DATA	:	25/07/2024	
---------------------------------------------------------------------------------------------------

---------------------------------------------------------------------------------------------------
--		SELECT * FROM VW_CONQUISTE_TOTAL ORDER BY NU_AVALIACAO,NU_UNIDADE,NU_ITEM	,AM_REF
---------------------------------------------------------------------------------------------------
--		GAP_TOTAL
--		VLR_VELOCIDADE_DIA
--		VLR_VELOCIDADE_NECESSARIA
--		PC_ITEM_MES
--NO_ITEM_TRAT

--NO_UNIDADE (PODE CRUZAR COM A TABELA WORK_GEPLAC.dbo.TB_ESTRUTURA_SURED)
--NU_ITEM_PAI (CRUZAR COM A TABELA VW_CONQUISTE_PARAMETROS)
--NO_ITEM_PAI (CRUZAR COM A TABELA VW_CONQUISTE_PARAMETROS)

--PESO (TRATAR O TIPO DE DADO)  ??
--QT_PESO_REAL (TRATAR O TIPO DE DADO)
---------------------------------------------------------------------------------------------------
WITH 

CONQUISTE AS (				

SELECT	A.NU_AVALIACAO
		,A.AM_REF
		,A.NU_UNIDADE
		,A.NU_ITEM
		,A.QT_PESO_REAL
		,A.VR_OBJETIVO
		,A.VR_REALIZADO
		,A.PC_ESPERADO
		,A.QT_PONTO_ITEM
		,A.PC_ITEM
		,A.VR_OBJETIVO		AS	VR_OBJETIVO_ATU
		,B.VR_OBJETIVO		AS	VR_OBJETIVO_ANT
		,A.VR_REALIZADO		AS	VR_REALIZADO_ATU
		,B.VR_REALIZADO		AS	VR_REALIZADO_ANT
		,VR_OBJETIVO_MES	=	A.VR_OBJETIVO	- ISNULL(B.VR_OBJETIVO, 0) 
		,VR_REALIZADO_MES	=	A.VR_REALIZADO	- ISNULL(B.VR_REALIZADO, 0) 
		,GAP_TOTAL = CONVERT(FLOAT, A.VR_REALIZADO) - CONVERT(FLOAT,A.VR_OBJETIVO) 
		,GAP_PROPORCIONAL = CONVERT(FLOAT,A.VR_REALIZADO) - ( CONVERT(FLOAT,A.VR_OBJETIVO ) * (CONVERT(FLOAT, A.PC_ESPERADO)/100)) 
		--,CASE WHEN A.NOM_ARQUIVO LIKE 'RESULTADO%' THEN CONVERT(DATE,SUBSTRING(A.NOM_ARQUIVO,30,8)) ELSE CONVERT(DATE,SUBSTRING(A.NOM_ARQUIVO,23,8)) END AS DTA_ARQUIVO
		,CONVERT(DATE,REPLACE(RIGHT(A.NOM_ARQUIVO,12), '.zip','')) AS DTA_ARQUIVO
		--select count(*)
FROM	DMDB41..DM_ARQ_CONQUISTE_TOTAL A ( nolock ) 

LEFT JOIN DMDB41..DM_ARQ_CONQUISTE_TOTAL B  ( nolock ) 
ON		A.NU_UNIDADE	=	B.NU_UNIDADE
AND		A.NU_ITEM		=	B.NU_ITEM
AND		A.NU_AVALIACAO	=	B.NU_AVALIACAO
AND		B.AM_REF		=	CASE	WHEN RIGHT(A.AM_REF,2) IN ('01','07')   -- ED, CONTINUA COM A QUEBRA ??
									THEN '99' 
									ELSE A.AM_REF - 1 
									END
WHERE	A.AM_REF >= 202101
)
---------------------------------------------------------------------------------------------------
--		APURA A EVOLUÇÃO ENTRE OS MESES
---------------------------------------------------------------------------------------------------
,CONQUISTE_1 AS (


SELECT	A.NU_AVALIACAO
		,A.AM_REF
		,A.NU_UNIDADE
		,A.NU_ITEM
		,A.QT_PESO_REAL
		,A.VR_OBJETIVO
		,A.VR_REALIZADO
		,A.PC_ESPERADO
		,A.QT_PONTO_ITEM
		,A.PC_ITEM
		,A.VR_OBJETIVO_MES
		,A.VR_REALIZADO_MES	
		,A.GAP_TOTAL 

		,A.VR_OBJETIVO_ATU
		,A.VR_OBJETIVO_ANT
		,A.VR_REALIZADO_ATU
		,A.VR_REALIZADO_ANT

		,VLR_VELOCIDADE_DIA			=	CONVERT(numeric(17,4),(A.VR_OBJETIVO_ATU - ISNULL(A.VR_OBJETIVO_ANT, 0))  / NULLIF(D.QTD_DIAS_UTEIS_MES_DECORRIDO ,0))				
		,VLR_VELOCIDADE_NECESARIA	=	CONVERT(numeric(17,4),(A.GAP_PROPORCIONAL  /  NULLIF(( D.QTD_DIAS_UTEIS_MES - D.QTD_DIAS_UTEIS_MES_DECORRIDO),0 )) )			
		,D.QTD_DIAS_UTEIS_MES_DECORRIDO 
		,D.QTD_DIAS_UTEIS_MES 
		,PC_ESP_MES			=	CONVERT(NUMERIC(17,4),(CAST(D.QTD_DIAS_UTEIS_MES_DECORRIDO  AS numeric) / CAST(D.QTD_DIAS_UTEIS_MES AS numeric))) * 100
		,PC_REALIZADO_MES	=   ((CAST( ( A.VR_REALIZADO_MES - A.VR_OBJETIVO_MES ) AS DECIMAL(18,4)) / NULLIF(ABS( A.VR_OBJETIVO_MES ),0) )	+ 1) * 100

--        CASE 
--            WHEN A.VR_OBJETIVO_ATU < A.VR_OBJETIVO_ANT 
--                THEN (1 - (
GO
 
