CREATE  VIEW [dbo].[VW_CONTRATO_SINISTROS] as (
SELECT b.NUM_CERTIFICADO AS numContrato,
Case b.NOM_SEGMENTO 
  when 'VIDA' then 1
  when 'PREVIDENCIA' then 11
  when 'PRESTAMISTA' then 3 end as indContrato,
COD_CAUSA AS codCausa,
COD_COBERTURA AS codCobertura,
DTA_OCORRENCIA_SINISTRO AS dataHoraSinistro,
DES_COBERTURA AS coberturas,
MOTIVO_SINISTRO AS causas,
DTA_OCORRENCIA_SINISTRO AS dataHoraAtualizacao,
c.NUM_APOLICE as numero_apolice,
'0' as numero_protocolo,
d.NUM_CPF_CNPJ as numcpfcnpj,
d.NOM_PESSOA as nompessoa
FROM DM_SINISTROS_CVP b
 inner join DM_CONTRATOS_CVP c
 on b.NOM_SEGMENTO = c.NOM_SEGMENTO
 and b.NUM_CERTIFICADO = c.NUM_CERTIFICADO
 left join DM_CLIENTES_CONTRATOS_CVP d
 on d.NOM_SEGMENTO = c.NOM_SEGMENTO
 and d.NUM_CERTIFICADO = c.NUM_CERTIFICADO
)
GO
 
