 CREATE	VIEW [dbo].[VW_CONTROLE_CARGA] AS
--
---------------------------------------------------------------------------------------------------
--
--		SELECT * FROM DMDB41.[DBO].[VW_CONTROLE_CARGA] 
--
-- ================================================================================================
--	
--		VIEW	:	VW_CONTROLE_CARGA
--					SQL14\DMCVP\DMDB41
--
--		OBJETIVO:	CRIAR BASE DE VENDA PARA ACESSO DA GECLIC PARA CARGA BI
---------------------------------------------------------------------------------------------------
--
--	BI_PREVIDENCIA						BI_CVP
--	----------------					------------
--	.	MJUNMOV							.	SSDDIROT
--	.	RAJADA							.	-	AIC	
--	.	ARQUIVOS GPS
--	.	ARQUIVOS HENCEC
--	.	FUNCIONARIOS
--	.	CONQUISTE
---------------------------------------------------------------------------------------------------

--	PRESTAMISTA			 VIDA		 PREVIDENCIA		PAINEL

--		8:01			 8:05			01:00			 8:30
--	    9:01			 9:05			 				 9:30
--	   10:01			10:05							10:30

-- 	   12:50  			12:55       					13:30

-- 	   15:30  			15:35       					16:00
-- 	   16:50  			16:55       					17:30

--	aic proposta
--	22:00 
-- MJUNMOV
--	7:30 
 -- PRESTA
--  VIDA 
--	12:00

--	14
  
--	17


---------------------------------------------------------------------------------------------------


---------------------------------------------------------------------------------------------------
--		VIDA		PRESTAMISTA		 PREVIDENCIA		PAINEL

--		1/1HS			2/2HS

--		 8:12			8:01			01:00			9:30

---------------------------------------------------------------------------------------------------
--		MJUNMOV
---------------------------------------------------------------------------------------------------
WITH 

MJUNMOV AS (

SELECT	'VENDA'					AS	ASSUNTO, 
		'MJUNMOV'				AS	ARQUIVO 
		,'3'					AS	SEQ_CORRETA
		,'VIDA / PRESTAMISTA'	AS	SEGMENTO
		,DTA_ARQUIVO			AS	DTH_VENDA
		,DTH_CADASTRAMENTO		AS	DTH_ULTIMA_CARGA 
		,COUNT(*)				AS	QTD_REGISTROS 
FROM	DMDB41.[DBO].[DM_ARQ_PROPOSTA_MJUNMOV_VIDA_PREST] (NOLOCK)
WHERE	DTH_CADASTRAMENTO = (	SELECT	MAX(DTH_CADASTRAMENTO) 
								FROM	DMDB41.[DBO].[DM_ARQ_PROPOSTA_MJUNMOV_VIDA_PREST] (NOLOCK))
group by DTA_ARQUIVO
		,DTH_CADASTRAMENTO		

),

---------------------------------------------------------------------------------------------------
--		RAJADA
---------------------------------------------------------------------------------------------------
RAJADA AS (

SELECT	'VENDA'					AS	ASSUNTO,
		'RAJADA'				AS	ARQUIVO 
		,'4'					AS	SEQ_CORRETA
		,'VIDA / PRESTAMISTA'	AS	SEGMENTO
		,DTA_ARQUIVO			AS	DTH_VENDA
		,DTH_CADASTRAMENTO		AS	DTH_ULTIMA_CARGA
		,COUNT(*)				AS	QTD_REGISTROS 
FROM	DMDB41.[DBO].DM_ARQ_RAJADA_COBRANCA_PAGA (NOLOCK)
WHERE	DTH_CADASTRAMENTO = (	SELECT	MAX(DTH_CADASTRAMENTO) 
								FROM	DMDB41.[DBO].DM_ARQ_RAJADA_COBRANCA_PAGA (NOLOCK))
group by DTA_ARQUIVO
		,DTH_CADASTRAMENTO		

),
---------------------------------------------------------------------------------------------------
--		AIC_PROPOSTA
---------------------------------------------------------------------------------------------------
AIC AS (

SELECT	'VENDA'					AS	ASSUNTO,
		ARQUIVO = 'AIC_PROPOSTA' 
		,'5'					AS	SEQ_CORRETA
		,UPPER(NOM_SEGMENTO)	AS	SEGMENTO
		,MAX(DTH_VENDA)			AS	DTH_VENDA
		,CONVERT(datetime2,convert(varchar(16),CAST(DTH_CADASTRAMENTO AS datetime2))) AS	DTH_ULTIMA_CARGA
		,COUNT(*)				AS	QTD_REGISTROS -- SELECT TOP 8 *
FROM	DMDB41..DM_AIC_PROPOSTA WITH (NOLOCK)
WHERE	NOM_SEGMENTO IN  ( 'VIDA' , 'Vida PF')
AND		CONVERT(VARCHAR(16),CAST(DTH_CADASTRAMENTO AS DATETIME2)) = (	SELECT  CONVERT(VARCHAR(16),CAST(MAX(DTH_CADASTRAMENTO) AS DATETIME2))
																		FROM	DMDB41..DM_AIC_PROPOSTA WITH (NOLOCK)
																		WHERE	NOM_SEGMENTO = 'VIDA') 
GROUP BY NOM_SEGMENTO
		,CONVERT(datetime2,convert(varchar(16),CAST(DTH_CADASTRAMENTO AS datetime2))   )

UNION 

SELECT	'VENDA'					AS	AS
GO
 
