CREATE VIEW [dbo].[VW_CONTROLE_REPLICAS_VIDA_PREVIDENCIA]
AS
select [DTA_REFERENCIA]
      ,[NOM_TABELA]
      ,[ORACLE] as QTD_ORIGEM
      ,[SQL_SERVER] as QTD_REPLICA
      ,[NUM_DIFERENCA]
      ,[DES_INDICADOR]
	  ,'Previdencia' as NOM_SEGMENTO
	  from [DMDB11].[dbo].[SB_P_202004_MONITORAMENTO_REPLICA]
union all
select CONVERT(varchar, [Data], 23) as DTA_REFERENCIA
      ,[tabela] as NOM_TABELA
      ,[contagem_db2] as QTD_ORIGEM
	  ,[contagem_replica] as QTD_REPLICA
	  ,[diferenca] as NUM_DIFERENCA
      ,case when [diferenca] >= 0 then 'OK'
	  else 'ERRO'
	  end DES_INDICADOR
	  ,'Vida' as NOM_SEGMENTO
  FROM [DMDB05].[dbo].[DM_203_ALERTA_REPLICA]
  union all
select CONVERT(varchar, [Data], 23) as DTA_REFERENCIA
      ,[tabela] as NOM_TABELA
      ,[contagem_db2] as QTD_ORIGEM
	  ,[contagem_replica] as QTD_REPLICA
	  ,[diferenca] as NUM_DIFERENCA
      ,case when [diferenca] >= 0 then 'OK'
	  else 'ERRO'
	  end DES_INDICADOR
	  ,'Prestamista' as NOM_SEGMENTO
  FROM [DMDB41].[dbo].[TB_CONTROLE_REPLICA_WISER]
GO
 
IF OBJECT_ID('[dbo].[VW_CONTROLE_SUBSIDIO_SIS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CONTROLE_SUBSIDIO_SIS];
