CREATE VIEW [dbo].[VW_CONTROLE_SUBSIDIO_SIS]
AS

SELECT [DTH_ABERTURA]
      ,[IDT_PROCESSO]
      ,[NOM_SEGMENTO]
      ,[IND_PRAZO_CEF]
      ,[DES_RESPONSAVEL_DISTRIBUICAO]
      ,[DTH_DISTRIBUICAO]
      ,[DES_STATUS_DISTRIBUICAO]
      ,[DES_ANALISTA_RESPONSAVEL]
      ,[COD_UF]
      ,[DES_AUTOR_PRINCIPAL]
      ,[DES_ADVOGADO_AUTOR]
      ,[DES_NATUREZA]
      ,[DES_FATO_GERADOR]
      ,[DTH_PRAZO_JUDICIAL]
      ,isnull([DTH_SOLICITACAO],[DTH_SOLICITACAO_DEVOLUCAO]) as [DTH_SOLICITACAO] -- Data Solicitação para Analise e Data Devolucao para Reanalise
      ,case when [DES_EMPRESA_RE] = 'CEF' THEN 'CAIXA'
			WHEN [DES_EMPRESA_RE] = 'CSH/CEF' THEN 'CSH/CAIXA'
			WHEN [DES_EMPRESA_RE] = 'CVP/CEF' THEN 'CVP/CAIXA'
			else [DES_EMPRESA_RE]
		end as [DES_EMPRESA_RE]
			
      ,[DES_TIPO_PRAZO]
      ,[DTH_PRAZO_ENTREGA]
      ,[DES_STATUS_SOLICITACAO]
      ,[DTH_ENTREGA_SUBSIDIO]
      ,[DES_STATUS_SUBSIDIO]
      ,case when [IND_COMPETENCIA] = 'S' THEN 'SIM' ELSE 'NÃO' END AS [IND_COMPETENCIA]


      ,[QTD_CERTIFICADOS]
      ,[IND_SINISTRO]
      ,[NUM_SINISTRO]
      ,[DES_DEVOLUCAO]
      ,[DTH_SOLICITACAO_DEVOLUCAO]
      ,[DTH_PRAZO_ENTREGA_DEVOLUCAO]
      ,[DES_STATUS_SOLICITACAO_DEVOLUCAO]
      ,[DTH_ENTREGA_SUBSIDIO_DEVOLUCAO]
      ,[DES_STATUS_SUBSIDIO_DEVOLUCAO]
      ,[DES_OBSERVACAO]

	  -- status processo (REPORT)
	  ,CASE 
			WHEN DES_STATUS_DISTRIBUICAO = 'EM ATRASO' and DES_STATUS_SUBSIDIO = 'EM ATENDIMENTO'
				then 'EM ATENDIMENTO - EM ATRASO' 
			WHEN DES_STATUS_DISTRIBUICAO = 'NO PRAZO' and DES_STATUS_SUBSIDIO = 'EM ATENDIMENTO'
				then 'EM ANDAMENTO - NO PRAZO' 
			WHEN DES_STATUS_DISTRIBUICAO = 'NO PRAZO' and DES_STATUS_SUBSIDIO = 'FINALIZADO'
				then 'FINALIZADO - NO PRAZO' 
			WHEN DES_STATUS_DISTRIBUICAO = 'EM ATRASO' and DES_STATUS_SUBSIDIO = 'FINALIZADO'
				then 'FINALIZADO - EM ATRASO' 
			--WHEN DES_STATUS_DISTRIBUICAO is null then 'FINALIZADO - NO PRAZO' 
			ELSE CONCAT([DES_STATUS_SOLICITACAO],' - ', [DES_STATUS_SUBSIDIO]) 
			END AS DES_STATUS

	 -- status devolucao (REPORT)
	  ,CASE WHEN [DTH_ENTREGA_SUBSIDIO_DEVOLUCAO] IS NULL THEN null
			when [DTH_ENTREGA_SUBSIDIO_DEVOLUCAO] IS not NULL then CONCAT('FINALIZADO - ', [DES_STATUS_SUBSIDIO_DEVOLUCAO]) 
			 else CONCAT([DES_STATUS_SOLICITACAO_DEVOLUCAO],' - ', [DES_STATUS_SUBSIDIO_DEVOLUCAO]) 
			end AS DES_STATUS_DEVOLUCAO

		,(select max(TC.dth_carga) from [TB_CONTROLE_SUBSIDIO_SIS] TC) as DTH_ULTIMA_CARGA
		,[IND_DILACAO_PRAZO]
		,[COD_SUBJUD]
		,[IND_DEVOLUCAO]
		,NUM_PROCESSO

  FROM [dbo].[TB_CONTROLE_SUBSIDIO_SIS]


 --where IDT_PROCESSO = 8655525


GO
 
IF OBJECT_ID('[dbo].[VW_CONTROLE_TABELAS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CONTROLE_TABELAS];
