CREATE VIEW [dbo].[VW_CONTROLE_TABELAS]
AS
SELECT hoje.NOM_BANCO as Banco, hoje.NOM_TABELA as Tabela, hoje.NUM_REGISTROS - ontem.NUM_REGISTROS AS Diferenca_dia_anterior, hoje.NUM_REGISTROS AS Total_registros,
case WHEN hoje.NUM_REGISTROS > 0 THEN 
            FORMAT(
                CAST((hoje.NUM_REGISTROS - ontem.NUM_REGISTROS) AS FLOAT) / hoje.NUM_REGISTROS * 100, 
                'N2'
            ) + '%'
        ELSE '0.00%'
		end Porcentagem_alteracao,
case WHEN hoje.NUM_REGISTROS > 0 THEN 
            ROUND(CAST((hoje.NUM_REGISTROS - ontem.NUM_REGISTROS) AS FLOAT) / hoje.NUM_REGISTROS * 100,2)
        ELSE 0
		end Porcentagem_alteracao_numerico


FROM     dbo.DM_DOC_CONTROLE_TABELAS_COUNT_DIFERENCA AS hoje INNER JOIN
                  dbo.DM_DOC_CONTROLE_TABELAS_COUNT_DIFERENCA AS ontem ON hoje.NOM_BANCO = ontem.NOM_BANCO AND hoje.NOM_TABELA = ontem.NOM_TABELA AND hoje.DTH_CONSULTA = CAST(GETDATE() AS DATE) AND 
                  ontem.DTH_CONSULTA = DATEADD(DAY, - 1, CAST(GETDATE() AS DATE))
WHERE hoje.NOM_TABELA not like '%STG_%'

GO
 
