CREATE VIEW [dbo].[VW_CPF_CNPJ_SANCOES_NEOWAY_ATIVOS]
AS
	select  DISTINCT 
	A.NUM_CPF_CNPJ, 
	COD_TIPO_PESSOA,
	'ATIVO' AS DES_STATUS,
	CASE WHEN 
	B.DTA_INICIO_VIGENCIA='1900-01-01' THEN B.DTA_QUITACAO
	ELSE B.DTA_INICIO_VIGENCIA
	END DTA_INICIO_VIGENCIA
	from DM_CLIENTES_CONTRATOS_CVP A
		left join DM_CONTRATOS_CVP B on a.NOM_SEGMENTO=b.NOM_SEGMENTO and a.NUM_CERTIFICADO=b.NUM_CERTIFICADO
	where B.COD_STATUS_CONTRATO='A' 
	AND A.IND_CARGA<>'D'
	AND A.NUM_CPF_CNPJ IS NOT NULL
	AND  A.NUM_CPF_CNPJ not in (-1,0)
	AND A.COD_TIPO_PESSOA<>'N'

GO
 
