GO

CREATE VIEW [dbo].[VW_CPF_CNPJ_SANCOES_NEOWAY_INAT_EXC_VENDAS]
AS
WITH ATIVOS AS (
SELECT DISTINCT
    A.NUM_CPF_CNPJ
FROM DM_CLIENTES_CONTRATOS_CVP A
INNER JOIN DM_CONTRATOS_CVP B 
    ON A.NOM_SEGMENTO = B.NOM_SEGMENTO
   AND A.NUM_CERTIFICADO = B.NUM_CERTIFICADO
WHERE B.COD_STATUS_CONTRATO = 'A'
  AND A.IND_CARGA <> 'D'
  AND A.NUM_CPF_CNPJ IS NOT NULL
  AND A.NUM_CPF_CNPJ NOT IN (-1,0)
)

, INATIVOS AS (
SELECT DISTINCT
    A.NUM_CPF_CNPJ,
    A.COD_TIPO_PESSOA,
    'INATIVO' AS DES_STATUS,
    ISNULL(A.DTH_CARGA_ATUALIZACAO, A.DTH_CARGA) AS DTH_ULTIMA_MOVIMENTACAO
FROM DM_CLIENTES_CONTRATOS_CVP A
INNER JOIN DM_CONTRATOS_CVP B 
    ON A.NOM_SEGMENTO = B.NOM_SEGMENTO
   AND A.NUM_CERTIFICADO = B.NUM_CERTIFICADO
WHERE B.COD_STATUS_CONTRATO = 'I'
  AND A.IND_CARGA <> 'D'
  AND ISNULL(A.DTH_CARGA_ATUALIZACAO, A.DTH_CARGA) >= DATEADD(DAY, -1, GETDATE())
  AND A.NUM_CPF_CNPJ IS NOT NULL
  AND A.NUM_CPF_CNPJ NOT IN (-1,0)
  AND NOT EXISTS (
        SELECT 1
        FROM ATIVOS X
        WHERE X.NUM_CPF_CNPJ = A.NUM_CPF_CNPJ
  )
)

, EXCLUIDOS AS (
SELECT DISTINCT
    A.NUM_CPF_CNPJ,
    A.COD_TIPO_PESSOA,
    'EXCLUIDO' AS DES_STATUS,
    ISNULL(A.DTH_CARGA, A.DTH_CARGA_ATUALIZACAO) AS DTH_ULTIMA_MOVIMENTACAO
FROM DM_CLIENTES_CONTRATOS_CVP A
WHERE A.IND_CARGA = 'D'
  AND A.NUM_CPF_CNPJ IS NOT NULL
  AND A.NUM_CPF_CNPJ NOT IN (-1,0)
  AND ISNULL(A.DTH_CARGA_ATUALIZACAO, A.DTH_CARGA) >= DATEADD(DAY, -1, GETDATE())
  AND NOT EXISTS (
        SELECT 1
        FROM ATIVOS X
        WHERE X.NUM_CPF_CNPJ = A.NUM_CPF_CNPJ
  )
  --AND NOT EXISTS (
  --      SELECT 1
  --      FROM INATIVOS X
  --      WHERE X.NUM_CPF_CNPJ = A.NUM_CPF_CNPJ
  --)
)

, VENDA_DIARIA AS (
SELECT DISTINCT
    B.NUM_CPF_CNPJ,
    CASE B.COD_TIPO_PESSOA
        WHEN 2 THEN 'J'
        ELSE 'F'
    END COD_TIPO_PESSOA,
    'VENDA NOVA' AS DES_STATUS,
    DATEADD(DAY,-1,GETDATE()) AS DTH_ULTIMA_MOVIMENTACAO
FROM VW_PLDFT_CLASSIFICACAO_RISCO_VENDAS_DIARIAS B
)

SELECT *
FROM INATIVOS

UNION ALL

SELECT *
FROM EXCLUIDOS

UNION ALL

SELECT *
FROM VENDA_DIARIA
GO
 
