IF OBJECT_ID('[dbo].[VW_CVP_612_BENEFICIARIO_DIFERENTE]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CVP_612_BENEFICIARIO_DIFERENTE];
GO

CREATE view [dbo].[VW_CVP_612_BENEFICIARIO_DIFERENTE] as 
-- View destinada ao motor 612
-- Recupera os CPFs dos beneficiarios que estão atrelados a mais de um contrato (CPF Titular)
-- PRESTAMISTA
------------------------------
select	distinct  		
		C.NUM_CPF_CNPJ as NUM_CPF_CNPJ_TITULAR, 		
		b.NUM_CPF AS NUM_CPF_CNPJ_BENEFICIARIO 
from 	dmdb42.dbo.DM_ODS_PRS_CONTRATOS_U as C with(nolock)	
		join dmdb42.dbo.DM_DIM_BENEFICIARIOS AS B with(nolock) 			
			ON B.NUM_PROPOSTA_ESTIP = C.NUM_CONTRATO_TERC
where	B.NUM_CPF in (	select	BEN.NUM_CPF 						
						from 	dmdb42.dbo.DM_ODS_PRS_CONTRATOS_U as CON with(nolock) 								
								join dmdb42.dbo.DM_DIM_BENEFICIARIOS AS BEN with(nolock) 									
									ON BEN.NUM_PROPOSTA_ESTIP = CON.NUM_CONTRATO_TERC  						
						where 	CON.STA_CONTRATO_BU = 'A' 								
								and BEN.NUM_CPF is not null 						
						group by BEN.NUM_CPF 						
						having	count(distinct CON.NUM_CPF_CNPJ)> 1)	
union all
-- PREVIDENCIA
------------------------------
SELECT 	CPF_TIT as NUM_CPF_CNPJ_TITULAR,
		NUM_CPF_BENEF as NUM_CPF_CNPJ_BENEFICIARIO
FROM
(
SELECT	DISTINCT
		PE_T.NUM_CPF_CNPJ CPF_TIT,
		BENEF_BASE.NUM_CPF NUM_CPF_BENEF
FROM
		dmdb11.dbo.DM_032_BENEFICIARIO BENEF_BASE with(nolock)
		INNER JOIN dmdb11.dbo.DM_012_CERTIFICADO CER with(nolock)
			ON CER.SUK_CERTIFICADO = BENEF_BASE.SUK_CERTIFICADO
		INNER JOIN dmdb11.dbo.DM_074_BASE_CARTEIRA BC with(nolock)
			ON BC.SUK_CERTIFICADO = BENEF_BASE.SUK_CERTIFICADO
		INNER JOIN dmdb11.dbo.DM_001_PESSOA PE_T with(nolock)
			ON BC.SUK_PESSOA = PE_T.SUK_PESSOA
		INNER JOIN
		(	SELECT NUM_CPF
			FROM	dmdb11.dbo.DM_032_BENEFICIARIO BENEF with(nolock)
					INNER JOIN dmdb11.dbo.DM_012_CERTIFICADO CER with(nolock)
						ON CER.SUK_CERTIFICADO = BENEF.SUK_CERTIFICADO
					INNER JOIN dmdb11.dbo.DM_074_BASE_CARTEIRA BC with(nolock)
						ON BC.SUK_CERTIFICADO = BENEF.SUK_CERTIFICADO
					INNER JOIN dmdb11.dbo.DM_001_PESSOA PE_T with(nolock)
						ON BC.SUK_PESSOA = PE_T.SUK_PESSOA
			GROUP BY NUM_CPF
			HAVING COUNT(DISTINCT PE_T.NUM_CPF_CNPJ) > 1
		) RS
			ON BENEF_BASE.NUM_CPF = RS.NUM_CPF
WHERE	CER.COD_SIT_CERTIFICADO IN ('A','U','B') 
		AND BENEF_BASE.NUM_CPF  <> '00000000000'
		AND BENEF_BASE.NUM_CPF  <> '99999999999'
) RS2
WHERE CPF_TIT <>  NUM_CPF_BENEF

GO
 
IF OBJECT_ID('[dbo].[VW_CVP_612_CLIENTES_ATIVOS_AUDIT]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CVP_612_CLIENTES_ATIVOS_AUDIT];
