-- DEMANDA
-- GEGOP - 1408 - Disponibilizar base de clientes ativos
-----------------------------------------------------------------
creATE view VW_CVP_612_CLIENTES_ATIVOS_AUDIT AS 


select	distinct 
		CLI.NOM_SEGMENTO,
		cli.DES_PESSOA,
		CLI.NOM_PESSOA,
		CLI.NUM_CPF_CNPJ,
		C.COD_PRODUTO,
		P.DES_PRODUTO,
		C.DTA_INICIO_VIGENCIA,
		CLI.NUM_CERTIFICADO,
		CLI.IND_PEP,
		CLi.NUM_SCORE_RISCO,
		CLI.DES_CLASSIFICACAO_RISCO,
		C.DES_CANAL_VENDA

from	DM_CLIENTES_CONTRATOS_CVP as CLI
		left join DM_CONTRATOS_CVP as C
			on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
			and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO
		left join VW_PRODUTOS_CVP as P
			on P.COD_PRODUTO_COMPLETO = C.COD_PRODUTO_COMPLETO

where	C.COD_STATUS_CONTRATO = 'A'
		and cli.NUM_CPF_CNPJ <> 0 
		and cli.NUM_CPF_CNPJ is not null
GO
 
