CREATE view [dbo].[VW_CVP_612_NLIST_COMPLETA] as 

-- view VW_CVP_612_NLIST_COMPLETA
select	NUM_CPF_CNPJ as CPF_CNPJ,
		NOM_NOME as NOME,
		IND_TIPO_PESSOA as TIPO_PESSOA,
		cast(case when IND_IMPEDIDO ='SIM' THEN 'S' ELSE 'N' END as char(1)) as IMPEDIDO,
		DES_ORIGEM as COD_ORIGEM,
		DES_COMENTARIOS as COMENTARIOS,
		IND_TIPO_OPERACAO as TIPO_OPERACAO,
		IND_TIPO_NLIST as IND_TIPO_NLIST,
		NUM_CPF_CNPJ_TITULAR_RELACIONADO,
		DTA_INI_VIGENCIA as DTA_INI_VIGENCIA,
		DTA_FIM_VIGENCIA as DTA_FIM_VIGENCIA,
		DTH_CARGA as DTH_CARGA,
		DTH_ATUALIZACAO

from	[dbo].[DM_NLIST_CVP]
where	DTA_FIM_VIGENCIA is null
GO
 
IF OBJECT_ID('[dbo].[VW_CVP_612_PEP_COMPLETA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CVP_612_PEP_COMPLETA];
