 CREATE view [dbo].[VW_CVP_612_PEP_COMPLETA] as 
-------------------------------------
-- CTE01 - PEP Softon
-------------------------------------
with PEP_SOFTON as 
(
SELECT
	cast(P.[CPF_CNPJ] as bigint) as [CPF_CNPJ]
	,P.[NOME_RAZAOSOCIAL]
	,P.[APELIDO_NOMEFANTASIA]
	,P.[SEXO]
	,P.[DTA_NASCIMENTO]
	,P.[NOME_CARGO]
	,P.[NOME_ORGAO]
	,P.[MUNICIPIO_CARGO]
	,P.[UF_CARGO]
	,P.DTA_INICIO_VIGENCIA as [DTA_INI_EXERCICIO]
	,P.[DTA_FIM_EXERCICIO]
	,P.[DTA_FIM_VIGENCIA_PEP]
	,P.DTA_FIM_VIGENCIA
	,P.[TIPO_PEP]
	,P.[CPF_PEP_RELACIONADO]
	,P.[NOME_PEP_RELACIONADO]

	--nova regra de relacionamento -----------------------------
	,case	when P.[TIPO_PEP] = 'R' and P.[GRAU_RELACIONAMENTO] in ('SOCIA','SOCIO') THEN 'EC' -- Estreito Colaborador
			when P.[TIPO_PEP] = 'R' then 'FA' -- Familiar
			else null
	end as [GRAU_RELACIONAMENTO]

	,P.[CNPJ_EMPRESA_RELACIONADA]
	,P.[NOME_EMPRESA_RELACIONADA]
	,case when P.[TIPO_PESSOA] = 'PF' then 'F'
		when P.[TIPO_PESSOA] = 'PJ' then 'J'
		else P.[TIPO_PESSOA]
	end as [TIPO_PESSOA]
	,NULL as [TXT_NOTICIA]
	,'SOFTON' AS DES_ORI
	,P.ID
	,P.DTA_CARGA
	
from	[dbo].[DM_PEP_CVP] P -- PEP Softon
where	P.DTA_FIM_VIGENCIA is null -- sem data de final de vigencia		
		and P.[CPF_CNPJ] <> -8

),
-------------------------------------
-- Uniao entre PEP Softon e PEP Cruzado
-- CTE01 - PEP Cruzado
-------------------------------------
PEP_CRUZADO as 
(

SELECT 
	distinct 
	cast([CPF_CNPJ] as bigint) as [CPF_CNPJ]
	,NOME AS [NOME_RAZAOSOCIAL]
	,NULL AS [APELIDO_NOMEFANTASIA]
	,NULL AS [SEXO]
	,NULL AS [DTA_NASCIMENTO]
	,CARGO AS [NOME_CARGO]
	,INSTITUICAO AS [NOME_ORGAO]
	,NULL AS [MUNICIPIO_CARGO]
	,NULL AS [UF_CARGO]
	,DTA_INI_VIGENCIA AS DTA_INI_EXERCICIO
	,DTA_INI_VIGENCIA AS DTA_FIM_EXERCICIO
	,NULL AS [DTA_FIM_VIGENCIA_PEP]
	,DTA_FIM_VIGENCIA
	,[TIPO_PEP]
	,CPF_CNPJ_TITULAR_RELACIONADO AS [CPF_PEP_RELACIONADO]
	,NOME_TITULAR_RELACIONADO AS [NOME_PEP_RELACIONADO]
	,GRAU_RELAC_PEP as [GRAU_RELACIONAMENTO]
	,CASE WHEN TIPO_PESSOA_TITULAR_RELACIONADO = 'J' THEN   CPF_CNPJ_TITULAR_RELACIONADO
		ELSE NULL 
	END AS [CNPJ_EMPRESA_RELACIONADA]
	,CASE WHEN TIPO_PESSOA_TITULAR_RELACIONADO = 'J' THEN   NOME_TITULAR_RELACIONADO
		ELSE NULL 
	END AS [NOME_EMPRESA_RELACIONADA]

	,case when PC.[TIPO_PESSOA] = 'PF' then 'F'
		when PC.[TIPO_PESSOA] = 'PJ' then 'J'
		else PC.[TIPO_PESSOA]
	end as [TIPO_PESSOA]

	,NULL as [TXT_NOTICIA]
	,'CRUZADO' AS DES_ORI
	,ID
	,DTA_CARGA

from	[dbo].[DM_PEP_CRUZADO_CVP] as PC

where	DTA_FIM_VIGENCIA is null -- sem data de final de vigencia
		AND TIPO_PEP = 'R' -- Relacionado
		and [CPF_CNPJ] <> -8
		and PC.id = (	SELECT MAX(PC2.id) 
						from [dbo].[DM_PEP_CRUZADO_CVP] as PC2 
						where PC.CPF_CNPJ = PC2.CPF_CNPJ
						and		PC2.DTA_FIM_VIGENCIA is null -- sem data de final de vigencia
								AND PC2.TIPO_PEP = 'R' -- Relacionado
								and PC2.[CPF_CNPJ] <> -8)
)

-------------------------------------
-- Uniao entre PEP Softon e PEP Cruzado
-------------------------------------
select 
	   A.CPF_CNPJ
      ,A.NOME_RAZAOSOCIAL
      ,A.APELIDO_NOMEFANTASIA
      ,A.SEXO
      ,A.DTA_NASCIMENTO
      ,A.NOME_CARGO
      ,A.NOME_ORGAO
      ,A.MUNICIPIO_CARGO
      ,A.UF_CARGO
      ,A.DTA_INI_EXERCICIO
      ,A.DTA_FIM_EXERCICIO
      ,A.DTA_FIM_VIGENCIA_PEP
	  ,A.DTA_FIM_VIGENCIA
      ,A.TIPO_PEP
      ,A.CPF_PEP_RELACIONADO
      ,A.NOME_PEP_RELACIONADO
      ,A.GRAU_RELACIONAMENTO
      ,A.CNPJ_EMPRESA_RELACIONADA
      ,A.NOME_EMPRESA_RELACIONADA
      ,A.TIPO_PESSOA
      ,A.TXT_NOTICIA
	  ,A.DES_ORI
	  ,A.DTA_CARGA

from 
(
	Select * from PEP_SOFTON as S
	union
	Select * from PEP_CRUZADO as C 
	where C.CPF_CNPJ not in (Select CPF_CNPJ from PEP_SOFTON)
			
) A



GO
 
IF OBJECT_ID('[dbo].[VW_CVP_612_PEP_MONITORAMENTO_DADOS_INCOMPLETOS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CVP_612_PEP_MONITORAMENTO_DADOS_INCOMPLETOS];
GO

------------------------------------------
--- Monitoramento Dados Completos
------------------------------------------

CREATE view [dbo].[VW_CVP_612_PEP_MONITORAMENTO_DADOS_INCOMPLETOS]
as 

select	VALID.NOM_SEGMENTO,
		VALID.DES_PESSOA,
		VALID.NUM_CERTIFICADO,
		VALID.ANO_CONTRATACAO,
		VALID.MES_CONTRATACAO,
		VALID.NUM_CPF_CNPJ,
		VALID.NOM_PESSOA,
		case	when VALID.COD_TIPO_PESSOA = 'J' then	'Pessoa Jurídica'
				when VALID.COD_TIPO_PESSOA = 'F' then	'Pessoa Física'
				else 'Não Informado'
		end as COD_TIPO_PESSOA,

		-- Endereço
		VALID.NOM_LOGRADOURO,
		VALID.NOM_BAIRRO,
		VALID.COD_CEP,
		VALID.NOM_CIDADE,
		VALID.COD_UF,

		case when IND_VALIDA_NOM_PESSOA = 1 then 'Não' else 'Sim' end as IND_VALIDA_NOM_PESSOA,
		case when IND_VALIDA_NUM_CPF_CNPJ = 1 then 'Não' else 'Sim' end as IND_VALIDA_NUM_CPF_CNPJ,
		case when (IND_VALIDA_NOM_LOGRADOURO + IND_VALIDA_COD_CEP +IND_VALIDA_NOM_CIDADE + IND_VALIDA_COD_UF) > 0 then 'Não' else 'Sim' end as IND_VALIDA_ENREDECO,
		DTA_INICIO_VIGENCIA

from (

select	CLI.NOM_SEGMENTO,
		CLI.DES_PESSOA,
		CLI.NUM_CERTIFICADO,
		YEAR(con.DTA_INICIO_VIGENCIA) AS ANO_CONTRATACAO,
		MONTH(con.DTA_INICIO_VIGENCIA) AS MES_CONTRATACAO,
		con.DTA_INICIO_VIGENCIA,
		CLI.NUM_CPF_CNPJ,
		CLI.NOM_PESSOA,
		CLI.COD_TIPO_PESSOA,
		CLI.NOM_LOGRADOURO,
		CLI.NOM_BAIRRO,
		CLI.COD_CEP,
		CLI.NOM_CIDADE,
		CLI.COD_UF,

		----------------------------
		-- VALIDADORES
		-- 1. Sem dado / 0. Dado OK
		----------------------------
		case when CLI.NOM_PESSOA is null then 1 else 0 end AS IND_VALIDA_NOM_PESSOA,
		case when (CLI.NUM_CPF_CNPJ IS NULL or CLI.NUM_CPF_CNPJ = 0) then 1 else 0 end as IND_VALIDA_NUM_CPF_CNPJ,
		case when CLI.NOM_LOGRADOURO is null then 1 else 0 end as IND_VALIDA_NOM_LOGRADOURO,
		--case when CLI.NOM_BAIRRO is null or TRIM(CLI.NOM_BAIRRO) = '' then 1 else 0 end as IND_VALIDA_NOM_BAIRRO,
		case when CLI.COD_CEP is null or TRIM(CLI.COD_CEP) = '' then 1 else 0 end as IND_VALIDA_COD_CEP,
		case when CLI.NOM_CIDADE is null then 1 else 0 end as IND_VALIDA_NOM_CIDADE,
		case when CLI.COD_UF is null then 1 else 0 end as IND_VALIDA_COD_UF


from	DM_CLIENTES_CONTRATOS_CVP as CLI
		left join DM_CONTRATOS_CVP as CON
			on CLI.NUM_CERTIFICADO = CON.NUM_CERTIFICADO
			and CLI.NOM_SEGMENTO = CON.NOM_SEGMENTO
	
where	CON.COD_STATUS_CONTRATO = 'A'
		AND CLI.COD_PESSOA in (1,3,5) 
		and  CON.DTA_INICIO_VIGENCIA >= '2022-06-01'

		-- VALIDA ATRIBUTOS
		----------------------------
		AND 
		(	CLI.NOM_PESSOA IS NULL
			or CLI.NUM_CPF_CNPJ IS NULL 
			or CLI.NUM_CPF_CNPJ = 0
			or CLI.NOM_LOGRADOURO is null
			--or CLI.NOM_BAIRRO is null
			or CLI.COD_CEP is null
			--OR TRIM(CLI.NOM_BAIRRO) = ''
			or CLI.NOM_CIDADE is null 
			or CLI.COD_UF is null
		)
		
) VALID



--  select distinct NOM_BAIRRO, nom_segmento, cod_pessoa from DM_CLIENTES_CONTRATOS_CVP order by 1
--  where NUM_CERTIFICADO = 
--  83446460000345
GO
 
IF OBJECT_ID('[dbo].[VW_CVP_612_REINCIDENCIA_REPRESENTANTE]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CVP_612_REINCIDENCIA_REPRESENTANTE];
GO
CREATE view [dbo].[VW_CVP_612_REINCIDENCIA_REPRESENTANTE] as   
-- View destinada ao motor 612
-- Recupera os representantes em mais de CNPJ (PJ)
-- PRESTAMISTA
---------------------------------------
select	distinct  		
		R.num_Cpf_CNPJ_REPRESENTANTE as CPF_SOCIO,
		R.NUM_CPF_CNPJ_SEGURADO as CNPJ_EMPRESA
		
from   dmdb42..DM_DIM_REPRESENTANTE_PJ AS R  with(nolock)	
where	R.num_Cpf_CNPJ_REPRESENTANTE in (	Select  S.num_Cpf_CNPJ_REPRESENTANTE as SOCIO 						
							from 	dmdb42.dbo.DM_ODS_PRS_CONTRATOS_U as C  with(nolock)										
									join	dmdb42..DM_DIM_REPRESENTANTE_PJ as S  with(nolock)											
												on S.NUM_PROPOSTA = C.NUM_PROPOSTA_ESTIP  						
									where 	C.STA_CONTRATO = 'A' 								
											and C.IND_TP_PESSOA = 'J' 								
											and S.num_Cpf_CNPJ_REPRESENTANTE <> 0 						
									group by S.num_Cpf_CNPJ_REPRESENTANTE 						
									having	count(distinct C.NUM_CPF_CNPJ)> 1)
union all
-- PREVIDENCIA
---------------------------------------
SELECT	DISTINCT
		RL.CPF_CNPJ_REPRESENTANTE CPF_SOCIO,
		RL.CPF_CNPJ CNPJ_EMPRESA
FROM	dmdb11.dbo.SB_P_202108_PREV_REPRESENTANTES_LEGAIS RL with(nolock)	
		INNER JOIN
		(	SELECT CPF_CNPJ_REPRESENTANTE
			FROM dmdb11.dbo.SB_P_202108_PREV_REPRESENTANTES_LEGAIS with(nolock)	
			WHERE CPF_CNPJ_REPRESENTANTE <> '00000000000'
			GROUP BY CPF_CNPJ_REPRESENTANTE
			HAVING COUNT(DISTINCT CPF_CNPJ) > 1
		) RS
			ON RS.CPF_CNPJ_REPRESENTANTE = RL.CPF_CNPJ_REPRESENTANTE
WHERE	RL.CPF_CNPJ_REPRESENTANTE <> '00000000000'
GO
 
IF OBJECT_ID('[dbo].[VW_CVP_PLD_BENEFICIARIO_DIFERENTE]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CVP_PLD_BENEFICIARIO_DIFERENTE];
GO

CREATE view [dbo].[VW_CVP_PLD_BENEFICIARIO_DIFERENTE] as 
-- View destinada ao motor 612
-- Recupera os CPFs dos beneficiarios que estão atrelados a mais de um contrato (CPF Titular)
-- PRESTAMISTA
------------------------------
select	distinct  		
		C.NUM_CPF_CNPJ as NUM_CPF_CNPJ_TITULAR, 		
		b.NUM_CPF AS NUM_CPF_CNPJ_BENEFICIARIO 
from 	dmdb42.dbo.DM_ODS_PRS_CONTRATOS_U as C with(nolock)	
		join dmdb42.dbo.DM_DIM_BENEFICIARIOS AS B with(nolock) 			
			ON B.NUM_PROPOSTA_ESTIP = C.NUM_CONTRATO_TERC
where	B.NUM_CPF in (	select	BEN.NUM_CPF 						
						from 	dmdb42.dbo.DM_ODS_PRS_CONTRATOS_U as CON with(nolock) 								
								join dmdb42.dbo.DM_DIM_BENEFICIARIOS AS BEN with(nolock) 									
									ON BEN.NUM_PROPOSTA_ESTIP = CON.NUM_CONTRATO_TERC  						
						where 	CON.STA_CONTRATO_BU = 'A' 								
								and BEN.NUM_CPF is not null 						
						group by BEN.NUM_CPF 						
						having	count(distinct CON.NUM_CPF_CNPJ)> 1)	
union all
-- PREVIDENCIA
------------------------------
SELECT 	CPF_TIT as NUM_CPF_CNPJ_TITULAR,
		NUM_CPF_BENEF as NUM_CPF_CNPJ_BENEFICIARIO
FROM
(
SELECT	DISTINCT
		PE_T.NUM_CPF_CNPJ CPF_TIT,
		BENEF_BASE.NUM_CPF NUM_CPF_BENEF
FROM
		dmdb11.dbo.DM_032_BENEFICIARIO BENEF_BASE with(nolock)
		INNER JOIN dmdb11.dbo.DM_012_CERTIFICADO CER with(nolock)
			ON CER.SUK_CERTIFICADO = BENEF_BASE.SUK_CERTIFICADO
		INNER JOIN dmdb11.dbo.DM_074_BASE_CARTEIRA BC with(nolock)
			ON BC.SUK_CERTIFICADO = BENEF_BASE.SUK_CERTIFICADO
		INNER JOIN dmdb11.dbo.DM_001_PESSOA PE_T with(nolock)
			ON BC.SUK_PESSOA = PE_T.SUK_PESSOA
		INNER JOIN
		(	SELECT NUM_CPF
			FROM	dmdb11.dbo.DM_032_BENEFICIARIO BENEF with(nolock)
					INNER JOIN dmdb11.dbo.DM_012_CERTIFICADO CER with(nolock)
						ON CER.SUK_CERTIFICADO = BENEF.SUK_CERTIFICADO
					INNER JOIN dmdb11.dbo.DM_074_BASE_CARTEIRA BC with(nolock)
						ON BC.SUK_CERTIFICADO = BENEF.SUK_CERTIFICADO
					INNER JOIN dmdb11.dbo.DM_001_PESSOA PE_T with(nolock)
						ON BC.SUK_PESSOA = PE_T.SUK_PESSOA
			GROUP BY NUM_CPF
			HAVING COUNT(DISTINCT PE_T.NUM_CPF_CNPJ) > 1
		) RS
			ON BENEF_BASE.NUM_CPF = RS.NUM_CPF
WHERE	CER.COD_SIT_CERTIFICADO IN ('A','U','B') 
		AND BENEF_BASE.NUM_CPF  <> '00000000000'
		AND BENEF_BASE.NUM_CPF  <> '99999999999'
) RS2
WHERE CPF_TIT <>  NUM_CPF_BENEF

GO
 
