/*PESQUISA ENDEREÇOS DAS VIEWS DO MOTOR (DIARIA E SEMANAL)*/
CREATE VIEW dbo.VW_PLDFT_CIDADES_FRONTEIRICAS
AS
WITH ENDERECO AS (SELECT NUM_CPF_CNPJ, NOM_PESSOA, COD_TIPO_PESSOA, NOM_CIDADE, COD_UF
                                   FROM    dbo.VW_PLDFT_CLASSIFICACAO_RISCO_VENDAS_DIARIAS
                                   UNION ALL
                                   SELECT NUM_CPF_CNPJ, NOM_PESSOA, COD_TIPO_PESSOA, NOM_CIDADE, COD_UF
                                   FROM   dbo.VW_PLDFT_RECLASSIFICACAO_SIS)
    SELECT DISTINCT E.NUM_CPF_CNPJ, E.NOM_PESSOA, E.COD_TIPO_PESSOA, E.NOM_CIDADE, E.COD_UF, CASE WHEN MUN.NOM_CIDADE IS NOT NULL THEN 'S' ELSE 'N' END AS IND_FRONTEIRA
   FROM    ENDERECO AS E LEFT OUTER JOIN
                dbo.TB_MUNICIPIO_FRONTEIRA AS MUN ON REPLACE(REPLACE(REPLACE(E.NOM_CIDADE COLLATE Latin1_General_CI_AI, '-', ' '), '''', ''), '"', '') = MUN.NOM_CIDADE_PURO AND E.COD_UF = MUN.COD_UF
   WHERE (E.NUM_CPF_CNPJ > 0)
GO
 
IF OBJECT_ID('[dbo].[VW_CVP_PLD_CIDADES_FRONTEIRICAS_BASE_HISTORICA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CVP_PLD_CIDADES_FRONTEIRICAS_BASE_HISTORICA];
GO
/*PESQUISA ENDEREÇOS BASE HISTORICA BUCC*/
CREATE VIEW dbo.VW_CVP_PLD_CIDADES_FRONTEIRICAS_BASE_HISTORICA
AS
WITH ENDERECO AS (SELECT CC.NUM_CPF_CNPJ, CC.NOM_PESSOA, CC.COD_TIPO_PESSOA, CC.NOM_CIDADE, CC.COD_UF
                                   FROM    dbo.DM_CLIENTES_CONTRATOS_CVP AS CC LEFT OUTER JOIN
                                                dbo.DM_CONTRATOS_CVP AS CON ON CC.NUM_CERTIFICADO = CON.NUM_CERTIFICADO AND CC.NOM_SEGMENTO = CON.NOM_SEGMENTO
                                   WHERE (CON.COD_STATUS_CONTRATO = 'A'))
    SELECT DISTINCT E.NUM_CPF_CNPJ, E.NOM_PESSOA, E.COD_TIPO_PESSOA, E.NOM_CIDADE, E.COD_UF, CASE WHEN MUN.NOM_CIDADE IS NOT NULL THEN 'S' ELSE 'N' END AS IND_FRONTEIRA
   FROM    ENDERECO AS E LEFT OUTER JOIN
                dbo.TB_MUNICIPIO_FRONTEIRA AS MUN ON REPLACE(REPLACE(REPLACE(E.NOM_CIDADE COLLATE Latin1_General_CI_AI, '-', ' '), '''', ''), '"', '') = MUN.NOM_CIDADE_PURO AND E.COD_UF = MUN.COD_UF
GO
 
