-- Todos os segmentos (BUCC)
--------------------------------------------------------------------
CREATE view [VW_CVP_PLD_CLIENTES_ONGS] AS 
SELECT	distinct

		d.EMPRESA as EMPRESA_SIGLA,
		a.NOM_PESSOA as NOME,
		a.NUM_CPF_CNPJ as CPF_CNPJ,
		a.COD_TIPO_PESSOA as TIPO_PESSOA,
		b.COD_PRODUTO as COD_PRODUTO,
		d.DES_PRODUTO as NOME_PRODUTO,
		b.NUM_CERTIFICADO as NUM_CERTIFICADO,
		a.NOM_PESSOA as NOME_TITULAR,
		a.NUM_CPF_CNPJ as CPF_TITULAR,
		a.NOM_SEGMENTO
		
from	DM_CLIENTES_CONTRATOS_CVP a
		left join DM_CONTRATOS_CVP b 
			on a.NOM_SEGMENTO=b.NOM_SEGMENTO 
			and a.NUM_CERTIFICADO=b.NUM_CERTIFICADO
		left join VW_PRODUTOS_CVP d 
			on b.COD_PRODUTO_COMPLETO=d.COD_PRODUTO_COMPLETO
 
where	a.COD_CNAE= 9430800 -- ONGS
GO
 
