CREATE VIEW [dbo].[VW_CVP_PLD_CONSULTAS_SOFTON]
AS
WITH PEP AS (SELECT DISTINCT NUM_CPF_CNPJ, 'S' AS IND_PEP
                       FROM   dbo.TB_CONSULTA_DTFLEX
                       WHERE (IND_PEP = 'S')),
	FONTES as (SELECT 
    NUM_CPF_CNPJ,
	CASE WHEN DES_LINK_NOTICIA IS NOT NULL THEN 'MIDIA NEGATIVA' ELSE 'LISTAS SOFTON' END AS FONTE,
    STRING_AGG(DES_FONTE_NOTICIA, ', ') WITHIN GROUP (ORDER BY DES_FONTE_NOTICIA) AS NOME_FONTE
FROM (
    SELECT DISTINCT NUM_CPF_CNPJ, DES_FONTE_NOTICIA, DES_LINK_NOTICIA
    FROM dbo.TB_CONSULTA_DTFLEX 	
) AS X
GROUP BY NUM_CPF_CNPJ,
CASE WHEN DES_LINK_NOTICIA IS NOT NULL THEN 'MIDIA NEGATIVA' ELSE 'LISTAS SOFTON' END
),
	PROCESSO as (SELECT
	NUM_CPF_CNPJ,
	IND_PROCESSO
	FROM   dbo.TB_CONSULTA_DTFLEX
	WHERE IND_PROCESSO = 'S'
	)
    SELECT DISTINCT 
                T.NUM_CPF_CNPJ, T.NOM_PESSOA, T.COD_TIPO_PESSOA, DES_TIPO_SUSPEITA, 
                FONTE,NOME_FONTE, P.IND_PEP
				 ,PR.IND_PROCESSO
				
   FROM    dbo.TB_CONSULTA_DTFLEX AS T LEFT OUTER JOIN
                PEP AS P ON T.NUM_CPF_CNPJ = P.NUM_CPF_CNPJ LEFT OUTER JOIN
				FONTES F ON T.NUM_CPF_CNPJ = F.NUM_CPF_CNPJ and CASE WHEN DES_LINK_NOTICIA IS NOT NULL THEN 'MIDIA NEGATIVA' ELSE 'LISTAS SOFTON' END = F.FONTE LEFT OUTER JOIN 
				PROCESSO PR ON T.NUM_CPF_CNPJ = PR.NUM_CPF_CNPJ
GO
 
