IF OBJECT_ID('[dbo].[VW_CVP_PLD_PEP_COMPLETA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_CVP_PLD_PEP_COMPLETA];
GO

 CREATE view [dbo].[VW_CVP_PLD_PEP_COMPLETA] as 
-------------------------------------
-- CTE01 - PEP Softon
-------------------------------------
with PEP_SOFTON as 
(
SELECT
	cast(P.[CPF_CNPJ] as bigint) as [CPF_CNPJ]
	,P.[NOME_RAZAOSOCIAL]
	,P.[APELIDO_NOMEFANTASIA]
	,P.[SEXO]
	,P.[DTA_NASCIMENTO]
	,P.[NOME_CARGO]
	,P.[NOME_ORGAO]
	,P.[MUNICIPIO_CARGO]
	,P.[UF_CARGO]
	,P.DTA_INICIO_VIGENCIA as [DTA_INI_EXERCICIO]
	,P.[DTA_FIM_EXERCICIO]
	,P.[DTA_FIM_VIGENCIA_PEP]
	,P.DTA_FIM_VIGENCIA
	,P.[TIPO_PEP]
	,P.[CPF_PEP_RELACIONADO]
	,P.[NOME_PEP_RELACIONADO]

	--nova regra de relacionamento -----------------------------
	,case	when P.[TIPO_PEP] = 'R' and P.[GRAU_RELACIONAMENTO] in ('SOCIA','SOCIO') THEN 'EC' -- Estreito Colaborador
			when P.[TIPO_PEP] = 'R' then 'FA' -- Familiar
			else null
	end as [GRAU_RELACIONAMENTO]

	,P.[CNPJ_EMPRESA_RELACIONADA]
	,P.[NOME_EMPRESA_RELACIONADA]
	,case when P.[TIPO_PESSOA] = 'PF' then 'F'
		when P.[TIPO_PESSOA] = 'PJ' then 'J'
		else P.[TIPO_PESSOA]
	end as [TIPO_PESSOA]
	,NULL as [TXT_NOTICIA]
	,'SOFTON' AS DES_ORI
	,P.ID
	,P.DTA_CARGA
	
from	[dbo].[DM_PEP_CVP] P -- PEP Softon
where	P.DTA_FIM_VIGENCIA is null -- sem data de final de vigencia		
		and P.[CPF_CNPJ] <> -8

),
-------------------------------------
-- Uniao entre PEP Softon e PEP Cruzado
-- CTE01 - PEP Cruzado
-------------------------------------
PEP_CRUZADO as 
(

SELECT 
	distinct 
	cast([CPF_CNPJ] as bigint) as [CPF_CNPJ]
	,NOME AS [NOME_RAZAOSOCIAL]
	,NULL AS [APELIDO_NOMEFANTASIA]
	,NULL AS [SEXO]
	,NULL AS [DTA_NASCIMENTO]
	,CARGO AS [NOME_CARGO]
	,INSTITUICAO AS [NOME_ORGAO]
	,NULL AS [MUNICIPIO_CARGO]
	,NULL AS [UF_CARGO]
	,DTA_INI_VIGENCIA AS DTA_INI_EXERCICIO
	,DTA_INI_VIGENCIA AS DTA_FIM_EXERCICIO
	,NULL AS [DTA_FIM_VIGENCIA_PEP]
	,DTA_FIM_VIGENCIA
	,[TIPO_PEP]
	,CPF_CNPJ_TITULAR_RELACIONADO AS [CPF_PEP_RELACIONADO]
	,NOME_TITULAR_RELACIONADO AS [NOME_PEP_RELACIONADO]
	,GRAU_RELAC_PEP as [GRAU_RELACIONAMENTO]
	,CASE WHEN TIPO_PESSOA_TITULAR_RELACIONADO = 'J' THEN   CPF_CNPJ_TITULAR_RELACIONADO
		ELSE NULL 
	END AS [CNPJ_EMPRESA_RELACIONADA]
	,CASE WHEN TIPO_PESSOA_TITULAR_RELACIONADO = 'J' THEN   NOME_TITULAR_RELACIONADO
		ELSE NULL 
	END AS [NOME_EMPRESA_RELACIONADA]

	,case when PC.[TIPO_PESSOA] = 'PF' then 'F'
		when PC.[TIPO_PESSOA] = 'PJ' then 'J'
		else PC.[TIPO_PESSOA]
	end as [TIPO_PESSOA]

	,NULL as [TXT_NOTICIA]
	,'CRUZADO' AS DES_ORI
	,ID
	,DTA_CARGA

from	[dbo].[DM_PEP_CRUZADO_CVP] as PC

where	DTA_FIM_VIGENCIA is null -- sem data de final de vigencia
		AND TIPO_PEP = 'R' -- Relacionado
		and [CPF_CNPJ] <> -8
		and PC.id = (	SELECT MAX(PC2.id) 
						from [dbo].[DM_PEP_CRUZADO_CVP] as PC2 
						where PC.CPF_CNPJ = PC2.CPF_CNPJ
						and		PC2.DTA_FIM_VIGENCIA is null -- sem data de final de vigencia
								AND PC2.TIPO_PEP = 'R' -- Relacionado
								and PC2.[CPF_CNPJ] <> -8)
)

-------------------------------------
-- Uniao entre PEP Softon e PEP Cruzado
-------------------------------------
select 
	   A.CPF_CNPJ
      ,A.NOME_RAZAOSOCIAL
      ,A.APELIDO_NOMEFANTASIA
      ,A.SEXO
      ,A.DTA_NASCIMENTO
      ,A.NOME_CARGO
      ,A.NOME_ORGAO
      ,A.MUNICIPIO_CARGO
      ,A.UF_CARGO
      ,A.DTA_INI_EXERCICIO
      ,A.DTA_FIM_EXERCICIO
      ,A.DTA_FIM_VIGENCIA_PEP
	  ,A.DTA_FIM_VIGENCIA
      ,A.TIPO_PEP
      ,A.CPF_PEP_RELACIONADO
      ,A.NOME_PEP_RELACIONADO
      ,A.GRAU_RELACIONAMENTO
      ,A.CNPJ_EMPRESA_RELACIONADA
      ,A.NOME_EMPRESA_RELACIONADA
      ,A.TIPO_PESSOA
      ,A.TXT_NOTICIA
	  ,A.DES_ORI
	  ,A.DTA_CARGA

from 
(
	Select * from PEP_SOFTON as S
	union
	Select * from PEP_CRUZADO as C 
	where C.CPF_CNPJ not in (Select CPF_CNPJ from PEP_SOFTON)
			
) A



GO
 
IF OBJECT_ID('[dbo].[VW_DECLINIOS_PRESTAMISTA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_DECLINIOS_PRESTAMISTA];
GO
---------------------------------------------------------------
--- DECLINO PRESTAMISTA
---------------------------------------------------------------




 CREATE view DBO.VW_DECLINIOS_PRESTAMISTA as 
 (


select  AGE.COD_AGENCIA AS CodigoAgencia,
        P.NUM_PROPOSTA_ESTIP AS NumProposta,
        CASE WHEN P.STA_DOCUMENTO = 'NRU' AND S.MotivoDeclinio IS NULL AND CRI.MotivoDeclinio IS NULL THEN 'NAO REALIZOU UPLOAD'
		ELSE ISNULL(S.MotivoDeclinio, CRI.MotivoDeclinio) END AS MotivoDeclinio,
        isnull(P.DTH_FINANC_DEVOLUCAO,DTA_RECEBIMENTO_FINANC) AS DataHoraPrevistaDevolucao,
        P.NUM_CPF_CNPJ_SEGURADO AS CpfCnpjSegurado,
        P.NOM_SEGURADO AS NomeSegurado,
        P.COD_PRODUTO AS Produto,
        P.VLR_PREMIO AS ValorPremio,
        P.COD_BANCO AS BancoDevolucao,
        P.NUM_CC_BANCO AS ContaDevolucao,
        P.NUM_DV_CONTA_BANCO AS DVContaDevolucao,
        CASE WHEN P.NUM_CC_BANCO IS NULL THEN 'S'
        ELSE 'N' END AS PendenciaConta
    
from    DMDb42..DM_ODS_PRS_PROPOSTAS_U as P
        LEFT JOIN	(
						select  P.SEQ_PROPOSTA,
								S.DES_JUSTIFICATIVA AS MotivoDeclinio
    
						from    DMDb42..DM_ODS_PRS_PROPOSTAS_U as P
								LEFT JOIN DMDb42..DM_ODS_PRS_PROPOSTAS_SUBSCRICAO AS S
									ON S.NUM_PROPOSTA_ESTIP = P.NUM_PROPOSTA_ESTIP
 
						where   YEAR(P.DTA_PROPOSTA)  >= YEAR(GETDATE())
								and P.STA_MOVTO = 'REJ'
								and P.STA_PROPOSTA = '2' -- NÃO ACEITA
								and S.STA_AUTORIZACAO = 'D' -- Declinada pela subscrição
								and  P.COD_SUB_TIPO_REPASSE NOT IN (2,7,6) -- retira os cancelamentos
					)
		AS S
            ON S.SEQ_PROPOSTA = P.SEQ_PROPOSTA
        left join 
				(
					select  STRING_AGG(DES_CRITICA, ', ') as MotivoDeclinio, 
					seq_proposta            
					from    DMDb42..DM_DIM_CRITICAS_PROPOSTA
					where   IND_TP_CRITICA = 'F' -- Fatal
							and COD_CRITICA NOT IN (4034, 4035, 4037, 4036, 4004, 208, 216, 4033 , 4007, 125, 4009) -- críticas reprocessadas
					group by seq_proposta

				)
		
		as CRI
              on CRI.SEQ_PROPOSTA = P.SEQ_PROPOSTA
        left join dmdb41.dbo.DM_AGENCIA as AGE 
            on AGE.COD_AGENCIA = P.COD_UNO_VENDA
        LEFT JOIN DMDb42..[DM_ODS_PRS_FINANCEIRO_MOVTO] AS F
                on F.SEQ_FINANCEIRO = p.[SEQ_FIN_DEVOLUCAO]
                and F.[IND_ULTIMA_OCORRENCIA] = 'S'
 
where   YEAR(P.DTA_PROPOSTA)  >= YEAR(GETDATE())
        and P.STA_MOVTO = 'REJ' -- Rejeitada
        and P.STA_PROPOSTA = '2' -- Não Aceita
        and P.COD_SUB_TIPO_REPASSE NOT IN (2,7,6) -- retira os cancelamentos


)
GO
 
