CREATE VIEW [dbo].[VW_DPS_CVP] AS 
	
SELECT D.NUM_PROPOSTA_ASSOCIADA_DPS AS NUM_PROPOSTA,
       D.DTA_PROPOSTA,
	   D.NUM_CPF_CLIENTE AS CPF_CNPJ,
	   FORMAT(D.NUM_AGENCIA_USUARIO, '0000') AS AGENCIA,
	   D.DTA_ENVIO_MAX_DPS AS ENVIO_DPS_ATE,
	   D.DES_STATUS_ENVIO_DPS AS STATUS_ENVIO_DPS,  -- 090, 089 tpsituacao
	   NULL AS STATUS_DOCS_COMPL, -- NAO TEM AINDA, AGUARDANDO EVOLUÇÃO DA SAMPLEMED.
	   C.DES_SITUACAO AS STATUS_PROPOSTA, --STATUS BACKEND
	   D.NOM_CLIENTE,
	   D.DTA_NASCIMENTO,
	   D.COD_SEXO,
	   D.NUM_TELEFONE_CLIENTE,
	   LOWER(D.DES_EMAIL_CLIENTE) AS EMAIL_CLIENTE,
	   CONVERT(MONEY, D.VLR_PREMIO) AS VLR_PREMIO,
	   CONVERT(MONEY, D.VLR_GARANTIA) AS VLR_IS, 
	   CONVERT(MONEY, IsNUll(U.VLR_IS_ACUMULADA_PRESTAMISTA,0) + IsNUll(U.VLR_IS_ACUMULADA_VIDA,0) + IsNUll(U.VLR_IS_ACUMULADA_PREV,0)) AS VLR_ACUMULO 
FROM   DMDB41..DM_DPS AS D WITH(NOLOCK)
LEFT JOIN DMDB41..DM_CONTRATOS_CVP AS C WITH(NOLOCK) ON C.NUM_PROPOSTA = D.NUM_PROPOSTA_ASSOCIADA_DPS
LEFT JOIN DMDB40..SB_P_202005_IS_UNIFICADA_CPF U WITH(NOLOCK) ON CAST(U.NUM_CPF AS BIGINT) = D.NUM_CPF_CLIENTE

GO
 
