CREATE VIEW [dbo].[VW_ENDERECO_CONTRATOS_CVP] as (
 select distinct
 c.NUM_CERTIFICADO as 'numContrato',
 a.NUM_CPF_CNPJ as  'codCpfCnpj',
 trim(cast(null as varchar(20))) as sistema,
 'LEGADO' as situacao,
 trim(e.NOM_LOGRADOURO) as 'contato',
 trim(e.NOM_BAIRRO) as 'bairro',
 trim(e.COD_UF) as 'uf',
 REPLACE(REPLACE(TRIM(e.NOM_CIDADE), CHAR(13), ''), CHAR(10), '') as 'cidade',
 trim(cast(e.COD_CEP as varchar(20))) as 'cep',
 null as rating,
 null as dth_referencia,
 null as dth_atualizacao
from 
DM_CLIENTES_UNIFICADOS_CVP a
inner join DM_CLIENTES_ENDERECO_CVP e
on a.COD_PESSOA_UNIFICADA = e.COD_PESSOA_UNIFICADA
and e.SEQ_ENDERECO = (select max(SEQ_ENDERECO) 
                        from DM_CLIENTES_ENDERECO_CVP 
                        where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)

 
inner join DM_CLIENTES_CONTRATOS_CVP b
on a.NUM_CPF_CNPJ=b.NUM_CPF_CNPJ
and b.COD_PESSOA = (select min(COD_PESSOA) from DM_CLIENTES_CONTRATOS_CVP 
                     where NUM_CPF_CNPJ=b.NUM_CPF_CNPJ)
inner join DM_CONTRATOS_CVP c
on b.NOM_SEGMENTO = c.NOM_SEGMENTO
and b.NUM_CERTIFICADO = c.NUM_CERTIFICADO
inner join VW_PRODUTOS_CVP p
on c.COD_PRODUTO = p.COD_PRODUTO
and c.NOM_SEGMENTO = p.DES_SEGMENTO
)
GO
 
