IF OBJECT_ID('[dbo].[VW_EVOLUCAO_BI_COBRANCA_PRESTAMISTA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_EVOLUCAO_BI_COBRANCA_PRESTAMISTA];
GO


CREATE view VW_EVOLUCAO_BI_COBRANCA_PRESTAMISTA as 


/* 
 Projeto GEMCO 878- Evolução no BI de Cobrança para Prestamista
 Solicitante: Diego Barros Alves da Silva
 Link:
 Regra: POC 
 Fonte:
 Business Owner: 
 Data Coordinator: Rodrigo Santini
 Manager: Leandro Branquinho
 Versão: 1.0
 Data: 14/03/2024
 Nome da fonte no PBI: 
 Estatística:  4h / 
 */
with CTE_INSIDE as (
    --Consulta para trazer a massa de contratos elegíveis na base prestamista ODS para cruzamento com a base de dados AIC_PROPOSTAS
    SELECT
        INSIDE.[SEQ_PROPOSTA] AS LEGADO_SEQ_PROPOST,
        CAST(INSIDE.[NUM_PROPOSTA_ESTIP] as decimal (19, 0)) AS LEGADO_NUM_PROPOSTA_ESTIP,
        INSIDE.[NUM_LINHA_PRODUTO] AS LEGADO_NUM_LINHA_PRODUTO,
        INSIDE.[DTA_PROPOSTA] AS LEGADO_DTA_PROPOSTA,
        INSIDE.[STA_PROPOSTA] AS LEGADO_STA_PROPOSTA,
        INSIDE.[DES_STATUS_PROPOSTA] AS LEGADO_DES_STATUS_PROPOSTA,
        INSIDE.[STA_MOVTO] AS LEGADO_STA_MOVTO,
        INSIDE.[DTA_ULT_ATUALIZACAO] AS LEGADO_DTA_ULT_ATUALIZACAO,
        INSIDE.[DTA_COBRANCA] AS LEGADO_DTA_COBRANCA,
        INSIDE.[DTA_QUITACAO] AS LEGADO_DTA_QUITACAO,
        INSIDE.[VLR_PREMIO] AS LEGADO_VLR_PREMIO,
        INSIDE.[VLR_IS] AS LEGADO_VLR_IS,
        INSIDE.[NUM_ORI_CONTRATO] AS LEGADO_NUM_ORI_CONTRATO,
        INSIDE.[DTA_ENVIO_SIGPF] AS LEGADO_DTA_ENVIO_SIGPF,
        CAST(INSIDE.[NUM_CONTRATO_SIGPF] as decimal (19, 0)) AS LEGADO_NUM_CONTRATO_SIGPF,
        INSIDE.[COD_PRODUTO] AS LEGADO_COD_PRODUTO,
        INSIDE.[STA_ORIGEM_CONTRATO] AS LEGADO_STA_ORIGEM_CONTRATO,
        INSIDE.[NUM_APOLICE] AS LEGADO_NUM_APOLICE,
        INSIDE.[COD_OPCAO_PGTO] AS LEGADO_COD_OPCAO_PGTO,
        INSIDE.[VLR_IOF] AS LEGADO_VLR_IOF,
        INSIDE.[NUM_PROP_EMISSAO] AS LEGADO_NUM_PROP_EMISSAO,
        INSIDE.[DTH_CADASTRAMENTO_ARQUIVO] AS LEGADO_DTH_CADASTRAMENTO_ARQUIVO,
        INSIDE.[DTA_DEVOLUCAO_FINANC_SAP] AS LEGADO_DTA_DEVOLUCAO_FINANC_SAP,
        INSIDE.[DTA_ENTRADA_FINANC_SAP] AS LEGADO_DTA_ENTRADA_FINANC_SAP,
        INSIDE.[COD_ORIGEM_PROPOSTA] AS LEGADO_COD_ORIGEM_PROPOSTA,
        INSIDE.[DTH_CARGA] AS LEGADO_DTH_CARGA,
        INSIDE.IND_ULTIMO_STA_PROPOSTA as IND_ULTIMO_STA_PROPOSTA
    FROM
        [DMDB42].[dbo].[DM_ODS_PRS_PROPOSTAS] as INSIDE with (nolock) --- Proposta IND_ULT_STATUS RSC
    WHERE
        1 = 1 --AND INSIDE.[DTA_PROPOSTA] >= (select cast((GETDATE()) - 120 as date)) 
        --AND INSIDE.[NUM_PROPOSTA_ESTIP] in (80053770323488,80138770322841)
)
SELECT
    CAST(GETDATE() as DATE) as AIC_DTA_EXECUCAO,
    OUTSIDE.COD_PROPOSTA as AIC_COD_PROPOSTA,
    OUTSIDE.DTA_VENDA as AIC_DTA_VENDA,
    OUTSIDE.DTA_INICIO_VIGENCIA as AIC_DTA_INICIO_VIGENCIA,
    OUTSIDE.DES_FL_PROCESSADO as AIC_DES_FL_PROCESSADO,
    OUTSIDE.IND_UPLOAD_DOCUMENTO as AIC_IND_UPLOAD_DOCUMENTO,
    OUTSIDE.NOM_PRODUTO as AIC_NOM_PRODUTO,
    OUTSIDE.IND_CONJUGADO as AIC_IND_CONJUGADO,
    OUTSIDE.NOM_CANAL as AIC_NOM_CANAL,
    OUTSIDE.COD_AGENCIA as AIC_COD_AGENCIA,
    OUTSIDE.FL_PROCESSADO as AIC_FL_PROCESSADO,
    OUTSIDE.STA_CANCELADA as AIC_STA_CANCELADA,
    OUTSIDE.DES_FORMA_PGTO as AIC_DES_FORMA_PGTO,
    OUTSIDE.FLG_PAGO_MJUNMOV as AIC_FLG_PAGO_MJUNMOV,
    OUTSIDE.FLG_PAGO_RAJADA as AIC_FLG_PAGO_RAJADA,
    OUTSIDE.COD_PERIODICIDADE_PGTO as AIC_COD_PERIODICIDADE_PGTO,
    OUTSIDE.VLR_PREMIO as AIC_VLR_PREMIO,
    OUTSIDE.VLR_IMPORTANCIA_SEGURADA as AIC_VLR_IMPORTANCIA_SEGURADA,
    INSIDE.*
FROM
    CTE_INSIDE as INSIDE
    RIGHT JOIN [DMDB41].[dbo].[DM_AIC_PROPOSTA] OUTSIDE with (nolock) ON (
        OUTSIDE.COD_PROPOSTA = INSIDE.[LEGADO_NUM_PROPOSTA_ESTIP]
        OR OUTSIDE.COD_PROPOSTA = INSIDE.[LEGADO_NUM_CONTRATO_SIGPF]
    )
WHERE
    1 = 1 --
    --AND OUTSIDE.COD_PROPOSTA in (80053770323488,80138770322841) --
