IF OBJECT_ID('[dbo].[VW_GENESYS_FILA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_GENESYS_FILA];
GO
CREATE   VIEW DBO.VW_GENESYS_FILA
AS
WITH PARAMS AS (
    SELECT
        DT_INI_UTC = CAST('2026-01-01T03:00:00Z' AS DATETIMEOFFSET(7))
),

BASE AS (
    SELECT
        CS.CONVERSATION_ID,
        CS.ID AS SESSION_ID,
        CS.NAME,
        CS.PURPOSE,
        CS.QUEUE_NAME,
        CS.QUEUE_ID,
        CS.START_TIME,
        CS.END_TIME,
        PURPOSE_LIMPO = LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(CS.PURPOSE, CHAR(13), ''), CHAR(10), ''), CHAR(9), ''))),
        START_DT_UTC = SWITCHOFFSET(TRY_CONVERT(DATETIMEOFFSET(7), CS.START_TIME, 127), '-03:00'),
        END_DT_UTC   = SWITCHOFFSET(TRY_CONVERT(DATETIMEOFFSET(7), CS.END_TIME,   127), '-03:00')
    FROM DBO.TB_CONVERSATION_SURVEY CS
    CROSS JOIN PARAMS P
    CROSS APPLY (
        SELECT TRY_CONVERT(DATETIMEOFFSET(7), CS.START_TIME, 127) AS DT
    ) T
    WHERE CS.START_TIME IS NOT NULL
      AND CS.END_TIME   IS NOT NULL
      AND T.DT >= P.DT_INI_UTC
),

FILAS AS (
    SELECT
        B.CONVERSATION_ID,
        B.SESSION_ID,
        B.START_DT_UTC,
        B.END_DT_UTC,
        B.QUEUE_ID,
        B.QUEUE_NAME
    FROM BASE B
    WHERE B.PURPOSE_LIMPO = 'acd'
      AND B.QUEUE_NAME IS NOT NULL
      AND B.START_DT_UTC IS NOT NULL
      AND B.END_DT_UTC   IS NOT NULL
      AND B.END_DT_UTC   >= B.START_DT_UTC
),

FILAS_COM_EPS AS (
    SELECT
        F.CONVERSATION_ID,
        F.SESSION_ID,
        F.START_DT_UTC,
        F.END_DT_UTC,
        F.QUEUE_NAME,
        Q.ID AS FILA_ID,
        Q.MEDIA_SETTINGS_CALL_SERVICE_LEVEL_PERCENTAGE AS EPS
    FROM FILAS F
    LEFT JOIN DBO.TB_QUEUES Q
        ON LTRIM(RTRIM(Q.ID)) = LTRIM(RTRIM(F.QUEUE_ID))
)

SELECT
    CONVERSATION_ID,
    SESSION_ID,
    QUEUE_NAME,
    FILA_ID,
    EPS,
    START_DT_UTC AS START_TIME,
    END_DT_UTC   AS END_TIME,
    DATEPART(HOUR, START_DT_UTC) AS RANGE_HORA,
    DATEDIFF_BIG(SECOND, START_DT_UTC, END_DT_UTC) AS DURACAO_SEGUNDOS,
    DATEDIFF_BIG(MINUTE, START_DT_UTC, END_DT_UTC) AS DURACAO_MINUTOS,
    CONCAT(
        DATEDIFF_BIG(SECOND, START_DT_UTC, END_DT_UTC) / 60,
        ':',
        RIGHT('0' + CAST(DATEDIFF_BIG(SECOND, START_DT_UTC, END_DT_UTC) % 60 AS VARCHAR(2)), 2)
    ) AS DURACAO_MIN_SEG
FROM FILAS_COM_EPS;
GO
 
IF OBJECT_ID('[dbo].[VW_GENESYS_PESQUISA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_GENESYS_PESQUISA];
GO
CREATE   VIEW DBO.VW_GENESYS_PESQUISA
AS
WITH PARAMS AS (
    SELECT
        DT_INI_UTC = CAST('2026-01-01T03:00:00Z' AS DATETIMEOFFSET(7)),
        DT_MIN_OK  = CAST('2000-01-01T00:00:00Z' AS DATETIMEOFFSET(7))
),
CONVS AS (
    SELECT DISTINCT
        CS.CONVERSATION_ID
    FROM [DBO].[TB_CONVERSATION_SURVEY] CS
    CROSS JOIN PARAMS P
    CROSS APPLY (
        SELECT TRY_CONVERT(DATETIMEOFFSET(7), CS.START_TIME, 127) AS START_DT
    ) T
    WHERE CS.START_TIME IS NOT NULL
      AND T.START_DT >= P.DT_INI_UTC
),
BASE AS (
    SELECT
        CS.CONVERSATION_ID,
        CS.ID,
        CS.NAME,
        CS.PURPOSE,
        CS.QUEUE_NAME,
        CS.QUEUE_ID,
        CS.START_TIME,
        CS.END_TIME,
        CS.ATTRIBUTES_CPF_CNPJ,
        CS.ATTRIBUTES_PROTOCOLO,
        CS.ATTRIBUTES_QUESTAO1,
        CS.ATTRIBUTES_QUESTAO2,
        CS.ATTRIBUTES_QUESTAO3,
        CS.ATTRIBUTES_SAC_QUESTAO_FCR,
        CS.ORIGINATING_DIRECTION,
        CS.DISCONNECT_TYPE,
        CS.USER_ID AS USER_ID_RAW,

        PURPOSE_LIMPO = LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(CS.PURPOSE, CHAR(13), ''), CHAR(10), ''), CHAR(9), ''))),

        START_DT_RAW = TRY_CONVERT(DATETIMEOFFSET(7), CS.START_TIME, 127),
        END_DT_RAW   = TRY_CONVERT(DATETIMEOFFSET(7), CS.END_TIME, 127),

        START_DT_UTC = CASE
                         WHEN TRY_CONVERT(DATETIMEOFFSET(7), CS.START_TIME, 127) >= P.DT_MIN_OK
                         THEN TRY_CONVERT(DATETIMEOFFSET(7), CS.START_TIME, 127)
                         ELSE NULL
                       END,
        END_DT_UTC   = CASE
                         WHEN TRY_CONVERT(DATETIMEOFFSET(7), CS.END_TIME, 127) >= P.DT_MIN_OK
                         THEN TRY_CONVERT(DATETIMEOFFSET(7), CS.END_TIME, 127)
                         ELSE NULL
                       END
    FROM [DBO].[TB_CONVERSATION_SURVEY] CS
    INNER JOIN CONVS C
        ON C.CONVERSATION_ID = CS.CONVERSATION_ID
    CROSS JOIN PARAMS P
),
CPF_CONVERSA AS (
    SELECT
        B.CONVERSATION_ID,
        MAX(CASE WHEN LEN(B.CPF) = 14 THEN B.CPF END) AS CNPJ_14,
        MAX(CASE WHEN LEN(B.CPF) = 11 THEN B.CPF END) AS CPF_11,
        MAX(B.CPF) AS CPF_ANY
    FROM (
        SELECT
            CONVERSATION_ID,
            CPF = NULLIF(LTRIM(RTRIM(CONVERT(VARCHAR(30), ATTRIBUTES_CPF_CNPJ))), '')
        FROM BASE
        WHERE ATTRIBUTES_CPF_CNPJ IS NOT NULL
          AND LTRIM(RTRIM(CONVERT(VARCHAR(30), ATTRIBUTES_CPF_CNPJ))) <> ''
    ) B
    WHERE B.CPF <> REPLICATE('0', LEN(B.CPF))
    GROUP BY B.CONVERSATION_ID
),
INTERACOES AS (
    SELECT
        B.CONVERSATION_ID,
        MIN(CASE WHEN B.START_DT_UTC IS NOT NULL THEN SWITCHOFFSET(B.START_DT_UTC, '-03:00') END) AS START_TIME,
        MAX(CASE WHEN B.END_DT_UTC   IS NOT NULL THEN SWITCHOFFSET(B.END_DT_UTC, '-03:00') END) AS END_TIME
    FROM BASE B
    WHERE B.START_DT_UTC IS NOT NULL
    GROUP BY B.CONVERSATION_ID
),
PESQUISADOS AS (
    SELECT
        B.CONVERSATION_ID,
        1 AS PESQUISADO,
        MAX(DATEDIFF_BIG(SECOND, B.START_DT_UTC, B.END_DT_UTC)) AS TEMPO_PESQUISA_MAX,
        SUM(DATEDIFF_BIG(SECOND, B.START_DT_UTC, B.END_DT_UTC)) AS TEMPO_PESQUISA_TOTAL,
        COUNT(*) AS QTD_PESQUISAS,
        CASE
            WHEN COUNT(*) > 1 THEN SUM(DATEDIFF_BIG(SECOND, B.START_DT_UTC, B.END_DT_UTC))
            ELSE 0
        END AS TEMPO_PESQUISA_SOMA_MULTIPLAS
    FROM BASE B
    WHERE B.NAME LIKE 'Survey_DB_%'
      AND B.START_DT_UTC IS NOT NULL
      AND B.END_DT_UTC   IS NOT NULL
    GROUP BY B.CONVERSATION_ID
),
COMENTARIOS AS (
