CREATE VIEW dbo.VW_JOBS_ABORTADOS
AS
SELECT CASE WHEN NOM_JOB_CONTROLADOR = 'not available' THEN NOM_JOB ELSE NOM_JOB_CONTROLADOR END AS NOM_SEQUENCE_JOB, NOM_JOB, DES_STATUS_JOB, DTH_INICIO_JOB, DTH_FINAL_JOB, NOM_PROJETO
FROM     dbo.DM_DOC_CONTROLE_JOBS
WHERE  (COD_STATUS_JOB = 3) AND (DTH_INICIO_JOB > DATEADD(WEEK, - 1, GETDATE()))
GO
 
IF OBJECT_ID('[dbo].[VW_JOBS_ABORTADOS_CONTAGEM]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_JOBS_ABORTADOS_CONTAGEM];
GO

CREATE VIEW [dbo].[VW_JOBS_ABORTADOS_CONTAGEM]
AS
--CTE_1 CONTA OS ERROS DO JOB NO DIA CORRENTE
WITH CTE_1 AS (
SELECT NOM_JOB_CONTROLADOR, NOM_JOB, CASE WHEN NOM_JOB_CONTROLADOR = 'not available' THEN NOM_JOB ELSE NOM_JOB_CONTROLADOR END AS NOM_SEQUENCE_JOB, DES_STATUS_JOB, NOM_PROJETO, COUNT(*) 
                  AS NUM_ERROS_DIA
FROM     dbo.DM_DOC_CONTROLE_JOBS
WHERE  (COD_STATUS_JOB = 3) AND (FORMAT(DTH_INICIO_JOB, 'yyyy-MM-dd') = FORMAT(GETDATE(), 'yyyy-MM-dd'))
GROUP BY NOM_JOB_CONTROLADOR, NOM_JOB, DES_STATUS_JOB, NOM_PROJETO
),
--CTE_2 CONTA OS ERROS DO JOB NA ULTIMA SEMANA
CTE_2 AS (
SELECT NOM_JOB_CONTROLADOR, NOM_JOB, CASE WHEN NOM_JOB_CONTROLADOR = 'not available' THEN NOM_JOB ELSE NOM_JOB_CONTROLADOR END AS NOM_SEQUENCE_JOB, DES_STATUS_JOB, NOM_PROJETO, COUNT(*) 
                  AS NUM_ERROS_SEMANA
FROM     dbo.DM_DOC_CONTROLE_JOBS
WHERE  (COD_STATUS_JOB = 3) AND (DTH_INICIO_JOB > DATEADD(WEEK, - 1, GETDATE()))
GROUP BY NOM_JOB_CONTROLADOR, NOM_JOB, DES_STATUS_JOB, NOM_PROJETO
)
SELECT CASE WHEN A.NOM_JOB_CONTROLADOR = 'not available' THEN A.NOM_JOB 
		ELSE A.NOM_JOB_CONTROLADOR 
		END AS NOM_SEQUENCE_JOB,
		A.DES_STATUS_JOB,
		A.NOM_PROJETO,
		B.NUM_ERROS_DIA,
		C.NUM_ERROS_SEMANA,
		COUNT(*) AS NUM_ERROS_TOTAL	
		

FROM     dbo.DM_DOC_CONTROLE_JOBS A LEFT JOIN CTE_1 B
		ON A.NOM_JOB_CONTROLADOR=B.NOM_JOB_CONTROLADOR AND A.NOM_JOB=B.NOM_JOB AND A.NOM_PROJETO=B.NOM_PROJETO
		LEFT JOIN CTE_2 C
		ON A.NOM_JOB_CONTROLADOR=C.NOM_JOB_CONTROLADOR AND A.NOM_JOB=C.NOM_JOB AND A.NOM_PROJETO=C.NOM_PROJETO
WHERE  (COD_STATUS_JOB = 3)
GROUP BY A.NOM_JOB_CONTROLADOR, A.NOM_JOB, A.DES_STATUS_JOB, A.NOM_PROJETO, B.NUM_ERROS_DIA,c.NUM_ERROS_SEMANA
GO
 
