create view VW_MDL_CLIENTES_ENGAJADOS AS (
SELECT DISTINCT
    cliu.NOM_PESSOA,
    cli.NUM_CERTIFICADO,
    cli.NUM_CPF_CNPJ,
    cli.DES_PESSOA,
    cli.NOM_SEGMENTO,
    cli.COD_PESSOA,
    cli.NUM_IDADE,
    cli.DTA_NASCIMENTO,
    cli.VLR_RENDA_FAMILIAR,
    cli.VLR_RENDA_INDIVIDUAL,
    cli.COD_UF,
    cli.DES_ESTADO_CIVIL,
    cli.IND_GENERO,
    cli.COD_CBO,
    cli.DES_CBO,
    cli.DES_CATEG_SEGMENTACAO,
    cli.COD_SEGMENTO_CAIXA,
    cli.DES_CLASSIFICACAO_RISCO,
    cli.DES_ESCOLARIDADE_BIRO,
    cliu.PERSONA,
    c.DTA_ULTIMO_ACIONAMENTO,
    cli.DTH_CARGA_ATUALIZACAO,
    cli.DTH_CARGA,
    app.QTD_ACESSOS_APP,
    qc.QTD_ATENDIMENTO,
    c.ORIGEM,
    bc.TB_ORIGEM,
    bc.FLAG_BOUNCE,
    bc.DTH_ENVIO,
    bc.DTH_ABERTURA
FROM 
    /* ====================================================================
       SUBQUERY: CASES (Substitui CTEs CASES e CASES_REMOTO)
       Lógica: Filtra apenas o RN = 1 da subquery interna
    ==================================================================== */
    (
        SELECT 
            NUM_CPF,
            ORIGEM,
            DTA_ULTIMO_ACIONAMENTO
        FROM (
            SELECT  
                CAST(Acc.Numdoc__c AS VARCHAR(20)) AS NUM_CPF,
                Cs.Origin AS ORIGEM,
                Cs.CreatedDate AS DTA_ULTIMO_ACIONAMENTO,
                ROW_NUMBER() OVER (
                    PARTITION BY cs.Account_Document_Number__c 
                    ORDER BY Cs.CreatedDate DESC
                ) AS rn
            FROM [SQL18\STAGING4].[TDDB46].[dbo].[RecordType] rt
            INNER JOIN [SQL18\STAGING4].[TDDB46].[dbo].[Case_Task__c] ct 
                ON ct.RecordTypeId = rt.Id
            INNER JOIN [SQL18\STAGING4].[TDDB46].[dbo].[Case] cs 
                ON cs.Id = ct.Case__c
            INNER JOIN [SQL18\STAGING4].[TDDB46].[dbo].[Account] acc 
                ON acc.Id = cs.AccountId
            WHERE 
                cs.LastModifiedDate >= DATEADD(MONTH, -12, CAST(GETDATE() AS date))
                AND acc.Numdoc__c IS NOT NULL
                AND cs.Origin <> 'Ação Judicial'
        ) Remoto
        WHERE rn = 1
    ) c

    /* ====================================================================
       SUBQUERY: QTD_CASES_SF
    ==================================================================== */
    LEFT JOIN (
        SELECT
            CAST(Acc.Numdoc__c AS VARCHAR(20)) AS NUM_CPF, 
            COUNT(CASE WHEN Cs.Queue__c = 'Ouvidoria' THEN 1 END) AS QTD_OUVIDORIA,
            COUNT(CASE WHEN Cs.Queue__c <> 'Ouvidoria' THEN 1 END) AS QTD_ATENDIMENTO,
            COUNT(Cs.CaseNumber) AS QTD_TOTAL
        FROM [SQL18\STAGING4].[TDDB46].[dbo].[RecordType] rt
        INNER JOIN [SQL18\STAGING4].[TDDB46].[dbo].[Case_Task__c] ct 
            ON ct.RecordTypeId = rt.Id
        INNER JOIN [SQL18\STAGING4].[TDDB46].[dbo].[Case] cs 
            ON cs.Id = ct.Case__c
        INNER JOIN [SQL18\STAGING4].[TDDB46].[dbo].[Account] acc 
            ON acc.Id = cs.AccountId
        WHERE 
            cs.LastModifiedDate >= DATEADD(MONTH, -12, CAST(GETDATE() AS date))
            AND acc.Numdoc__c IS NOT NULL
        GROUP BY 
            Acc.Numdoc__c
    ) qc ON qc.NUM_CPF = c.NUM_CPF

    /* ====================================================================
       SUBQUERY: QTD_ACESSOS_APP
    ==================================================================== */
    LEFT JOIN (
        SELECT
            APP.COD_USUARIO,
            COUNT(APP.DTA_ACESSO) AS QTD_ACESSOS_APP
        FROM [SQL18\STAGING4].[TDDB50].[dbo].[PREV_LOG_APP] APP
        WHERE APP.DES_OPERACAO = 'AutenticarUsuario'
        GROUP BY APP.COD_USUARIO
    ) app ON app.COD_USUARIO = c.NUM_CPF

    /* ====================================================================
       SUBQUERY: BASE_COMUNICACAO
    ==================================================================== */
    LEFT JOIN 
GO
 
