CREATE VIEW [dbo].[VW_NEGOCIAL_PRESTAMISTA_SF]
AS
SELECT DISTINCT 
                  NOM_PROPRIETARIO_NIVEL_1 AS Proprietario_Nivel_1, NOM_ALIAS_PROPRIETARIO_NIVEL_1 AS Alias_Proprietario_Nivel_1, NUM_FUNCIONARIO_NIVEL_1 AS Numero_Funcionario_Nivel_1,
				  NOM_PROPRIETARIO_NIVEL_2 AS Proprietario_Nivel_2, NOM_ALIAS_PROPRIETARIO_NIVEL_2 AS Alias_Proprietario_Nivel_2, NUM_FUNCIONARIO_NIVEL_2 AS Numero_Funcionario_Nivel_2,
                  NOM_USUARIO_NIVEL_1 AS Nome_Usuario_Proprietario_Nivel_1, FORMAT(DTH_ABERTURA, 'dd/MM/yyyy HH:mm') AS Data_Hora_Abertura, NUM_PROTOCOLO AS Numero_Protocolo, NUM_ATENDIMENTO AS Numero_Solicitacao, 
                  CASE WHEN a.DTH_ENVIO_NIVEL_2 IS NULL THEN 'FALSO' ELSE 'VERDADEIRO' END AS Segundo_Nivel, DES_OPORTUNIDADE AS Oportunidade, ISNULL(ISNULL(NUM_CONTRATO_SALESFORCE, NUM_CONTRATO_BU_SALESFORCE), 
                  NUM_CONTRATO_SELECIONADO_SALESFORCE) AS Numero_Contrato, DES_PRODUTO_CONTRATO AS Produto_Contrato, COD_PRODUTO AS Codigo_Produto, DES_STATUS_CONTRATO AS Situacao_Contrato, 
                  CAST(VLR_PREMIO_BRUTO AS decimal(15, 2)) AS Valor_Premio_Bruto, CAST(VLR_IS AS decimal(15, 2)) AS Importancia_Segurada, NUM_CPF_CNPJ AS CPF_CNPJ_Cliente, NOM_CLIENTE AS Nome_Cliente, 
                  NUM_TELEFONE_ACCOUNT AS Telefone, DES_EMAIL_ACCOUNT AS Email, DES_EMAIL_CONTATO AS Email_Contato, DES_RETENCAO_REALIZADA AS Retencao_Realizada, DES_RSULTADO_NIVEL_1 AS Resultado, 
                  DES_OFERTA AS Oferta_Escolhida, DES_ASSUNTO AS Assunto, STA_ICON AS Status, DES_ATENDIMENTO AS Descricao, COD_ID_PESQUISA_SATISFACAO AS ID_Pesquisa_Satisfacao, 
                  IND_PESQUISA_ENVIADA_CASE AS Pesquisa_Enviada, DES_EMAIL_PESQUISA AS Email_Pesquisa, NOM_UF AS Estado, DES_ESCOLARIDADE AS Escolaridade, FORMAT(DTA_NASCIMENTO, 'dd/MM/yyyy') AS Data_Nascimento, 
                  DES_ESTADO_CIVIL AS Estado_Civil, DES_SEXO AS Sexo, NUM_AGENCIA AS Agencia, STA_ATENDIMENTO AS Status_Atendimento, DES_DIRECIONADOR_ORIGEM AS Direcionador_Origem, IND_VALIDACAO_DOCUMENTOS as Precisa_Validar_Documentos
FROM     dbo.DM_SALESFORCE_ATENDIMENTO AS a
WHERE  (DES_SEGMENTO = 'PREST') AND (DES_FILA IN ('Prest Serviços','Retenção PREST')) AND (STA_ATENDIMENTO IN ('Closed')) AND (DES_ASSUNTO LIKE 'Solicitar cancelamento%') AND (DES_CANAL IN ('[Phone]'))
AND (DES_DIRECIONADOR_ORIGEM IN ('Prest Serviços','Retenção PREST'))
GO
 
