CREATE VIEW [dbo].[VW_NEGOCIAL_PREVIDENCIA_SF]
AS
SELECT DISTINCT 
                  DES_FILA AS Direcionador
                  , FORMAT(DTH_ABERTURA, 'dd/MM/yyyy HH:mm') AS Data_Hora_Abertura
                  ,NOM_PROPRIETARIO_NIVEL_1 AS Proprietario_Nivel_1
                  ,NOM_ALIAS_PROPRIETARIO_NIVEL_1 AS Alias_Proprietario_Nivel_1
                  ,NUM_FUNCIONARIO_NIVEL_1 AS Numero_Funcionario_Nivel_1
                  ,NOM_PROPRIETARIO_NIVEL_2 AS Proprietario_Nivel_2
                  ,NOM_ALIAS_PROPRIETARIO_NIVEL_2 AS Alias_Proprietario_Nivel_2
                  ,NUM_FUNCIONARIO_NIVEL_2 AS Numero_Funcionario_Nivel_2
                  ,NOM_CLIENTE AS Nome_Cliente
                  ,NOM_SEGMENTO_EXCLUSIVO_PREV AS Segmento_Exclusivo_Prev
                  ,NUM_CPF_CNPJ AS CPF_CNPJ
                  ,NUM_TELEFONE_ACCOUNT AS CLIENTE_TELEFONE
                  ,NUM_PROTOCOLO AS Numero_Protocolo
                  ,NUM_ATENDIMENTO AS Numero_Solicitacao
                  ,ISNULL(ISNULL(NUM_CONTRATO_SALESFORCE
                  ,NUM_CONTRATO_BU_SALESFORCE)
                  ,NUM_CONTRATO_SELECIONADO_SALESFORCE) AS Numero_Contrato
                  ,DES_STATUS_CONTRATO AS Situacao_Contrato
                  ,DES_PRODUTO_CONTRATO AS Produto_Contrato
                  ,DES_SEGMENTO_CONTRATO AS Segmento_Produto
                  ,COD_PRODUTO AS Codigo_Produto
                  ,DES_ASSUNTO AS Assunto
                  ,CAST(VLR_SALDO_DISPONIVEL_PREV AS decimal(20, 2)) AS Saldo_Disponivel_Previdencia
                  ,CAST(VLR_URA AS decimal(20, 2)) AS Valor_URA
                  ,CAST(VLR_DESEJADO AS decimal(20, 2)) AS Valor_Desejado
                  ,CAST(VLR_SOLICITADO AS decimal(20, 2)) AS Valor_Solicitado
                  ,CAST(VLR_RETIDO AS decimal(20, 2)) AS Valor_Retido
                  ,DES_RETENCAO_RESGATE AS Retencao_Resgate
                  ,VLR_URA_PROTOCOLO AS Valor_URA_Protocolo
                  ,CASE WHEN DTH_ENVIO_NIVEL_2 IS NULL THEN 'FALSO' ELSE 'VERDADEIRO' END AS Segundo_Nivel
                  ,STA_ATENDIMENTO AS Status_Atendimento
FROM     dbo.DM_SALESFORCE_ATENDIMENTO AS a
WHERE  (DES_SEGMENTO = 'PREV') 
    AND (DES_FILA IN ('Prev Fideliza', 'Prev Fideliza Grandes Valores')) 
    AND (STA_ATENDIMENTO IN ('Closed')) 
    AND (DES_ASSUNTO LIKE 'Solicitar resgate%')
    AND (DES_ASSUNTO NOT IN ('Solicitar resgate > Programar resgate'))
GO
 
