CREATE VIEW [dbo].[VW_NEGOCIAL_SERVICOS_SF]
AS
(
SELECT distinct
	a.DES_SEGMENTO as Solicitacao_Segmento,
	a.DES_FILA as Solicitacao_Direcionador,
	a.DES_CANAL as Solicitacao_Canal,
	format(a.DTH_ABERTURA, 'dd/MM/yyyy HH:mm') as Data_Hora_Abertura,
	format(a.DTH_RESOLUCAO, 'dd/MM/yyyy HH:mm') as Data_Hora_Fechamento,
	a.NOM_PROPRIETARIO_NIVEL_1 as Solicitacao_Proprietario_1_Nivel_Nome_Completo,
	a.NUM_FUNCIONARIO_NIVEL_1 as Solicitacao_Proprietario_1_Nivel_Numero_Funcionario,
	a.NOM_USUARIO_NIVEL_1 as Solicitacao_Proprietario_1_Nivel_Nome_Usuario,
	a.NOM_EMPRESA_NIVEL_1 as Solicitacao_Proprietario_1_Nivel_Nome_Empresa,
	a.NUM_PROTOCOLO as Solicitacao_Numero_Protocolo,
	a.NUM_ATENDIMENTO as Solicitacao_Numero_Solicitacao,
	a.NUM_CPF_CNPJ as Solicitacao_CPF_CNPJ_Cliente,
	a.NOM_CLIENTE as Solicitacao_Nome_Cliente_Prospect,
	a.DES_ATENDIMENTO as Solicitacao_Descricao,
	a.DES_ASSUNTO as Solicitacao_Assunto,
	a.NUM_CONTRATO as Solicitacao_Numero_Contrato,
	a.DES_PRODUTO_CONTRATO as Solicitacao_Contrato_Nome_Produto,
	a.DES_STATUS_CONTRATO as Solicitacao_Situacao_Contrato,
	a.DES_FORMA_PAGAMENTO as Forma_Pagamento,
	format(a.DTA_APORTE, 'dd/MM/yyyy') as Data_Aporte,
	a.VLR_APORTE as Valor_Aporte,
	Case when a.DTH_ENVIO_NIVEL_2 is NULL then 'Falso'
	else 'Verdadeiro'
	END Solicitacao_Segundo_Nivel,
	a.STA_ATENDIMENTO as Solicitacao_Status	
	
FROM [DMDB41].[dbo].[DM_SALESFORCE_ATENDIMENTO] a

WHERE a.DES_SEGMENTO = 'PREV' and
	a.DES_CANAL in ('Telefone', '[Phone]') and
	a.DES_FILA = 'Prev Serviços' and 
	a.STA_ATENDIMENTO = 'Closed' and
	a.DES_ASSUNTO like 'Financeiro - Emissão de aporte%'


)
GO
 
