                  NOM_CLIENTE AS Nome_Cliente, NUM_TELEFONE_ACCOUNT AS Telefone, DES_EMAIL_ACCOUNT AS Email, DES_EMAIL_CONTATO AS Email_Contato, DES_RETENCAO_REALIZADA AS Retencao_Realizada, 
                  DES_RSULTADO_NIVEL_1 AS Resultado, DES_OFERTA AS Oferta_Escolhida, DES_ASSUNTO AS Assunto, STA_ICON AS Status, DES_ATENDIMENTO AS Descricao, 
