CREATE	VIEW [dbo].[VW_PAINEL_PRESTAMISTA_CONFERE] AS
--
--		USE [DMDB41]

---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_PAINEL_PRESTAMISTA_CONFERE

--					SQL14\DMCVP\DMDB42 
--
--		OBJETIVO:	CONFERE OS TOTAIS POR DATA 
--		
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J®
--		DATA	:	18/08/2022	
---------------------------------------------------------------------------------------------------
WITH	CANCELAMENTOS AS  (

SELECT	A.NUM_CONTRATO_TERC, 
		A.DES_MOTIVO_CANCEL, 
		A.DTA_CANCELAMENTO

FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS A

INNER JOIN (SELECT	NUM_CONTRATO_TERC, 
					MAX(STA_MOVIMENTO) AS STA_MOVIMENTO,  
					MAX(DTH_CARGA) AS DTH_CARGA 			
			FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS WITH ( NOLOCK ) 
			WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
			GROUP BY NUM_CONTRATO_TERC) B 
ON		A.NUM_CONTRATO_TERC =	B.NUM_CONTRATO_TERC
AND		A.STA_MOVIMENTO		=	B.STA_MOVIMENTO
AND		A.DTH_CARGA			=	B.DTH_CARGA
WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
) 

---------------------------------------------------------------------------------------------------
--		RECUPERA VENDAS DO PRESTAMISTA ( EXCETO CONSORCIO ) SIAPI SIAPX SIFEC
---------------------------------------------------------------------------------------------------
,MOV_SIAPI AS (

SELECT	DISTINCT 
		'PRESTA SIAPI		 '		AS	SEGMENTO,
		A.NUM_PROPOSTA_ESTIP			AS	NUM_PROPOSTA,
		CONVERT(DATE, A.DTA_PROPOSTA)	AS DTA_PROPOSTA,
		CONVERT(DATE, A.DTH_CADASTRAMENTO_PROP_SEGURO) AS DTA_PAGAMENTO,

		CASE WHEN ISNULL(C.DES_PERI_PG_PREMIO,'') = 'Mensal' 
			 THEN 'M'
			 WHEN ISNULL(C.DES_PERI_PG_PREMIO,'') = 'À vista' 
			 THEN 'U'
			 ELSE '' 
		END							AS	TIPO_PAGAMENTO,
		CONVERT(FLOAT, A.VLR_PREMIO)AS	VLR_PREMIO,
		'S'							AS	FL_PAGO,
		CONVERT(FLOAT, A.VLR_PREMIO)AS	VLR_PAGO ,

		CASE WHEN CANC.DES_MOTIVO_CANCEL LIKE '% RISCO%' OR CANC.DES_MOTIVO_CANCEL LIKE 'IDADE + PRAZO%' THEN 'RECUSA TECNICA'
			 WHEN DATEDIFF(DAY, A.DTA_PROPOSTA, CANC.DTA_CANCELAMENTO) BETWEEN 0 AND 7 THEN 'CANCELADA'
			 WHEN DES_STATUS_PROPOSTA = 'EM CRITICA' AND A.STA_MOVTO = 'REJ' THEN 'NÃO ACEITA'
			 WHEN DES_STATUS_PROPOSTA IN ('INTEGRADA', 'EM CRITICA') AND A.STA_MOVTO = 'CAN' THEN 'CANCELADA'
			 ELSE TRIM(DES_STATUS_PROPOSTA) 
		END							AS	DES_STATUS_PROPOSTA 

FROM	DMDB42..DM_ODS_PRS_PROPOSTAS_U		A		WITH (NOLOCK)

LEFT JOIN DMDB42..DM_DIM_PRODUTO			C		WITH (NOLOCK)
ON		A.COD_PRODUTO			=	C.COD_PRODUTO

LEFT JOIN CANCELAMENTOS						CANC	WITH (NOLOCK)
ON		A.NUM_PROPOSTA_ESTIP	=	CANC.NUM_CONTRATO_TERC

WHERE	A.DTA_PROPOSTA			BETWEEN '2023-01-01' AND GETDATE()  -- eliminar data futura

AND		A.NUM_PROPOSTA_ESTIP NOT IN (	SELECT	COD_PROPOSTA  
										FROM	DMDB41..DM_AIC_PROPOSTA WITH ( NOLOCK INDEX = PK_DM_AIC )
										WHERE	NOM_SEGMENTO	=		'PRESTAMISTA' 	
										)    
)

