CREATE VIEW [dbo].[VW_PESSOAS_VINCULADAS] as (
 select distinct
 c.NUM_CERTIFICADO as 'numContrato',
 trim(cast(null as varchar(20))) as 'indContrato',
 a.NUM_CPF_CNPJ as  'codCpfCnpj',
 trim(b.DES_PESSOA) as 'tipoRelacionamento',
 trim(cast(null as varchar(20))) as sistema,
 trim(em.DES_EMAIL) as 'email',
 --trim(cast(tel.TIPO_TELEFONE as varchar(3))) 
 'TELEFONIA CELULAR' as 'tipoTelefone',
 trim(cast(tel.NUM_TELEFONE as varchar(10))) as 'telefone',
 trim(e.NOM_LOGRADOURO) as 'endereco',
 trim(e.NOM_BAIRRO) as 'bairro',
 trim(e.COD_UF) as 'uf',
 REPLACE(REPLACE(TRIM(e.NOM_CIDADE), CHAR(13), ''), CHAR(10), '') as 'cidade',
 trim(cast(e.COD_CEP as varchar(20))) as 'cep',
 case when a.NOM_SOCIAL is null then a.NOM_PESSOA
		else a.NOM_PESSOA end as 'nomePessoa',
 Case When a.COD_TIPO_PESSOA = 'F'THEN 'PESSOA FISICA' 
		When a.COD_TIPO_PESSOA = 'J'THEN 'PESSOA JURIDICA' END as 'tipoPessoa',
 null as 'indVinculoPrincipal',
 null as nomeBancoCobranca,
 null as codAgenciaCobranca,
 null  as numContaCobranca,
 null as codOperContaCobranca,
 NULL as 'percentualPactuacaoContrato',
 NULL as 'situacao',
 cast(a.DTA_NASCIMENTO as varchar(30)) as 'dthNascimento',
 classe_social as classeSocial,
 a.dependentes as dependentes,
 a.DTA_ABERTURA as dataHoraFundacao,
 cast(a.DTA_NASCIMENTO as varchar(30)) as 'dataHoraNascimento',
 cast(a.DES_ESTADO_CIVIL as varchar(40)) as estadoCivil,
 cast(a.filhos as varchar(40)) as filhos,
 cast(a.nacionalidade as varchar(40)) as nacionalidade,
 cast(a.NOM_FANTASIA as varchar(200)) as nomeFantasia,
 null as profissaoDeclarada,
 cast(a.VLR_RENDA_INDIVIDUAL as decimal) as renda,
 Case when a.IND_GENERO = 'F' then 'FEMININO'
	when a.IND_GENERO = 'M' then 'MASCULINO' end as sexo,
 a.educacao as escolaridade,
 NULL as situacaoEmail,
 null as situacaoTelefone,
 null as situacaoEndereco,
 null as ratingEmail,
 null as ratingEndereco,
 null as ratingTelefone,
cast(a.VLR_RENDA_INDIVIDUAL as decimal) as rendaIndividual,
 null as indRendaIndividual,
 null as rendaIndividualOrigem,
 cast(a.VLR_RENDA_FAMILIAR as decimal)as rendaFamiliar,
 null as indRendaFamiliar,
 null as rendaFamiliarOrigem,
 a.cod_CBO as codCbo,
 null as nomeMae,
 null as desComplemento,
concat(fixo.NUM_DDD_TELEFONE,fixo.NUM_TELEFONE)  as telefoneFixo,
null as ratingTelefoneFixo,
null as telefoneFixoOrigem,
null as situacaoTelefoneFixo,
concat(tel.NUM_DDD_TELEFONE,tel.NUM_TELEFONE) as  telefoneCelular,
 null as ratingTelefoneCelular,
 null as telefoneCelularOrigem,
 null  as situacaoTelefoneCelular,
 null as telefoneRural,
 null as ratingTelefoneRural,
 null as telefoneRuralOrigem,
 null as situacaoTelefoneRural,
 null as naturalidade,
 null as codDocRg,
 null as orgaoExpedidorRg,
 null as dataHoraEmissaoDoc,
 null as pessoaId,
 null as funcionario,
 null as numMatricula,
 null as tempoCliente,
 cast(a.IND_PEP as varchar(10)) as pep,
 null as obito,
 null as dataHoraObito,
 null as situacaoCadastral,
 cast(a.IND_NLIST as varchar(10)) as nList,
 a.DES_RISCO_CAIXA as desMotivoNList,
 null as obitoSistemaOrigem,
 null as clienteVip,
 null as pepOrigem,
 null as nListOrigem,
 null as desMotivoNListOrigem,
 null as segmentoLtv,
 null as situacaoInformacaoJudicial,
 null as processoJudicial,
 null as ouvidoria,
 null as statusLRI,
 null as indNipOdonto,
 null as dataHoraReferencia,
 null as agravo,
 null as nadaConstaSpcSerasa,
 null as aposentadoInvalidez,
 null as dataHoraNascimentoReferencia,
 null as dataHoraNascimentoOrigem,
 null as dataHoraAtualizacao
from 
DM_CLIENTES_UNIFICADOS_CVP a WITH (NOLOCK)
inner join DM_CLIENTES_ENDERECO_CVP e WITH (NOLOCK)
on a.COD_PESSOA_UNIFICADA = e.COD_PESSOA_UNIFICADA
and e.SEQ_ENDERECO = (select max(SEQ_ENDERECO) 
                        from DM_CLIENTES_ENDERECO_CVP 
                        where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)

 


LEFT join dm_clientes_email_cvp em WITH (NOLOCK)
on a
GO
 
IF OBJECT_ID('[dbo].[vw_pipeline_dependencies]', 'V') IS NOT NULL DROP VIEW [dbo].[vw_pipeline_dependencies];
GO

-- View de dependências (para preview no painel Admin)
-- Usa as colunas corretas verificadas no diagnóstico
CREATE   VIEW dbo.vw_pipeline_dependencies AS
SELECT
    p.pipeline_name,
    p.project_name,
    p.active,
    COUNT(DISTINCT j.job_name)  AS total_jobs,
    COUNT(DISTINCT l.id)        AS total_lineage,
    p.DAG_CRIADA                AS dag_criada,
    p.updated_at
FROM dbo.etl_pipeline p
LEFT JOIN dbo.etl_pipeline_job j ON j.pipeline_name = p.pipeline_name
LEFT JOIN dbo.etl_job_lineage  l ON l.pipeline_name = p.pipeline_name
GROUP BY p.pipeline_name, p.project_name, p.active, p.DAG_CRIADA, p.updated_at;
GO
 
IF OBJECT_ID('[dbo].[VW_PLDFT_BASE_ATIVA_PREV]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PLDFT_BASE_ATIVA_PREV];
GO
 CREATE VIEW [dbo].[VW_PLDFT_BASE_ATIVA_PREV] AS 
(

SELECT
	--CC.NUM_CERTIFICADO,
	CC.NOM_SEGMENTO
	,CASE WHEN CC.NOM_SEGMENTO='PREVIDENCIA' THEN 'KIPREV'
	WHEN CC.NOM_SEGMENTO='PRESTAMISTA' THEN 'WISER'
	ELSE 'SIAS'
	END 'DES_ORIGEM'
	,CASE WHEN CC.COD_TIPO_PESSOA='F' THEN 'PF'
	WHEN CC.COD_TIPO_PESSOA='J' then 'PJ'
	ELSE CC.COD_TIPO_PESSOA
	END 'COD_TIPO_PESSOA'
	,C.NUM_PROPOSTA
	,isnull(C.VLR_PREMIO,isnull(C.VLR_PMBAC,C.VLR_PMBAC_EMP)) as VLR_PREMIO
	,CC.NUM_CPF_CNPJ
	,CC.COD_PESSOA
	,CC.DES_PESSOA
	,CC.NOM_PESSOA
	,CC.DES_CBO
	,CC.NOM_LOGRADOURO
	,CC.NOM_BAIRRO
	,CC.NOM_CIDADE
	,CC.COD_UF
	,CC.COD_CEP
	,CC.DES_EMAIL
	,CC.NUM_DDD_CELULAR
	,CC.NUM_CELULAR
	,c.DTA_EMISSAO_PROPOSTA
	,CASE WHEN cc.COD_CLASSIFICACAO_RISCO IS NULL THEN 'N' ELSE 'S' END AS IND_CLASSIFICADO


FROM	[DMDB41].[dbo].[DM_CLIENTES_CONTRATOS_CVP] CC
		LEFT JOIN [DMDB41].[dbo].[DM_CONTRATOS_CVP] C 
			on	CC.NUM_CERTIFICADO=C.NUM_CERTIFICADO 
				and CC.NOM_SEGMENTO=C.NOM_SEGMENTO

WHERE	C.COD_STATUS_CONTRATO = 'A'
		and C.NOM_SEGMENTO = 'PREVIDENCIA'
		and CC.NUM_CPF_CNPJ <> 0
)
GO
 
IF OBJECT_ID('[dbo].[VW_PLDFT_BASE_FULL_SIS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PLDFT_BASE_FULL_SIS];
GO


CREATE view [dbo].[VW_PLDFT_BASE_FULL_SIS] AS

-- Regras
--------------------------------------
-- Ultimo endereço cadastrado (certificado)
-- Segurado e Beneficiário
-- Contratos Ativos (data Consulta)
-- Valor Premio para Vida e Prestamista, Valor reserva para Previdencia

with ENDERECO AS
(	

	select	NUM_CPF_CNPJ
			,CL.[NOM_LOGRADOURO]
			,[NUM_LOGRADOURO]
			,[DES_COMPL_ENDERECO]
			,[NOM_BAIRRO]
			,[NOM_CIDADE]
			,[COD_CEP]
			,[COD_UF]
			,[DES_EMAIL]
			,[NUM_DDD_TELEFONE]
			,[NUM_TELEFONE]
			,[NUM_DDD_CELULAR]
			,[NUM_CELULAR]

	from	DM_CLIENTES_CONTRATOS_CVP CL 
			left join DM_CONTRATOS_CVP as C 
				on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

	where	1=1
			and CL.NUM_CERTIFICADO = (	select MAX(CL2.NUM_CERTIFICADO) 
										from DM_CLIENTES_CONTRATOS_CVP CL2 
												left join DM_CONTRATOS_CVP as C2
													on CL2.NOM_SEGMENTO = C2.NOM_SEGMENTO
													and  CL2.NUM_CERTIFICADO = C2.NUM_CERTIFICADO
										where		CL2.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
													and	C2.COD_STATUS_CONTRATO = 'A'
													AND CL2.COD_PESSOA IN (1,4)
														--and CL2.nom_segmento = 'PREVIDENCIA'

											
											
											)
			and	C.COD_STATUS_CONTRATO = 'A'
			--and CL.nom_segmento = 'PREVIDENCIA'
			AND CL.COD_PESSOA IN (1,4)
			and CL.NUM_CPF_CNPJ > 0
			--AND CL.NUM_CPF_CNPJ = 6150577643
)

,VALOR AS 
(
	select	 CL.nom_segmento,
			Cl.NUM_CPF_CNPJ,
			CL.DES_PESSOA,
			--c.NUM_CERTIFICADO,
			sum(C.VLR_PMBAC+ C.vlr_pmbac_emp) as VLR_RESERVA,
			sum(C.VLR_PREMIO) as VLR_PREMIO
	
	from	DM_CLIENTES_CONTRATOS_CVP CL
			left join DM_CONTRATOS_CVP as C
				on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

	where	1=1
			--CL.NUM_CERTIFICADO = (	select MAX(CL2.NUM_CERTIFICADO) from DM_CLIENTES_CONTRATOS_CVP CL2 where CL2.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ)
			and	C.COD_STATUS_CONTRATO = 'A'
			--and CL.nom_segmento = 'PREVIDENCIA'
			AND CL.COD_PESSOA IN (1,4)
			and CL.NUM_CPF_CNPJ > 0

			--and CL.NUM_CPF_CNPJ = 06150577643

	group by	Cl.NUM_CPF_CNPJ,
				CL.DES_PESSOA,
				 CL.nom_segmento
				--C.NUM_CERTIFICADO
)

-- CONSULTA 
--------------------
select	distinct

		cL.NOM_PESSOA,
		CL.nom_segmento as SEGMENTO,
		Cl.NUM_CPF_CNPJ,
		isnull(VAL.VLR_RESERVA,val.vlr_premio) as VLR_PREMIO_RESERVA,
		CL.DES_PESSOA

		,CON.[NOM_LOGRADOURO]
		,CON.[NUM_LOGRADOURO]
		,CON.[DES_COMPL_ENDERECO]
		,CON.[NOM_BAIRRO]
		,CON.[NOM_CIDADE]
		,CON.[COD_CEP]
		,CON.[COD_UF]
		,CON.[DES_EMAIL]
		,CON.[NUM_DDD_TELEFONE]
		,CON.[NUM_TELEFONE]
		,CON.[NUM_DDD_CELULAR]
		,CON.[NUM_CELULAR]
		,case	when CL.[COD_TIPO_PESSOA] = 'J' then 2
				else 1
		END as [COD_TIPO_PESSOA]


from	DM_CLIENTES_CONTRATOS_CVP as CL
		left join DM_CONTRATOS_CVP as C
			on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
			and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

		-- End/contato
		left join ENDERECO as CON
			on CON.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
	
		-- valor
		left join VALOR as VAL
			on	VAL.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
				and VAL.NOM_SEGMENTO = CL.NOM_SEGMENTO
				and VAL.DES_PESSOA = CL.DES_PESSOA

where	C.COD_STATUS_CONTRATO = 'A'
		--and CL.nom_segmento = 'PREVIDENCIA'
		AND CL.COD_PESSOA IN (1,4)
		and CL.NUM_CPF_CNPJ > 0

	
	
	-- and CL.NUM_CPF_CNPJ = 06150577643 



GO
 
IF OBJECT_ID('[dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_AGREGADO_SIS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_AGREGADO_SIS];
GO




CREATE VIEW [dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_AGREGADO_SIS] AS


----------------------------------------------------------
-- ANALISE BASE UNIFICADA - CLASSIFICACAO RISCO
----------------------------------------------------------
-- Agrega informações da carteira ativa de clientes informando se existe classificação de risco ou não, tipo de classificação, PEP e NLIST.


-- carteira ativa analitica class risco
----------------------------------------------------
with CLASS_RISCO AS (

SELECT  NUM_CPF_CNPJ,
		NOM_SEGMENTO,
		COD_CLASSIFICACAO_RISCO,
		[DES_CLASSIFICACAO_RISCO]

FROM [dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_ORIGEM_SEGMENTO]

)

-- sem classificação -------------------
, CTR_SEM_CLASS AS 
(
	select	cli.NOM_SEGMENTO, 
			cli.DES_PESSOA,
			CR.[DES_CLASSIFICACAO_RISCO],
			Count(distinct P.CPF_CNPJ) as QTD_PEP,
			COUNT(DISTINCT N.NUM_CPF_CNPJ) AS QTD_NLIST,

			count(distinct Cli.NUM_CPF_CNPJ) as QTD_SEM_CLASSIFICACAO,
			0 as QTD_COM_CLASSIFICACAO

	from	DM_CLIENTES_CONTRATOS_CVP as CLI with (nolock)

			left join DM_CONTRATOS_CVP as C with (nolock)
				on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
				and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO

			left join CLASS_RISCO CR
				on CR.NUM_CPF_CNPJ = CLI.NUM_CPF_CNPJ
				and CR.NOM_SEGMENTO = CLI.NOM_SEGMENTO

			left join DM_PEP_CVP as P with (nolock)
				on P.CPF_CNPJ = CLI.NUM_CPF_CNPJ
				and P.DTA_FIM_VIGENCIA IS NULL

			LEFT join DM_NLIST_CVP as N with (nolock)
				on N.NUM_CPF_CNPJ = CLI.NUM_CPF_CNPJ
	where	
			C.COD_STATUS_CONTRATO = 'A'
			and cli.IND_CARGA <> 'D'
			and c.IND_CARGA <> 'D'
			and CR.COD_CLASSIFICACAO_RISCO is null
			and cli.NUM_CPF_CNPJ <> 0 
			and cli.NUM_CPF_CNPJ is not null
			and CLI.NOM_PESSOA <> '' -- desconsidera nome em branco
			and CLI.NOM_PESSOA is not null -- desconsidera nome nulo

	group by cli.NOM_SEGMENTO, cli.DES_PESSOA, CR.[DES_CLASSIFICACAO_RISCO]

),

-- com classificacao -------------------
CTR_COM_CLASS AS
(
	select	cli.NOM_SEGMENTO, 
			cli.DES_PESSOA,
			CR.[DES_CLASSIFICACAO_RISCO],
			Count(distinct P.CPF_CNPJ) as QTD_PEP,
			COUNT(DISTINCT N.NUM_CPF_CNPJ) AS QTD_NLIST,

			0 as QTD_SEM_CLASSIFICACAO,
			count(distinct Cli.NUM_CPF_CNPJ) as QTD_COM_CLASSIFICACAO

	from	DM_CLIENTES_CONTRATOS_CVP as CLI with (nolock)

			left join DM_CONTRATOS_CVP as C with (nolock)
				on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
				and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO

			left join CLASS_RISCO CR
				on CR.NUM_CPF_CNPJ = CLI.NUM_CPF_CNPJ
				and CR.NOM_SEGMENTO = CLI.NOM_SEGMENTO

			left join DM_PEP_CVP as P with (nolock)
				on P.CPF_CNPJ = CLI.NUM_CPF_CNPJ
				and P.DTA_FIM_VIGENCIA IS NULL

			LEFT join DM_NLIST_CVP as N with (nolock)
				on N.NUM_CPF_CNPJ = CLI.NUM_CPF_CNPJ
	where	
			C.COD_STATUS_CONTRATO = 'A'
			and cli.IND_CARGA <> 'D'
			and c.IND_CARGA <> 'D'
			and CR.COD_CLASSIFICACAO_RISCO is NOT null
			and cli.NUM_CPF_CNPJ <> 0 
			and cli.NUM_CPF_CNPJ is not null
			and CLI.NOM_PESSOA <> '' -- desconsidera nome em branco
			and CLI.NOM_PESSOA is not null -- desconsidera nome nulo

	group by cli.NOM_SEGMENTO, cli.DES_PESSOA, CR.[DES_CLASSIFICACAO_RISCO]
),

-- sem classificação TOTAL -------------------
CTR_SEM_CLASS_TOTAL AS 
(
	select	'TOTAL' as NOM_SEGMENTO, 
			'TOTAL'	AS DES_PESSOA,
			CR.[DES_CLASSIFICACAO_RISCO],
			Count(distinct P.CPF_CNPJ) as QTD_PEP,
			COUNT(DISTINCT N.NUM_CPF_CNPJ) AS QTD_NLIST,

			count(distinct Cli.NUM_CPF_CNPJ) as QTD_SEM_CLASSIFICACAO,
			0 as QTD_COM_CLASSIFICACAO

	from	DM_CLIENTES_CONTRATOS_CVP as CLI with (nolock)

			left join DM_CONTRATOS_CVP as C with (nolock)
				on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
				and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO

			left join CLASS_RISCO CR
				on CR.NUM_CPF_CNPJ = CLI.NUM_CPF_CNPJ
				and CR.NOM_SEGMENTO = CLI.NOM_SEGMENTO

			left join DM_PEP_CVP as P with (nolock)
				on P.CPF_CNPJ = CLI.NUM_CPF_CNPJ
				and P.D
GO
 
IF OBJECT_ID('[dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_FULL_SIS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_FULL_SIS];
GO




CREATE VIEW [dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_FULL_SIS] AS

-- CLASSIFICACAO DE RISCO - ANALITICO FULL
-- Carteira ativa analitica de clientes informando se existe classificação de risco ou não, tipo de classificação, PEP e NLIST.

-- Base classificação de risco por segmento
----------------------------------------------------
with CLASS_RISCO AS (

SELECT  NUM_CPF_CNPJ,
		NOM_SEGMENTO,
		COD_CLASSIFICACAO_RISCO,
		[DES_CLASSIFICACAO_RISCO]

FROM [dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_ORIGEM_SEGMENTO]

)

select	distinct
		cli.NOM_SEGMENTO, 
		cli.DES_PESSOA,
		cli.NUM_CPF_CNPJ,
		CR.[DES_CLASSIFICACAO_RISCO],
		case when P.CPF_CNPJ IS NULL THEN 'N' ELSE 'S' END as IND_PEP,
		case when N.NUM_CPF_CNPJ IS NULL THEN 'N' ELSE 'S' END as IND_NLIST

from	DM_CLIENTES_CONTRATOS_CVP as CLI with (nolock)

		left join DM_CONTRATOS_CVP as C with (nolock)
			on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
			and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO

		left join CLASS_RISCO CR with (nolock)
			on CR.NUM_CPF_CNPJ = CLI.NUM_CPF_CNPJ
			and CR.NOM_SEGMENTO = CLI.NOM_SEGMENTO

		left join DM_PEP_CVP as P with (nolock)
			on P.CPF_CNPJ = CLI.NUM_CPF_CNPJ
			and P.DTA_FIM_VIGENCIA IS NULL

		LEFT join DM_NLIST_CVP as N with (nolock)
			on N.NUM_CPF_CNPJ = CLI.NUM_CPF_CNPJ

where	C.COD_STATUS_CONTRATO = 'A'
		and cli.IND_CARGA <> 'D'
		and c.IND_CARGA <> 'D'
		--and CR.COD_CLASSIFICACAO_RISCO is null
		and cli.NUM_CPF_CNPJ <> 0 
		and cli.NUM_CPF_CNPJ is not null
		and CLI.NOM_PESSOA <> '' -- desconsidera nome em branco
		and CLI.NOM_PESSOA is not null -- desconsidera nome nulo

GO
 
