----------------------------------------------------------

CREATE VIEW [dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_RESULT_SIS] AS


-- ANALISE BASE UNIFICADA - CLASSIFICACAO RISCO

-- Job: 
-- tabela: TB_PLDFT_CLASSIFICACAO_RISCO_MONITOR_AGR
----------------------------------------------------------

with CLASS_RISCO AS (

SELECT  NUM_CPF_CNPJ,
		NOM_SEGMENTO,
		COD_CLASSIFICACAO_RISCO

FROM [dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_ORIGEM_SEGMENTO]

)

-- Consulta Principal ------------------
select	
		---getdate() as DTH_CARGA,
		cast(NOM_SEGMENTO as varchar(50)) as NOM_SEGMENTO,
		cast(DES_PESSOA as varchar(50)) as DES_PESSOA,
		cast(sum(QTD_SEM_CLASSIFICACAO) as bigint) as QTD_SEM_CLASSIFICACAO,
		cast(sum(QTD_COM_CLASSIFICACAO) as bigint) as QTD_COM_CLASSIFICACAO,
		cast(sum(QTD_SEM_CLASSIFICACAO) + sum(QTD_COM_CLASSIFICACAO) as bigint) AS VLR_TOTAL,

		-- Percentual de classificacao
		CAST(	cast(sum(QTD_COM_CLASSIFICACAO) as decimal(15,3))
				/ cast(sum(QTD_SEM_CLASSIFICACAO) + sum(QTD_COM_CLASSIFICACAO) as decimal(15,3)) * 100  
		AS decimal(15,3)) AS PCT_COM_CLASSIFICACAO

from (

-- sem classificação -------------------
select	cli.NOM_SEGMENTO, 
		cli.DES_PESSOA,
		count(distinct Cli.NUM_CPF_CNPJ) as QTD_SEM_CLASSIFICACAO,
		0 as QTD_COM_CLASSIFICACAO

from	DM_CLIENTES_CONTRATOS_CVP as CLI WITH (NOLOCK)

		left join DM_CONTRATOS_CVP as C WITH (NOLOCK)
			on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
			and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO

		left join CLASS_RISCO as CR with (nolock)
			on CR.NUM_CPF_CNPJ = CLI.NUM_CPF_CNPJ
			and CR.NOM_SEGMENTO = cli.nom_segmento
			
where	
		C.COD_STATUS_CONTRATO = 'A'
		and cli.IND_CARGA <> 'D'
		and c.IND_CARGA <> 'D'
		and CR.COD_CLASSIFICACAO_RISCO is null
		and cli.NUM_CPF_CNPJ <> 0 
		and cli.NUM_CPF_CNPJ is not null
		and CLI.NOM_PESSOA <> '' -- desconsidera nome em branco
		and CLI.NOM_PESSOA is not null -- desconsidera nome nulo

group by cli.NOM_SEGMENTO, cli.DES_PESSOA

UNION ALL 

-- com classificacao -------------------
select	cli.NOM_SEGMENTO, 
		cli.DES_PESSOA,
		0 as QTD_SEM_CLASSIFICACAO,
		count(distinct Cli.NUM_CPF_CNPJ) as QTD_COM_CLASSIFICACAO

from	DM_CLIENTES_CONTRATOS_CVP as CLI WITH (NOLOCK)

		left join DM_CONTRATOS_CVP as C WITH (NOLOCK)
			on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
			and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO

		left join CLASS_RISCO as CR with (nolock)
			on CR.NUM_CPF_CNPJ = CLI.NUM_CPF_CNPJ
			and CR.NOM_SEGMENTO = cli.nom_segmento
where	
		C.COD_STATUS_CONTRATO = 'A'
		and cli.IND_CARGA <> 'D'
		and c.IND_CARGA <> 'D'
		and CR.COD_CLASSIFICACAO_RISCO is not null
		and cli.NUM_CPF_CNPJ <> 0 
		and cli.NUM_CPF_CNPJ is not null
		and CLI.NOM_PESSOA <> '' -- desconsidera nome em branco
		and CLI.NOM_PESSOA is not null -- desconsidera nome nulo

group by cli.NOM_SEGMENTO, cli.DES_PESSOA

UNION ALL
-- sem classificação TOTAL -------------------
select	' TOTAL' as NOM_SEGMENTO, 
		'TOTAL'	 AS DES_PESSOA,
		count(distinct Cli.NUM_CPF_CNPJ) as QTD_SEM_CLASSIFICACAO,
		0 as QTD_COM_CLASSIFICACAO

from	DM_CLIENTES_CONTRATOS_CVP as CLI WITH (NOLOCK)

		left join DM_CONTRATOS_CVP as C WITH (NOLOCK)
			on cli.NOM_SEGMENTO = C.NOM_SEGMENTO
			and Cli.NUM_CERTIFICADO = C.NUM_CERTIFICADO

		left join CLASS_RISCO as CR with (nolock)
			on CR.NUM_CPF_CNPJ = CLI.NUM_CPF_CNPJ
			and CR.NOM_SEGMENTO = cli.nom_segmento
where	
		C.COD_STATUS_CONTRATO = 'A'
		and cli.IND_CARGA <> 'D'
		and c.IND_CARGA <> 'D'
		and CR.COD_CLASSIFICACAO_RISCO is null
		and cli.NUM_CPF_CNPJ <> 0 
		and cli.NUM_CPF_CNPJ is not null
		and CLI.NOM_PESSOA <> '' -- desconsidera nome em branco
		and CLI.NOM_PESSOA is not null -- desconsidera nome nulo

UNION ALL 

-- com classificacao TOTAL -------------------
select	' TOTAL' as NOM_SEGMENTO, 
		'TOTAL'	 AS DES_PESSOA,
		0 as QTD_SEM_CLASSIFICACAO,
		count(distinct Cli.NUM_CPF_CNPJ) as QTD_COM_CLASSIFICACAO

from	DM_CLIENT
GO
 
