IF OBJECT_ID('[dbo].[VW_PLDFT_CONTINGENCIA_RISCO]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PLDFT_CONTINGENCIA_RISCO];
GO



 CREATE VIEW [dbo].[VW_PLDFT_CONTINGENCIA_RISCO] AS 


with CLASS_RISCO AS (

SELECT  NUM_CPF_CNPJ,
		NOM_SEGMENTO,
		COD_CLASSIFICACAO_RISCO,
		[DES_CLASSIFICACAO_RISCO]

FROM [dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_ORIGEM_SEGMENTO]

)

SELECT

	--CC.NUM_CERTIFICADO,


	CC.NOM_SEGMENTO
	,CASE WHEN CC.NOM_SEGMENTO='PREVIDENCIA' THEN 'KIPREV'
	WHEN CC.NOM_SEGMENTO='PRESTAMISTA' THEN 'WISER'
	ELSE 'SIAS'
	END 'DES_ORIGEM'
	,CASE WHEN CC.COD_TIPO_PESSOA='F' THEN 'PF'
	WHEN CC.COD_TIPO_PESSOA='J' then 'PJ'
	ELSE CC.COD_TIPO_PESSOA
	END 'COD_TIPO_PESSOA'
	,C.NUM_PROPOSTA
	,isnull(C.VLR_PREMIO,isnull(C.VLR_PMBAC,C.VLR_PMBAC_EMP)) as VLR_PREMIO
	,CC.NUM_CPF_CNPJ
	,CC.COD_PESSOA
	,CC.DES_PESSOA
	,CC.NOM_PESSOA
	,CC.DES_CBO
	,CC.NOM_LOGRADOURO
	,CC.NOM_BAIRRO
	,CC.NOM_CIDADE
	,CC.COD_UF
	,CC.COD_CEP
	,CC.DES_EMAIL
	,CC.NUM_DDD_CELULAR
	,CC.NUM_CELULAR
	,c.DTA_EMISSAO_PROPOSTA
	,CASE WHEN cc.COD_CLASSIFICACAO_RISCO IS NULL THEN 'N' ELSE 'S' END AS IND_CLASSIFICADO


FROM	[DMDB41].[dbo].[DM_CLIENTES_CONTRATOS_CVP] CC with (nolock)

		LEFT JOIN [DMDB41].[dbo].[DM_CONTRATOS_CVP] C with (nolock)
			on	CC.NUM_CERTIFICADO=C.NUM_CERTIFICADO 
				and CC.NOM_SEGMENTO=C.NOM_SEGMENTO

			left join CLASS_RISCO CR
				on CR.NUM_CPF_CNPJ = CC.NUM_CPF_CNPJ
				and CR.NOM_SEGMENTO = CC.NOM_SEGMENTO

WHERE
		-- BUSCA TODOS OS CPFS SEM CLASSIFICACAO
		(	CC.NUM_CPF_CNPJ is not null
			and CR.COD_CLASSIFICACAO_RISCO is null
			and C.COD_STATUS_CONTRATO = 'A'
			and CC.NUM_CPF_CNPJ <> 0
			and len(CC.NUM_CPF_CNPJ) <= 14
			and CC.NUM_CPF_CNPJ not in (Select distinct NUM_CPF_CNPJ from DM_NLIST_CVP where IND_IMPEDIDO = 'SIM') -- Exclui Nlist

			------ TESTE ---------
			--and C.NUM_PROPOSTA = 83308180323791
			------ TESTE ---------

		)

		-- BUSCA TODOS OS CPFS COM CLASSIFICACAO DIFERENTE DE ALTA E MARCADO COMO PEP
		or 
		(	CC.NUM_CPF_CNPJ IS NOT NULL
			and Cr.COD_CLASSIFICACAO_RISCO <> 4 -- classificação baixa
			and C.COD_STATUS_CONTRATO = 'A' -- contrato ativo
			AND CC.NUM_CPF_CNPJ <> 0 
			and len(CC.NUM_CPF_CNPJ) <= 14
			and CC.IND_PEP = 'S' -- marcado como PEP
			and CC.NUM_CPF_CNPJ not in (Select distinct NUM_CPF_CNPJ from DM_NLIST_CVP where IND_IMPEDIDO = 'SIM') -- Exclui Nlist

			------ TESTE ---------
			--and C.NUM_PROPOSTA = 83308180323791
			------ TESTE ---------

		)
		-- BUSCA TITULAR DOS BENEFICIARIOS SEM CLASSIFICACAO (PREVIDENCIA)
		or 
		(	CC.des_CLASSIFICACAO_RISCO is NOT NULL -- COM CASSIFICACAO
			AND CC.NOM_SEGMENTO = 'PREVIDENCIA'
			AND CC.COD_PESSOA = 1
			and C.COD_STATUS_CONTRATO = 'A'
			and C.NUM_PROPOSTA IN 
			(
				-- BUSCA A PROPOSTA EM QUE O BENEFICIARIO ESTA SEM CLASSIFICACAO
				SELECT DISTINCT C2.NUM_PROPOSTA
				FROM	[DMDB41].[dbo].[DM_CLIENTES_CONTRATOS_CVP] CC2

						LEFT JOIN [DMDB41].[dbo].[DM_CONTRATOS_CVP] C2
							on	CC2.NUM_CERTIFICADO=C2.NUM_CERTIFICADO 
							and CC2.NOM_SEGMENTO=C2.NOM_SEGMENTO
						
						left join CLASS_RISCO CR2
							on CR2.NUM_CPF_CNPJ = CC2.NUM_CPF_CNPJ
							and CR2.NOM_SEGMENTO = CC2.NOM_SEGMENTO

				WHERE	CC2.NUM_CPF_CNPJ is not null
						AND CR2.COD_CLASSIFICACAO_RISCO is null
						and C2.COD_STATUS_CONTRATO = 'A'
						and CC2.NUM_CPF_CNPJ <> 0
						and len(CC2.NUM_CPF_CNPJ) <= 14
						and CC2.NUM_CPF_CNPJ not in (Select distinct NUM_CPF_CNPJ from DM_NLIST_CVP where IND_IMPEDIDO = 'SIM') -- Exclui Nlist
						and CC2.NUM_CERTIFICADO = CC.NUM_CERTIFICADO
			)
		)


GO
 
IF OBJECT_ID('[dbo].[VW_PLDFT_NAO_CLASSIFICADOS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PLDFT_NAO_CLASSIFICADOS];
GO






CREATE view [dbo].[VW_PLDFT_NAO_CLASSIFICADOS] AS

-- Regras
--------------------------------------
-- Ultimo endereço cadastrado (certificado)
-- Contratos Ativos (data Consulta)
-- Classificação Nula

with CLASS_RISCO AS (

SELECT  NUM_CPF_CNPJ,
		NOM_SEGMENTO,
		COD_CLASSIFICACAO_RISCO,
		[DES_CLASSIFICACAO_RISCO]

FROM [dbo].[VW_PLDFT_CLASSIFICACAO_RISCO_ORIGEM_SEGMENTO]

)

, ENDERECO AS
(	

	select	CL.NUM_CPF_CNPJ
			,CL.[NOM_LOGRADOURO]
			,[NUM_LOGRADOURO]
			,[DES_COMPL_ENDERECO]
			,[NOM_BAIRRO]
			,[NOM_CIDADE]
			,[COD_CEP]
			,[COD_UF]
			,[DES_EMAIL]
			,[NUM_DDD_TELEFONE]
			,[NUM_TELEFONE]
			,[NUM_DDD_CELULAR]
			,[NUM_CELULAR]

	from	DM_CLIENTES_CONTRATOS_CVP CL 
			left join DM_CONTRATOS_CVP as C 
				on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

			left join CLASS_RISCO CR
				on CR.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
				and CR.NOM_SEGMENTO = CL.NOM_SEGMENTO

	where	1=1
			and CL.NUM_CERTIFICADO = (	select MAX(CL2.NUM_CERTIFICADO) 
										from DM_CLIENTES_CONTRATOS_CVP CL2 
												left join DM_CONTRATOS_CVP as C2
													on CL2.NOM_SEGMENTO = C2.NOM_SEGMENTO
													and  CL2.NUM_CERTIFICADO = C2.NUM_CERTIFICADO
										where		CL2.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
													and	C2.COD_STATUS_CONTRATO = 'A'
													AND CL2.COD_PESSOA IN (1,4)
														--and CL2.nom_segmento = 'PREVIDENCIA'

											
											
											)
			and	C.COD_STATUS_CONTRATO = 'A'
			and CR.COD_CLASSIFICACAO_RISCO is null
			and CL.NUM_CPF_CNPJ > 0
			and CL.NUM_CPF_CNPJ IS NOT NULL
			and CL.IND_CARGA <> 'D'
			
)

,VALOR AS 
(
	select	 CL.nom_segmento,
			Cl.NUM_CPF_CNPJ,
			CL.DES_PESSOA,
			--c.NUM_CERTIFICADO,
			sum(C.VLR_PMBAC+ C.vlr_pmbac_emp) as VLR_RESERVA,
			sum(C.VLR_PREMIO) as VLR_PREMIO
	
	from	DM_CLIENTES_CONTRATOS_CVP CL
			left join DM_CONTRATOS_CVP as C
				on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO
			left join CLASS_RISCO CR
				on CR.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
				and CR.NOM_SEGMENTO = CL.NOM_SEGMENTO

	where	1=1
			--CL.NUM_CERTIFICADO = (select MAX(CL2.NUM_CERTIFICADO) from DM_CLIENTES_CONTRATOS_CVP CL2 where CL2.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ)
			and C.COD_STATUS_CONTRATO = 'A'
			and CR.COD_CLASSIFICACAO_RISCO is null
			and CL.NUM_CPF_CNPJ > 0
			and CL.NUM_CPF_CNPJ IS NOT NULL
			and CL.IND_CARGA <> 'D'

			--and CL.NUM_CPF_CNPJ = 06150577643

	group by	Cl.NUM_CPF_CNPJ,
				CL.DES_PESSOA,
				 CL.nom_segmento
				--C.NUM_CERTIFICADO
)

-- CONSULTA 
--------------------
select	distinct

		-- PESSOAL
		Cl.NUM_CPF_CNPJ
		,cL.NOM_PESSOA

		-- CONTRATO
		,CL.nom_segmento as SEGMENTO
		,CL.DES_PESSOA
		,isnull(VAL.VLR_RESERVA,val.vlr_premio) as VLR_PREMIO_RESERVA
		,C.DES_FORMA_PAGAMENTO
		
		-- ENDEREÇO
		,CON.[NOM_LOGRADOURO]
		,CON.[NUM_LOGRADOURO]
		,CON.[DES_COMPL_ENDERECO]
		,CON.[NOM_BAIRRO]
		,CON.[NOM_CIDADE]
		,CON.[COD_CEP]
		,CON.[COD_UF]
		,CON.[DES_EMAIL]
		,CON.[NUM_DDD_TELEFONE]
		,CON.[NUM_TELEFONE]
		,CON.[NUM_DDD_CELULAR]
		,CON.[NUM_CELULAR]

		-- COMPLEMENTO
		,CL.[COD_TIPO_PESSOA]
		,CL.IND_PEP
		,CL.IND_NLIST
		,CL.COD_CBO
		,CL.DES_CBO
		,CL.COD_CNAE
		,CL.DES_CNAE

from	DM_CLIENTES_CONTRATOS_CVP as CL
		left join DM_CONTRATOS_CVP as C
			on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
			and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

		-- End/contato
		left join ENDERECO as CON
			on CON.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
	
		-- valor
		left join VALOR as VAL
			on	VAL.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
				and VAL.NOM_SEGMENTO = CL.NOM_SEGMENTO
				and VAL.DES_PESSOA = CL.DES_PESSOA

		left join CLASS_RISCO CR
			on CR.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
			and CR.NOM_SEGMENTO = CL.NOM_SEGMENTO

where	C.COD_STATUS_CONTRATO = 'A'
		and CR.COD_CLASSIFICACAO_RISCO is null
		and CL.NUM_CPF_CNPJ > 0
		and CL.NUM_CPF_CNPJ IS NOT NULL
		a
GO
 
IF OBJECT_ID('[dbo].[VW_PLDFT_PEP_NLIST_SIS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PLDFT_PEP_NLIST_SIS];
GO


CREATE	VIEW VW_PLDFT_PEP_NLIST_SIS AS

--------------------------------------
-- Extação PEP e NLIST CVP
--------------------------------------
Select  CPF_CNPJ as NUM_CPF_CNPJ,
        max(isnull(IND_PEP,'N')) as IND_PEP,
        max(isnull(IND_NLIST,'N')) as IND_NLIST
from 
--------------------------------------
(
-- Extração de todos os Peps - base SOFTON (Oficial)
select    distinct CPF_CNPJ, 
        cast('S' as char(1)) as IND_PEP,
        null as IND_NLIST
from    [dbo].[DM_PEP_CVP]
where DTA_FIM_VIGENCIA IS NULL

union all

-- Extração de todos os Nlists - base SOFTON (Oficial)
select  distinct NUM_CPF_CNPJ, 
        null as IND_PEP,
        cast('S' as char(1)) as IND_NLIST
from    [DM_NLIST_CVP]
WHERE   DTA_FIM_VIGENCIA IS NULL
		and IND_IMPEDIDO = 'SIM'
			   
) A
group by A.CPF_CNPJ
GO
 
