CREATE VIEW VW_PLDFT_RECLASSIFICACAO_HIST_ATVS_CRIT_ELEV AS

WITH 
 LISTA_DADOS_CADASTRAIS AS 
		(
		SELECT TOP 1 WITH TIES 
		 W1.NUM_CPF_CNPJ
		,W1.NOM_SEGMENTO
		,UPPER(W1.COD_TIPO_PESSOA) AS COD_TIPO_PESSOA
		,UPPER(W1.DES_PESSOA) AS DES_PESSOA
		,UPPER(W1.NOM_PESSOA) AS NOM_PESSOA
		,UPPER(W1.NOM_LOGRADOURO) AS NOM_LOGRADOURO
		,UPPER(W1.NUM_LOGRADOURO) AS NUM_LOGRADOURO
		,UPPER(W1.DES_COMPL_ENDERECO) AS DES_COMPL_ENDERECO
		,UPPER(W1.NOM_BAIRRO) AS NOM_BAIRRO
		,UPPER(W1.NOM_CIDADE) AS NOM_CIDADE
		,UPPER(W1.COD_CEP) AS COD_CEP
		,UPPER(W1.COD_UF) AS COD_UF
		,UPPER(W1.DES_EMAIL) AS DES_EMAIL
		,UPPER(W1.NUM_DDD_TELEFONE) AS NUM_DDD_TELEFONE
		,UPPER(W1.NUM_TELEFONE) AS NUM_TELEFONE
		,UPPER(W1.NUM_DDD_CELULAR) AS NUM_DDD_CELULAR
		,UPPER(W1.NUM_CELULAR) AS NUM_CELULAR
		,W1.COD_CLASSIFICACAO_RISCO
		,W1.NUM_SCORE_RISCO
		FROM DMDB41.DBO.DM_CLIENTES_CONTRATOS_CVP W1 WITH(NOLOCK)

		INNER JOIN DMDB41.DBO.DM_CONTRATOS_CVP W2 WITH(NOLOCK)
		ON W1.NOM_SEGMENTO = W2.NOM_SEGMENTO
		AND  W1.NUM_CERTIFICADO = W2.NUM_CERTIFICADO
		AND W2.COD_STATUS_CONTRATO = 'A'

		WHERE W1.IND_CARGA <> 'D'
		AND W1.NUM_CPF_CNPJ > 0

		ORDER BY RANK() OVER (PARTITION BY W1.NUM_CPF_CNPJ, W1.NOM_SEGMENTO ORDER BY W1.DTH_CARGA DESC, W1.DTH_CARGA_ATUALIZACAO DESC, W1.NUM_CERTIFICADO DESC)
		)

,LISTA_VALORES AS
		(
		SELECT
		 W3.NUM_CPF_CNPJ
		,W3.NOM_SEGMENTO
		,SUM(W4.VLR_PMBAC + W4.VLR_PMBAC_EMP) AS VLR_RESERVA
		,SUM(W4.VLR_PREMIO) AS VLR_PREMIO
		FROM DMDB41.DBO.DM_CLIENTES_CONTRATOS_CVP W3 WITH(NOLOCK)

		INNER JOIN DMDB41.DBO.DM_CONTRATOS_CVP W4 WITH(NOLOCK)
		ON W3.NOM_SEGMENTO = W4.NOM_SEGMENTO
		AND  W3.NUM_CERTIFICADO = W4.NUM_CERTIFICADO
		AND W4.COD_STATUS_CONTRATO = 'A'

		WHERE W3.IND_CARGA <> 'D'
		AND W3.NUM_CPF_CNPJ > 0

		GROUP BY 
		 W3.NUM_CPF_CNPJ
		,W3.NOM_SEGMENTO
		)

,LISTA_CLASSIFICACAO_RISCO AS
		(
		SELECT DISTINCT
		 W5.NUM_CPF_CNPJ
		,W5.NOM_SEGMENTO
		,W5.COD_CLASSIFICACAO_RISCO
		,W5.NUM_SCORE_RISCO
		FROM DMDB41.DBO.TB_PLDFT_CLASSIFICACAO_RISCO W5 WITH(NOLOCK)
		WHERE W5.NOM_SEGMENTO IN ('PREVIDENCIA', 'VIDA')

		UNION ALL

		SELECT DISTINCT
		 W6.NUM_CPF_CNPJ
		,'PRESTAMISTA' AS NOM_SEGMENTO
		,W6.COD_CLASSIFICACAO_RISCO
		,W6.NUM_SCORE_RISCO
		FROM DMDB41.DBO.TB_PLDFT_CLASSIFICACAO_RISCO W6 WITH(NOLOCK)
		WHERE W6.NOM_SEGMENTO = 'VIDA'
		)

SELECT DISTINCT
 T1.NUM_CPF_CNPJ
,T3.NOM_PESSOA
,T1.NOM_SEGMENTO AS SEGMENTO
,T3.DES_PESSOA
,COALESCE(T4.VLR_RESERVA, T4.VLR_PREMIO) AS VLR_PREMIO_RESERVA
,T3.NOM_LOGRADOURO
,T3.NUM_LOGRADOURO
,T3.DES_COMPL_ENDERECO
,T3.NOM_BAIRRO
,T3.NOM_CIDADE
,T3.COD_CEP
,T3.COD_UF
,T3.DES_EMAIL
,T3.NUM_DDD_TELEFONE
,T3.NUM_TELEFONE
,T3.NUM_DDD_CELULAR
,T3.NUM_CELULAR
,T3.COD_TIPO_PESSOA
FROM DMDB41.DBO.DM_CLIENTES_CONTRATOS_CVP T1 WITH(NOLOCK)

INNER JOIN DMDB41.DBO.DM_CONTRATOS_CVP T2 WITH(NOLOCK)
ON T1.NOM_SEGMENTO = T2.NOM_SEGMENTO
AND  T1.NUM_CERTIFICADO = T2.NUM_CERTIFICADO
AND T2.COD_STATUS_CONTRATO = 'A'

LEFT JOIN LISTA_DADOS_CADASTRAIS T3
ON T1.NUM_CPF_CNPJ = T3.NUM_CPF_CNPJ
AND T1.NOM_SEGMENTO = T3.NOM_SEGMENTO

LEFT JOIN LISTA_VALORES T4
ON T1.NUM_CPF_CNPJ = T4.NUM_CPF_CNPJ
AND T1.NOM_SEGMENTO = T4.NOM_SEGMENTO

LEFT JOIN LISTA_CLASSIFICACAO_RISCO T5
ON T1.NUM_CPF_CNPJ = T5.NUM_CPF_CNPJ
AND T1.NOM_SEGMENTO = T5.NOM_SEGMENTO

WHERE T1.IND_CARGA <> 'D'
AND T1.NUM_CPF_CNPJ > 0
AND UPPER(TRANSLATE(TRIM(T1.DES_CLASSIFICACAO_RISCO),'Íí','Ii')) IN ('CRITICO', 'ELEVADO')

GO
 
