GO

--select * from VW_PLDFT_RECLASSIFICACAO_nlist_SIS

-- TODOS OS REGISTROS COM ALTERAÇÃO DE nlist
CREATE view [dbo].[VW_PLDFT_RECLASSIFICACAO_NLIST_SIS] AS


with NLIST_CVP as
(
	select	CL.NUM_CPF_CNPJ,
			CL.IND_NLIST

	from	DM_CLIENTES_CONTRATOS_CVP as CL  with (nolock)
			left join DM_CONTRATOS_CVP as C  with (nolock)
				on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

	where	C.COD_STATUS_CONTRATO = 'A'
			and CL.NUM_CPF_CNPJ is not null
			and CL.NUM_CPF_CNPJ <> 0
			and CL.IND_CARGA <> 'D'
)

,NLIST as 
(
    SELECT NUM_CPF_CNPJ AS cpf_cnpj,
           CASE WHEN IND_IMPEDIDO = 'SIM' THEN 'S' ELSE 'N' END AS IND_NLIST,
           DTA_INI_VIGENCIA,
           DTA_FIM_VIGENCIA
          -- ROW_NUMBER() OVER (PARTITION BY cpf_cnpj ORDER BY DTA_INICIO_VIGENCIA DESC) AS ORD -- 1 para p ultimo status
    FROM DM_NLIST_CVP P with (nolock)
)

,NLIST_ALTERACAO AS 
(
	select	DISTINCT
			PC.NUM_CPF_CNPJ,
			PC.IND_NLIST as IND_NLIST_CVP,
			P.IND_NLIST AS IND_NLIST_BASE,
			P.DTA_INI_VIGENCIA AS DTA_INICIO_VIGENCIA,
			P.DTA_FIM_VIGENCIA

	from	NLIST_CVP PC
			join NLIST P
				on PC.NUM_CPF_CNPJ = P.CPF_CNPJ
				--and P.ORD = 1
	where	(PC.IND_NLIST = 'S' and P.IND_NLIST = 'N')
			or
			(PC.IND_NLIST = 'N' and P.IND_NLIST = 'S')
)


,ENDERECO AS
(	

	select	NUM_CPF_CNPJ
			,CL.[NOM_LOGRADOURO]
			,[NUM_LOGRADOURO]
			,[DES_COMPL_ENDERECO]
			,[NOM_BAIRRO]
			,[NOM_CIDADE]
			,[COD_CEP]
			,[COD_UF]
			,[DES_EMAIL]
			,[NUM_DDD_TELEFONE]
			,[NUM_TELEFONE]
			,[NUM_DDD_CELULAR]
			,[NUM_CELULAR]

	from	DM_CLIENTES_CONTRATOS_CVP CL with (nolock)
			left join DM_CONTRATOS_CVP as C  with (nolock) 
				on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

	where	1=1
				and CL.NUM_CERTIFICADO = (	select MAX(CL2.NUM_CERTIFICADO) 
											from	DM_CLIENTES_CONTRATOS_CVP CL2 
													left join DM_CONTRATOS_CVP as C2
														on CL2.NOM_SEGMENTO = C2.NOM_SEGMENTO
														and  CL2.NUM_CERTIFICADO = C2.NUM_CERTIFICADO
											where		CL2.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
														and	C2.COD_STATUS_CONTRATO = 'A'
														--AND CL2.COD_PESSOA IN (1,4)
														--and CL2.nom_segmento = 'PREVIDENCIA'

											
											
											)
			and	C.COD_STATUS_CONTRATO = 'A'
			and CL.IND_CARGA <> 'D'
			--and CL.NUM_CPF_CNPJ = 23548533
			and CL.NUM_CPF_CNPJ In (select P.NUM_CPF_CNPJ  from NLIST_ALTERACAO P)
			
)

,VALOR AS 
(
	select	 CL.nom_segmento,
			Cl.NUM_CPF_CNPJ,
			CL.DES_PESSOA,
			--c.NUM_CERTIFICADO,
			sum(C.VLR_PMBAC+ C.vlr_pmbac_emp) as VLR_RESERVA,
			sum(C.VLR_PREMIO) as VLR_PREMIO
	
	from	DM_CLIENTES_CONTRATOS_CVP CL  with (nolock)
			left join DM_CONTRATOS_CVP as C  with (nolock)
				on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

	where	1=1
			and CL.NUM_CPF_CNPJ In (select P.NUM_CPF_CNPJ  from NLIST_ALTERACAO P)
			--CL.NUM_CERTIFICADO = (select MAX(CL2.NUM_CERTIFICADO) from DM_CLIENTES_CONTRATOS_CVP CL2 where CL2.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ)
			and C.COD_STATUS_CONTRATO = 'A'
			and CL.IND_CARGA <> 'D'

	group by	Cl.NUM_CPF_CNPJ,
				CL.DES_PESSOA,
				 CL.nom_segmento
				--C.NUM_CERTIFICADO
)

-------------------------------------------------------------
-- TODOS OS REGISTROS COM ALTERACAO DE PEP
-------------------------------------------------------------

select	distinct

		-- PESSOAL
		Cl.NUM_CPF_CNPJ
		,cL.NOM_PESSOA

		-- CONTRATO
		,CL.nom_segmento as SEGMENTO
		,CL.DES_PESSOA
		,isnull(VAL.VLR_RESERVA,val.vlr_premio) as VLR_PREMIO_RESERVA
		----,C.DES_FORMA_PAGAMENTO
		
		-- ENDEREÇO
		,CON.[NOM_LOGRADOURO]
		,CON.[NUM_LOGRADOURO]
		,CON.[DES_COMPL_ENDERECO]
		,CON.[NOM_BAIRRO]
		,CON.[NOM_CIDADE]
		,CON.[COD_CEP]
		,CON.[COD_UF]
		,CON.[DES_EMAIL]
		,CON.[NUM_DDD_TELEFONE]
		,CON.[NUM_TELEFONE]
		,CON.[NUM_DDD_CELULAR]
		,CON.[NUM_C
GO
 
