CREATE view [dbo].[VW_PLDFT_RECLASSIFICACAO_PEP_SIS_A] AS
-- TODOS OS REGISTROS COM ALTERAÇÃO DE PEP

with PEP_CVP as
(
	select	CL.NUM_CPF_CNPJ,
			CL.IND_PEP

	from	DM_CLIENTES_CONTRATOS_CVP as CL  with (nolock)
			left join DM_CONTRATOS_CVP as C  with (nolock)
				on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

	where	C.COD_STATUS_CONTRATO = 'A'
	and     CL.NUM_CPF_CNPJ > 0
)

,PEP as 
(
    SELECT cpf_cnpj,
           CASE WHEN DTA_FIM_VIGENCIA IS NULL THEN 'S' ELSE 'N' END AS IND_PEP,
           DTA_INICIO_VIGENCIA,
           DTA_FIM_VIGENCIA,
           ROW_NUMBER() OVER (PARTITION BY cpf_cnpj ORDER BY DTA_INICIO_VIGENCIA DESC) AS ORD -- 1 para p ultimo status
    FROM DM_PEP_CVP P with (nolock)
)

,PEP_ALTERACAO AS 
(
	select	DISTINCT
			PC.NUM_CPF_CNPJ,
			PC.IND_PEP as IND_PEP_CVP,
			P.IND_PEP AS IND_PEP_BASE,
			P.DTA_INICIO_VIGENCIA,
			P.DTA_FIM_VIGENCIA

	from	PEP_CVP PC
			join PEP P
				on PC.NUM_CPF_CNPJ = P.CPF_CNPJ
				and P.ORD = 1
	where	(PC.IND_PEP = 'S' and P.IND_PEP = 'N')
			or
			(PC.IND_PEP = 'N' and P.IND_PEP = 'S')
)


,ENDERECO AS
(	

	select	CL.[NUM_CPF_CNPJ]
			,CL.[NOM_LOGRADOURO]
			,[NUM_LOGRADOURO]
			,[DES_COMPL_ENDERECO]
			,[NOM_BAIRRO]
			,[NOM_CIDADE]
			,[COD_CEP]
			,[COD_UF]
			,[DES_EMAIL]
			,[NUM_DDD_TELEFONE]
			,[NUM_TELEFONE]
			,[NUM_DDD_CELULAR]
			,[NUM_CELULAR]

	from	DM_CLIENTES_CONTRATOS_CVP CL with (nolock)
			left join DM_CONTRATOS_CVP as C  with (nolock) 
				 on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO
			join PEP_ALTERACAO as P with (nolock) 
		         on CL.NUM_CPF_CNPJ = P.NUM_CPF_CNPJ

	where	1=1
				and CL.NUM_CERTIFICADO = (	select MAX(CL2.NUM_CERTIFICADO) 
											from	DM_CLIENTES_CONTRATOS_CVP CL2 
													left join DM_CONTRATOS_CVP as C2
														on CL2.NOM_SEGMENTO = C2.NOM_SEGMENTO
														and  CL2.NUM_CERTIFICADO = C2.NUM_CERTIFICADO
											where		CL2.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
														and	C2.COD_STATUS_CONTRATO = 'A'
										 )
										 
			and	C.COD_STATUS_CONTRATO = 'A'
			and CL.IND_CARGA <> 'D'
			
)

,VALOR AS 
(
	select	 CL.nom_segmento,
			Cl.NUM_CPF_CNPJ,
			CL.DES_PESSOA,
			--c.NUM_CERTIFICADO,
			sum(C.VLR_PMBAC+ C.vlr_pmbac_emp) as VLR_RESERVA,
			sum(C.VLR_PREMIO) as VLR_PREMIO
	
	from	DM_CLIENTES_CONTRATOS_CVP CL  with (nolock)
			left join DM_CONTRATOS_CVP as C  with (nolock)
				on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO
			join PEP_ALTERACAO as P with (nolock) 
		         on CL.NUM_CPF_CNPJ = P.NUM_CPF_CNPJ

	where	1=1
			and C.COD_STATUS_CONTRATO = 'A'
			and CL.IND_CARGA <> 'D'

	group by	Cl.NUM_CPF_CNPJ,
				CL.DES_PESSOA,
				CL.nom_segmento
)

-------------------------------------------------------------
-- TODOS OS REGISTROS COM ALTERACAO DE PEP
-------------------------------------------------------------

select	distinct

		-- PESSOAL
	   	 Cl.NUM_CPF_CNPJ
		,cL.NOM_PESSOA

		-- CONTRATO
		,CL.nom_segmento as SEGMENTO
		,CL.DES_PESSOA
		,isnull(VAL.VLR_RESERVA,val.vlr_premio) as VLR_PREMIO_RESERVA
		
		-- ENDEREÇO
		,CON.[NOM_LOGRADOURO]
		,CON.[NUM_LOGRADOURO]
		,CON.[DES_COMPL_ENDERECO]
		,CON.[NOM_BAIRRO]
		,CON.[NOM_CIDADE]
		,CON.[COD_CEP]
		,CON.[COD_UF]
		,CON.[DES_EMAIL]
		,CON.[NUM_DDD_TELEFONE]
		,CON.[NUM_TELEFONE]
		,CON.[NUM_DDD_CELULAR]
		,CON.[NUM_CELULAR]

		-- COMPLEMENTO
		,CL.[COD_TIPO_PESSOA]

from	DM_CLIENTES_CONTRATOS_CVP as CL  with (nolock)
		left join DM_CONTRATOS_CVP as C  with (nolock)
			on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
			and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

		-- End/contato
		left join ENDERECO as CON
			on CON.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
	
		-- valor
		left join VALOR as VAL
			on	VAL.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
				and VAL.NOM_SEGMENTO = CL.NOM_SEGMENTO
				and VAL.DES_PES
GO
 
