CREATE VIEW [dbo].[VW_PLDFT_RECLASSIFICACAO_SIS] AS



WITH 
 LISTA_DADOS_CADASTRAIS AS 
		(
		SELECT TOP 1 WITH TIES 
		 W1.NUM_CPF_CNPJ
		,W1.NOM_SEGMENTO
		,UPPER(W1.COD_TIPO_PESSOA) AS COD_TIPO_PESSOA
		,UPPER(W1.DES_PESSOA) AS DES_PESSOA
		,UPPER(W1.NOM_PESSOA) AS NOM_PESSOA
		,UPPER(W1.NOM_LOGRADOURO) AS NOM_LOGRADOURO
		,UPPER(W1.NUM_LOGRADOURO) AS NUM_LOGRADOURO
		,UPPER(W1.DES_COMPL_ENDERECO) AS DES_COMPL_ENDERECO
		,UPPER(W1.NOM_BAIRRO) AS NOM_BAIRRO
		,UPPER(W1.NOM_CIDADE) AS NOM_CIDADE
		,UPPER(W1.COD_CEP) AS COD_CEP
		,UPPER(W1.COD_UF) AS COD_UF
		,UPPER(W1.DES_EMAIL) AS DES_EMAIL
		,UPPER(W1.NUM_DDD_TELEFONE) AS NUM_DDD_TELEFONE
		,UPPER(W1.NUM_TELEFONE) AS NUM_TELEFONE
		,UPPER(W1.NUM_DDD_CELULAR) AS NUM_DDD_CELULAR
		,UPPER(W1.NUM_CELULAR) AS NUM_CELULAR
		,W1.COD_CLASSIFICACAO_RISCO
		,W1.NUM_SCORE_RISCO
		FROM DMDB41.DBO.DM_CLIENTES_CONTRATOS_CVP W1

		INNER JOIN DMDB41.DBO.DM_CONTRATOS_CVP W2
		ON W1.NOM_SEGMENTO = W2.NOM_SEGMENTO
		AND  W1.NUM_CERTIFICADO = W2.NUM_CERTIFICADO
		AND W2.COD_STATUS_CONTRATO = 'A'

		WHERE W1.IND_CARGA <> 'D'
		AND W1.NUM_CPF_CNPJ > 0

		ORDER BY RANK() OVER (PARTITION BY W1.NUM_CPF_CNPJ, W1.NOM_SEGMENTO ORDER BY W1.DTH_CARGA DESC, W1.DTH_CARGA_ATUALIZACAO DESC, W1.NUM_CERTIFICADO DESC)
		)

,LISTA_VALORES AS
		(
		SELECT
		 W3.NUM_CPF_CNPJ
		,W3.NOM_SEGMENTO
		,SUM(W4.VLR_PMBAC + W4.VLR_PMBAC_EMP) AS VLR_RESERVA
		,SUM(W4.VLR_PREMIO) AS VLR_PREMIO
		FROM DMDB41.DBO.DM_CLIENTES_CONTRATOS_CVP W3

		INNER JOIN DMDB41.DBO.DM_CONTRATOS_CVP W4
		ON W3.NOM_SEGMENTO = W4.NOM_SEGMENTO
		AND  W3.NUM_CERTIFICADO = W4.NUM_CERTIFICADO
		AND W4.COD_STATUS_CONTRATO = 'A'

		WHERE W3.IND_CARGA <> 'D'
		AND W3.NUM_CPF_CNPJ > 0

		GROUP BY 
		 W3.NUM_CPF_CNPJ
		,W3.NOM_SEGMENTO
		)

,LISTA_CLASSIFICACAO_RISCO AS
		(
		SELECT DISTINCT
		 W5.NUM_CPF_CNPJ
		,W5.NOM_SEGMENTO
		,W5.COD_CLASSIFICACAO_RISCO
		,W5.NUM_SCORE_RISCO
		FROM DMDB41.DBO.TB_PLDFT_CLASSIFICACAO_RISCO W5
		WHERE W5.NOM_SEGMENTO IN ('PREVIDENCIA', 'VIDA')

		UNION ALL

		SELECT DISTINCT
		 W6.NUM_CPF_CNPJ
		,'PRESTAMISTA' AS NOM_SEGMENTO
		,W6.COD_CLASSIFICACAO_RISCO
		,W6.NUM_SCORE_RISCO
		FROM DMDB41.DBO.TB_PLDFT_CLASSIFICACAO_RISCO W6
		WHERE W6.NOM_SEGMENTO = 'VIDA'
		)

,LISTA_VENDAS_DIARIAS AS
		(
		SELECT DISTINCT
		 CAST(W7.NUM_CPF_CNPJ AS BIGINT) AS NUM_CPF_CNPJ
		,'VIDA' AS NOM_SEGMENTO
		,SUM(W7.VLR_PREMIO) VLR_PREMIO_RESERVA
		FROM DMDB49.dbo.PD_AIC_PROPOSTA_VIDA_FAT W7
		WHERE CAST(W7.DTH_VENDA AS DATE) = CAST(GETDATE()-1 AS DATE)
		GROUP BY W7.NUM_CPF_CNPJ
 
		UNION ALL

		SELECT DISTINCT
		 CAST(COALESCE(W8.NUM_CPF, W8.NUM_CNPJ) AS BIGINT) AS NUM_CPF_CNPJ
		,'PRESTAMISTA' AS NOM_SEGMENTO
		,SUM(W8.VLR_PREMIO) VLR_PREMIO_RESERVA
		FROM DMDB49.dbo.PD_AIC_PROPOSTA_PREST_FAT W8
		WHERE CAST(W8.DTH_VENDA AS DATE) = CAST(GETDATE()-1 AS DATE)
		GROUP BY CAST(COALESCE(W8.NUM_CPF, W8.NUM_CNPJ) AS BIGINT)

		UNION ALL

		SELECT DISTINCT
		 CAST(W9.NUM_CPF_CNPJ AS BIGINT) AS NUM_CPF_CNPJ
		,'PREVIDENCIA' AS NOM_SEGMENTO
		,SUM(W9.VLR_GERADO) VLR_PREMIO_RESERVA
		FROM DMDB49.dbo.PD_AIC_PROPOSTA_PREV_FAT W9
		WHERE CAST(W9.DTH_VENDA AS DATE) = CAST(GETDATE()-1 AS DATE)
		GROUP BY W9.NUM_CPF_CNPJ
		)


SELECT DISTINCT 
 T9.NUM_CPF_CNPJ
,T9.NOM_PESSOA
,T9.NOM_SEGMENTO AS SEGMENTO
,T9.DES_PESSOA
,SUM(T9.VLR_PREMIO_RESERVA) AS VLR_PREMIO_RESERVA
,T9.NOM_LOGRADOURO
,T9.NUM_LOGRADOURO
,T9.DES_COMPL_ENDERECO
,T9.NOM_BAIRRO
,T9.NOM_CIDADE
,T9.COD_CEP
,T9.COD_UF
,T9.DES_EMAIL
,T9.NUM_DDD_TELEFONE
,T9.NUM_TELEFONE
,T9.NUM_DDD_CELULAR
,T9.NUM_CELULAR
,T9.COD_TIPO_PESSOA
FROM	(
		SELECT DISTINCT
		 T1.NUM_CPF_CNPJ
		,T3.NOM_PESSOA
		,T1.NOM_SEGMENTO
		,T3.DES_PESSOA
		,COALESCE(T4.VLR_RESERVA, T4.VLR_PREMIO) AS VLR_PREMIO_RESERVA
		,T3.NOM_LOGRADOURO
		,T3.NUM_LOGRADOURO
		,T3.DES_COMPL_ENDERECO
		,T3.NOM_BAIRRO
		,T3.NOM_CIDADE
		,T3.COD_CEP
		,T3.COD_UF
		,T3.DES_EMAIL
		,T3.NUM_DDD_TEL
GO
 
