  create view [dbo].[VW_PLDFT_RECLASSIFICACAO_SIS_RT] AS
  
  with CLASS_RISCO AS (

SELECT  NUM_CPF_CNPJ,
		NOM_SEGMENTO,
		COD_CLASSIFICACAO_RISCO,
