UNION ALL

SELECT  NUM_CPF_CNPJ,
		'VIDA' AS NOM_SEGMENTO,
		COD_CLASSIFICACAO_RISCO,
		DTA_CLASSIFICACAO_RISCO,
		DES_CLASSIFICACAO_RISCO

FROM TB_PLDFT_CLASSIFICACAO_RISCO CR with (nolock)
WHERE NOM_SEGMENTO = 'VIDA'

UNION ALL

SELECT  NUM_CPF_CNPJ,
		'PRESTAMISTA' AS NOM_SEGMENTO,
		COD_CLASSIFICACAO_RISCO,
		DTA_CLASSIFICACAO_RISCO,
		DES_CLASSIFICACAO_RISCO

FROM TB_PLDFT_CLASSIFICACAO_RISCO CR with (nolock)
WHERE NOM_SEGMENTO = 'VIDA'
)

, ENDERECO AS

(	select	cl.NUM_CPF_CNPJ
			,CL.[NOM_LOGRADOURO]
			,[NUM_LOGRADOURO]
			,[DES_COMPL_ENDERECO]
			,[NOM_BAIRRO]
			,[NOM_CIDADE]
			,[COD_CEP]
			,[COD_UF]
			,[DES_EMAIL]
			,[NUM_DDD_TELEFONE]
			,[NUM_TELEFONE]
			,[NUM_DDD_CELULAR]
			,[NUM_CELULAR]

	from	DM_CLIENTES_CONTRATOS_CVP CL with (nolock)
			left join DM_CONTRATOS_CVP as C  with (nolock) 
				on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

			left join CLASS_RISCO CR with (nolock)
				on CR.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
				and CR.NOM_SEGMENTO = CL.NOM_SEGMENTO

	where	1=1
			and CL.NUM_CERTIFICADO = (	select MAX(CL2.NUM_CERTIFICADO) 
										from DM_CLIENTES_CONTRATOS_CVP CL2 
												left join DM_CONTRATOS_CVP as C2
													on CL2.NOM_SEGMENTO = C2.NOM_SEGMENTO
													and  CL2.NUM_CERTIFICADO = C2.NUM_CERTIFICADO
										where		CL2.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
													and	C2.COD_STATUS_CONTRATO = 'A'
													--AND CL2.COD_PESSOA IN (1,4)
													--and CL2.nom_segmento = 'PREVIDENCIA'

											)

			and	C.COD_STATUS_CONTRATO = 'A'
			and CR.COD_CLASSIFICACAO_RISCO is null
			and CL.NUM_CPF_CNPJ > 0
			and CL.NUM_CPF_CNPJ IS NOT NULL
			and CL.IND_CARGA <> 'D'
			-- teste
			--and CL.NUM_CPF_CNPJ = 30185122	
)

,VALOR AS 
(
	select	CL.nom_segmento,
			Cl.NUM_CPF_CNPJ,
			CL.DES_PESSOA,
			--c.NUM_CERTIFICADO,
			sum(C.VLR_PMBAC+ C.vlr_pmbac_emp) as VLR_RESERVA,
			sum(C.VLR_PREMIO) as VLR_PREMIO
	
	from	DM_CLIENTES_CONTRATOS_CVP CL  with (nolock)

			left join DM_CONTRATOS_CVP as C  with (nolock)
				on CL.NOM_SEGMENTO = C.NOM_SEGMENTO
				and  CL.NUM_CERTIFICADO = C.NUM_CERTIFICADO

			left join CLASS_RISCO CR with (nolock)
				on CR.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
				and CR.NOM_SEGMENTO = CL.NOM_SEGMENTO

	where	1=1
			--CL.NUM_CERTIFICADO = (select MAX(CL2.NUM_CERTIFICADO) from DM_CLIENTES_CONTRATOS_CVP CL2 where CL2.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ)
			and CL.NUM_CERTIFICADO = (	select MAX(CL2.NUM_CERTIFICADO) 
										from DM_CLIENTES_CONTRATOS_CVP CL2 
												left join DM_CONTRATOS_CVP as C2
													on CL2.NOM_SEGMENTO = C2.NOM_SEGMENTO
													and  CL2.NUM_CERTIFICADO = C2.NUM_CERTIFICADO
										where		CL2.NUM_CPF_CNPJ = CL.NUM_CPF_CNPJ
													and	C2.COD_STATUS_CONTRATO = 'A'
													--AND CL2.COD_PESSOA IN (1,4)
													--and CL2.nom_segmento = 'PREVIDENCIA'
													)
			and C.COD_STATUS_CONTRATO = 'A'
			and CR.COD_CLASSIFICACAO_RISCO is null
			and CL.NUM_CPF_CNPJ > 0
			and CL.NUM_CPF_CNPJ IS NOT NULL
			and CL.IND_CARGA <> 'D'
			--and CL.NUM_CPF_CNPJ = 06150577643

	group by	Cl.NUM_CPF_CNPJ,
				CL.DES_PESSOA,
				 CL.nom_segmento
				--C.NUM_CERTIFIC
GO
 
