CREATE	VIEW [dbo].[VW_PORTABILIDADE_FUNDO] AS
---------------------------------------------------------------------------------------------------
--		 select  distinct des_sit_portabilidade from dmdb41..VW_PORTABILIDADE_FUNDO order by 1
---------------------------------------------------------------------------------------------------
--
--		VIEW DE PORTABILIDADE DE SAIDA COM OS FUNDOS DE DESTINO
--		
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J® :	15/04/2024 - Criação	
---------------------------------------------------------------------------------------------------

SELECT 
		P.NUM_PORTABILIDADE,
		C.NUM_CERTIFICADO,
		AG.COD_AGENCIA,
		AG.NOM_AGENCIA,
		C.DTA_INICIO_VIGENCIA		AS DTA_EMISSAO_CERTIFICADO,
		SI.DTH_PROTOCOLO,
		P.DTA_SOLICITACAO,
		P.DTA_CREDITO,
		P.DTA_EFETIVACAO,
		PES.NOM_PESSOA,
		PES.NUM_CPF_CNPJ,
		PES.DTA_NASC_FUNDACAO		AS DTA_NASCIMENTO,
		PES.STA_SEXO,
		SP.DES_SIT_PORTABILIDADE,


		CASE	WHEN	SP.DES_SIT_PORTABILIDADE	=	'Cancelada'					THEN 'CANCELADA'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Devolvida'					THEN 'EM ANDAMENTO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Devolução por Divergência' THEN 'EM ANDAMENTO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Doc/Ted Confirmado'		THEN 'NAO RETIDO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Doc/Ted Informado'			THEN 'NAO RETIDO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Em Pagamento'				THEN 'NAO RETIDO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Em Preenchimento'			THEN 'NAO RETIDO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Em Reten¿¿o'				THEN 'EM ANDAMENTO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Solicitada'				THEN 'EM ANDAMENTO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Estornada'					THEN 'RETIDO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Excluída'					THEN 'CANCELADA'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Finalizada'				THEN 'NAO RETIDO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Finalizado sem Confirmação do Side' THEN 'NAO RETIDO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Informar Doc/Ted'			THEN 'NAO RETIDO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Liberada'					THEN 'EM ANDAMENTO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Liberado para Cessionária' THEN 'EM ANDAMENTO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Pendente'					THEN 'EM ANDAMENTO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Recusada'					THEN 'RETIDO'
				WHEN	SP.DES_SIT_PORTABILIDADE	=	'Simulacao'					THEN 'CANCELADA'
				ELSE	SP.DES_SIT_PORTABILIDADE
				END		AS			DES_SIT_PORTABILIDADE_TRADADA,

		MP.MOT_PORTABILIDADE,
		DP.DES_DIR_PORTABILIDADE	AS TIPO_PORTABILIDADE,
		TP.DES_TP_PORTABILIDADE		AS PARCIAL_TOTAL,
		
		I.NOM_INSTITUICAO			AS NOM_INSTITUICAO_CED,
		I.NUM_CNPJ_INSTITUICAO		AS CNPJ_INSTITUICAO_CED,
		I.DES_TP_INSTITUICAO		AS TIPO_CED,
		I.DES_REG_TRIBUTARIO		AS REGIME_TRIB_CED,
		----
		CASE	WHEN I.NUM_CNPJ_FUNDO IS NULL 
				THEN F.NUM_CNPJ_FUNDO 
				ELSE I.NUM_CNPJ_FUNDO 
				END					AS CNPJ_FUNDO_CED_CVP,

		I.NUM_PROC_SUSEP			AS NUM_PROC_SUSEP_CED,

		S.NOM_FUNDO					AS NOM_FUNDO_CVP ,
		S.DTA_INICIO_FUNDO			AS DTA_INICIO_FUNDO_CVP,
		S.DES_CLASSIF_ANBIMA		AS DES_CLASSIF_ANBIMA_CVP,
		S.PCT_TAXA_ADM				AS PCT_TAXA_ADM_CVP,
		S.PCT_RET_TRIMESTRAL		AS PCT_RET_TRIMESTRAL_CVP,
		S.PCT_RET_SEMESTRAL			AS PCT_RET_SEMESTRAL_CVP,
		S.PCT_RET_ANUAL				AS PCT_RET_ANUAL_CVP,
		S.PCT_VOLATIL_TRIMESTRAL	AS PCT_VOLATIL_TRIMESTRAL_CVP,
		S.PCT_VOLATIL_SEMESTRAL		AS PCT_VOLATIL_SEMESTRAL_CVP,
		S.PCT_VOLATIL_ANUAL			AS PCT_VOLATIL_ANUAL_CVP,

		---
		SI.IND_PLN_CED_CES			AS IDENTIFICACAO_PLANO_CED_CES,
		I2.NOM_INSTITUICAO			AS NOM_INSTITUICAO_CES,
		I2.NUM_CNPJ_INSTITUICAO		AS CNPJ_INSTITUICAO_CES,
		I2.DES_TP_INSTITUICAO		AS TIPO_CES,
		I2.DES_REG_TRIBUTARIO		AS REGIME_TRIB_CES,
		I2.NUM_CNPJ_FUNDO			AS NUM_CNPJ_FUNDO_EXT,
		CASE	WHEN I2.NUM_CNPJ_INSTITUICAO not in (  '-9' , '-7')
				THEN I2.NUM_CNPJ_FUNDO  
				ELSE null
				END					AS CNPJ_FUNDO_CES,
		I2.NUM_PROC_SUSEP			AS NUM_PROC_SUSEP
GO
 
IF OBJECT_ID('[dbo].[VW_PRC_530_ENVIA_RESGATES_REINF]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PRC_530_ENVIA_RESGATES_REINF];
GO


---------------------------------------------------------------------------------------------------
--		RITM0035913 - Extração de dados 
---------------------------------------------------------------------------------------------------
--		Para que possamos estar validando mensalmente a REINF com o KIPREV, preciso que seja 
--		disponibilizado os arquivos mensais de resgate e benefício. 
--		o relatorio deve ser emitido mensalmente com todas as informações constantes nos anexos. 

--		Área do solicitante: DIRFI_CVP GEFIS_CVP

--		CRIANDO NO SQL14 DEVIDO A KIPREV OPENQUERY
--		RECUPERADO NO SSC
---------------------------------------------------------------------------------------------------
--		28/08/2025	:	J®	-	CRIAÇÃO 
---------------------------------------------------------------------------------------------------

CREATE 	VIEW  [dbo].[VW_PRC_530_ENVIA_RESGATES_REINF] 

AS

----------------------------------------------------------------------------------------------------
--		AIC +  VENDA INTERNA KIPREV (COM PGTO) + RAJADA +  SAP
----------------------------------------------------------------------------------------------------
---------------------------------------------------------------------------------------------------
WITH 
BASE1 AS (

SELECT	*
FROM	OPENQUERY(KIPRD,
'SELECT ''RESGATE PAGAR PARA'' TIPO_PAGAMENTO, -- 1
       I.CPF, -- 2
       TO_CHAR(ADD_MONTHS(SYSDATE, -1), ''YYYY'')  AS ANO, -- 3
       I.MODALIDADE, -- 4
       I.OPCAO_TRIBUTACAO_IRRF, -- 5
       I.VLR_SAIDA_BRT, -- 6
       I.VLR_SAIDA_LIQ, -- 7
       I.VLR_BASE_IRRF, -- 8
       I.VLR_IRRF, -- 9
	   I.DATA_PAGAMENTO
  FROM (SELECT  ID.NUM_ID CPF,
                SUM(CALC.VLR_SAIDA_BRT) VLR_SAIDA_BRT,
                SUM(CALC.VLR_SAIDA_LIQ) VLR_SAIDA_LIQ,
                SUM(CALC.VLR_BASE_IRRF) VLR_BASE_IRRF,
                SUM(CALC.VLR_IRRF) VLR_IRRF,
                MOD.DESCRIPCION MODALIDADE,
                RS.OPCAO_TRIBUTACAO_IRRF, -- US 30515 - TASK 30518
				TO_CHAR(TRUNC(NVL(TIT.DATA_PGTO_EFETIVO, TIT.DATA_PGTO)), ''YYYY-MM-DD'') DATA_PAGAMENTO
          FROM KIPREV.BA_CPG_SOLICITACOES SOL
          JOIN KIPREV.BA_CPG_TITULOS TIT
            ON SOL.COD_EMPRESA = TIT.COD_EMPRESA
           AND SOL.NUM_MOVTO_CP = TIT.NUM_MOVTO_CP
          JOIN KIPREV.PA_STATUS ST
            ON ST.COD_STATUS = TIT.STATUS
           AND ST.TIP_STATUS = TIT.TIP_STATUS
          JOIN KIPREV.FO_DETALHE_CALCULO CALC
            ON CALC.COD_EMPRESA = SOL.COD_EMPRESA
           AND CALC.NUM_RESGATE = SOL.NUM_DOCUMENTO_ORIGEM
          JOIN KIPREV.FO_CUENTAS CUE
            ON CUE.COD_EMPRESA = SOL.COD_EMPRESA
           AND CUE.COD_CUENTA = SOL.COD_CUENTA
          JOIN KIPREV.ID_PERSONAS ID
            ON ID.COD_PERSONA = CUE.COD_CLIENTE
           AND ID.COD_TIPO_ID = ''1''
           AND ID.COD_PESSOA_TITULAR IS NULL
          JOIN KIPREV.FO_PRODUCTOS PROD
            ON PROD.COD_EMPRESA = CUE.COD_EMPRESA
           AND PROD.COD_PRODUCTO = CUE.COD_PRODUCTO
          JOIN KIPREV.SUBCAT_PRODUCTOS MOD
            ON MOD.COD_CAT_PRODUCTO = PROD.COD_CAT_PRODUTO
           AND MOD.COD_SUBCAT_PRODUCTO = PROD.COD_SUBCAT_PRODUTO
          JOIN KIPREV.FO_RESG_SOLIC RS
            ON RS.COD_EMPRESA = SOL.COD_EMPRESA
           AND RS.NUM_RESGATE = SOL.NUM_DOCUMENTO_ORIGEM
         WHERE SOL.COD_EMPRESA = ''500''
           AND SOL.COD_OPER = ''4'' -- PAGAMENTO DE RESGATE
           AND SOL.STATUS = ''3'' -- STATUS PAGO
           AND ID.NUM_ID <> NVL(SOL.CPF_CNPJ_FAVORECIDO, SOL.NUM_ID) -- SOMENTE PAGAR PARA
		 AND TO_CHAR(NVL(TIT.DATA_PGTO_EFETIVO, TIT.DATA_PGTO),''YYYYMM'') =  TO_CHAR(ADD_MONTHS(SYSDATE, -1), ''YYYYMM'')
         GROUP BY ID.NUM_ID,
                   MOD.DESCRIPCION,
                   RS.OPCAO_TRIBUTACAO_IRRF, -- US 30515 - TASK 30518
                  TO_CHAR(TRUNC(NVL(TIT.DATA_PGTO_EFETIVO, TIT.DATA_PGTO)), ''YYYY-MM-DD'') 
        ) I

') ) ,

------
GO
 
