IF OBJECT_ID('[dbo].[VW_PREVIDENCIA_ESTUDO]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PREVIDENCIA_ESTUDO];
GO
	CREATE	VIEW [dbo].[VW_PREVIDENCIA_ESTUDO] AS
---------------------------------------------------------------------------------------------------
--		1.	RECUPERA VENDAS DO KIPREV 
---------------------------------------------------------------------------------------------------
SELECT 
		'PREVIDENCIA KIP'			AS	SEGMENTO,
		V.DTA_EMISSAO				AS	DTA_VENDA, -- PROPOSTA,
		DTA_PAGAMENTO,		
		CONVERT(VARCHAR(6),A.COD_AGENCIA)				AS COD_AGENCIA,
		SC.NOM_SUBCANAL_VENDA		AS	NOM_CANAL_VENDA,		
		CASE WHEN SUBSTRING(PR.DES_PRODUTO_KIPREV, 1, CHARINDEX('-', PR.DES_PRODUTO_KIPREV)-2) = 'PREV INVESTIDOR CAIXA' 
			 THEN CONCAT(SUBSTRING(PR.DES_PRODUTO_KIPREV, 1, CHARINDEX('-', PR.DES_PRODUTO_KIPREV)-2), ' ', PR.DES_MODALIDADE)
			 ELSE SUBSTRING(PR.DES_PRODUTO_KIPREV, 1, CHARINDEX('-', PR.DES_PRODUTO_KIPREV)-2)
		END							AS	DES_PRODUTO,
		-------------------------------------------------------------------------------------------
		CONVERT(FLOAT, SUM(V.VLR_CONTR_INICIAL + ISNULL(V.VLR_VENDA,0)))	AS	VLR_VENDA_TOTAL,
		CONVERT(FLOAT, SUM(V.VLR_CONTR_INICIAL + ISNULL(V.VLR_VENDA,0)))	AS	VLR_PAGO ,
		COUNT(*)					AS	QTD_TOTAL
FROM	DMDB11..DM_066_VENDA AS V WITH (NOLOCK)
LEFT JOIN DMDB11..DM_012_CERTIFICADO C WITH (NOLOCK )--INDEX = DM012IP)  
ON		C.SUK_CERTIFICADO = V.SUK_CERT_PART
LEFT JOIN DMDB11..DM_040_COB_CONTRIBUICAO COB  WITH (NOLOCK )-- INDEX = DM040IP)
ON		COB.SUK_CONTRIBUICAO = V.SUK_CONTRIBUICAO
LEFT JOIN DMDB11..DM_036_PROPOSTA PROP WITH (NOLOCK )-- INDEX = DM036IP)
ON		PROP.SUK_PROPOSTA = V.SUK_PROPOSTA
LEFT JOIN DMDB11..DM_008_PRODUTO PR  WITH (NOLOCK)
ON		PR.SUK_PRODUTO = V.SUK_PRODUTO
LEFT JOIN DMDB11..DM_025_AGENCIA A  WITH (NOLOCK )-- INDEX = DM025IP)
ON		A.SUK_AGENCIA = V.SUK_AGENCIA
LEFT OUTER JOIN DMDB11..DM_101_SUBCANAL_VENDA AS SC
ON		LEFT(PROP.NUM_PROPOSTA, 1) = SC.COD_SUBCANAL_VENDA
WHERE	V.DTA_EMISSAO		BETWEEN '2021-01-01' AND GETDATE()
AND		ISNULL(C.SUK_CERTIFICADO,0) > 0
GROUP BY 
		V.DTA_EMISSAO, 
		DTA_PAGAMENTO,		
		CONVERT(VARCHAR(6),A.COD_AGENCIA),
		SC.NOM_SUBCANAL_VENDA,	
		CASE WHEN SUBSTRING(PR.DES_PRODUTO_KIPREV, 1, CHARINDEX('-', PR.DES_PRODUTO_KIPREV)-2) = 'PREV INVESTIDOR CAIXA' 
			 THEN CONCAT(SUBSTRING(PR.DES_PRODUTO_KIPREV, 1, CHARINDEX('-', PR.DES_PRODUTO_KIPREV)-2), ' ', PR.DES_MODALIDADE)
			 ELSE SUBSTRING(PR.DES_PRODUTO_KIPREV, 1, CHARINDEX('-', PR.DES_PRODUTO_KIPREV)-2)
		END 
---------------------------------------------------------------------------------------------------
--		2.	RECUPERA VENDAS DO AIC
---------------------------------------------------------------------------------------------------
UNION ALL
SELECT	
		'PREVIDENCIA AIC'		AS	SEGMENTO,
		A.DTA_VENDA				AS	DTA_VENDA, 
		CONVERT(DATE, CASE WHEN A.DTA_PAGAMENTO_MJUNMOV  IS NOT NULL
						   THEN	A.DTA_PAGAMENTO_MJUNMOV 
						   ELSE	A.DTA_PAGAMENTO_RAJADA 
					  END )		AS	DTA_PAGAMENTO,
		REPLACE(A.COD_AGENCIA,'-','') AS COD_AGENCIA,
		NOM_CANAL				AS	NOM_CANAL_VENDA,
		A.NOM_PRODUTO			AS	DES_PRODUTO,
		-------------------------------------------------------------------------------------------
		CONVERT(FLOAT, SUM(ISNULL(A.VLR_PREMIO,0)))					AS	VLR_VENDA_TOTAL,
		CONVERT(FLOAT, SUM(CASE	WHEN (IIF(CASE	WHEN DTA_VENDA <> CONVERT(DATE, GETDATE()) 
												THEN FLG_PAGO_MJUNMOV 
												ELSE FLG_PAGO_RAJADA 
												END = 'S', A.VLR_PREMIO, 0)) = 0  
								THEN	0
								ELSE	A.VLR_PREMIO 
								END))	AS	VLR_PAGO 
		,COUNT(*)		AS		QTD_TOTAL
FROM	DMDB41..DM_AIC_PROPOSTA  A WITH (NOLOCK)
