	CREATE VIEW [dbo].[VW_Previdencia_FGB] AS
---------------------------------------------------------------------------------------------------
--			SELEÇÃO DOS CERTIFICADOS
---------------------------------------------------------------------------------------------------
SELECT		CAST( CE.NUM_CERTIFICADO as bigint) NUM_CERTIFICADO  , 
			PE.NOM_PESSOA, 
			PE.NUM_CPF_CNPJ, 
			CE.DES_SIT_CERTIFICADO, 
			CE.DES_SUB_SITUACAO, 
			PR.COD_PRODUTO_KIPREV, 
			PR.DES_PRODUTO_KIPREV, 
			PR.DES_MODALIDADE, 
			DM_025_AGENCIA.COD_AGENCIA, 
			DM_025_AGENCIA.NOM_AGENCIA,
			VLR_RESERVA
FROM        DMDB11..DM_074_BASE_CARTEIRA AS BC  WITH (NOLOCK)
INNER JOIN  DMDB11..DM_012_CERTIFICADO AS CE   WITH (NOLOCK)
ON			BC.SUK_CERTIFICADO = CE.SUK_CERTIFICADO 
INNER JOIN  DMDB11..DM_001_PESSOA AS PE   WITH (NOLOCK)
ON			BC.SUK_PESSOA = PE.SUK_PESSOA 
INNER JOIN  DMDB11..DM_008_PRODUTO AS PR   WITH (NOLOCK)
ON			BC.SUK_PRODUTO = PR.SUK_PRODUTO 
INNER JOIN  DMDB11..DM_025_AGENCIA   WITH (NOLOCK)
ON			BC.SUK_AGENCIA = DM_025_AGENCIA.SUK_AGENCIA
WHERE   	PR.DES_MODALIDADE	=	'FGB' 
AND			CE.NUM_CERTIFICADO	>	0
AND			VLR_RESERVA > 100

GO
 
