IF OBJECT_ID('[dbo].[VW_PRODUTO_ELAS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PRODUTO_ELAS];
GO
---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_Produto_Elas
--					SQL14\DMCVP\DMDB42 
--
--		OBJETIVO:	CRIAR BASE DE CLIENTES MULHERES DOS SEGMENTOS DA CVP
--		
---------------------------------------------------------------------------------------------------
--		AUTOR	:	SILVIO J® / WILLIAN KOLODA
--		DATA	:	21/09/2022	
---------------------------------------------------------------------------------------------------
--DROP  VIEW VW_PRODUTO_ELAS
CREATE VIEW VW_PRODUTO_ELAS AS
---------------------------------------------------------------------------------------------------
--		BASE DE PRODUTOS
--------------------------------------------------------------------------------------------------
WITH	BASE_PRODUTOS  AS ( 
			select distinct COD_PRODUTO, NOM_PRODUTO_NEGOCIO as NOME_PRODUTO, 'VIDA' as SEGMENTO, '' as MODALIDADE
			from	DMDB05..DM_052_PRODUTO
			union all
			select distinct COD_PRODUTO, DES_PRODUTO as NOME_PRODUTO, 'PRESTAMISTA' as SEGMENTO, '' as MODALIDADE
			from	DMDB42..DM_DIM_PRODUTO
			union all
			select distinct COD_PRODUTO_KIPREV as COD_PRODUTO, DES_GRUPO_PRODUTO as NOME_PRODUTO, 'PREVIDENCIA' as SEGMENTO, DES_MODALIDADE as MODALIDADE
			from	DMDB11..DM_008_PRODUTO
		) 
--------------------------------------------------------------------------------------------------
--		BASE PARA DASHBOARD
--------------------------------------------------------------------------------------------------
SELECT DISTINCT	
		A.NOM_SEGMENTO,
		case
			when A.NOM_SEGMENTO = 'PRESTAMISTA' THEN 'PRESTAMISTA'
			when A.NOM_SEGMENTO = 'PREVIDENCIA' THEN 'PREVIDENCIA'
			when A.NOM_SEGMENTO = 'VIDA' and B.COD_PRODUTO IN (3701, 3704, 3705, 3709, 3716, 3721, 3724, 3725, 8103, 8104, 8105, 8112, 8113, 8115,
									8116, 8117, 8118, 8119, 8120, 8121, 8122, 8123, 8144, 8145, 8146, 8147, 8148, 8149,
									8150, 8201, 8203, 8214, 8234, 8246, 8511, 8512, 8521, 8522, 8523, 8524, 8525, 8526,
									8528, 8529) THEN 'AP'
			when A.NOM_SEGMENTO = 'VIDA' and B.COD_PRODUTO NOT IN (3701, 3704, 3705, 3709, 3716, 3721, 3724, 3725, 8103, 8104, 8105, 8112, 8113, 8115,
									8116, 8117, 8118, 8119, 8120, 8121, 8122, 8123, 8144, 8145, 8146, 8147, 8148, 8149,
									8150, 8201, 8203, 8214, 8234, 8246, 8511, 8512, 8521, 8522, 8523, 8524, 8525, 8526,
									8528, 8529) THEN 'VIDA'
		end as NOM_SEGMENTO_2,
		A.COD_TIPO_PESSOA,
		A.NUM_CPF_CNPJ,
		A.DES_CBO,
		A.DTA_NASCIMENTO,
		cast(FLOOR(DATEDIFF(DAY, A.DTA_NASCIMENTO, GETDATE()) / 365.25) as integer) as NUM_IDADE,
		A.VLR_RENDA_INDIVIDUAL,
		A.COD_UF,
		A.IND_GENERO,
		A.DES_ESTADO_CIVIL,
		case
			when A.DES_ESTADO_CIVIL in ('Não Informado','Inválido','Menor emancipado') or A.DES_ESTADO_CIVIL is null then 'Outros'
			when A.DES_ESTADO_CIVIL in ('União Estável','Casado c/ comunhão total de bens','Casado c/ comunhão parcial de bens',
										'Casado com separação de bens','Com União Estável','Casado com comunhão parcial de bens',
										'Casado com comunhão total de bens','Casado sem comunhão de bens') then 'Casado'
			when A.DES_ESTADO_CIVIL in ('Divorciado,judicialmente','Divorciado, judicialmente') then 'Divorciado'
			when A.DES_ESTADO_CIVIL in ('Viúvo') then 'Viuvo'
			else A.DES_ESTADO_CIVIL
		end as DES_ESTADO_CIVIL_GRUPO,
		A.NUM_CERTIFICADO,
		B.COD_STATUS_CONTRATO,
		B.COD_PRODUTO,
		C.NOME_PRODUTO,
		C.MODALIDADE,
		B.COD_AGENCIA,
		B.DES_FORMA_PAGAMENTO,
		B.IND_PERIODICIDADE_COBRANCA,
		B.DTA_INICIO_VIGENCIA,
		B.DTA_FIM_VIGENCIA,
		case
			when cast(FLOOR(DATEDIFF(DAY, A.DTA_NASCIMENTO, GETDATE()) / 365.25) as integer) <= 0 or cast(FLOOR(DATEDIFF(DAY, A.DTA_NASCIMENTO, GETDATE()) / 365.25) as integer) is null then '00. Não Informado'
			when cast(FLOOR(DATEDIFF(DAY, A.DTA_NASCIMENTO, GETDATE()) / 365.25) as integer) > 0 and cast(FLOOR(DATEDIFF(DAY, A.DTA_NASCIMENTO, GETDATE()) / 365.25) as integer) < 18 then '01. Menor 18'
			when cast(FLOOR(DATEDIFF(DAY, A.DTA_NASCIMENTO, GETDATE()) / 365.25) as intege
GO
 
IF OBJECT_ID('[dbo].[VW_PRODUTO_SIMPLIFICADA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PRODUTO_SIMPLIFICADA];
GO
create view [dbo].[VW_PRODUTO_SIMPLIFICADA] as

SELECT DISTINCT 
	2 AS [SUK_SEGMENTO],
	'VIDA' as NOM_SEGMENTO,
    P.COD_PRODUTO,
    CASE 
        WHEN SE.NOM_SEGMENTO_NEGOCIO = '? - Não informado'
        THEN MAX(P.NOM_PRODUTO)
		WHEN SE.NOM_SEGMENTO_NEGOCIO = 'TELEFONE'
		THEN 'Caixa Fácil'
        ELSE SE.NOM_SEGMENTO_NEGOCIO
    END AS NOM_PRODUTO,
	    CASE 
        WHEN SE.NOM_SEGMENTO_NEGOCIO = '? - Não informado'
        THEN MAX(P.NOM_PRODUTO)
		WHEN SE.NOM_SEGMENTO_NEGOCIO = 'TELEFONE'
		THEN 'Caixa Fácil'
        ELSE SE.NOM_SEGMENTO_NEGOCIO
    END AS NOM_PRODUTO_SIMPLIFICADO,
	NOM_PESSOA_PROD as TIPO_PRODUTO,
	NULL as DES_MODALIDADE,
	P.NOM_SEGMENTO_BP as NOME_BU,
	NULL as NUM_PROCESSO_SUSEP
FROM 
    DMDB05.dbo.DM_052_PRODUTO P
LEFT JOIN 
    DMDB05.dbo.DM_068_SEGMENTO_PRODUTO SE ON P.SUK_SEGMENTO_PRODUTO = SE.SUK_SEGMENTO_PRODUTO
 
GROUP BY 
    P.COD_PRODUTO,
    SE.NOM_SEGMENTO_NEGOCIO,
	NOM_PESSOA_PROD,
	P.NOM_SEGMENTO_BP
 
UNION ALL
 
SELECT DISTINCT
	1 AS [SUK_SEGMENTO],
	'PREVIDENCIA' as NOM_SEGMENTO,
	COD_PRODUTO_KIPREV as COD_PRODUTO,
	DES_PRODUTO_KIPREV AS NOM_PRODUTO,
	CASE 
		WHEN PATINDEX('%- [0-9]%', DES_PRODUTO_KIPREV) > 0 
		     OR PATINDEX('%-[0-9]%', DES_PRODUTO_KIPREV) > 0 
		THEN LEFT(DES_PRODUTO_KIPREV, CHARINDEX('-', DES_PRODUTO_KIPREV) - 1) 
		ELSE DES_PRODUTO_KIPREV 
	END AS NOM_PRODUTO_SIMPLIFICADO,
	CASE 
	WHEN 
	P.DES_TIPO_PRODUTO = 'INDIVIDUAL' THEN 'PF'
	WHEN 
	P.DES_TIPO_PRODUTO = 'EMPRESARIAL' THEN 'PJ'
	ELSE
	'NN'
	END AS TIPO_PRODUTO,
	DES_MODALIDADE,
	NULL AS NOME_BU,
	NULL as NUM_PROCESSO_SUSEP
FROM DMDB11.DBO.DM_008_PRODUTO P
 
 
UNION ALL
 
SELECT DISTINCT
	3 AS [SUK_SEGMENTO],
	'PRESTAMISTA' as NOM_SEGMENTO,
	COD_PRODUTO,
	DES_PRODUTO AS NOM_PRODUTO,
	DES_PRODUTO AS NOM_PRODUTO_SIMPLIFICADO,
	CASE 
	WHEN 
	IND_TIPO_PRODUTO = 'F' THEN 'PF'
	WHEN 
	IND_TIPO_PRODUTO = 'J' THEN 'PJ'
	ELSE
	'NN'
	END AS TIPO_PRODUTO,
	NULL as DES_MODALIDADE,
	DES_LINHA_PROD as NOME_BU,
	NUM_PROCESSO_SUSEP
 
FROM DMDB42.DBO.[DM_DIM_PRODUTO]
 

UNION ALL

SELECT 
	-1 AS [SUK_SEGMENTO],
	'NÃO SE APLICA' as NOM_SEGMENTO,
	-8 AS COD_PRODUTO,
	'TODOS OS PRODUTOS' AS NOM_PRODUTO,
	'TODOS OS PRODUTOS' AS NOM_PRODUTO_SIMPLIFICADO,
	NULL AS TIPO_PRODUTO,
	NULL as DES_MODALIDADE,
	NULL AS NOME_BU,
	NULL NUM_PROCESSO_SUSEP


GO
 
