CREATE view [dbo].[VW_PRODUTO_SIMPLIFICADA_RT] as

SELECT DISTINCT 
	2 AS [SUK_SEGMENTO],
	'VIDA' as NOM_SEGMENTO,
    P.COD_PRODUTO,
    CASE 
        WHEN SE.NOM_SEGMENTO_NEGOCIO = '? - Não informado'
        THEN MAX(P.NOM_PRODUTO)
		WHEN SE.NOM_SEGMENTO_NEGOCIO = 'TELEFONE'
		THEN 'Caixa Fácil'
        ELSE SE.NOM_SEGMENTO_NEGOCIO
    END AS NOM_PRODUTO,
	NOM_PESSOA_PROD as TIPO_PRODUTO,
	NULL as DES_MODALIDADE,
	P.NOM_SEGMENTO_BP as NOME_BU,
	NULL as NUM_PROCESSO_SUSEP
FROM 
    DMDB05.dbo.DM_052_PRODUTO P
LEFT JOIN 
    DMDB05.dbo.DM_068_SEGMENTO_PRODUTO SE ON P.SUK_SEGMENTO_PRODUTO = SE.SUK_SEGMENTO_PRODUTO
	WHERE P.COD_PRODUTO NOT IN (-9,-8,-7)
	AND STA_PROC_SUSEP = 'ATIVO'
 
 
GROUP BY 
    P.COD_PRODUTO,
    SE.NOM_SEGMENTO_NEGOCIO,
	NOM_PESSOA_PROD,
	P.NOM_SEGMENTO_BP
 
UNION ALL
 
SELECT DISTINCT
	1 AS [SUK_SEGMENTO],
	'PREVIDENCIA' as NOM_SEGMENTO,
	COD_PRODUTO_KIPREV as COD_PRODUTO,
	DES_PRODUTO_KIPREV AS NOM_PRODUTO,
	CASE 
	WHEN 
	P.DES_TIPO_PRODUTO = 'INDIVIDUAL' THEN 'PF'
	WHEN 
	P.DES_TIPO_PRODUTO = 'EMPRESARIAL' THEN 'PJ'
	ELSE
	'NN'
	END AS TIPO_PRODUTO,
	DES_MODALIDADE,
	NULL AS NOME_BU,
	NULL as NUM_PROCESSO_SUSEP
FROM DMDB11.DBO.DM_008_PRODUTO P
 
 
UNION ALL
 
SELECT DISTINCT
	3 AS [SUK_SEGMENTO],
	'PRESTAMISTA' as NOM_SEGMENTO,
	COD_PRODUTO,
	DES_PRODUTO AS NOM_PRODUTO,
	CASE 
	WHEN 
	IND_TIPO_PRODUTO = 'F' THEN 'PF'
	WHEN 
	IND_TIPO_PRODUTO = 'J' THEN 'PJ'
	ELSE
	'NN'
	END AS TIPO_PRODUTO,
	NULL as DES_MODALIDADE,
	DES_LINHA_PROD as NOME_BU,
	NUM_PROCESSO_SUSEP
 
FROM DMDB42.DBO.[DM_DIM_PRODUTO]
 

UNION ALL

SELECT 
	-1 AS [SUK_SEGMENTO],
	'NÃO SE APLICA' as NOM_SEGMENTO,
	-8 AS COD_PRODUTO,
	'TODOS OS PRODUTOS' AS NOM_PRODUTO,
	NULL AS TIPO_PRODUTO,
	NULL as DES_MODALIDADE,
	NULL AS NOME_BU,
	NULL NUM_PROCESSO_SUSEP
GO
 
