GO



CREATE View [dbo].[VW_PRODUTOS_CVP] AS 

	------------------------------------
	-- PRODUTOS PREVIDENCIA
	------------------------------------
	SELECT 
		'PREVIDENCIA' AS DES_SEGMENTO,
		COD_PRODUTO_KIPREV as COD_PRODUTO,
		DES_PRODUTO_KIPREV as DES_PRODUTO,
		IND_CONJUGADO,
		DES_MODALIDADE,
		93 AS COD_RAMO,
		NULL AS NOME_BU, 
		NULL as EMPRESA,
		NUM_GRUPO_RISCO as COD_CLASS_RISCO,
		DTA_CADASTRAMENTO as DTA_INSERCAO,
		NULL as DES_TIPO_SEGMENTO,
		CAST(COD_PRODUTO_KIPREV as VARCHAR(20)) as COD_PRODUTO_COMPLETO,
		prsu.SUSEP as COD_PRODUTO_SUSEP,
		pr.DES_TIPO_PRODUTO,
		cast(SIAS.COD_PRODUTO_SIAS as varchar(255)) as COD_PRODUTO_SIAS

	FROM DMDB11.dbo.DM_008_PRODUTO as pr
		LEFT JOIN (
			SELECT DISTINCT PRODUTO_KIPREV, SUSEP 
			FROM DMDB11.dbo.SB_P_201902_PRODUTO_SUSEP_PREV 
			where SUSEP is not null
		) AS prsu 
			ON prsu.PRODUTO_KIPREV = pr.COD_PRODUTO_KIPREV
		LEFT JOIN
		(	select	A.COD_PRODUTO,
					STRING_AGG(A.COD_PRODUTO_SIAS,',') AS COD_PRODUTO_SIAS
			FROM (
					select distinct 
							P.COD_PRODUTO_KIPREV AS COD_PRODUTO,
							PS.COD_PRODUTO_SIAS
					from	DMDB11.[dbo].[DM_074_BASE_CARTEIRA] V
							left join DMDB11.dbo.DM_008_PRODUTO P
								on P.SUK_PRODUTO = v.SUK_PRODUTO
							LEFT JOIN 
								(	SELECT	DISTINCT 
											COD_PRODUTO_SIAS, 
											suk_produto_sias
									from	 DMDB11.dbo.DM_009_PRODUTO_SIAS AS PS2
								) PS
								on PS.suk_produto_sias = V.suk_produto_sias
					where	P.COD_PRODUTO_KIPREV > 0
							and PS.COD_PRODUTO_SIAS > 0
			) A
			GROUP BY	A.COD_PRODUTO
		) SIAS
			on SIAS.COD_PRODUTO = pr.COD_PRODUTO_KIPREV

	WHERE pr.COD_PRODUTO_KIPREV NOT IN (-9,-8,-7)

	------------------------------------
	-- PRODUTOS PRESTAMISTA
	------------------------------------
	UNION ALL
	SELECT 'PRESTAMISTA' AS DES_SEGMENTO,
			COD_PRODUTO as COD_PRODUTO,
			DES_PRODUTO,
			null as IND_CONJUGADO,
			null as DES_MODALIDADE,
			NUM_RAMO as COD_RAMO,
			DES_LINHA_PROD as NOME_BU,
			IND_EMPRESA as EMPRESA,
			COD_CLASS_RISCO,
			DTA_CADASTRAMENTO as DTA_INSERCAO,
			null as DES_TIPO_SEGMENTO,
			cast(COD_PRODUTO as varchar(20)) as COD_PRODUTO_COMPLETO,
			NUM_PROCESSO_SUSEP as COD_PRODUTO_SUSEP,
			null as DES_TIPO_PRODUTO,
			cast(COD_PRODUTO as varchar(255)) as COD_PRODUTO_SIAS

	FROM DMDB42.DBO.DM_DIM_PRODUTO

	------------------------------------
	-- PRODUTOS VIDA
	------------------------------------
	UNION ALL
	SELECT DISTINCT 
			'VIDA' AS DES_SEGMENTO,
			a.COD_PRODUTO as COD_PRODUTO,
			a.NOM_PRODUTO as DES_PRODUTO,
			null as IND_CONJUGADO,
			null as DES_MODALIDADE,
			a.COD_RAMO,
			a.NOM_SEGMENTO_BP as NOME_BU,
			a.DES_EMPRESA as EMPRESA,
			a.COD_TP_CLASS_RISCO as COD_CLASS_RISCO,
			a.DTH_INSERCAO as DTA_INSERCAO,
			b.DES_TIPO_SEGMENTO as DES_TIPO_SEGMENTO,
			cast(CONCAT(a.COD_PRODUTO,'-',a.COD_SUBGRUPO) as varchar(20)) as COD_PRODUTO_COMPLETO,
			NUM_PROC_SUSEP as COD_PRODUTO_SUSEP,
			null as DES_TIPO_PRODUTO,
			cast(a.COD_PRODUTO as varchar(255)) as COD_PRODUTO_SIAS

	FROM	DMDB05.dbo.DM_052_PRODUTO a
			left join [DMDB05].[dbo].[DM_068_SEGMENTO_PRODUTO] b
				on b.SUK_SEGMENTO_PRODUTO = a.SUK_SEGMENTO_PRODUTO
	WHERE a.COD_PRODUTO NOT IN (-9,-8,-7)
	--and STA_PROC_SUSEP = 'ATIVO'
GO
 
