		) SIAS
			on SIAS.COD_PRODUTO = pr.COD_PRODUTO_KIPREV

	WHERE pr.COD_PRODUTO_KIPREV NOT IN (-9,-8,-7)

	------------------------------------
	-- PRODUTOS PRESTAMISTA
	------------------------------------
	UNION ALL
