IF OBJECT_ID('[dbo].[VW_PROPOSTAS_CVP]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PROPOSTAS_CVP];
GO





CREATE VIEW [dbo].[VW_PROPOSTAS_CVP] as (
select
 null as id,
 c.NUM_CERTIFICADO as 'numContrato',
 c.NUM_PROPOSTA as numProposta,
 trim(cast(a.NUM_CPF_CNPJ as varchar(255))) as  'codCpfCnpj',
 trim(cast(a.NOM_PESSOA as varchar(400))) as 'nomePessoa',
 trim(b.DES_PESSOA) as 'tipoRelacionamento',
   Case c.NOM_SEGMENTO 
  when 'VIDA' then 1
  when 'PREVIDENCIA' then 11
  when 'PRESTAMISTA' then 3 end as 'indContrato',
 trim(cast(null as varchar(20))) as sistema,
 trim(em.DES_EMAIL) as 'email',
 --trim(cast(tel.TIPO_TELEFONE as varchar(3))) 
 'TELEFONIA CELULAR'as 'tipoTelefone',
 trim(cast(tel.NUM_TELEFONE as varchar(10))) as 'telefone',
 trim(e.NOM_LOGRADOURO) as 'endereco',
 trim(e.NOM_BAIRRO) as 'bairro',
 trim(e.COD_UF) as 'uf',
 REPLACE(REPLACE(TRIM(e.NOM_CIDADE), CHAR(13), ''), CHAR(10), '') as 'cidade',
 trim(cast(e.COD_CEP as varchar(20))) as 'cep',
 c.COD_PRODUTO as codProduto,
 null as codAgenciaVenda,
 'PROPOSTA' as tipoContrato,
 null as canalVenda,
  'Proposta aceita' as situacaoProposta,
 'EMITIDA' as estadoProposta,
 p.DES_PRODUTO as nomeProduto,
 p.des_segmento as segmentoProduto,
 c.IND_PERIODICIDADE_COBRANCA as opcaoPagamento,
 c.DES_FORMA_PAGAMENTO as formaPagamento,
 null as numParcelasContratadas,
 null as numMatriculaVendedor,
 null as valorIof,
 null as numDiaVencimentoParcela,
 null as dataHoraRejeicaoProposta,
 c.DTA_INICIO_VIGENCIA as dataHoraIniVigencia,
 null as dataHoraFimVigencia,
 null as dataHoraVenda,
 null as valorProposta,
 null as desDiretoria,
 null as dataHoraReferencia,
 null as dataHoraAtualizacao,
 null as dataHoraAssinatura,
 dateadd(day,-1,c.DTA_INICIO_VIGENCIA) as dataHoraEmissaoProposta,
 1 as codGrupoEmpresa,
 'JV1' as desGrupoEmpresa,
 c.NUM_APOLICE as numApolice,
 c.NUM_CERTIFICADO as numTitulo,
 case when c.COD_STATUS_CONTRATO = 'A' Then 'Ativo'
 when c.COD_STATUS_CONTRATO = 'I' Then 'Inativo' end as situacaoContrato,
 c.NOM_SEGMENTO as desSegmento,
 null as codCota,
 null as numSorteCap,
 null as numeroIdentificadorPagamento,
 null as itemSegurado,
 NULL as codGrupo
 from 
 DM_CLIENTES_UNIFICADOS_CVP a
 inner join DM_CLIENTES_ENDERECO_CVP e
 on a.COD_PESSOA_UNIFICADA = e.COD_PESSOA_UNIFICADA
 and e.SEQ_ENDERECO = (select max(SEQ_ENDERECO) 
						from DM_CLIENTES_ENDERECO_CVP 
						where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)


 LEFT join dm_clientes_email_cvp em
 on a.COD_PESSOA_UNIFICADA = em.COD_PESSOA_UNIFICADA
 and em.seq_email = (select max(seq_email) 
					from dm_clientes_email_cvp 
					where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)

LEFT join DM_CLIENTES_TELEFONE_CVP tel
 on a.COD_PESSOA_UNIFICADA = tel.COD_PESSOA_UNIFICADA
 and tel.SEQ_TELEFONE = (select max(SEQ_TELEFONE) 
						from DM_CLIENTES_TELEFONE_CVP 
						where COD_PESSOA_UNIFICADA = a.COD_PESSOA_UNIFICADA)

 inner join DM_CLIENTES_CONTRATOS_CVP b
 on a.NUM_CPF_CNPJ=b.NUM_CPF_CNPJ
 inner join DM_CONTRATOS_CVP c
 on b.NOM_SEGMENTO = c.NOM_SEGMENTO
 and b.NUM_CERTIFICADO = c.NUM_CERTIFICADO
 inner join VW_PRODUTOS_CVP p
 on c.COD_PRODUTO = p.COD_PRODUTO
 and c.NOM_SEGMENTO = p.DES_SEGMENTO

)
GO
 
IF OBJECT_ID('[dbo].[VW_PROPOSTAS_RENOVACAO]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PROPOSTAS_RENOVACAO];
GO

 CREATE VIEW [dbo].[VW_PROPOSTAS_RENOVACAO] as (


---------------------------------------------
 -- PROPOSTAS EM SENSIBILIZACAO DE RENOVACAO
 -------------------------------------------- 

 SELECT A.COD_USUARIO, A.DATA_SOLICITACAO, A.IDE_SISTEMA, A.COD_RELATORIO,
       A.NUM_APOLICE, A.COD_SUBGRUPO, A.COD_PLANO, A.NUM_CERTIFICADO, 
       CASE E.SIT_REGISTRO
            WHEN '4' THEN 'CANC'  
       ELSE               ' '     
       END  AS SITCERTIF   
       , A.NUM_PARCELA,
       A.SIT_REGISTRO AS SITRELATO, A.TIMESTAMP, B.NUM_PROPOSTA_SIVPF, C.DATA_VENCIMENTO,
       D.SIT_REGISTRO AS SITPARCEL, (C.PREMIO_VG + C.PREMIO_AP) AS VL_PARCELA,
       D.DATA_MOVIMENTO AS DATA_PGTO,
       F.MATRIC_INDICADOR, G.AGE_RCAP AS PV, H.DATA_INIVIGENCIA
FROM   [SQL18\STAGING4].TDDB05_CDC.dbo.RELATORIOS A
INNER  JOIN   [SQL18\STAGING4].TDDB05_CDC.dbo.PROPOSTA_FIDELIZ B
  ON   B.NUM_SICOB = A.NUM_CERTIFICADO
LEFT JOIN 
       [SQL18\STAGING4].TDDB05_CDC.dbo.PARCELAS_VIDAZUL C
  ON   C.NUM_CERTIFICADO  = A.NUM_CERTIFICADO
 AND   C.NUM_PARCELA      = A.NUM_PARCELA  
LEFT JOIN
       [SQL18\STAGING4].TDDB05_CDC.dbo.HIST_CONT_PARCELVA D
  ON   D.NUM_CERTIFICADO  = A.NUM_CERTIFICADO
 AND   D.NUM_PARCELA      = A.NUM_PARCELA  
INNER  JOIN   [SQL18\STAGING4].TDDB05_CDC.dbo.PROPOSTAS_VA E
  ON   E.NUM_CERTIFICADO  = A.NUM_CERTIFICADO  
INNER  JOIN   [SQL18\STAGING4].TDDB05_CDC.dbo.PLANO_AGENCIAMENTO  F  
  ON   F.NUM_APOLICE  = E.NUM_APOLICE
 AND   F.COD_SUBGRUPO = E.COD_SUBGRUPO 
INNER  JOIN   [SQL18\STAGING4].TDDB05_CDC.dbo.ENDOSSOS  G
  ON   G.NUM_APOLICE  = E.NUM_APOLICE
 AND   G.NUM_ENDOSSO  = 0  
INNER  JOIN   [SQL18\STAGING4].TDDB05_CDC.dbo.PLANOS_VGAP  H
  ON   H.NUM_APOLICE  = A.NUM_APOLICE
 AND   H.COD_SUBGRUPO = A.COD_SUBGRUPO
 AND   H.COD_PLANO    = A.COD_PLANO
WHERE  A.COD_RELATORIO IN ('VGICA', 'VGIDA', 'VGIEA')
AND    A.IDE_SISTEMA      = 'VG'
AND    A.DATA_SOLICITACAO >= '2025-01-01'
AND    A.NUM_PARCELA      > 0
AND    A.NUM_CERTIFICADO  > 0
AND    E.NUM_CERTIFICADO = A.NUM_CERTIFICADO
)
 
GO
 
IF OBJECT_ID('[dbo].[VW_PRS_CARGA_DIARIA_TEMPO_EXECUCAO]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_PRS_CARGA_DIARIA_TEMPO_EXECUCAO];
GO
------------------------------------------
-- tempo execução carga
------------------------------------------
create view VW_PRS_CARGA_DIARIA_TEMPO_EXECUCAO AS 

select cast(DTH_CARGA as date) as DTH_CARGA, 
	cast (DATEDIFF(MINUTE,min(DTH_CARGA),max(DTH_CARGA)) / 60 as varchar) + ':' + cast (DATEDIFF(MINUTE,min(DTH_CARGA),max(DTH_CARGA)) - ((DATEDIFF(MINUTE,min(DTH_CARGA),max(DTH_CARGA)) / 60) * 60) as varchar) as TEMPO_EXECUCAO,
	cast(replace(cast (DATEDIFF(MINUTE,min(DTH_CARGA),max(DTH_CARGA)) / 60 as varchar) + ':' + cast (DATEDIFF(MINUTE,min(DTH_CARGA),max(DTH_CARGA)) - ((DATEDIFF(MINUTE,min(DTH_CARGA),max(DTH_CARGA)) / 60) * 60) as varchar),':','.') as decimal(5,2)) as TEMPO_INT
from DM_DOC_CONTROLE_CARGA
group by cast(DTH_CARGA as date)
GO
 
