 CREATE view [dbo].[VW_REVERSAO_PRESTAMISTA] as 
 (


select 
	   AG.COD_AGENCIA AS CodigoAgencia,
	   C.NUM_CONTRATO_SEGURO AS	NumeroContrato,
	   C.NUM_CPF_CNPJ AS CpfCnpjSegurado,
	   C.NOM_CLIENTE AS NomeSegurado,
	   C.DTA_LIMITE_REATIVACAO AS DataHoraLimiteReativacao,
	   PROD.COD_PRODUTO AS Produto, 
	   PROD.DES_PRODUTO AS NomeProduto, 
	   FINANC.VLR_RESTITUICAO AS ValorRest
from [DMDB42].[dbo].DM_ODS_PRS_CANCEL_REATIVACAO_HIST as C
JOIN [DMDB41].[dbo].[DM_AGENCIA] AS AG ON C.COD_AGENCIA = AG.COD_AGENCIA
JOIN [DMDB42].[dbo].DM_ODS_PRS_CONTRATOS_U AS CONT ON C.NUM_CONTRATO_SEGURO = CONT.NUM_CONTRATO_SEGURO
JOIN [DMDB42].[dbo].DM_DIM_PRODUTO AS PROD ON CONT.COD_PRODUTO = PROD.COD_PRODUTO
JOIN [DMDB42].[dbo].DM_ODS_PRS_CANCEL_U as FINANC ON C.NUM_CONTRATO_SEGURO = FINANC.NUM_CONTRATO_SEGURO
where IND_REATIVACAO IS NULL
AND C.DTA_LIMITE_REATIVACAO in ( SELECT    top (6) DTA_DATA ---- 6 DIAS UTEIS 
                    from    [DMDB42].[dbo].[DM_DIM_TEMPO]-- dim tempo
                    where    DTA_DATA >= cast(getdate() as date)
                            and STA_DIA_UTIL = 'S'
						---	and c.NUM_CONTRATO_SEGURO = 31741600
                    order by 1
        ) 


)
GO
 
