CREATE VIEW [dbo].[VW_SF_MKT_AGENCIA]  AS  
---------------------------------------------------------------------
--		AGENCIA / SEV / SR
---------------------------------------------------------------------
WITH SEV AS (SELECT A2.UN_SEV AS UN_SEV,
                    MAX(A2.MATR_CONSULTOR) AS MATR_CONSULTOR,
					MAX(A2.SUB_GERENCIA) AS SUB_GERENCIA,
					MAX(A2.GERENCIA) AS GERENCIA,
					MAX(A2.NOM_GERENTE) AS NOM_GERENTE,
					MAX(A2.DES_EMAIL_GERENTE) AS DES_EMAIL_GERENTE
			FROM DMDB41.dbo.TB_ESTRUTURA A2 WITH(NOLOCK) --RITM0040231 FROM [DMDB47].[dbo].[01_VW_ESTRUTURA_CAIXA_TDV_ARQ_AG_ENAR4] A2
			WHERE A2.TP_UNIDADE_2 = 'SEV'
			GROUP BY A2.UN_SEV),

SR AS (SELECT A2.UN_SR AS UN_SR,
              MAX(A2.MATR_CONSULTOR) AS MATR_CONSULTOR,
              MAX(A2.SUB_GERENCIA) AS SUB_GERENCIA,
              MAX(A2.GERENCIA) AS GERENCIA,
              MAX(A2.NOM_GERENTE) AS NOM_GERENTE,
              MAX(A2.DES_EMAIL_GERENTE) AS DES_EMAIL_GERENTE
       FROM DMDB41.dbo.TB_ESTRUTURA A2 WITH(NOLOCK) --RITM0040231 FROM [DMDB47].[dbo].[01_VW_ESTRUTURA_CAIXA_TDV_ARQ_AG_ENAR4] A2 --RITM0040231
       WHERE A2.TP_UNIDADE = 'PV'
       and A2.GERENCIA = (SELECT MAX(A.GERENCIA) FROM DMDB41.dbo.TB_ESTRUTURA A WITH(NOLOCK) WHERE A.UN_SR = A2.UN_SR) --RITM0040231: PARA PREVALECER O CONSULTOR VAREJO NOS CASOS COM MAIS DE UM CONSULTOR POR SR
       --and a2.UN_SR = 2541
       GROUP BY A2.UN_SR)

SELECT CASE WHEN S.UN_SEV IS NOT NULL THEN 'SEV'
            WHEN SR.UN_SR IS NOT NULL THEN 'SR'
			ELSE TP_UNIDADE 
			END AS "Type" --[TP_UNIDADE]          AS "Type"
      ,NU_UNIDADE                    AS "COD_UNIDADE__c"
      ,NO_UNIDADE                    AS "Name"
      ,ISNULL(CONVERT(VARCHAR(5),A.NU_PORTE),'')               AS "PORTE__c"
      ,ISNULL(CONVERT(VARCHAR(5),A.UN_SEV),'')                        AS "COD_SEV_TEXT__c"
      ,ISNULL(CONVERT(VARCHAR(5),A.UN_SR),'')                       AS "COD_SR_TEXT__c"
      , ''				              AS "SEP__c"
      ,''					          AS "COD_SN__c"
      ,''						      AS "NOME_SN__c"

      --,ISNULL(CONVERT(VARCHAR(5),UN_SN),'')                         AS "COD_SN__c"
      --,ISNULL(NOMe_SN,'')                         AS "NOME_SN__c"
     -- ,ISNULL(CONVERT(VARCHAR(5),COD_VP),'')                         AS "COD_VP__c"
     -- ,ISNULL(NOM_VP,'')                         AS "NOME_VP__c"

      , ''										AS "COD_VP__c"
      , ''										AS "NOME_VP__c"

      , ''										AS "TIPO_PV__C"
      --,CASE WHEN S.UN_SEV IS NOT NULL THEN ISNULL(CONVERT(VARCHAR(15), S.MATR_CONSULTOR),'') ELSE ISNULL(CONVERT(VARCHAR(15), A.MATR_CONSULTOR),'') END AS "Matricula_Consultor_Text__c" --06/01/2025 Alterado a pedido do Rane para recuperar os dados do consultor das SEVs
	  ,CASE WHEN S.UN_SEV IS NOT NULL THEN ISNULL(CONVERT(VARCHAR(15), S.MATR_CONSULTOR),'')
	        WHEN SR.UN_SR IS NOT NULL THEN ISNULL(CONVERT(VARCHAR(15), SR.MATR_CONSULTOR),'')
			ELSE ISNULL(CONVERT(VARCHAR(15), A.MATR_CONSULTOR),'') 
			END AS "Matricula_Consultor_Text__c" --06/01/2025 Alterado a pedido do Rane para recuperar os dados do consultor das SEVs

	  --,ISNULL(CONVERT(VARCHAR(15), MATR_CONSULTOR),'')         AS "Matricula_Consultor_Text__c"
      
	  ,CASE WHEN S.UN_SEV IS NOT NULL THEN ISNULL(S.SUB_GERENCIA,'')
	        WHEN SR.UN_SR IS NOT NULL THEN ISNULL(SR.SUB_GERENCIA,'')
			ELSE ISNULL(A.SUB_GERENCIA,'') 
			END AS "Sub_gerencia__c" --06/01/2025 Alterado a pedido do Rane para recuperar a subgerência das SEVs

	  ,CASE WHEN S.UN_SEV IS NOT NULL THEN ISNULL(S.GERENCIA,'')
	        WHEN SR.UN_SR IS NOT NULL THEN ISNULL(SR.GERENCIA,'')
			ELSE ISNULL(A.GERENCIA,'') 
			END AS "GERENCIA__c" --06/01/2025 Alterado a pedido do Rane para recuperar a gerência das SEVs

	  --,ISNULL(A.SUB_GERENCIA,'')                AS "Sub_gerencia__c"
      --,ISNULL( GERENCIA,'')						AS "GERENCIA__c"
      
	  ,CASE WHEN S.UN_SEV IS NOT NULL THEN ISNULL(S.NOM_GERENTE,'')
	  
GO
 
