CREATE VIEW [dbo].[VW_SF_MKT_DIM_CONTRATOS] AS


----------------------------------------------------- VIEW VW_SF_MKT_DIM_CONTRATOS --------------------------------------------------------
WITH

--dta_max as (
--			select 
--				cc.NUM_CERTIFICADO,
--				cc.NOM_SEGMENTO,
--				MAX(coalesce(cc.dth_carga_atualizacao,cc.dth_carga)) as DTH_MAX_CARGA
--			from 
--				DM_CLIENTES_CONTRATOS_CVP as cc 
--				LEFT JOIN DM_CONTRATOS_CVP													as C
--				ON cc.NUM_CERTIFICADO = C.NUM_CERTIFICADO 
--				AND cc.NOM_SEGMENTO = C.NOM_SEGMENTO
--			where 
--				cc.cod_pessoa = 1 
--				AND cc.COD_TIPO_PESSOA = 'F'
--				AND C.COD_STATUS_CONTRATO = 'A'
--				AND C.COD_PRODUTO IN ( 8521 , 8528, 8529 )
--				--AND NUM_CERTIFICADO = 123896

--group by 
--				cc.NUM_CERTIFICADO,
--				cc.NOM_SEGMENTO

--			),

TABELA_FINAL_CONTRATO as (
							SELECT 
								cc.COD_TIPO_PESSOA as TIPO_PESSOA,
								cc.NUM_CPF_CNPJ AS NUM_CPF_CNPJ,
								LEFT( cc.NOM_PESSOA, CHARINDEX (' ', cc.NOM_PESSOA + ' ') - 1 ) as NOME,
								cc.NOM_PESSOA,
								cc.NOM_SOCIAL,
								FORMAT(cc.DTA_NASCIMENTO ,'d','en-gb') as DT_NASCIMENTO,
								cc.IND_GENERO AS SEXO,
								cc.DES_ESTADO_CIVIL,
								cc.NUM_CERTIFICADO,
								cc.NOM_SEGMENTO,
								cc.DTH_CARGA as DTA_CARGA_CLIENTES_CONTRATO,
								cc.DTH_CARGA_ATUALIZACAO as DTA_CARGA_ATUALIZACAO_CLIENTES_CONTRATO,
								CONCAT( cc.NOM_SEGMENTO, ' - ', cc.NUM_CERTIFICADO ) as CHAVE_UNICA__c,
								ROW_NUMBER() OVER (PARTITION BY cc.NUM_CERTIFICADO ORDER BY COALESCE(cc.DTH_CARGA_ATUALIZACAO, cc.DTH_CARGA) DESC) AS RN
								
							FROM 
								DM_CLIENTES_CONTRATOS_CVP cc
								LEFT JOIN DM_CONTRATOS_CVP																						as C
								ON cc.NUM_CERTIFICADO = C.NUM_CERTIFICADO 
								AND cc.NOM_SEGMENTO = C.NOM_SEGMENTO
								--left join dta_max 
								--on cc.NUM_CERTIFICADO = dta_max.NUM_CERTIFICADO AND cc.NOM_SEGMENTO = dta_max.NOM_SEGMENTO
							WHERE 
								COD_PESSOA = 1
								AND cc.COD_TIPO_PESSOA = 'F'
								AND C.COD_STATUS_CONTRATO = 'A'
								AND cc.IND_CARGA <> 'D'
								--AND YEAR(C.DTA_EMISSAO_CONTRATO) >= 2020 AND YEAR(C.DTA_EMISSAO_CONTRATO) <= 2024
								AND cc.NUM_CPF_CNPJ IS NOT NULL
								--AND c.NUM_CERTIFICADO = 82042460007141
								--and coalesce (cc.DTH_CARGA_ATUALIZACAO, cc.DTH_CARGA) = DTH_MAX_CARGA
								--AND C.COD_PRODUTO IN ( 8521 , 8528, 8529 )
							),

-------------------------------- BUSCAR DADOS DO ÚLTIMO CONTRATO ----------------------------------------
REGISTROS_PESSOAIS AS (
					SELECT
						CLI1.COD_TIPO_PESSOA as TIPO_PESSOA,
						CLI1.NUM_CPF_CNPJ AS NUM_CPF_CNPJ,
						LEFT( CLI1.NOM_PESSOA, CHARINDEX (' ', CLI1.NOM_PESSOA + ' ') - 1 ) as NOME,
						CLI1.NOM_PESSOA,
						CLI1.NOM_SOCIAL,
						FORMAT(cli1.DTA_NASCIMENTO ,'d','en-gb') as DT_NASCIMENTO,
						CLI1.IND_GENERO AS SEXO,
						CLI1.DES_ESTADO_CIVIL,
						CLI1.NUM_CERTIFICADO,
						CLI1.NOM_SEGMENTO,
						DTH_CARGA_ATUALIZACAO
				
					FROM DM_CLIENTES_CONTRATOS_CVP as cli1 WITH (NOLOCK)
					WHERE 
						DTH_CARGA_ATUALIZACAO IN (
									SELECT MAX(DTH_CARGA_ATUALIZACAO) 
									FROM DM_CLIENTES_CONTRATOS_CVP cli2 WITH (NOLOCK)
									where cli1.num_cpf_cnpj = cli2.num_cpf_cnpj AND CLI2.COD_PESSOA = '1' --Somente Titular
									)

						),

---------------------------------------------- RISCO DECLINADO - PREV -----------------------------------------

RISCO_DECLINADO as (
					SELECT
						'PREVIDENCIA' as NOM_SEGMENTO,
						NUM_CERTIFICADO,
						CASE WHEN
							DATEDIFF (DAY, CAST(DTA_PROPOSTA as date), CAST(DTA_RECUSA as date)) >= 30 
							THEN -2 
							ELSE -1 
							END AS FLAG_CUIDADO_EXTRA
 
					FROM 
						[DMDB11].[DBO].SB_P_202406_BASE_PROPOSTAS_ANALISE_DECLINIO_DIARIO A
							INNER JOIN [DMDB11].[DBO].DM_040_COB_CONTRIBUICAO B
								ON A.COD_CONTRIB = B.COD_CONTRIBUICAO AND NAT_COBERTURA = 'RISCO'
					WHER
GO
 
