CREATE VIEW dbo.VW_SF_MKT_DIM_CONTRATOS_GESUC
AS

SELECT 
	  B.NUM_CPF_CNPJ																	AS CPF
	 ,B.NOM_PESSOA																		AS NOME_TITULAR
	 ,B.NOM_SOCIAL																		AS NOME_SOCIAL
	 ,A.NUM_CERTIFICADO																	AS NUM_CERTIFICADO
	 ,A.NUM_APOLICE																		AS NUM_APOLICE
	 ,CONCAT('55', B.NUM_DDD_CELULAR , B.NUM_CELULAR )                                  AS CELULAR 
	 ,CONCAT('55', B.NUM_DDD_TELEFONE, B.NUM_TELEFONE)                                  AS TELEFONE
	 ,B.DES_EMAIL																		AS EMAIL
	 ,A.COD_STATUS_CONTRATO																AS STATUS_CONTRATO
	 ,A.NOM_SEGMENTO																	AS SEGMENTO_PLANO
	 ,A.COD_PRODUTO																		AS COD_PRODUTO
	 ,A.COD_PRODUTO_COMPLETO															AS COD_PRODUTO_COMPLETO
	 ,C.NOM_PRODUTO																		AS NOM_PRODUTO
	 ,C.AGRUPADOR_FINAL																	AS NOM_PRODUTO_AGREGADO
	 ,E.NUM_PROCESSO_SUSEP																AS PROC_SUSEP
	 ,A.VLR_PREMIO																		AS VLR_PREMIO
	 ,A.VLR_PMBAC																		AS VLR_RESERVA
	 ,A.VLR_IS																			AS VLR_IS
	 ,F2.VLR_IS_PROPOSTA																AS VLR_IS_INICIAL
	 ,A.VLR_ATUAL_CONTRIBUICAO															AS VLR_CONTRIBUICAO
	 ,CASE WHEN		A.NOM_SEGMENTO <> 'VIDA '
		   THEN		A.NOM_SEGMENTO 
		   ELSE		A.IND_PERIODICIDADE_COBRANCA
	  END																				AS IND_PERIODICIDADE_COBRANCA
	 ,A.DES_FORMA_PAGAMENTO																AS DES_FORMA_PAGAMENTO
	 ,A.DES_CANAL_VENDA																	AS DES_CANAL_VENDA
	 ,A.DTA_INICIO_VIGENCIA																AS DTA_INICIO_VIGENCIA
	 ,A.DTA_FIM_VIGENCIA																AS DTA_FIM_VIGENCIA
	 ,A.DTA_CANCELAMENTO																AS DTA_CANCELAMENTO			
	 ,A.DTA_ENCERRAMENTO																AS DTA_ENCERRAMENTO	
	 ,H2.DES_ASSISTENCIA																AS CATEGORIA_PLANO
	 ,D.DES_MODALIDADE																	AS MODALIDADE
	 ,A.COD_REGIME_TRIBUTACAO															AS REGIME_TRIBUTARIO
	 ,CASE WHEN		G.DTA_OPCAO_TRIBUTACAO_IRRF IS NOT NULL 
		   THEN		1
		   ELSE		0
	  END																				AS FLAG_TROCOU_TRIBUTACAO
FROM DMDB41..DM_CONTRATOS_CVP					AS A
INNER JOIN DMDB41..DM_CLIENTES_CONTRATOS_CVP	AS B				-- N DUPLICA
 ON
		A.NUM_CERTIFICADO	=	B.NUM_CERTIFICADO
	AND A.NOM_SEGMENTO		=	B.NOM_SEGMENTO
	AND	A.IND_CARGA		   <>  'D'
	AND	B.IND_CARGA		   <>  'D'
	AND B.COD_PESSOA		=	1
	AND (	A.COD_STATUS_CONTRATO	 =	'A'
		 OR A.DTA_ENCERRAMENTO		>= '2025-01-01'
		)						-- FILTRO ADICIONAL: SÓ CONTRATOS PÓS 2025
LEFT JOIN WORK_GEPLAC..WK_PRODUTOS_2			AS C				-- N DUPLICA
 ON
		A.COD_PRODUTO		=	C.COD_PRODUTO
LEFT JOIN DMDB11..[DM_008_PRODUTO]				AS D				-- N DUPLICA
 ON
		A.COD_PRODUTO		=	D.COD_PRODUTO_KIPREV				
LEFT JOIN DMDB41..VW_PRODUTO_SIMPLIFICADA		AS E				-- RESOLVIDO
 ON
		A.COD_PRODUTO		=	E.COD_PRODUTO
	AND A.IND_CARGA		   <>	'D'
	AND E.NUM_PROCESSO_SUSEP IS NOT NULL -- SOLUÇÃO PARA DUPLICAÇÕES
LEFT JOIN DMDB05..DM_066_CONTRATO_VIDA			AS F1				-- N DUPLICA
 ON
		A.IND_CARGA		  <>	'D'
	AND A.NOM_SEGMENTO		=	'VIDA'
	AND A.NUM_CERTIFICADO	=	F1.NUM_CERTIFICADO
LEFT JOIN DMDB05.dbo.DM_003_PROPOSTA			AS F2				-- N DUPLICA
 ON
		F1.SUK_CONTRATO_VIDA	=	F2.SUK_CONTRATO_VIDA
LEFT JOIN DMDB11.[dbo].[DM_012_CERTIFICADO]		AS G				-- N DUPLICA
 ON
		A.IND_CARGA		   <>	'D'
	AND A.NOM_SEGMENTO		=	'PREVIDENCIA'
	AND A.NUM_CERTIFICADO	=	G.NUM_CERTIFICADO
LEFT JOIN (
	SELECT 
		   SUK_CONTRATO_VIDA
		  ,SUK_PRODUTO
		  ,ROW_NUMBER() OVER (PARTITION BY SUK_CONTRATO_VIDA ORDER BY DTH_ATUALIZACAO DESC) AS RN
	FROM DMDB05..DM_005_CONTRATO
	)											AS H1				-- BUXA
 ON
		F1.SUK_CONTRATO_VIDA =	H1.SUK_CONTRATO_VIDA
	AND H1.RN = 1
LEFT JOIN [DMDB05].[dbo].[DM_052_PRODUTO]		AS H2
 ON
		DES_ASSISTENCIA		IS NOT NULL
	AND H1.SUK_PRODUTO		=	H2.SUK_PRODUTO
GO
 
