CREATE VIEW [dbo].[VW_SF_MKT_DIM_PESSOAS] AS
----------------------------------------------------- VIEW VW_SF_MKT_DIM_PESSOAS --------------------------------------------------------

WITH

BUSCA_COD_PESSOA AS (
					SELECT  
						cli1.COD_PESSOA_UNIFICADA											as COD_PESSOA,
						cli1.COD_TIPO_PESSOA												as TIPO_PESSOA,
						cli1.NUM_CPF_CNPJ													as NUM_CPF_CNPJ,
						cli1.PRIMEIRO_NOME													as NOME,
						cli1.NOM_PESSOA														as NOME_SOBRENOME,
						cli1.NOM_SOCIAL														as NOME_SOCIAL,
						FORMAT(cli1.DTA_NASCIMENTO ,'d','en-gb')							as DT_NASCIMENTO,
						cli1.IND_GENERO														as SEXO,
						cli1.DES_ESTADO_CIVIL												as DESC_ESTADO_CIVIL
							
					FROM 
						DM_CLIENTES_UNIFICADOS_CVP											as cli1 WITH (NOLOCK)
					WHERE 
						DTA_ATUALIZACAO IN (
											SELECT MAX(DTA_ATUALIZACAO)
											FROM DM_CLIENTES_UNIFICADOS_CVP					as cli2 WITH (NOLOCK)
											WHERE cli1.num_cpf_cnpj = cli2.num_cpf_cnpj
											) 
						AND COD_TIPO_PESSOA = 'F'
					),

-------------------------------- BUSCAR DADOS DO ÚLTIMO CONTRATO - CORRETA ----------------------------------------
dta_max AS (
			SELECT 
				cc.NUM_CPF_CNPJ, 
				MAX(COALESCE(cc.DTH_CARGA_ATUALIZACAO, cc.DTH_CARGA))						as DTH_MAX_CARGA
			FROM 
				DM_CLIENTES_CONTRATOS_CVP													as cc WITH (NOLOCK)
				LEFT JOIN DM_CONTRATOS_CVP													as C WITH (NOLOCK)
				ON cc.NUM_CERTIFICADO = C.NUM_CERTIFICADO 
				AND cc.NOM_SEGMENTO = C.NOM_SEGMENTO
			WHERE 
				cc.COD_PESSOA = 1 
				AND cc.COD_TIPO_PESSOA = 'F'
				AND C.COD_STATUS_CONTRATO = 'A'
				AND cc.IND_CARGA <> 'D'
				--AND C.COD_PRODUTO IN ( 8521 , 8528, 8529 )
			GROUP BY 
				NUM_CPF_CNPJ
),

vigencia_max AS (
    SELECT 
        cc.NUM_CPF_CNPJ, 
        MAX(C.DTA_INICIO_VIGENCIA) AS DTA_INICIO_VIGENCIA
    FROM 
        DM_CLIENTES_CONTRATOS_CVP AS cc WITH (NOLOCK)
        LEFT JOIN DM_CONTRATOS_CVP AS C WITH (NOLOCK)
        ON cc.NUM_CERTIFICADO = C.NUM_CERTIFICADO 
        AND cc.NOM_SEGMENTO = C.NOM_SEGMENTO
    WHERE 
        cc.COD_PESSOA = 1 
        AND cc.COD_TIPO_PESSOA = 'F'
        AND C.COD_STATUS_CONTRATO = 'A'
        AND cc.IND_CARGA <> 'D'
        --AND C.COD_PRODUTO IN (8521, 8528, 8529)
    GROUP BY 
        cc.NUM_CPF_CNPJ
),

TABELA_FINAL_CONTRATO AS (
						SELECT 
							cc.COD_TIPO_PESSOA																								AS TIPO_PESSOA,
							cc.NUM_CPF_CNPJ																									AS NUM_CPF_CNPJ,
							LEFT(cc.NOM_PESSOA, CHARINDEX(' ', cc.NOM_PESSOA + ' ') - 1)													AS NOME,
							cc.NOM_PESSOA,
							cc.NOM_SOCIAL,
							FORMAT(cc.DTA_NASCIMENTO, 'd', 'en-gb')																			AS DT_NASCIMENTO,
							cc.IND_GENERO																									AS SEXO,
							cc.COD_UF,
							cc.NOM_CIDADE,
							cc.DES_ESTADO_CIVIL,
							cc.NUM_CERTIFICADO,
							cc.NOM_SEGMENTO,
							cc.COD_SEGMENTO_CAIXA,
							cc.IND_PEP,
							cc.DTH_CARGA																									AS DTA_CARGA_CLIENTES_CONTRATO,
							cc.DTH_CARGA_ATUALIZACAO																						AS DTA_CARGA_ATUALIZACAO_CLIENTES_CONTRATO,
							vigencia_max.DTA_INICIO_VIGENCIA 																	    		AS DTA_INICIO_VIGENCIA_CONTRATO,
							c.DES_CANAL_VENDA_COMERCIAL																						AS DES_CANAL_VENDA_COMERCIAL,
							ROW_NUMBER() OVER (PARTITION BY cc.NUM_CPF_CNPJ ORDER BY COALESCE(cc.DTH_CARGA, cc.DTH_CARGA_ATUALIZACAO) DESC) AS RN
						FROM 
							DM_CLIENTES_CONTRATOS_CVP																						as cc WITH (NOLOCK)
							LEFT JOIN DM_CONTRATOS_CVP																						as C WITH (NOLOCK)
							ON cc.NUM_CERTIFICADO = C.NUM_CERTIFICADO 
							AND cc.NOM_SEGMENTO = C.NOM_SEGMENTO
							LEFT JOIN dta_max 
							ON cc.NUM_CPF_CNPJ = dta_max.NUM_CPF_CNPJ 
							AND cc.COD_TIPO_PESSOA = 'F'
							LEFT JOIN vigencia_max                                                                                           
							ON cc.NUM_CPF_C
GO
 
IF OBJECT_ID('[dbo].[VW_SF_MKT_DIM_PESSOAS_GESUC]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_SF_MKT_DIM_PESSOAS_GESUC];
GO

CREATE VIEW [dbo].[VW_SF_MKT_DIM_PESSOAS_GESUC]
AS
--DROP TABLE IF EXISTS WORK_GEPLAC.coec_raw.base_clientes_geral_igor_2
--GO

WITH 

 CLIENTES_BASE AS (
     SELECT 
           A.NUM_CERTIFICADO                                                                                            AS NUM_CERTIFICADO                         -- GRANULARIDADE: CERTIFICADO
          ,A.NUM_CPF_CNPJ                                                                                               AS NUM_CPF_CNPJ                            -- GRANULARIDADE: CLIENTE
          ,A.NOM_PESSOA                                                                                                 AS NOME_CLIENTE                            -- GRANULARIDADE: CLIENTE
          ,A.NOM_SOCIAL                                                                                                 AS NOME_SOCIAL                             -- GRANULARIDADE: CLIENTE
          ,A.IND_GENERO                                                                                                 AS GENERO                                  -- GRANULARIDADE: CLIENTE
          ,A.COD_TIPO_PESSOA                                                                                            AS COD_TIPO_PESSOA                         -- GRANULARIDADE: CLIENTE
          ,A.DES_ESTADO_CIVIL                                                                                           AS ESTADO_CIVIL                            -- GRANULARIDADE: CLIENTE
          ,A.IND_PERMITE_CONTATO_EMAIL                                                                                  AS FLAG_AUTORIZA_CONTATO_EMAIL             -- GRANULARIDADE: CLIENTE
          ,A.IND_RECEBER_EMAIL                                                                                          AS FLAG_AUTORIZA_CONTATO_EMAIL_2           -- GRANULARIDADE: CLIENTE
          ,A.IND_PERMITE_CONTATO_WHATSAPP                                                                               AS FLAG_AUTORIZA_CONTATO_WHATSAPP          -- GRANULARIDADE: CLIENTE
          ,CONCAT('55', A.NUM_DDD_CELULAR,  A.NUM_CELULAR )                                                             AS CELULAR                                 -- GRANULARIDADE: CLIENTE
          ,CONCAT('55', A.NUM_DDD_TELEFONE, A.NUM_TELEFONE)                                                             AS TELEFONE                                -- GRANULARIDADE: CLIENTE
          ,A.DES_EMAIL                                                                                                  AS EMAIL                                   -- GRANULARIDADE: CLIENTE
          ,B.COD_AGENCIA                                                                                                AS COD_AGENCIA                             -- GRANULARIDADE: CERTIFICADO
          ,C.SEGMENTO                                                                                                   AS SEGMENTO_CAIXA                          -- GRANULARIDADE: CLIENTE
          ,CASE                          
              WHEN EXISTS (
                  SELECT 1
                  FROM DMDB41..DM_CLIENTES_CONTRATOS_CVP AS A2
                  WHERE 
                        A2.NUM_CERTIFICADO = A.NUM_CERTIFICADO
                    AND A2.NOM_SEGMENTO    = A.NOM_SEGMENTO
                    AND A2.COD_PESSOA     = 4
                    AND A2.IND_CARGA     <> 'D'
                    )          
              THEN '1'
              ELSE '0'
           END                                                                                                          AS FLAG_BENEFICIARIO                       -- GRANULARIDADE: CLIENTE
          ,C.PERSONA                                                                                                    AS PERSONA                                 -- GRANULARIDADE: CLIENTE
          ,A.DTA_NASCIMENTO                                                                
GO
 
IF OBJECT_ID('[dbo].[VW_SF_MKT_DIM_PESSOAS_RITM0064948]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_SF_MKT_DIM_PESSOAS_RITM0064948];
GO

CREATE VIEW [dbo].[VW_SF_MKT_DIM_PESSOAS_RITM0064948]
AS
WITH

BUSCA_COD_PESSOA AS (
					SELECT  
						cli1.COD_PESSOA_UNIFICADA											as COD_PESSOA,
						cli1.COD_TIPO_PESSOA												as TIPO_PESSOA,
						cli1.NUM_CPF_CNPJ													as NUM_CPF_CNPJ,
						cli1.PRIMEIRO_NOME													as NOME,
						cli1.NOM_PESSOA														as NOME_SOBRENOME,
						cli1.NOM_SOCIAL														as NOME_SOCIAL,
						FORMAT(cli1.DTA_NASCIMENTO ,'d','en-gb')							as DT_NASCIMENTO,
						cli1.IND_GENERO														as SEXO,
						cli1.DES_ESTADO_CIVIL												as DESC_ESTADO_CIVIL,
						cli1.PERSONA
							
					FROM 
						DM_CLIENTES_UNIFICADOS_CVP											as cli1 WITH (NOLOCK)
					WHERE 
						DTA_ATUALIZACAO IN (
											SELECT MAX(DTA_ATUALIZACAO)
											FROM DM_CLIENTES_UNIFICADOS_CVP					as cli2 WITH (NOLOCK)
											WHERE cli1.num_cpf_cnpj = cli2.num_cpf_cnpj
											) 
						AND COD_TIPO_PESSOA = 'F'
					),

-------------------------------- BUSCAR DADOS DO ÚLTIMO CONTRATO - CORRETA ----------------------------------------
dta_max AS (
			SELECT 
				cc.NUM_CPF_CNPJ, 
				MAX(COALESCE(cc.DTH_CARGA_ATUALIZACAO, cc.DTH_CARGA))						as DTH_MAX_CARGA
			FROM 
				DM_CLIENTES_CONTRATOS_CVP													as cc WITH (NOLOCK)
				LEFT JOIN DM_CONTRATOS_CVP													as C WITH (NOLOCK)
				ON cc.NUM_CERTIFICADO = C.NUM_CERTIFICADO 
				AND cc.NOM_SEGMENTO = C.NOM_SEGMENTO
			WHERE 
				cc.COD_PESSOA = 1 
				AND cc.COD_TIPO_PESSOA = 'F'
				AND C.COD_STATUS_CONTRATO = 'A'
				AND cc.IND_CARGA <> 'D'
				--AND C.COD_PRODUTO IN ( 8521 , 8528, 8529 )
			GROUP BY 
				NUM_CPF_CNPJ
),

vigencia_max AS (
    SELECT 
        cc.NUM_CPF_CNPJ,
        MAX(C.DTA_INICIO_VIGENCIA) AS DTA_INICIO_VIGENCIA
    FROM 
        DM_CLIENTES_CONTRATOS_CVP AS cc WITH (NOLOCK)
        LEFT JOIN DM_CONTRATOS_CVP AS C WITH (NOLOCK)
        ON cc.NUM_CERTIFICADO = C.NUM_CERTIFICADO 
        AND cc.NOM_SEGMENTO = C.NOM_SEGMENTO
    WHERE 
        cc.COD_PESSOA = 1 
        AND cc.COD_TIPO_PESSOA = 'F'
        AND C.COD_STATUS_CONTRATO = 'A'
        AND cc.IND_CARGA <> 'D'
        --AND C.COD_PRODUTO IN (8521, 8528, 8529)
    GROUP BY 
        cc.NUM_CPF_CNPJ
),

-----------------------------------------------REGISTRO MAIS ANTIGO RITM0064948----------------------------------------------
MAIS_ANTIGO AS (
SELECT
	A.NUM_CPF_CNPJ,
	MIN(B.DTA_INICIO_VIGENCIA) AS DTA_INICIO_RELACIONAMENTO
FROM [DMDB41].[dbo].[DM_CLIENTES_CONTRATOS_CVP] A
LEFT JOIN [DMDB41].[dbo].[DM_CONTRATOS_CVP] B ON A.NUM_CERTIFICADO=B.NUM_CERTIFICADO AND A.NOM_SEGMENTO=B.NOM_SEGMENTO
WHERE 			A.COD_PESSOA = 1 
				AND A.COD_TIPO_PESSOA = 'F'
GROUP BY A.NUM_CPF_CNPJ),

-----------------------------------------------REGISTRO MAIS ANTIGO ATIVO RITM0064948----------------------------------------------
MAIS_ANTIGO_ATIVO AS (
SELECT
	A.NUM_CPF_CNPJ,
	B.COD_STATUS_CONTRATO,
	MIN(B.DTA_INICIO_VIGENCIA) AS DTA_INICIO_RELACIONAMENTO_ATIVO
FROM [DMDB41].[dbo].[DM_CLIENTES_CONTRATOS_CVP] A
LEFT JOIN [DMDB41].[dbo].[DM_CONTRATOS_CVP] B ON A.NUM_CERTIFICADO=B.NUM_CERTIFICADO AND A.NOM_SEGMENTO=B.NOM_SEGMENTO
WHERE 			A.COD_PESSOA = 1 
				AND A.COD_TIPO_PESSOA = 'F'
				AND B.COD_STATUS_CONTRATO = 'A'
				AND A.IND_CARGA <> 'D'
GROUP BY 	A.NUM_CPF_CNPJ,
	B.COD_STATUS_CONTRATO
				),



TABELA_FINAL_CONTRATO AS (
						SELECT 
							cc.COD_TIPO_PESSOA																								AS TIPO_PESSOA,
							cc.NUM_CPF_CNPJ																									AS NUM_CPF_CNPJ,
							LEFT(cc.NOM_PESSOA, CHARINDEX(' ', cc.NOM_PESSOA + ' ') - 1)													AS NOME,
							cc.NOM_PESSOA,
							cc.NOM_SOCIAL,
							FORMAT(cc.DTA_NASCIMENTO, 'd', 'en-gb')																			AS DT_NASCIMENTO,
							cc.IND_GENERO																									AS SEXO,
							cc.COD_UF,
							cc.NOM_CIDADE,
							cc.DES_ESTADO_CIVIL,
							cc.NUM_CERTIFICADO,
							cc.NOM_SEGMENTO,
							cc.COD_SEGMENTO_CAIXA,
							cc.I
GO
 
IF OBJECT_ID('[dbo].[VW_SF_MKT_ECONOMIARIO]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_SF_MKT_ECONOMIARIO];
GO
CREATE VIEW [dbo].[VW_SF_MKT_ECONOMIARIO]  AS


SELECT	
		E.SEQ_REGISTRO			AS	SEQ_REGISTRO__c 
		,E.MATR_FUNC            AS	MATR_FUNC__c                        
		,E.DV_MATR_FUNC 		AS	DV_MATR_FUNC__c 
		,E.NOM_FUNC             AS	NOM_FUNC__c                                    
		,E.NOM_FUNC             AS	LastName 
		,E.SIT_FUNC 			AS	SIT_FUNC__c 
		,E.EMAIL_CONTATO        AS	EMAIL_FUNC__c                               
		,E.SEXO 				AS	SEXO__c 
		,E.NUM_CPF     			AS	NUM_CPF__c     
		,E.NU_PIS      			AS	NU_PIS__c      
		,E.DAT_NAS    			AS	Birthdate    
		,E.LOT_FUNC   			AS	LOT_FUNC__c   
		,E.NOM_UNIDADE          AS	NOM_UNIDADE__c                  
		,E.IND_AREA 			AS	IND_AREA__c 
		,E.COD_FUNCAO 			AS	COD_FUNCAO__c 
		,E.DES_FUNCAO           AS	DES_FUNCAO__c                        
		,IsNull(E.DT_INICIO_FUNCAO,'') 	AS	DT_INICIO_FUNCAO__c 
		,CASE WHEN ISNULL(E.IND_FAIXA_FUNCAO,'') = '' THEN 0 ELSE E.IND_FAIXA_FUNCAO END 	AS	IND_FAIXA_FUNCAO__C 
		,CAST(E.COD_UNIDADE AS SMALLINT) AS	COD_UNIDADE__c 
		,E.UF_LOTACAO 			AS	UF_LOTACAO__c 
		,E.CIDADE_LOTACAO       AS	CIDADE_LOTACAO__c               
		,E.EMAIL_LOTACAO        AS	EMAIL_LOTACAO__c                               
		,IsNull(E.DT_INICIO_LOTACAO,'') 	AS	DT_INICIO_LOTACAO__c

		, IsNull(substring(convert(varchar(20),E.DT_INICIO_LOTACAO,112),1,4) + '-' 
		+ substring(convert(varchar(20),E.DT_INICIO_LOTACAO,112),5,2) + '-'
		+ substring(convert(varchar(20),E.DT_INICIO_LOTACAO,112),7,2) + 'T00:00:00.000','') AS DTH_ATUALIZACAO_TDV__c

		,E.DDD_LOTACAO 			AS	DDD_LOTACAO__c 
		,E.TELEFONE_LOTACAO 	AS	TELEFONE_LOTACAO__c 
--		,E.DTA_CADASTRAMENTO    AS	DTA_CADASTRAMENTO__c
		 
		,substring(convert(varchar(20),E.DTA_CADASTRAMENTO,112),1,4) + '-' 
		+ substring(convert(varchar(20),E.DTA_CADASTRAMENTO,112),5,2) + '-'
		+ substring(convert(varchar(20),E.DTA_CADASTRAMENTO,112),7,2) + 'T'
		+ SUBSTRING(convert(varchar(20),E.DTA_CADASTRAMENTO,114),1,8) AS DTA_CADASTRAMENTO__c


FROM	DMDB41.dbo.DM_ECONOMIARIO E (nolock)

LEFT JOIN [DMDB41].[dbo].[SB_P_202106_ARQUIVO_AGENCIAS_CAIXA] S (NOLOCK)
ON		E.COD_UNIDADE	=	S.CODAGE

WHERE E.SIT_FUNC		=	1 -- ATIVO   (2 - DESATIVADO 3- AFASTADO )
AND   S.TIPO_UNID		IN	('PV', 'SR')  --retirada em 03/01/2025 para corrigir problema no SF para pegar os economiários vinculados em SEV e SR
GO
 
