CREATE VIEW [dbo].VW_SF_MKT_ESTRUTURA_GECAN  AS

SELECT	 
		COD_UNIDADE								AS	COD_AGENCIA_TEXT__c
		,ISNULL(COD_SR					,'')	AS	COD_SR_TEXT__c
		,ISNULL(COD_SEV					,'')	AS	COD_SEV_TEXT__c
		,ISNULL(STA_ATIVO				,'')	AS	Status_do_Parceiro__c
		,ISNULL(MATRICULA_TRATADA		,'')	AS	CONVENIO_PARCEIRO__c
		,ISNULL(NOM_PARCEIRO			,'')	AS	Name
		,ISNULL(CONVERT(VARCHAR(20),P.CGCCPF),'')	AS	CNPJ_PARCEIRO__c
		,ISNULL(P.TELEFONE				,'')	AS	Phone
		,ISNULL(TIP_PARCEIRO			,'')	AS  TIPO_PARCEIRO__c
		,ISNULL(DES_CLASSIFICACAO		,'')	as	Classificacao__c
		,ISNULL(QTD_PONTO_MENSAL		,'')	as	QTD_PONTO_MENSAL__c
		,ISNULL(QTD_PONTO_TEMPORADA		,'')	as	QTD_PONTO_TEMPORADA__c 
		,ISNULL(PCT_CANCELAMENTO		,'')	as	PCT_CANCELAMENTO__c                        
		,ISNULL(PCT_ASSINATURA_DIGITAL	,'')	as	PCT_ASSINATURA_DIGITAL__c                  
		,ISNULL(DTH_ATUALIZACAO			,'')	as	DTH_ATUALIZACAO_TDV__c 
		,ISNULL(DTA_SITUACAO			,'')	as	DTA_SITUACAO__c
		,ISNULL(DTA_INCLUSAO			,'')	as	DTA_INCLUSAO__c
		,ISNULL(MATRICULA_CONSULTOR		,'')	as	Matricula_Consultor_Text__c                                                                                                                                                                                                                                      
		,ISNULL(COD_GERENCIA_RESULTADO_CVP,'')	as	COD_GERENCIA_RESULTADO_CVP__c                                                                                                                                                                                                                                
		,ISNULL(GERENCIA				,'')	as	GERENCIA__c                                                                                                                                                                                                                                          
		,ISNULL(GERENTE_CVP				,'')	as	Gerente_CVP__c                                                                                                                                                                                                                                     
		,ISNULL(EMAIL_GERENTE			,'')	as	Email_do_gerente_CVP__c                                                                                                                                                                                                                                      
		,ISNULL(CARTEIRA				,'')	as	Carteira__c                                                                                                                                                                                                                                    
		, FORMAT(GETDATE(), 'yyyy-MM-ddTHH:mm:ss.ff') AS DTA_ATUALIZACAO_ESTRUTURA__c
		,ISNULL(P.ENDERECO				,'')	AS	BillingStreet
		,ISNULL(P.BAIRRO				,'')	AS	BAIRRO__c
		,ISNULL(P.CIDADE				,'')	AS	BillingCity
		,ISNULL(P.SIGLA_UF				,'')	AS	BillingState
		,ISNULL(P.CEP					,'')	AS	BillingPostalCode
		,'012Hu000000zmSsIAI'		as	RecordTypeId

FROM	dmdb41.[dbo].[TB_ESTRUTURA_PARCEIRO_SURED] S

LEFT JOIN [SQL18\STAGING4].[TDDB05_CDC].[dbo].[PRODUTORES] P
ON		SUBSTRING(S.MATRICULA_TRATADA,1,8)   = P.NUM_MATRICULA -- P.COD_PRODUTOR
and		convert(int,(right(format(convert(bigint,p.COD_PRODUTOR),'0000000'),6))) =	convert(int,(left(format(convert(bigint,p.COD_hierarquia),'0000000'),6))) 

WHERE	ANOMES = (	SELECT MAX(ANOMES) 
					FROM [dmdb41].[dbo].[TB_ESTRUTURA_PARCEIRO_SURED] ) 
GO
 
