CREATE VIEW [dbo].VW_SF_MKT_FAT_DETALHES_CONTRATO AS
----------------------------------------------------- VIEW VW_SF_MKT_FAT_DETALHES_CONTRATO --------------------------------------------------------

		SELECT DISTINCT 
		CON.NOM_SEGMENTO,
		CON.NUM_CERTIFICADO,
		COB.codCobertura,
		COB.descCobertura,
		ASS.NOME_ASSISTENCIA
		
		
		FROM DM_CONTRATOS_CVP CON
		LEFT JOIN DM_CONTRATO_COBERTURA_CVP COB
		ON CON.NUM_CERTIFICADO = COB.NUM_CERTIFICADO AND CON.NOM_SEGMENTO = COB.NOM_SEGMENTO
		LEFT JOIN DM_CONTRATO_ASSISTENCIA_CVP ASS
		ON CON.NUM_CERTIFICADO = ASS.NUMERO_CONTRATO AND CON.NOM_SEGMENTO = ASS.NOM_SEGMENTO
GO
 
