GO
CREATE VIEW [dbo].VW_SF_MKT_FAT_PESSOAS_CONTRATOS AS

----------------------------------------------------- VIEW VW_SF_MKT_FAT_PESSOAS_CONTRATOS --------------------------------------------------------



WITH

BUSCA_COD_PESSOA AS (
						SELECT  
							cli1.COD_PESSOA_UNIFICADA AS COD_PESSOA,
							cli1.COD_TIPO_PESSOA as TIPO_PESSOA,
							cli1.NUM_CPF_CNPJ AS NUM_CPF_CNPJ,
							cli1.PRIMEIRO_NOME as NOME,
							cli1.NOM_PESSOA as NOME_SOBRENOME,
							cli1.NOM_SOCIAL as NOME_SOCIAL,
							FORMAT(cli1.DTA_NASCIMENTO ,'d','en-gb') as DT_NASCIMENTO,
							cli1.IND_GENERO as SEXO,
							cli1.DES_ESTADO_CIVIL as DESC_ESTADO_CIVIL


						FROM 
							DM_CLIENTES_UNIFICADOS_CVP as cli1 WITH (NOLOCK)
						WHERE 
							DTA_ATUALIZACAO IN (
											SELECT MAX(DTA_ATUALIZACAO)
											FROM DM_CLIENTES_UNIFICADOS_CVP cli2 WITH (NOLOCK)
											WHERE cli1.num_cpf_cnpj = cli2.num_cpf_cnpj
											)
					)


SELECT 
CLI.NUM_CERTIFICADO,
CLI.NUM_CPF_CNPJ,
BCOD.COD_PESSOA,
CLI.COD_TIPO_PESSOA as TIPO_PESSOA,
LEFT( CLI.NOM_PESSOA, CHARINDEX (' ', CLI.NOM_PESSOA + ' ') - 1 ) as NOME,
CLI.NOM_PESSOA,
CLI.NOM_SOCIAL,
FORMAT(CLI.DTA_NASCIMENTO ,'d','en-gb') as DT_NASCIMENTO,
CLI.IND_GENERO AS SEXO,
CLI.DES_ESTADO_CIVIL,
CLI.NUM_DDD_CELULAR,
CLI.NUM_CELULAR,
CLI.NUM_DDD_TELEFONE,
CLI.NUM_TELEFONE,
CLI.DES_EMAIL,
					CASE
					WHEN 
					LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'GV' THEN 'AZUL'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'GC' THEN 'ESPECIAL'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'GR' THEN 'SINGULAR'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'FX' THEN 'PRIVATE'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'EE' THEN 'MEI'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'ES' THEN 'MICROEMPRESA'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'EF' THEN 'PEQUENA EMPRESA'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'EX' THEN 'EMPRESA'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'MD' THEN 'EMPRESARIAL'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'UD' THEN 'EMPRESARIAL MAIS'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'EC' THEN 'CORPORATIVO'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'LC' THEN 'CORPORATIVO ULTRA'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'IV' THEN 'INVESTIDOR INSTITUCIONAL PRIVADO'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'PD' THEN 'ESTATAL EMPRASARIAL'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'PU' THEN 'ESTATAL EMPRESARIAL MAIS'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'PG' THEN 'ESTATAL CORPORATIVO'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'PP' THEN 'ESTATAL CORPORATIVO ULTRA'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'ID' THEN 'EMPRESARIAL ATENDIMENTO VAREJO'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'IU' THEN 'EMPRESARIAL MAIS ATENDIMENTO VAREJO'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'IG' THEN 'CORPORATIVO ATENDIMENTO VAREJO'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'IP' THEN 'CORPORATIVO MAIS ATENDIMENTO VAREJO'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'PO' THEN 'MUNÍCIPIOS III'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'PN' THEN 'MUNÍCIPIOS II'
					WHEN LEFT(CLI.COD_SEGMENTO_CAIXA, 2) = 'PM' THEN 'MUNÍCIPIOS I'
					ELSE CLI.COD_SEGMENTO_CAIXA END             AS SEGMENTO_CAIXA,
CASE
WHEN
CLI.NOM_SEGMENTO = 'PREVIDENCIA'
THEN '1'
ELSE '0'
END AS INFORME_DE_RENDIMENTO,
CLI.DTH_CARGA,
CLI.DTH_CARGA_ATUALIZACAO



FROM DM_CLIENTES_CONTRATOS_CVP CLI

		LEFT JOIN BUSCA_COD_PESSOA BCOD WITH (NOLOCK)
		ON CLI.NUM_CPF_CNPJ = BCOD.NUM_CPF_CNPJ 

WHERE CLI.COD_PESSOA = 1
GO
 
