IF OBJECT_ID('[dbo].[VW_SF_MKT_MODELOS_PROPENSAO]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_SF_MKT_MODELOS_PROPENSAO];
GO
CREATE VIEW dbo.VW_SF_MKT_MODELOS_PROPENSAO
AS
WITH
RESGATE_PREV AS (
	SELECT 
		NUM_CERTIFICADO,
		SEGMENTO AS NOM_SEGMENTO,
		VLR_SCORE AS VLR_SCORE_RESGATE_PREV,
		ANO_MES,
		ROW_NUMBER() OVER(PARTITION BY NUM_CERTIFICADO ORDER BY ANO_MES DESC) AS RN
	FROM [DMDB41].[dbo].MDL_METRICAS_RESGATE_PREVIDENCIA
		),

PORT_PREV AS (
	SELECT 
		NUM_CERTIFICADO,
		SEGMENTO AS NOM_SEGMENTO,
		VLR_SCORE AS VLR_SCORE_PORTABIDADE_PREV,
		ANO_MES,
		ROW_NUMBER() OVER(PARTITION BY NUM_CERTIFICADO ORDER BY ANO_MES DESC) AS RN
	FROM [DMDB41].[dbo].[MDL_METRICAS_PORTABILIDADE_SAIDA]
		),

CANC_PREST AS (
	SELECT 
		NUM_CERTIFICADO,
		SEGMENTO AS NOM_SEGMENTO,
		VLR_SCORE AS VLR_SCORE_CANCELAMENTO_PREST,
		ANO_MES,
		ROW_NUMBER() OVER(PARTITION BY NUM_CERTIFICADO ORDER BY ANO_MES DESC) AS RN
	FROM [DMDB41].[dbo].[MDL_METRICAS_CANCELAMENTO_PRESTAMISTA]
		),

CANC_VIDA AS (
	SELECT 
		NUM_CERTIFICADO,
		SEGMENTO AS NOM_SEGMENTO,
		VLR_SCORE AS VLR_SCORE_CANCELAMENTO_VIDA,
		ANO_MES,
		ROW_NUMBER() OVER(PARTITION BY NUM_CERTIFICADO ORDER BY ANO_MES DESC) AS RN
	FROM [DMDB41].[dbo].[MDL_METRICAS_CANCELAMENTO_VIDA]
		),

APORTE_PREV AS (
	SELECT 
		NUM_CERTIFICADO,
		SEGMENTO AS NOM_SEGMENTO,
		VLR_SCORE AS VLR_SCORE_APORTE_PREV,
		ANO_MES,
		ROW_NUMBER() OVER(PARTITION BY NUM_CERTIFICADO ORDER BY ANO_MES DESC) AS RN
	FROM [DMDB41].[dbo].[MDL_METRICAS_APORTE_PREVIDENCIA]
		),

INADIMP_VIDA AS (
	SELECT 
		NUM_CERTIFICADO,
		SEGMENTO AS NOM_SEGMENTO,
		VLR_SCORE AS VLR_SCORE_INADIMP_VIDA,
		ANO_MES,
		ROW_NUMBER() OVER(PARTITION BY NUM_CERTIFICADO ORDER BY ANO_MES DESC) AS RN
	FROM [DMDB41].[dbo].[MDL_METRICAS_INADIMPLENCIA_VIDA]
		)
		
SELECT 
	CC.NUM_CERTIFICADO,
	CC.NOM_SEGMENTO,
	CC.NUM_CPF_CNPJ,
	RP.VLR_SCORE_RESGATE_PREV,
	RP.ANO_MES AS ANO_MES_RESGATE_PREV,
	PP.VLR_SCORE_PORTABIDADE_PREV,
	PP.ANO_MES AS ANO_MES_PORTABIDADE_PREV,
	CP.VLR_SCORE_CANCELAMENTO_PREST,
	CP.ANO_MES AS ANO_MES_CANCELAMENTO_PREST,
	CV.VLR_SCORE_CANCELAMENTO_VIDA,
	CV.ANO_MES AS ANO_MES_CANCELAMENTO_VIDA,
	AP.VLR_SCORE_APORTE_PREV,
	AP.ANO_MES AS ANO_MES_APORTE_PREV,
	IV.VLR_SCORE_INADIMP_VIDA,
	IV.ANO_MES AS ANO_MES_INADIMP_VIDA,
	PPI.NBO_PREV AS PRODUTOS_PRIORITARIOS_PREV,
	PPI.NBO_VIDA AS PRODUTOS_PRIORITARIOS_VIDA,
	'' AS NEXT_BEST_ACTION


FROM [DMDB41].[dbo].[DM_CLIENTES_CONTRATOS_CVP] CC WITH(NOLOCK)

LEFT JOIN [DMDB41].[dbo].[DM_CONTRATOS_CVP] C WITH(NOLOCK)
ON CC.NUM_CERTIFICADO=C.NUM_CERTIFICADO AND CC.NOM_SEGMENTO=C.NOM_SEGMENTO

LEFT JOIN RESGATE_PREV RP WITH(NOLOCK)
ON CC.NUM_CERTIFICADO=RP.NUM_CERTIFICADO AND CC.NOM_SEGMENTO=RP.NOM_SEGMENTO AND RP.RN=1

LEFT JOIN PORT_PREV PP WITH(NOLOCK)
ON CC.NUM_CERTIFICADO=PP.NUM_CERTIFICADO AND CC.NOM_SEGMENTO=PP.NOM_SEGMENTO AND PP.RN=1

LEFT JOIN CANC_PREST CP WITH(NOLOCK)
ON CC.NUM_CERTIFICADO=CP.NUM_CERTIFICADO AND CC.NOM_SEGMENTO=CP.NOM_SEGMENTO AND CP.RN=1

LEFT JOIN CANC_VIDA CV WITH(NOLOCK)
ON CC.NUM_CERTIFICADO=CV.NUM_CERTIFICADO AND CC.NOM_SEGMENTO=CV.NOM_SEGMENTO AND CV.RN=1

LEFT JOIN APORTE_PREV AP WITH(NOLOCK)
ON CC.NUM_CERTIFICADO=AP.NUM_CERTIFICADO AND CC.NOM_SEGMENTO=AP.NOM_SEGMENTO AND AP.RN=1

LEFT JOIN INADIMP_VIDA IV WITH(NOLOCK)
ON CC.NUM_CERTIFICADO=IV.NUM_CERTIFICADO AND CC.NOM_SEGMENTO=IV.NOM_SEGMENTO AND IV.RN=1

LEFT JOIN [DMDB41].[dbo].[MDL_PROPOSTA_IDEAL] PPI WITH(NOLOCK)
ON CC.NUM_CERTIFICADO=PPI.NUM_CERTIFICADO AND CC.NOM_SEGMENTO= (CASE PPI.SEGMENTO_ORIGEM WHEN 'PREST' THEN 'PRESTAMISTA' WHEN 'PREV' THEN 'PREVIDENCIA' ELSE SEGMENTO_ORIGEM END)

WHERE C.COD_STATUS_CONTRATO='A'
AND CC.COD_PESSOA=1
AND CC.IND_CARGA <> 'D'
GO
 
IF OBJECT_ID('[dbo].[VW_SF_MKT_PESSOA_STATUS_PJ]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_SF_MKT_PESSOA_STATUS_PJ];
GO
CREATE VIEW [dbo].[VW_SF_MKT_PESSOA_STATUS_PJ] AS
----------------------------------------------------- VIEW VW_SF_MKT_PESSOA_STATUS_PJ --------------------------------------------------------

WITH
    BUSCA_COD_PESSOA AS (
        SELECT  
            CLIUNI1.COD_PESSOA_UNIFICADA AS COD_PESSOA_UNIFICADA,
            CLIUNI1.NUM_CPF_CNPJ AS NUM_CPF_CNPJ
        FROM 
            DM_CLIENTES_UNIFICADOS_CVP AS CLIUNI1 WITH (NOLOCK)
        WHERE 
            DTA_ATUALIZACAO IN (
                SELECT MAX(DTA_ATUALIZACAO)
                FROM DM_CLIENTES_UNIFICADOS_CVP CLIUNI2 WITH (NOLOCK)
                WHERE CLIUNI1.NUM_CPF_CNPJ = CLIUNI2.NUM_CPF_CNPJ
            )
            AND COD_TIPO_PESSOA = 'J'
    ),
    
    TELEFONES AS (
        SELECT 
            TEL.COD_PESSOA_UNIFICADA,
            TEL.TIPO_TELEFONE,
            TEL.NUM_DDD_TELEFONE,
            TEL.NUM_TELEFONE,
            ROW_NUMBER() OVER (PARTITION BY TEL.COD_PESSOA_UNIFICADA, TEL.TIPO_TELEFONE ORDER BY TEL.DTA_ATUALIZACAO DESC) AS rn
        FROM 
            DM_CLIENTES_TELEFONE_CVP AS TEL WITH (NOLOCK)
    ),
    
    EMAILS AS (
        SELECT 
            EMAIL.COD_PESSOA_UNIFICADA,
            EMAIL.DES_EMAIL,
            ROW_NUMBER() OVER (PARTITION BY EMAIL.COD_PESSOA_UNIFICADA ORDER BY EMAIL.DTA_ATUALIZACAO DESC) AS rn
        FROM 
            DM_CLIENTES_EMAIL_CVP AS EMAIL WITH (NOLOCK)
    ),
	
    
    EXTRACAO_CONSULTA AS (
		SELECT
			ISNULL(CLI.DTH_CARGA_ATUALIZACAO, '') AS DTH_CARGA_ATUALIZACAO, 
			ISNULL(CLI.DTH_CARGA, '') AS DTH_CARGA,
			ISNULL(BCOD.COD_PESSOA_UNIFICADA, '') AS COD_PESSOA_UNIFICADA,
			ISNULL(CLI.NUM_CPF_CNPJ, '') AS NUM_CPF_CNPJ,
			ISNULL(CTR.COD_STATUS_CONTRATO, '') AS COD_STATUS_CONTRATO,
			ISNULL(CLI.NOM_SOCIAL, '') AS NOM_SOCIAL,
			ISNULL(CLI.NOM_FANTASIA, '') AS NOM_FANTASIA,
			ISNULL(CLI.DTA_ABERTURA, '') AS DATA_ABERTURA,
			ISNULL(CTR.DTA_ENCERRAMENTO, '') AS DATA_ENCERRAMENTO,
			ISNULL(SEG.NOM_SEGMENTO, '') AS NOM_SEGMENTO,
			ISNULL(AGE.NOM_AGENCIA, '') AS NOM_AGENCIA,
			ISNULL(CLI.DES_CNAE, '') AS CNAE,
			ISNULL(CLI.NOM_LOGRADOURO, '') AS NOM_LOGRADOURO,
			ISNULL(CLI.COD_CEP, '') AS COD_CEP,
			ISNULL(CLI.VLR_FATURAMENTO_ANUAL, 0) AS VLR_FATURAMENTO_ANUAL,
			ISNULL(CLI.NOM_CIDADE, '') AS NOM_CIDADE,
			ISNULL(CLI.COD_UF, '') AS COD_UF,
			ISNULL(EMAIL.DES_EMAIL, '') AS DES_EMAIL,
			-- Telefones
			ISNULL(MAX(CASE WHEN TEL.TIPO_TELEFONE <> 2 AND TEL.rn = 1 THEN TEL.NUM_DDD_TELEFONE END), '') AS NUM_DDD_TELEFONE,
			ISNULL(MAX(CASE WHEN TEL.TIPO_TELEFONE <> 2 AND TEL.rn = 1 THEN TEL.NUM_TELEFONE END), '') AS NUM_TELEFONE,
			ISNULL(MAX(CASE WHEN TEL.TIPO_TELEFONE = 2 AND TEL.rn = 1 THEN TEL.NUM_DDD_TELEFONE END), '') AS NUM_DDD_CELULAR,
			ISNULL(MAX(CASE WHEN TEL.TIPO_TELEFONE = 2 AND TEL.rn = 1 THEN TEL.NUM_TELEFONE END), '') AS NUM_CELULAR,	
			------------
			ISNULL(CASE WHEN CLI.IND_PEP = 'S' THEN 1 ELSE 0 END, 0) AS IND_PEP,
			ISNULL(CASE WHEN CLI.IND_NAO_PERTURBE_LGPD = 'S' THEN 1 ELSE 0 END, 0) AS IND_NAO_PERTURBE_LGPD,
			ISNULL(CLI.IND_PERMITE_CONTATO_EMAIL, '') AS IND_PERMITE_CONTATO_EMAIL,
			ISNULL(CLI.IND_PERMITE_CONTATO_TELEFONE, '') AS IND_PERMITE_CONTATO_TELEFONE,
			ISNULL(CLI.IND_PERMITE_CONTATO_WHATSAPP, '') AS IND_PERMITE_CONTATO_WHATSAPP,
			ISNULL(CLI.IND_RECEBER_OFERTAS_CAIXA_SEG, '') AS IND_RECEBER_OFERTAS_CAIXA_SEG,
			ISNULL(CLI.IND_RECEBER_OFERTAS_PARCEIROS, '') AS IND_RECEBER_OFERTAS_PARCEIROS,
			ROW_NUMBER() OVER (PARTITION BY CLI.NUM_CPF_CNPJ ORDER BY COALESCE(CLI.DTH_CARGA, CLI.DTH_CARGA_ATUALIZACAO) DESC) AS RN
        FROM 
            DM_CLIENTES_CONTRATOS_CVP AS CLI WITH (NOLOCK)
        
        LEFT JOIN 
            BUSCA_COD_PESSOA BCOD WITH (NOLOCK)
            ON CLI.NUM_CPF_CNPJ = BCOD.NUM_CPF_CNPJ 

        LEFT JOIN 
            DM_CONTRATOS_CVP AS CTR WITH (NOLOCK) 
            ON CTR.NUM_CERTIFICADO = CLI.NUM_CERTIFICADO

        LEFT JOIN 
            DM_AGENCIA 
GO
 
IF OBJECT_ID('[dbo].[VW_SF_MKT_UAU_CADASTRADOS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_SF_MKT_UAU_CADASTRADOS];
GO











CREATE VIEW [dbo].[VW_SF_MKT_UAU_CADASTRADOS]
AS
WITH CLIENTE AS (SELECT DISTINCT A.NUM_CPF_CNPJ, 'A' AS STATUS_CLIENTE
                              FROM    dbo.DM_CLIENTES_CONTRATOS_CVP AS A LEFT OUTER JOIN
                                            dbo.DM_CONTRATOS_CVP AS B ON A.NUM_CERTIFICADO = B.NUM_CERTIFICADO AND A.NOM_SEGMENTO = B.NOM_SEGMENTO
                              WHERE  (B.COD_STATUS_CONTRATO = 'A')), 
	PONTUACAO AS (
		SELECT  NUM_CERTIFICADO, CPF_CNPJ, QTD_VALOR_PONTOS
		FROM    [WORK_GERESD].[UAU].[RETORNO_MOVIMENTO]
		WHERE COD_RETORNO=00
	),

	PONTOS AS
    (SELECT NUM_CERTIFICADO, CPF_CNPJ,SUM(QTD_VALOR_PONTOS) AS PONTUACAO
    FROM    PONTUACAO
    GROUP BY NUM_CERTIFICADO, CPF_CNPJ),
	PAGAMENTO AS (
			select CLF.NUM_CERTIFICADO, 
		CASE OPC.OPCAO_PAGAMENTO 
		WHEN '0' THEN 'Pagamento Único' 
		WHEN '1' THEN 'Débito em Conta Corrente' 
		WHEN '2' THEN 'Débito em Conta Poupança' 
		WHEN '3' THEN 'Boleto' 
		WHEN '4' THEN 'Averbação' 
		WHEN '5' THEN 'Cartão de Crédito' 
		WHEN 'A' THEN '* - Inválido' 
		WHEN 'E' THEN '* - Inválido' 
		WHEN 'S' THEN '* - Inválido' 
		ELSE '* - Inválido' 
		END AS DES_FORMA_PAGAMENTO,
		ROW_NUMBER() over(partition by CLF.NUM_CERTIFICADO order by TIMESTAMP desc) AS RN
		  FROM   
		  [SQL18\STAGING4].SIAS_REPLICA.dbo.GE_CLIENTE_FIDELIZACAO AS CLF LEFT OUTER JOIN
		  [SQL18\STAGING4].SIAS_REPLICA.dbo.OPCAO_PAG_VIDAZUL AS OPC ON CLF.NUM_CERTIFICADO = OPC.NUM_CERTIFICADO)

    SELECT CLF.NUM_CERTIFICADO, PES.NOME_PESSOA, CLF.NUM_CPF, CLF.COD_PRODUTO, PROD.DESCR_PRODUTO AS NOM_PRODUTO, CLF.DTA_INI_ADERENCIA AS DTA_ADESAO, 
                PG.DES_FORMA_PAGAMENTO, PFD.VAL_PAGO AS VLR_PREMIO, PVA.DATA_VENCIMENTO, PVA.NUM_PARCELA, PT.PONTUACAO, 
                CASE WHEN CL.STATUS_CLIENTE = 'A' THEN 'S' ELSE 'N' END AS CLIENTE_ATIVO, 
				CASE WHEN (PFD.SIT_PROPOSTA = 'EMT' or PVA.SIT_REGISTRO in (3, 6)) THEN 'S' ELSE 'N' END AS CERTIFICADO_ATIVO,
				CASE WHEN PAR.SIT_REGISTRO='1' OR (PAR.SIT_REGISTRO<>'1' and PAR.DATA_VENCIMENTO >= CAST(GETDATE() AS DATE)) THEN 'N'	ELSE 'S' END AS CERTIFICADO_INADIMPLENTE
   FROM    [SQL18\STAGING4].SIAS_REPLICA.dbo.GE_CLIENTE_FIDELIZACAO AS CLF LEFT OUTER JOIN
                [SQL18\STAGING4].SIAS_REPLICA.dbo.PROPOSTAS_VA AS PVA ON CLF.NUM_CERTIFICADO = PVA.NUM_CERTIFICADO LEFT OUTER JOIN
                [SQL18\STAGING4].SIAS_REPLICA.dbo.PROPOSTA_FIDELIZ AS PFD ON PVA.NUM_CERTIFICADO = PFD.NUM_PROPOSTA_SIVPF LEFT OUTER JOIN
                [SQL18\STAGING4].SIAS_REPLICA.dbo.PRODUTO AS PROD ON CLF.COD_PRODUTO = PROD.COD_PRODUTO LEFT OUTER JOIN
                [SQL18\STAGING4].SIAS_REPLICA.dbo.PESSOA AS PES ON PFD.COD_PESSOA = PES.COD_PESSOA LEFT OUTER JOIN
				[SQL18\STAGING4].SIAS_REPLICA.dbo.PARCELAS_VIDAZUL AS PAR ON PVA.NUM_CERTIFICADO = PAR.NUM_CERTIFICADO AND PVA.NUM_PARCELA = PAR.NUM_PARCELA LEFT OUTER JOIN
                PONTOS AS PT ON cast(CLF.NUM_CERTIFICADO as varchar) = PT.NUM_CERTIFICADO AND CLF.NUM_CPF = PT.CPF_CNPJ LEFT OUTER JOIN
                CLIENTE AS CL ON CLF.NUM_CPF = CL.NUM_CPF_CNPJ LEFT OUTER JOIN
				PAGAMENTO PG ON CLF.NUM_CERTIFICADO = PG.NUM_CERTIFICADO
   WHERE (CLF.DTA_FIM_ADERENCIA = '9999-12-31') AND (CLF.IND_RESPOSTA_ADESAO = 'S') AND (CLF.NOM_PROGRAMA = 'SPBGE054') AND PG.RN=1
GO
 
IF OBJECT_ID('[dbo].[VW_SF_MKT_UAU_ELEGIVEIS]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_SF_MKT_UAU_ELEGIVEIS];
GO




CREATE VIEW [dbo].[VW_SF_MKT_UAU_ELEGIVEIS]
AS
WITH 	PAGAMENTO AS (
			select PROP.NUM_CERTIFICADO, 
		CASE OPC.OPCAO_PAGAMENTO 
		WHEN '0' THEN 'Pagamento Único' 
		WHEN '1' THEN 'Débito em Conta Corrente' 
		WHEN '2' THEN 'Débito em Conta Poupança' 
		WHEN '3' THEN 'Boleto' 
		WHEN '4' THEN 'Averbação' 
		WHEN '5' THEN 'Cartão de Crédito' 
		WHEN 'A' THEN '* - Inválido' 
		WHEN 'E' THEN '* - Inválido' 
		WHEN 'S' THEN '* - Inválido' 
		ELSE '* - Inválido' 
		END AS DES_FORMA_PAGAMENTO,
		ROW_NUMBER() over(partition by OPC.NUM_CERTIFICADO order by OPC.TIMESTAMP desc) AS RN
		  FROM [SQL18\STAGING4].SIAS_REPLICA.dbo.PROPOSTAS_VA AS PROP WITH (NOLOCK) LEFT OUTER JOIN
		  [SQL18\STAGING4].SIAS_REPLICA.dbo.OPCAO_PAG_VIDAZUL AS OPC WITH (NOLOCK) ON PROP.NUM_CERTIFICADO = OPC.NUM_CERTIFICADO
		    WHERE PROP.COD_PRODUTO IN (9731, 9735, 9741, 9745, 9750) AND CAST(PROP.DATA_QUITACAO AS DATE) >= '2026-01-13'
		  )
    SELECT distinct PROP.NUM_CERTIFICADO, PES.NOME_PESSOA, PF.CGCCPF as CPF, PROP.DATA_QUITACAO AS DATA_VENDA, PFD.DTQITBCO AS DATA_PAGAMENTO, PROP.COD_PRODUTO, PROD.DESCR_PRODUTO AS NOM_PRODUTO, 
                CASE PVG.PERI_PAGAMENTO WHEN 0 THEN 'Unico' WHEN 1 THEN 'Mensal' WHEN 2 THEN 'Bimestral' WHEN 3 THEN 'Trimestral' WHEN 4 THEN 'Quadrimestral' WHEN 6 THEN 'Semestral' WHEN 12 THEN 'Anual' ELSE '* - Inválido' END AS PERIODICIDADE_PAGAMENTO, 
              	CASE cc.DESCRICAO_CANAL
		WHEN 'SIVPF' THEN 'Balcão Caixa'
	--	WHEN 'CAIXA SEGUROS / FENAE / AIC' THEN 
		WHEN 'CAIXA AQUI' THEN 'CCA'
	--	WHEN 'ATM' THEN 
		WHEN 'GITEL / CERAT' THEN 'Balcão Caixa'
	--	WHEN 'MANUAIS' THEN 
	--	WHEN 'INTERNET BANKING/SILOJ/INTERNET'
		WHEN 'SIVPF WEB' THEN 'Balcão Caixa'
		WHEN 'CORRESPONDENTE' THEN 'CCA'
	END NOM_CANAL_VENDA, 
                PAG.DES_FORMA_PAGAMENTO, ISNULL(PROP_ATUAL.IMPSEGUR, HIS_COB_PROP.IMPSEGUR) AS VLR_IS, ISNULL(PROP_ATUAL.VLPREMIO, HIS_COB_PROP.VLPREMIO) AS VLR_PREMIO, 
                PFD.SIT_PROPOSTA AS STA_PROPOSTA, PEM.EMAIL
   FROM    [SQL18\STAGING4].SIAS_REPLICA.dbo.PROPOSTAS_VA AS PROP WITH (NOLOCK) LEFT OUTER JOIN
                [SQL18\STAGING4].SIAS_REPLICA.dbo.CLIENTES AS PF WITH (NOLOCK) ON PROP.COD_CLIENTE = PF.COD_CLIENTE LEFT OUTER JOIN
                [SQL18\STAGING4].SIAS_REPLICA.dbo.PRODUTO AS PROD WITH (NOLOCK) ON PROP.COD_PRODUTO = PROD.COD_PRODUTO LEFT OUTER JOIN
                [SQL18\STAGING4].SIAS_REPLICA.dbo.PRODUTOS_VG AS PVG WITH (NOLOCK) ON PROP.NUM_APOLICE = PVG.NUM_APOLICE AND PROP.COD_SUBGRUPO = PVG.COD_SUBGRUPO AND PVG.PERI_PAGAMENTO=1 LEFT OUTER JOIN
                PAGAMENTO AS PAG WITH (NOLOCK) ON PROP.NUM_CERTIFICADO = PAG.NUM_CERTIFICADO LEFT OUTER JOIN
                [SQL18\STAGING4].SIAS_REPLICA.dbo.HIS_COBER_PROPOST AS HIS_COB_PROP WITH (NOLOCK) ON HIS_COB_PROP.NUM_CERTIFICADO = PROP.NUM_CERTIFICADO AND HIS_COB_PROP.OCORR_HISTORICO = 1 LEFT OUTER JOIN
                [SQL18\STAGING4].SIAS_REPLICA.dbo.HIS_COBER_PROPOST AS PROP_ATUAL WITH (NOLOCK) ON PROP_ATUAL.NUM_CERTIFICADO = PROP.NUM_CERTIFICADO AND PROP_ATUAL.OCORR_HISTORICO = PROP.OCORR_HISTORICO LEFT OUTER JOIN
                [SQL18\STAGING4].SIAS_REPLICA.dbo.PROPOSTA_FIDELIZ AS PFD WITH (NOLOCK) ON PROP.NUM_CERTIFICADO = PFD.NUM_PROPOSTA_SIVPF LEFT OUTER JOIN
				[SQL18\STAGING4].SIAS_REPLICA.dbo.CANAL_VENDA cc ON  PFD.CANAL_PROPOSTA = cc.CANAL_PROPOSTA LEFT OUTER JOIN
                [SQL18\STAGING4].SIAS_REPLICA.dbo.PESSOA AS PES WITH (NOLOCK) ON PFD.COD_PESSOA = PES.COD_PESSOA LEFT OUTER JOIN      
	   		 [SQL18\STAGING4].SIAS_REPLICA.dbo.PESSOA_EMAIL PEM    ON PFD.COD_PESSOA = PEM.COD_PESSOA
    AND PEM.SITUACAO_EMAIL = 'A'
    AND PEM.[TIMESTAMP] = (
        SELECT MAX(PEM2.[TIMESTAMP])
        FROM [SQL18\STAGING4].SIAS_REPLICA.dbo.PESSOA_EMAIL PEM2
        WHERE PEM2.COD_PESSOA = PEM.COD_PESSOA
          AND PEM2.SITUACAO_EMAIL = 'A')

   WHERE (PROP.COD_PRODUTO IN (9731, 9735, 9741, 9745, 9750)) 
   AND (CAST(PROP.DATA_QUITACAO AS DATE) >= 
GO
 
