create view VW_SF_RESGATE_PREV as (
--criada por Bruno 04-01-24 atendimento de solicitação GEATE
select distinct DES_FILA,
DTH_ABERTURA,
NOM_PROPRIETARIO,
NOM_CLIENTE,
NOM_SEGMENTO_EXCLUSIVO_PREV,
NUM_DOCUMENTO_PROSPECT as NUM_DOCUMENTO_CLIENTE,
NUM_PROTOCOLO,
NUM_ATENDIMENTO as NUM_SOLICITACAO,
NUM_CONTRATO,
DES_STATUS_CONTRATO,
COD_PRODUTO,
DES_PRODUTO_CONTRATO,
DES_SEGMENTO_CONTRATO,
DES_ASSUNTO,
VLR_SALDO_DISPONIVEL_PREV,
VLR_URA,
VLR_DESEJADO,
VLR_SOLICITADO,
VLR_RETIDO,
DES_RETENCAO_RESGATE

from DM_SALESFORCE_ATENDIMENTO
 
where DES_SEGMENTO='PREV' 
and DES_ASSUNTO like 'Solicitar resgate%'
and not DES_ASSUNTO = 'Solicitar resgate > Programar resgate'
and DES_FILA in ('Prev Fideliza Grandes Valores', 'Prev Fideliza')
and DTH_ABERTURA>=GETDATE()-30
and STA_ATENDIMENTO='Closed'
)
GO
 
