CREATE VIEW dbo.VW_TABULACAO_ATENDIMENTO_SF
AS
SELECT FORMAT(DTH_ABERTURA, 'dd/MM/yyyy') AS Data_Criacao, FORMAT(DTH_ABERTURA, 'dd/MM/yyyy HH:mm') AS Data_Hora_Abertura, FORMAT(DTH_RESOLUCAO, 'dd/MM/yyyy HH:mm') AS Data_Hora_Fechamento, 
                  DES_ORIGEM_CONTATO AS Origem_Contato, DES_DIRECIONADOR_ORIGEM AS Direcionador_Origem, DES_FILA AS Direcionador, DES_ORIGEM AS Canal, NUM_PROTOCOLO AS Numero_Protocolo, 
                  NUM_ATENDIMENTO AS Numero_Solicitacao, SUBSTRING(DES_ASSUNTO, 1, CHARINDEX(' >', DES_ASSUNTO + ' >') - 1) AS Macroassunto, DES_ASSUNTO AS Assunto, DES_TIPO_ATENDIMENTO AS Classificacao_Atendimento, 
                  DES_SEGMENTO AS Segmento, STA_ATENDIMENTO AS Status_Atendimento, DES_RESULTADO AS Status_Resultado, CASE WHEN DTH_ENVIO_NIVEL_2 IS NOT NULL THEN 1 ELSE 0 END AS Segundo_Nivel, 
                  COD_PRODUTO AS Codigo_Produto, DES_PRODUTO_CONTRATO AS Produto_Contrato, NOM_CRIADOR_PROTOCOLO AS Criado_Por_Nome_Completo, CASE WHEN IND_TRANSFERENCIA = 'true' THEN 1 ELSE 0 END AS Transferencia, 
                  NOM_EMPRESA_NIVEL_1 AS Proprietario_Nivel_1_Nome_Empresa, NUM_CPF_CNPJ AS CPF_CNPJ, NOM_USUARIO_NIVEL_1 AS Proprietario_Nivel_1_Nome_Usuario, NOM_USUARIO_NIVEL_2 AS Proprietario_Nivel_2_Nome_Usuario, 
                  NUM_TELEFONE_URA AS Numero_Telefone_URA, DES_ASSUNTO_URA AS Assunto_URA, ISNULL(ISNULL(NUM_CONTRATO_SALESFORCE, NUM_CONTRATO_BU_SALESFORCE), NUM_CONTRATO_SELECIONADO_SALESFORCE) 
                  AS Numero_Contrato, DES_TIPO_PROTOCOLO AS Tipo, DES_ASSUNTO_NIVEL_2 AS Assunto_Nivel_2
FROM     dbo.DM_SALESFORCE_ATENDIMENTO
GO
 
