GO
CREATE VIEW [dbo].[VW_TDV_AgenciaSemMov] AS
---------------------------------------------------------------------------------------------------
--		PRESTAMISTA 
---------------------------------------------------------------------------------------------------
--		BASE DE CANCELADOS		PARA PRESTAMISTA
---------------------------------------------------------------------------------------------------
WITH CANCELAMENTOS AS ( 
						SELECT	A.NUM_CONTRATO_TERC, 
								A.DES_MOTIVO_CANCEL, 
								A.DTA_CANCELAMENTO
						FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS A
						INNER JOIN (SELECT	NUM_CONTRATO_TERC, 
											MAX(STA_MOVIMENTO) AS STA_MOVIMENTO,  
											MAX(DTH_CARGA) AS DTH_CARGA 			
									FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS WITH ( NOLOCK ) 
									WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
									GROUP BY NUM_CONTRATO_TERC) B 
						ON		A.NUM_CONTRATO_TERC =	B.NUM_CONTRATO_TERC
						AND		A.STA_MOVIMENTO		=	B.STA_MOVIMENTO
						AND		A.DTH_CARGA			=	B.DTH_CARGA
						WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
		) 
---------------------------------------------------------------------------------------------------
--		1	-			PRESTAMISTA :   RECUPERA VENDAS DO AIC
---------------------------------------------------------------------------------------------------
, SEGUIMENTOS AS (		SELECT	
								'PRESTAMISTA'	AS		SEGMENTO,
								CASE WHEN ISNUMERIC(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', '')) = 1 AND NOM_CANAL <> 'AIC EXTRA-REDE' 
									 THEN CONVERT(BIGINT, LEFT(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', ''),6)) 
									 ELSE 0 
								END  AS MATRICULA 
								,DTH_VENDA		AS		DTA_VENDA
								,COUNT(*)		AS		QTDE 
						FROM	DMDB41..DM_AIC_PROPOSTA  A WITH (NOLOCK)
						
						WHERE	NOM_SEGMENTO	=		'PRESTAMISTA'
						AND		DTH_VENDA		BETWEEN DATEADD(DAY, 2 - DATEPART(DW, DATEADD(WEEK,-2,CONVERT(DATE,GETDATE()))) ,DATEADD(WEEK,-2,CONVERT(DATE,GETDATE())))
												AND		DATEADD(DAY, 6 - DATEPART(DW, DATEADD(WEEK,-1,CONVERT(DATE,GETDATE()))), DATEADD(WEEK,-1,CONVERT(DATE,GETDATE())))
						AND		FL_PROCESSADO	<>		'8'  -- 8 = cancelado no AIC
						GROUP BY CASE WHEN ISNUMERIC(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', '')) = 1 AND NOM_CANAL <> 'AIC EXTRA-REDE' 
									  THEN CONVERT(BIGINT, LEFT(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', ''),6)) 
									  ELSE 0 
								 END
								,DTH_VENDA	
---------------------------------------------------------------------------------------------------
--		2	-			PRESTAMISTA :  ( EXCETO CONSORCIO ) SIAPI SIAPX SIFEC
---------------------------------------------------------------------------------------------------
		UNION ALL
						SELECT	
								'PRESTAMISTA'	AS		SEGMENTO,
								SUBSTRING(RIGHT('0000000' + CONVERT(VARCHAR(7), CNT.NUM_MATRICULA_VENDEDOR ),7),1,6)  AS MATRICULA -- RETIRANDO O DV
								,A.DTA_PROPOSTA AS DTA_VENDA
								,COUNT(*)		AS		QTDE 
						FROM	DMDB42..DM_ODS_PRS_PROPOSTAS_U A WITH (NOLOCK)
						LEFT JOIN DMDB42..DM_ODS_PRS_CONTRATOS_U CNT WITH (NOLOCK)
						ON		A.NUM_PROPOSTA_ESTIP = CNT.NUM_CONTRATO_TERC
						AND		A.COD_PRODUTO = CNT.COD_PRODUTO
						LEFT JOIN CANCELAMENTOS AS CANC WITH (NOLOCK)
						ON		A.NUM_PROPOSTA_ESTIP = CANC.NUM_CONTRATO_TERC
						
						WHERE	A.DTA_PROPOSTA	BETWEEN  DATEADD(DAY, 2 - DATEPART(DW, DATEADD(WEEK,-2,CONVERT(DATE,GETDATE()))) ,DATEADD(WEEK,-2,CONVERT(DATE,GETDATE())))
												AND		 DATEADD(DAY, 6 - DATEPART(DW, DATEADD(WEEK,-1,CONVERT(DATE,GETDATE()))), DATEADD(WEEK,-1,CONVERT(DATE,GETDATE()))) 
						AND		A.NUM_PROPOSTA_ESTIP NOT IN (	SELECT	COD_PROPOSTA  
																FROM	DMDB41..DM_AIC_PROPOSTA WITH ( NOLOCK INDEX = PK_DM_AIC )
																WHERE	NOM_SEGMENTO	=		'PRESTAMISTA' 				  )  
						GROUP BY SUBSTRING(RIGHT('0000000' + CONVERT(VARCHAR(7), CNT.NUM_MATRICULA_VENDEDOR ),7),1,6)
								,A.DTA_PROPOSTA 
---------------------------------------------------------------------------------------------------
--		3	-			PRESTAMISTA :  SOMENTE CONSORCIO 
----------
GO
 
IF OBJECT_ID('[dbo].[VW_TDV_AgenciaSemMovMensal]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_TDV_AgenciaSemMovMensal];
