		CREATE VIEW [dbo].[VW_TDV_AgenciaSemMovMensal] AS
---------------------------------------------------------------------------------------------------
--		Objetivo: demonstrar as vendas por unidade comparando mes (-1) com (-02)
---------------------------------------------------------------------------------------------------
---------------------------------------------------------------------------------------------------
--		PRESTAMISTA 
---------------------------------------------------------------------------------------------------
--		BASE DE CANCELADOS		PARA PRESTAMISTA
---------------------------------------------------------------------------------------------------
WITH CANCELAMENTOS AS ( 
						SELECT	A.NUM_CONTRATO_TERC, 
								A.DES_MOTIVO_CANCEL, 
								A.DTA_CANCELAMENTO
						FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS A
						INNER JOIN (SELECT	NUM_CONTRATO_TERC, 
											MAX(STA_MOVIMENTO) AS STA_MOVIMENTO,  
											MAX(DTH_CARGA) AS DTH_CARGA 			
									FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS WITH ( NOLOCK ) 
									WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
									GROUP BY NUM_CONTRATO_TERC) B 
						ON		A.NUM_CONTRATO_TERC =	B.NUM_CONTRATO_TERC
						AND		A.STA_MOVIMENTO		=	B.STA_MOVIMENTO
						AND		A.DTH_CARGA			=	B.DTH_CARGA
						WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
		) 
---------------------------------------------------------------------------------------------------
--		1	-			PRESTAMISTA :   RECUPERA VENDAS DO AIC
---------------------------------------------------------------------------------------------------
, SEGUIMENTOS AS (		SELECT	
								'PRESTAMISTA'	AS		SEGMENTO,
								CASE WHEN ISNUMERIC(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', '')) = 1 AND NOM_CANAL <> 'AIC EXTRA-REDE' 
									 THEN CONVERT(BIGINT, LEFT(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', ''),6)) 
									 ELSE 0 
								END  AS MATRICULA 
								,CONVERT(VARCHAR(6),DTH_VENDA,112)	AS		DTA_VENDA
								,COUNT(*)		AS		QTDE 
						FROM	DMDB41..DM_AIC_PROPOSTA  A WITH (NOLOCK)
						
						WHERE	NOM_SEGMENTO	=		'PRESTAMISTA'
						AND		CONVERT(VARCHAR(8),DTH_VENDA,112)	>=		CONVERT(VARCHAR(6),DATEADD(month,-2,getdate()),112) + '01'  
						AND		CONVERT(VARCHAR(8),DTH_VENDA,112)	<		CONVERT(VARCHAR(6),DATEADD(month,-0,getdate()),112) + '01'  
						AND		FL_PROCESSADO	<>		'8'  -- 8 = cancelado no AIC
						GROUP BY CASE WHEN ISNUMERIC(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', '')) = 1 AND NOM_CANAL <> 'AIC EXTRA-REDE' 
									  THEN CONVERT(BIGINT, LEFT(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', ''),6)) 
									  ELSE 0 
								 END
						,CONVERT(VARCHAR(6),DTH_VENDA,112)		
---------------------------------------------------------------------------------------------------
--		2	-			PRESTAMISTA :  ( EXCETO CONSORCIO ) SIAPI SIAPX SIFEC
---------------------------------------------------------------------------------------------------
		UNION ALL
						SELECT	
								'PRESTAMISTA'	AS		SEGMENTO,
								SUBSTRING(RIGHT('0000000' + CONVERT(VARCHAR(7), CNT.NUM_MATRICULA_VENDEDOR ),7),1,6)  AS MATRICULA -- RETIRANDO O DV
								,CONVERT(VARCHAR(6),A.DTA_PROPOSTA,112) AS DTA_VENDA
								,COUNT(*)		AS		QTDE 
						FROM	DMDB42..DM_ODS_PRS_PROPOSTAS_U A WITH (NOLOCK)
						LEFT JOIN DMDB42..DM_ODS_PRS_CONTRATOS_U CNT WITH (NOLOCK)
						ON		A.NUM_PROPOSTA_ESTIP = CNT.NUM_CONTRATO_TERC
						AND		A.COD_PRODUTO = CNT.COD_PRODUTO
						LEFT JOIN CANCELAMENTOS AS CANC WITH (NOLOCK)
						ON		A.NUM_PROPOSTA_ESTIP = CANC.NUM_CONTRATO_TERC
						
						WHERE	CONVERT(VARCHAR(8),A.DTA_PROPOSTA,112)	>=		CONVERT(VARCHAR(6),DATEADD(month,-2,getdate()),112) + '01'  
						AND		CONVERT(VARCHAR(8),A.DTA_PROPOSTA,112)	<		CONVERT(VARCHAR(6),DATEADD(month,-0,getdate()),112) + '01'  
						AND		A.NUM_PROPOSTA_ESTIP NOT IN (	SELECT	COD_PROPOSTA  
																FROM	DMDB41..DM_AIC_PROPOSTA WITH ( NOLOCK INDEX = PK_DM_AIC )
																WHERE	NOM_SEGMENTO	=		'PRESTAMISTA' 				  )  
						GROUP BY SUBSTRING(RIGHT('00000
GO
 
IF OBJECT_ID('[dbo].[VW_TDV_IndicadorFull]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_TDV_IndicadorFull];
GO
CREATE VIEW [dbo].[VW_TDV_IndicadorFull] AS
---------------------------------------------------------------------------------------------------
--		PRESTAMISTA 
---------------------------------------------------------------------------------------------------
--		BASE DE CANCELADOS		PARA PRESTAMISTA
---------------------------------------------------------------------------------------------------
WITH CANCELAMENTOS AS ( 
						SELECT	A.NUM_CONTRATO_TERC, 
								A.DES_MOTIVO_CANCEL, 
								A.DTA_CANCELAMENTO
						FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS A
						INNER JOIN (SELECT	NUM_CONTRATO_TERC, 
											MAX(STA_MOVIMENTO) AS STA_MOVIMENTO,  
											MAX(DTH_CARGA) AS DTH_CARGA 			
									FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS WITH ( NOLOCK ) 
									WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
									GROUP BY NUM_CONTRATO_TERC) B 
						ON		A.NUM_CONTRATO_TERC =	B.NUM_CONTRATO_TERC
						AND		A.STA_MOVIMENTO		=	B.STA_MOVIMENTO
						AND		A.DTH_CARGA			=	B.DTH_CARGA
						WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
		) 
---------------------------------------------------------------------------------------------------
--		1	-			PRESTAMISTA :   RECUPERA VENDAS DO AIC
---------------------------------------------------------------------------------------------------
, SEGUIMENTOS AS (		SELECT	'PRESTAMISTA		 '			AS	SEGMENTO,
								'VENDA				 ' 			AS	MOVIMENTO,
								CASE WHEN ISNUMERIC(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', '')) = 1 AND NOM_CANAL <> 'AIC EXTRA-REDE' 
									 THEN CONVERT(BIGINT, LEFT(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', ''),6)) 
									 ELSE 0 
								END  AS MATRICULA ,
								CONVERT(VARCHAR(6),DTA_VENDA,112) AS AAMM_VENDA,
								CASE	WHEN  	P.DTH_CADASTRAMENTO_PROP_SEGURO IS NOT NULL  -- HAVENDO PROPOSTA SEMPRE SERÁ PAGO
										THEN	CONVERT(VARCHAR(6),P.DTH_CADASTRAMENTO_PROP_SEGURO,112) 
										WHEN	DTA_VENDA <> CONVERT(DATE, GETDATE()) 
										THEN	CONVERT(VARCHAR(6),A.DTA_PAGAMENTO_MJUNMOV,112)   
										ELSE	CONVERT(VARCHAR(6),A.DTA_PAGAMENTO_RAJADA ,112) 
								END								AS	AAMM_PAGTO,
								CONVERT(FLOAT, SUM(ISNULL(A.VLR_PREMIO,0))) AS VLR_VENDA_TOTAL,
								COUNT(*)						AS	QTDE
						FROM	DMDB41..DM_AIC_PROPOSTA	 A		WITH (NOLOCK)
						LEFT JOIN DMDB42..DM_ODS_PRS_PROPOSTAS_U P WITH (NOLOCK)
						ON		A.COD_PROPOSTA = P.NUM_PROPOSTA_ESTIP
						WHERE	NOM_SEGMENTO	=		'PRESTAMISTA'
						AND		DTH_VENDA		BETWEEN '2022-01-01' AND  GETDATE()
						AND		FL_PROCESSADO	<>		'8'  -- 8 = cancelado no AIC
						GROUP BY 
								CASE WHEN ISNUMERIC(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', '')) = 1 AND NOM_CANAL <> 'AIC EXTRA-REDE' 
									 THEN CONVERT(BIGINT, LEFT(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', ''),6)) 
									 ELSE 0 
								END,
								CONVERT(VARCHAR(6),DTA_VENDA,112) ,
	
								CASE	WHEN  	P.DTH_CADASTRAMENTO_PROP_SEGURO IS NOT NULL  -- HAVENDO PROPOSTA SEMPRE SERÁ PAGO
										THEN	CONVERT(VARCHAR(6),P.DTH_CADASTRAMENTO_PROP_SEGURO,112) 
										WHEN	DTA_VENDA <> CONVERT(DATE, GETDATE()) 
										THEN	CONVERT(VARCHAR(6),A.DTA_PAGAMENTO_MJUNMOV,112)   
										ELSE	CONVERT(VARCHAR(6),A.DTA_PAGAMENTO_RAJADA ,112) 
								END								
---------------------------------------------------------------------------------------------------
--		2	-			PRESTAMISTA :  ( EXCETO CONSORCIO ) SIAPI SIAPX SIFEC
---------------------------------------------------------------------------------------------------
		UNION ALL
						SELECT	
								'PRESTAMISTA		 '			AS	SEGMENTO,
								'VENDA				 ' 			AS	MOVIMENTO,
								SUBSTRING(RIGHT('0000000' + CONVERT(VARCHAR(7), CNT.NUM_MATRICULA_VENDEDOR ),7),1,6)  AS MATRICULA  ,-- RETIRANDO O DV
								CONVERT(VARCHAR(6),A.DTA_PROPOSTA,112)					AS AAMM_VENDA,
								CONVERT(VARCHAR(6),A.DTH_CADASTRAMENTO_PROP_SEGURO,112) AS AAMM_PAGTO,
								CONVERT(FLOAT, SUM(ISNULL(A.VLR_PREMIO,0)))		AS VLR_VENDA_TOTAL,
								COUNT(*)						AS QTDE  -- select top 5 * 
						FROM	DMDB42..DM_ODS_PRS_PROPOSTAS
GO
 
IF OBJECT_ID('[dbo].[VW_TDV_IndicadorSemMov]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_TDV_IndicadorSemMov];
GO
	CREATE VIEW [dbo].[VW_TDV_IndicadorSemMov] AS
---------------------------------------------------------------------------------------------------
--		PRESTAMISTA 
---------------------------------------------------------------------------------------------------
--		BASE DE CANCELADOS		PARA PRESTAMISTA
---------------------------------------------------------------------------------------------------
WITH CANCELAMENTOS AS ( 
						SELECT	A.NUM_CONTRATO_TERC, 
								A.DES_MOTIVO_CANCEL, 
								A.DTA_CANCELAMENTO
						FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS A
						INNER JOIN (SELECT	NUM_CONTRATO_TERC, 
											MAX(STA_MOVIMENTO) AS STA_MOVIMENTO,  
											MAX(DTH_CARGA) AS DTH_CARGA 			
									FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS WITH ( NOLOCK ) 
									WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
									GROUP BY NUM_CONTRATO_TERC) B 
						ON		A.NUM_CONTRATO_TERC =	B.NUM_CONTRATO_TERC
						AND		A.STA_MOVIMENTO		=	B.STA_MOVIMENTO
						AND		A.DTH_CARGA			=	B.DTH_CARGA
						WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
		) 
---------------------------------------------------------------------------------------------------
--		1	-			PRESTAMISTA :   RECUPERA VENDAS DO AIC
---------------------------------------------------------------------------------------------------
, SEGUIMENTOS AS (		SELECT	DISTINCT 
								CASE WHEN ISNUMERIC(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', '')) = 1 AND NOM_CANAL <> 'AIC EXTRA-REDE' 
									 THEN CONVERT(BIGINT, LEFT(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', ''),6)) 
									 ELSE 0 
								END  AS MATRICULA
						FROM	DMDB41..DM_AIC_PROPOSTA  A WITH (NOLOCK)
						WHERE	NOM_SEGMENTO	=		'PRESTAMISTA'
						AND		DTH_VENDA		BETWEEN '2022-01-01' AND  GETDATE()
						AND		FL_PROCESSADO	<>		'8'  -- 8 = cancelado no AIC
---------------------------------------------------------------------------------------------------
--		2	-			PRESTAMISTA :  ( EXCETO CONSORCIO ) SIAPI SIAPX SIFEC
---------------------------------------------------------------------------------------------------
		UNION ALL
						SELECT	DISTINCT 
								SUBSTRING(RIGHT('0000000' + CONVERT(VARCHAR(7), CNT.NUM_MATRICULA_VENDEDOR ),7),1,6)  AS MATRICULA -- RETIRANDO O DV
						FROM	DMDB42..DM_ODS_PRS_PROPOSTAS_U A WITH (NOLOCK)
						LEFT JOIN DMDB42..DM_ODS_PRS_CONTRATOS_U CNT WITH (NOLOCK)
						ON		A.NUM_PROPOSTA_ESTIP = CNT.NUM_CONTRATO_TERC
						AND		A.COD_PRODUTO = CNT.COD_PRODUTO
						LEFT JOIN CANCELAMENTOS AS CANC WITH (NOLOCK)
						ON		A.NUM_PROPOSTA_ESTIP = CANC.NUM_CONTRATO_TERC
						WHERE	A.DTA_PROPOSTA BETWEEN '2022-01-01' AND GETDATE()  -- eliminar data futura
						AND		A.NUM_PROPOSTA_ESTIP NOT IN (	SELECT	COD_PROPOSTA  
																FROM	DMDB41..DM_AIC_PROPOSTA WITH ( NOLOCK INDEX = PK_DM_AIC )
																WHERE	NOM_SEGMENTO	=		'PRESTAMISTA' 				  )  
---------------------------------------------------------------------------------------------------
--		3	-			PRESTAMISTA :  SOMENTE CONSORCIO 
---------------------------------------------------------------------------------------------------
		UNION ALL
						SELECT	DISTINCT 
								CONVERT(BIGINT, LEFT(FORMAT(ISNULL(A.NUM_MATRICULA_VENDEDOR,0),'0000000'),6)) AS MATRICULA
						FROM	DMDB42..DM_ODS_PRS_CONTRATOS_U A WITH (NOLOCK)
						
						INNER JOIN DMDB42..DM_DIM_PRODUTO P WITH (NOLOCK)
						ON		A.COD_PRODUTO = P.COD_PRODUTO
						AND		P.DES_LINHA_PROD = 'CONSORCIO'
						
						WHERE	DTA_ASSINATURA BETWEEN '2022-01-01' AND GETDATE()
---------------------------------------------------------------------------------------------------
--		PREVIDENCIA
---------------------------------------------------------------------------------------------------
--		4	-			PREVIDENCIA : RECUPERA VENDAS DO KIPREV
---------------------------------------------------------------------------------------------------
		UNION ALL
						SELECT	DISTINCT 
								CASE WHEN  ISNUMERIC(SUBSTRING(CONVERT(VARCHAR(7),I.NUM_MATRICULA),1,1)) = 0
									 OR    SUBS
GO
 
IF OBJECT_ID('[dbo].[VW_VENDA_CAMPANHA_PREVIDENCIA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_VENDA_CAMPANHA_PREVIDENCIA];
GO
CREATE VIEW [dbo].[VW_VENDA_CAMPANHA_PREVIDENCIA] AS
WITH ECONOMIARIO AS (

SELECT	DISTINCT 
		CONVERT(VARCHAR(6),E.DTA_REFERENCIA,112)	AS	ANOMES_REF
		,CONVERT(BIGINT, E.COD_UNIDADE)	 			AS	AGENCIA_FUNCIONARIO
		,CONVERT(BIGINT, E.MATR_FUNC)				AS	NUM_MATRICULA
		,E.NOM_FUNC									AS	NOME_FUNCIONARIO
		,E.NUM_CPF									AS	NUM_CPF_FUNCIONARIO
		,DES_FUNCAO
		,CASE	WHEN	DES_FUNCAO LIKE '%PJ%' 
				THEN	1 
				ELSE	0 
				END		AS FL_ELEG_PREV_SOCIO -- SELECT TOP 8 *
FROM	DMDB41.[dbo].[DM_ECONOMIARIO_HIST]	E  ( NOLOCK ) 
WHERE   E.SIT_FUNC <> ''
AND    YEAR(E.DTA_REFERENCIA) >= YEAR(GETDATE())-1
--	E.SIT_FUNC		IN ( 1 , 3 )  
		--CONVERT(VARCHAR(6),E.DTA_REFERENCIA,112)	BETWEEN CONVERT(VARCHAR(6), '2024-01-01',112)  
		--										AND		CONVERT(VARCHAR(6), GETDATE(), 112)

UNION	--	CRIANDO PARA O MES ATUAL POIS SÓ TEM NO FINAL DO MES

SELECT	DISTINCT 
		CONVERT(VARCHAR(6),GETDATE(),112)			AS	ANOMES_REF
		,CONVERT(BIGINT, E.COD_UNIDADE)	 			AS	AGENCIA_FUNCIONARIO
		,CONVERT(BIGINT, E.MATR_FUNC)				AS	NUM_MATRICULA
		,E.NOM_FUNC									AS	NOME_FUNCIONARIO
		,E.NUM_CPF									AS	NUM_CPF_FUNCIONARIO
		,DES_FUNCAO
		,CASE	WHEN	DES_FUNCAO LIKE '%PJ%' 
				THEN	1 
				ELSE	0 
				END		AS FL_ELEG_PREV_SOCIO 
FROM	DMDB41.[dbo].[DM_ECONOMIARIO]	E ( NOLOCK ) 
WHERE   E.SIT_FUNC <> ''
--WHERE	E.SIT_FUNC IN (1,3)  

UNION	--	ETAPA PARA O DELAY DA TABELA HIST É CARREGADA SOMENTE NO DIA 2

SELECT	DISTINCT 
		CONVERT(VARCHAR(6),DATEADD(MONTH,-1,GETDATE()),112)		AS	ANOMES_REF
		,CONVERT(BIGINT, E.COD_UNIDADE)	 			AS	AGENCIA_FUNCIONARIO
		,CONVERT(BIGINT, E.MATR_FUNC)				AS	NUM_MATRICULA
		,E.NOM_FUNC									AS	NOME_FUNCIONARIO
		,E.NUM_CPF									AS	NUM_CPF_FUNCIONARIO
		,DES_FUNCAO
		,CASE	WHEN	DES_FUNCAO LIKE '%PJ%' 
				THEN	1 
				ELSE	0 
				END		AS FL_ELEG_PREV_SOCIO 
FROM	DMDB41.[dbo].[DM_ECONOMIARIO]	E ( NOLOCK ) 
WHERE   E.SIT_FUNC <> ''
AND  		0 =	 (	SELECT	ISNULL(COUNT(*),0) 
				FROM	DMDB41.[dbo].[DM_ECONOMIARIO_HIST]	A WITH  ( INDEX = DMECONIP NOLOCK  )  
				WHERE	CONVERT(VARCHAR(6),A.DTA_REFERENCIA,112)	= CONVERT(VARCHAR(6),DATEADD(MONTH,-1,GETDATE()),112)	)
),

ESTRUTURA AS (SELECT ANOMES,
            		      NU_UNIDADE AS COD_AGENCIA,
            		      NO_UNIDADE AS NOM_AGENCIA,
            		      UN_SEV AS COD_SEV, 
            		      NOME_SEV AS NOM_SEV,
            		      UN_SR AS COD_SR,
            		      NOME_SR AS NOM_SR,
            		      UN_SN AS COD_SURV,
            		      NOME_SN AS NOM_SURV,
            		      UN_SN AS COD_SN,
            		      NOME_SN AS NOM_SN,
						  NULL AS COD_SEP,
            		      NULL AS NOM_SEP,
						  UN_VP AS COD_VP,
            		      NOME_VP AS NOM_VP,
            		      GERENCIA AS NOM_GERENCIA,
            		      NOME_CARTEIRA AS NOM_CARTEIRA,
						  MATR_CONSULTOR AS COD_MATRICULA_CONSULTOR,
            		      NOM_CONSULTOR AS NOM_CONSULTOR,
            		      SUB_GERENCIA AS NOM_SUB_GERENCIA
                   FROM DMDB41..TB_ESTRUTURA_HIST WITH(NOLOCK)
				   WHERE ANOMES >= FORMAT(GETDATE()-60,'yyyyMM')),

ESTRUTURA_DIGITAL AS (SELECT ANO_MES,
                     		 MATR_FUNC,
                             DV_MATR_FUNC,
							 NOM_FUNC,
                     		 NU_UNIDADE AS COD_AGENCIA_DIGITAL,
                     		 NO_UNIDADE AS NOM_AGENCIA_DIGITAL,
                     		 UN_SEV AS COD_SEV_DIGITAL, 
                     		 NOME_SEV AS NOM_SEV_DIGITAL,
                     		 UN_SR AS COD_SR_DIGITAL,
                     		 NOME_SR AS NOM_SR_DIGITAL,
                     		 UN_SN AS COD_SURV_DIGITAL,
                     		 NOME_SN AS NOM_SURV_DIGITAL,
							 UN_SN AS COD_SN_DIGITAL,
                     		 NOME_SN AS NOM_SN_DIGITAL,
                     		 NULL AS COD_SEP_DIGITAL,
                     		 NULL AS NOM_SEP_DIGITAL,
							 UN_VP AS COD_VP_DIGITAL,
                     		 NOME_VP AS NOM_VP_DIGITAL,
                     		 GERENCIA AS NOM_
GO
 
