CREATE VIEW [dbo].[VW_VENDA_CAMPANHA_PREVIDENCIA] AS
WITH ESTRUTURA AS (SELECT ANOMES,
            		      NU_UNIDADE AS COD_AGENCIA,
            		      NO_UNIDADE AS NOM_AGENCIA,
            		      UN_SEV AS COD_SEV, 
            		      NOME_SEV AS NOM_SEV,
            		      UN_SR AS COD_SR,
            		      NOME_SR AS NOM_SR,
            		      NULL AS COD_SURV,
            		      NULL AS NOM_SURV,
            		      NULL AS COD_SEP,
            		      NULL AS NOM_SEP,
            		      GERENCIA AS NOM_GERENCIA,
            		      NOME_CARTEIRA AS NOM_CARTEIRA,
            		      NOM_CONSULTOR AS NOM_CONSULTOR,
            		      SUB_GERENCIA AS NOM_SUB_GERENCIA
                   FROM DMDB41..TB_ESTRUTURA_HIST
				   WHERE ANOMES >= FORMAT(GETDATE()-60,'yyyyMM')),

ESTRUTURA_DIGITAL AS (SELECT ANO_MES,
                     		 MATR_FUNC,
                             DV_MATR_FUNC,
							 NOM_FUNC,
                     		 NU_UNIDADE AS COD_AGENCIA_DIGITAL,
                     		 NO_UNIDADE AS NOM_AGENCIA_DIGITAL,
                     		 UN_SEV AS COD_SEV_DIGITAL, 
                     		 NOME_SEV AS NOM_SEV_DIGITAL,
                     		 UN_SR AS COD_SR_DIGITAL,
                     		 NOME_SR AS NOM_SR_DIGITAL,
                     		 NULL AS COD_SURV_DIGITAL,
                     		 NULL AS NOM_SURV_DIGITAL,
                     		 NULL AS COD_SEP_DIGITAL,
                     		 NULL AS NOM_SEP_DIGITAL,
                     		 GERENCIA AS NOM_GERENCIA_DIGITAL,
                     		 NOME_CARTEIRA AS NOM_CARTEIRA_DIGITAL,
                     		 NOM_CONSULTOR AS NOM_CONSULTOR_DIGITAL,
                     		 SUB_GERENCIA AS NOM_SUB_GERENCIA_DIGITAL 
                     FROM DMDB47..[01_VW_CEF_ECONOMIARIO_DIM_HIST_ESTRUTURA_DIGITAL] WITH(NOLOCK)
					 WHERE ANO_MES >= FORMAT(GETDATE()-60,'yyyyMM')),

FUND1 AS (
SELECT	 CAST(B.MOVIMENTO AS VARCHAR(50)) AS MOVIMENTO,
		B.DTA_VENDA,
		B.DTH_VENDA,
		B.HORA_VENDA_ORIGINAL,
		B.HORA_VENDA,
		B.HORA_QUEBRADA,
		B.DES_HORA,
		B.NUM_CPF_CNPJ,
		B.NUM_PROPOSTA,
		B.FL_PROCESSADO,
        B.DES_FL_PROCESSADO,
		B.DES_STATUS_PORTABILIDADE,
		B.NUM_CERTIFICADO,
		CAST(B.COD_AGENCIA AS VARCHAR(5)) AS COD_AGENCIA,
		E.NOM_AGENCIA,
		CAST(REPLACE(B.COD_MATRICULA,'-','') AS VARCHAR(15)) AS COD_MATRICULA,
		B.COD_MATRICULA_TRATADA,
		E2.NOM_FUNC,
		E.COD_SEV, 
		E.NOM_SEV,
		E.COD_SR,
		E.NOM_SR,
		E.COD_SURV,
		E.NOM_SURV,
		E.COD_SEP,
		E.NOM_SEP,
		E.NOM_CARTEIRA,
		E.NOM_CONSULTOR,
		E.NOM_GERENCIA,
		E.NOM_SUB_GERENCIA,
		CAST(B.COD_AGENCIA_INDICADOR AS VARCHAR(5)) AS COD_AGENCIA_INDICADOR,
		E2.COD_AGENCIA_DIGITAL,
		E2.NOM_AGENCIA_DIGITAL,
		E2.COD_SEV_DIGITAL,
		E2.NOM_SEV_DIGITAL,
		E2.COD_SR_DIGITAL,
		E2.NOM_SR_DIGITAL,
		E2.COD_SURV_DIGITAL,
		E2.NOM_SURV_DIGITAL,
		E2.COD_SEP_DIGITAL,
		E2.NOM_SEP_DIGITAL,
		E2.NOM_CARTEIRA_DIGITAL,
		E2.NOM_CONSULTOR_DIGITAL,
		E2.NOM_GERENCIA_DIGITAL,
		E2.NOM_SUB_GERENCIA_DIGITAL,
		B.COD_PRODUTO,
		B.NOM_PRODUTO,
		B.DES_MODALIDADE_PRODUTO,
		B.DES_FORMA_PGTO,
		CONVERT(MONEY,VLR_GERADO)	 				AS	VLR_GERADO,
		IsNull(B.VLR_APORTE_INICIAL,0) AS VLR_APORTE_INICIAL,
        IsNull(B.VLR_SOBREVIDA_MENSAL,0) AS VLR_SOBREVIDA_MENSAL,
        IsNull(B.VLR_PECULIO_MENSAL,0) AS VLR_PECULIO_MENSAL,
        IsNull(B.VLR_IS_PECULIO,0) AS VLR_IS_PECULIO,
		CONVERT(DATE,B.DTA_PGTO_KIPREV)				AS	DTA_PGTO_KIPREV,
		B.DTA_BAIXA_KIPREV,
		CONVERT(MONEY,B.VLR_PGTO_KIPREV)	 		AS	VLR_PGTO_KIPREV,
		B.NOSSO_NUMERO_KIPREV

FROM (SELECT C.MOVIMENTO, 
       C.DTA_VENDA,
       C.DTH_VENDA,
       C.HORA_VENDA_ORIGINAL,
       C.HORA_VENDA,
       C.HORA_QUEBRADA,
       C.DES_HORA,
       C.NUM_CPF_CNPJ,
       C.NUM_PROPOSTA,
	   CAST(C.FL_PROCESSADO AS SMALLINT) AS FL_PROCESSADO,
       CAST(C.DES_FL_PROCESSADO AS VARCHAR(30)) AS DES_FL_PROCESSADO,
       CAST(C.DES_STATUS_PORTABILIDADE AS VARCHAR(50)) AS DES_STATUS_PORTABILIDADE,
 
GO
 
IF OBJECT_ID('[dbo].[VW_VENDA_CAMPANHA_PREVIDENCIA_RANE]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_VENDA_CAMPANHA_PREVIDENCIA_RANE];
GO



CREATE VIEW [dbo].[VW_VENDA_CAMPANHA_PREVIDENCIA_RANE] AS

----------------------------------------------------------------------------------------------------
--		SELECT * FROM DMDB41..VW_VENDA_CAMPANHA_PREVIDENCIA  ORDER BY 1,2
----------------------------------------------------------------------------------------------------

----------------------------------------------------------------------------------------------------
--		VIEW DE VENDA DA CAMPANHA NOVEMBRO 2024
----------------------------------------------------------------------------------------------------
--		Venda (AIC VENDA +  kiprev) Pagamento (rajada) Valor (acumulado) Agência  Modalidade (PGBL / VGBL)
----------------------------------------------------------------------------------------------------
WITH FUND1 AS (
SELECT	 CAST(B.MOVIMENTO AS VARCHAR(50)) AS MOVIMENTO,
		B.DTA_VENDA,
		B.DTH_VENDA,
		B.HORA_VENDA_ORIGINAL,
		B.HORA_VENDA,
		B.HORA_QUEBRADA,
		B.DES_HORA,
		CAST(B.NUM_CPF_CNPJ AS VARCHAR(20)) AS NUM_CPF_CNPJ,
		B.NUM_PROPOSTA,
		B.NUM_CERTIFICADO,
		CAST(B.COD_AGENCIA AS VARCHAR(5)) AS COD_AGENCIA,
		E.NOM_AGENCIA,
		CAST(REPLACE(B.COD_MATRICULA,'-','') AS VARCHAR(15)) AS COD_MATRICULA,
		E.COD_SEV, 
		E.NOM_SEV,
		E.COD_SR,
		E.NOM_SR,
		E.COD_SURV,
		E.NOM_SURV,
		E.COD_SEP,
		E.NOM_SEP,
		E.NOM_CARTEIRA,
		E.NOM_CONSULTOR,
		E.NOM_GERENCIA,
		E.NOM_SUB_GERENCIA,
		CAST(B.COD_AGENCIA_INDICADOR AS VARCHAR(5)) AS COD_AGENCIA_INDICADOR,
		E2.NOM_AGENCIA AS NOM_AGENCIA_INDICADOR,
		E2.COD_SEV AS  COD_SEV_INDICADOR,
		E2.NOM_SEV AS NOM_SEV_INDICADOR,
		E2.COD_SR AS COD_SR_INDICADOR,
		E2.NOM_SR AS NOM_SR_INDICADOR,
		E2.COD_SURV AS COD_SURV_INDICADOR,
		E2.NOM_SURV AS NOM_SURV_INDICADOR,
		E2.COD_SEP AS COD_SEP_INDICADOR,
		E2.NOM_SEP AS NOM_SEP_INDICADOR,
		E2.NOM_CARTEIRA AS NOM_CARTEIRA_INDICADOR,
		E2.NOM_CONSULTOR AS NOM_CONSULTOR_INDICADOR,
		E2.NOM_GERENCIA AS NOM_GERENCIA_INDICADOR,
		E2.NOM_SUB_GERENCIA AS NOM_SUB_GERENCIA_INDICADOR,
		B.NOM_PRODUTO,
		B.DES_FORMA_PGTO,
		CONVERT(MONEY,VLR_GERADO)	 				AS	VLR_GERADO,
		CONVERT(DATE,B.DTA_PGTO_KIPREV)				AS	DTA_PGTO_KIPREV,
		B.DTA_BAIXA_KIPREV,
		CONVERT(MONEY,B.VLR_PGTO_KIPREV)	 		AS	VLR_PGTO_KIPREV 

FROM (	SELECT	DISTINCT 
				'VENDA AIC'										AS	MOVIMENTO, 
				CONVERT(DATE,A.DT_VENDA)						AS	DTA_VENDA,
				A.DT_VENDA										AS  DTH_VENDA,
			    CAST(FORMAT(A.DT_VENDA, N'HH:mm:ss')			AS VARCHAR(10)) AS HORA_VENDA_ORIGINAL,
				CAST(CONCAT(FORMAT(A.DT_VENDA, N'HH'),':00:00') AS VARCHAR(10)) AS HORA_VENDA,
				CASE	WHEN SUBSTRING(FORMAT(A.DT_VENDA, N'HH:mm:ss'),5,1) <= 4 
						Then CONCAT(SUBSTRING(FORMAT(A.DT_VENDA, N'HH:mm:ss'),1,4), '0:00') 
						ELSE CONCAT(SUBSTRING(FORMAT(A.DT_VENDA, N'HH:mm:ss'),1,4), '5:00') 
						END										AS HORA_QUEBRADA,
				CONCAT(SUBSTRING(FORMAT(A.DT_VENDA, N'HH:mm:ss'),1,2), 'h') AS DES_HORA,

				CONVERT(NUMERIC(20),A.COD_CPF_CNPJ)				AS	NUM_CPF_CNPJ,
				CONVERT(BIGINT,REPLACE(A.COD_PROPOSTA,'-',''))	AS	NUM_PROPOSTA,
				K.NUM_CERTIFICADO								AS  NUM_CERTIFICADO,
				A.COD_AGENCIA,
				A.XML_PV_AG AS COD_AGENCIA_INDICADOR,
				A.COD_MATRICULA,
				CAST(P.PRODUCTNAME AS VARCHAR(50))	COLLATE SQL_LATIN1_GENERAL_CP1_CI_AS  AS  NOM_PRODUTO,
				CASE	WHEN K.NOSSO_NUMERO IS NULL THEN 'DC' ELSE 'FC' END AS	DES_FORMA_PGTO,
				NULL											AS	IND_PAGO,
				CONVERT(MONEY,ISNULL(A.IPTPREMIOVALOR,0)) / 100 AS	VLR_GERADO ,
				CONVERT(DATE,K.FECHA_DEPOSITO)					AS  DTA_PGTO_KIPREV,
				CONVERT(DATE,K.DATA_BAIXA)						AS	DTA_BAIXA_KIPREV,
				CONVERT(MONEY,K.VALOR_BAIXADO_CON)				AS	VLR_PGTO_KIPREV,
				K.NOSSO_NUMERO									AS	NOSSO_NUMERO_KIPREV	,	
				K.NUM_COBRANCA									AS	NUM_COBRANCA ,	
				K.NUM_DEPOSITO									AS	NUM_DEPOSITO

		FROM	[SQL18\STAGING4].TDDB43.dbo.AIC_VENDA_FINALIZADA_METADADO A WITH(NOLOCK)
						
		JOIN	[SQL18\STAGING4].TDDB43.DBO.PRODUCTS AS P WITH(NOLOCK)
		ON		A.COD_PRODUTO = P.PRODUCTID

		LEFT JOIN DMDB41..TB_KIP
GO
 
IF OBJECT_ID('[dbo].[VW_VENDA_MATRICULA_PRESTAMISTA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_VENDA_MATRICULA_PRESTAMISTA];
GO
CREATE VIEW [DBO].[VW_VENDA_MATRICULA_PRESTAMISTA] AS

---------------------------------------------------------------------------------------------------
--		select top 80 * from VW_VENDA_MATRICULA_PRESTAMISTA 
---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_VENDAS_MATRICULA_PRESTAMISTA
--
--					SQL14\DMCVP\DMDB41
--
--		OBJETIVO:	EVOLUÇÃO DO MOVIMENTO REALIZADO DO VENDAS X MATRICULA
--
---------------------------------------------------------------------------------------------------
--		21/03/2023	AUTOR	:	SILVIO J®  -  CRIAÇÃO
---------------------------------------------------------------------------------------------------

---------------------------------------------------------------------------------------------------
--		LE MATRICULAS
---------------------------------------------------------------------------------------------------

WITH	FUNCIONARIOS AS (

SELECT	DISTINCT CONVERT(BIGINT, MATR_FUNC) AS NO_MATRICULA, 
		NOM_FUNC AS NOME_FUNCIONARIO, 
		CONVERT(BIGINT, A.COD_UNIDADE) AS COD_AGENCIA, 
		DES_FUNCAO,
		CASE WHEN DES_FUNCAO LIKE '%PJ%' THEN 1 ELSE 0 END AS FL_ELEG_PREV_SOCIO

FROM	DMDB41..SB_P_202106_ARQUIVO_FUNCIONARIOS_CAIXA A 
		INNER JOIN (SELECT DISTINCT AG.CODAGE FROM DMDB41..SB_P_202106_ARQUIVO_AGENCIAS_CAIXA AG WHERE AG.TIPO_UNID = 'PV' AND AG.DT_EXTINCAO = '0001-01-01' AND AG.DT_FIM_OPER = '0001-01-01') B
			ON CONVERT(BIGINT, A.COD_UNIDADE) = B.CODAGE
WHERE	A.SIT_FUNC IN (1,3)
)

---------------------------------------------------------------------------------------------------
--		PRESTAMISTA		0.	CANCELAMENTOS
---------------------------------------------------------------------------------------------------

,CANCELAMENTOS AS 		(			

SELECT	A.NUM_CONTRATO_TERC, 
		A.DES_MOTIVO_CANCEL, 
		A.DTA_CANCELAMENTO
FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS A   WITH ( NOLOCK )
INNER JOIN (SELECT	NUM_CONTRATO_TERC, 
					MAX(STA_MOVIMENTO) AS STA_MOVIMENTO,  
					MAX(DTH_CARGA) AS DTH_CARGA 			
			FROM	DMDB42..DM_ODS_PRS_CANCELAMENTOS WITH ( NOLOCK ) 
			WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
			GROUP BY NUM_CONTRATO_TERC) B 
ON		A.NUM_CONTRATO_TERC =	B.NUM_CONTRATO_TERC
AND		A.STA_MOVIMENTO		=	B.STA_MOVIMENTO
AND		A.DTH_CARGA			=	B.DTH_CARGA
WHERE	DES_FORMA_CANCEL	<>	'FIM DE VIGÊNCIA'
)

---------------------------------------------------------------------------------------------------
--		PRESTAMISTA		1.	 VENDAS DO PRESTAMISTA ( EXCETO CONSORCIO ) SIAPI SIAPX SIFEC
---------------------------------------------------------------------------------------------------
,  PRESTA AS  ( 

SELECT	DISTINCT 
		'PRESTAMISTA'					AS	SEGMENTO,
	
		CONVERT(BIGINT, LEFT(FORMAT(ISNULL(CNT.NUM_MATRICULA_VENDEDOR,0),'0000000'),6)) AS COD_MATRICULA,
		P.NUM_PROPOSTA_ESTIP			AS	NUM_PROPOSTA,

		CONVERT(DATE, P.DTA_PROPOSTA)	AS	DTA_PROPOSTA,
		CONVERT(FLOAT, P.VLR_PREMIO)	AS	VLR_PREMIO ,
		
