				THEN CONVERT(FLOAT, P.VLR_PREMIO)
				ELSE 0
				END AS	VLR_PREMIO_RURAL,

		CASE	WHEN LTRIM(RTRIM(UPPER(C.DES_PRODUTO))) IN ( 'PRESTAMISTA CONSÓRCIO AUTO'				
