CREATE VIEW [DBO].[VW_VENDA_MATRICULA_PREVIDENCIA] AS

---------------------------------------------------------------------------------------------------
--		select DISTINCT SEGMENTO,MOVIMENTO, QTD_PREMIO_SOCIO, QTD_PREV_MULHER from VW_VENDA_MATRICULA_PREVIDENCIA 
---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_VENDA_MATRICULA_PREVIDENCIA
--
--					SQL14\DMCVP\DMDB41
--
--		OBJETIVO:	EVOLUÇÃO DO MOVIMENTO REALIZADO DO VENDAS X MATRICULA
--
---------------------------------------------------------------------------------------------------
--		21/03/2023	AUTOR	:	SILVIO J®  -  CRIAÇÃO
---------------------------------------------------------------------------------------------------


---------------------------------------------------------------------------------------------------
--		LE MATRICULAS
---------------------------------------------------------------------------------------------------

WITH	FUNCIONARIOS AS (

SELECT	DISTINCT 
		CONVERT(BIGINT, MATR_FUNC) AS NO_MATRICULA, 
		NOM_FUNC		AS NOME_FUNCIONARIO, 
		DES_FUNCAO,
		CASE	WHEN	DES_FUNCAO LIKE '%PJ%' 
				THEN	1 
				ELSE	0 
				END		AS FL_ELEG_PREV_SOCIO
FROM	DMDB41.[dbo].[DM_ECONOMIARIO] 
WHERE	SIT_FUNC IN (1,3)
)

---------------------------------------------------------------------------------------------------
--		PREVIDENCIA		1.	RECUPERA VENDAS DO KIPREV 
---------------------------------------------------------------------------------------------------
,  PREVI AS  ( 

SELECT 
		'PREVIDENCIA'			AS		SEGMENTO,
		'VENDA     '			AS		MOVIMENTO,
	
		CASE WHEN	ISNUMERIC(SUBSTRING(CONVERT(VARCHAR(7),I.NUM_MATRICULA),1,1)) = 0
			 OR		SUBSTRING(CONVERT(VARCHAR(7),I.NUM_MATRICULA),1,1) = '-'
			 THEN	0
			 ELSE	SUBSTRING(RIGHT('0000000' + CONVERT(VARCHAR(7), I.NUM_MATRICULA ),7),1,6)   -- RETIRANDO O DV
		END						AS		COD_MATRICULA,

		CONVERT(VARCHAR(6),A.COD_AGENCIA)	AS COD_AGENCIA,
		V.DTA_EMISSAO			AS		DTA_VENDA, 
		CONVERT(VARCHAR(30),V.SUK_CERT_PART)	AS  DOC,
		-------------------------------------------------------------------------------------------
		CONVERT(FLOAT, (V.VLR_CONTR_INICIAL + ISNULL(V.VLR_VENDA,0)))	AS	VLR_PREMIO,
	--	CONVERT(FLOAT, (V.VLR_CONTR_INICIAL + ISNULL(V.VLR_VENDA,0)))	AS	VLR_VENDA,	
--		0  AS	VLR_APORTE,	
		--0  AS	VLR_PORT_ENTRA,		

	    CASE	WHEN	COB.NAT_COBERTURA = 'RISCO' 
				THEN	CONVERT(FLOAT,V.VLR_VENDA )
				ELSE	0 
				END		AS VLR_RISCO,

		CASE	WHEN	COB.NAT_COBERTURA <> 'RISCO' 
				THEN	CONVERT(FLOAT,V.VLR_VENDA )
				ELSE	0 
				END		AS VLR_RENDA,

		CASE	WHEN	PR.COD_PRODUTO_KIPREV < 2000   -- EMPRESARIAL
				THEN	0
				ELSE	ISNULL(V.VLR_CONTR_INICIAL,0) + ISNULL(V.VLR_VENDA,0)
				END		AS	VLR_PREMIO_PJ ,

		CASE	WHEN	PR.COD_PRODUTO_KIPREV < 2000   -- EMPRESARIAL
				THEN	0
				ELSE	1	
				END		AS	QTD_PREMIO_PJ ,
		
		CASE	WHEN	SUBSTRING(PR.IND_CONJUGADO,1,1) = 'S'
				THEN	ISNULL(V.VLR_CONTR_INICIAL,0) + ISNULL(V.VLR_VENDA,0)
				ELSE	0
				END  	AS	VLR_PREMIO_CONJUGADO,

		CASE	WHEN	SUBSTRING(PR.IND_CONJUGADO,1,1) = 'S'
				THEN	1
				ELSE	0
				END 	AS	QTD_PREMIO_CONJUGADO,

		CASE	WHEN	C.DES_TIPO_CONTRATACAO	=	'Prev. Sócio'
				THEN	ISNULL(V.VLR_CONTR_INICIAL,0) + ISNULL(V.VLR_VENDA,0)
				ELSE	0
				END		AS	VLR_PREMIO_SOCIO,

		CASE	WHEN	C.DES_TIPO_CONTRATACAO	=	'Prev. Sócio'
				THEN	1
				ELSE	0
				END		AS	QTD_PREMIO_SOCIO,

		CASE	WHEN	COD_TIPO_CERTIFICADO	=	'I'
				AND		COD_SIT_CERTIFICADO		NOT IN ('P','M')
				AND		COD_PRODUTO_KIPREV		IN	(1191, 1192, 1193, 1194, 1195, 1196, 1197, 1199, 1253,1100)
				AND		PROP.DTA_EMISSAO		BETWEEN 	'2022-09-16' AND '2023-10-31'
				THEN	CONVERT(FLOAT,V.VLR_VENDA )
				ELSE    0
				END  	AS	VLR_PREV_MULHER ,

		CASE	WHEN	COD_TIPO_CERTIFICADO	=	'I'
				AND		COD_SIT_CERTIFICADO		NOT IN ('P','M')
				AND		COD_PRODUTO_KIPREV		IN	(1191, 1192, 1193, 1194, 1195, 1196, 1197, 1199, 1253,1100)
				AND		PROP.DT
GO
 
IF OBJECT_ID('[dbo].[VW_VENDA_MATRICULA_VIDA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_VENDA_MATRICULA_VIDA];
GO
CREATE VIEW [DBO].[VW_VENDA_MATRICULA_VIDA] AS

---------------------------------------------------------------------------------------------------
--		select top 80 * from VW_VENDA_MATRICULA_VIDA 
---------------------------------------------------------------------------------------------------
--	
--		VIEW	:	VW_VENDAS_MATRICULA
--
--					SQL14\DMCVP\DMDB41
--
--		OBJETIVO:	EVOLUÇÃO DO MOVIMENTO REALIZADO DO VENDAS X MATRICULA
--
---------------------------------------------------------------------------------------------------
--		21/03/2023	AUTOR	:	SILVIO J®  -  CRIAÇÃO
---------------------------------------------------------------------------------------------------


---------------------------------------------------------------------------------------------------
--		LE MATRICULAS
---------------------------------------------------------------------------------------------------

WITH	

FUNCIONARIOS AS (

SELECT	DISTINCT CONVERT(BIGINT, MATR_FUNC) AS NO_MATRICULA, 
		NOM_FUNC AS NOME_FUNCIONARIO, 
		CONVERT(BIGINT, A.COD_UNIDADE) AS COD_AGENCIA, 
		DES_FUNCAO,
		CASE WHEN DES_FUNCAO LIKE '%PJ%' THEN 1 ELSE 0 END AS FL_ELEG_PREV_SOCIO

FROM	DMDB41..SB_P_202106_ARQUIVO_FUNCIONARIOS_CAIXA A 
		INNER JOIN (SELECT DISTINCT AG.CODAGE FROM DMDB41..SB_P_202106_ARQUIVO_AGENCIAS_CAIXA AG WHERE AG.TIPO_UNID = 'PV' AND AG.DT_EXTINCAO = '0001-01-01' AND AG.DT_FIM_OPER = '0001-01-01') B
			ON CONVERT(BIGINT, A.COD_UNIDADE) = B.CODAGE
WHERE	A.SIT_FUNC IN (1,3)
)

--=================================================================================================

---------------------------------------------------------------------------------------------------
--		VIDA		0.	CANCELADOS
---------------------------------------------------------------------------------------------------
, CANCELAMENTO AS  ( 

SELECT	SUK_PROPOSTA_VIDA, 
		DTH_VENDA, 
		DTH_CANCELAMENTO, 
		DATEDIFF(DAY, DTH_VENDA, DTH_CANCELAMENTO) AS QT_DIAS_CANCEL  

FROM	DMDB05..DM_002_CANCELAMENTO WITH ( NOLOCK )
WHERE	CONVERT(VARCHAR(6), DTH_VENDA,112)  BETWEEN		CONVERT(VARCHAR(6), DATEADD(MONTH,-1,GETDATE()) , 112) 
											AND			CONVERT(VARCHAR(6), GETDATE(), 112)
)

---------------------------------------------------------------------------------------------------
--		VIDA		1.	RECUPERA VENDAS DO AIC
---------------------------------------------------------------------------------------------------
,  VIDA AS  ( 

SELECT	DISTINCT
		'VIDA       '				AS	SEGMENTO,

		CASE	WHEN	ISNUMERIC(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', '')) = 1 AND NOM_CANAL <> 'AIC EXTRA-REDE' 
				THEN	CONVERT(BIGINT, LEFT(REPLACE(REPLACE(COD_MATRICULA,'-',''), 'C', ''),6)) 
				ELSE	0 
				END					AS  COD_MATRICULA,
		COD_PROPOSTA				AS	NUM_PROPOSTA,
		DTA_VENDA					AS	DTA_PROPOSTA,

		CASE	WHEN	COD_PERIODICIDADE_PGTO = 'A'      
				AND		A052.DES_PERIOD_PAGAMENTO = 'Unico'
				THEN	'Unico'

				WHEN	COD_PERIODICIDADE_PGTO = 'U'
				AND		A052.DES_PERIOD_PAGAMENTO = 'Unico'
				THEN	'Unico'

				WHEN	ISNULL(COD_PERIODICIDADE_PGTO,'') = ''
				AND		ISNULL(A052.DES_PERIOD_PAGAMENTO,'') =  ''
				THEN	'Unico'

				WHEN	COD_PERIODICIDADE_PGTO = 'U'
				THEN	'Unico'

				WHEN	COD_PERIODICIDADE_PGTO = 'A'
				THEN	'Anual' 

				WHEN	COD_PERIODICIDADE_PGTO = 'A'
				AND		A052.DES_PERIOD_PAGAMENTO = 'Anual'
				THEN	'Anual'
		
				WHEN	COD_PERIODICIDADE_PGTO = 'M'
				AND		A052.DES_PERIOD_PAGAMENTO = 'Mensal'
				THEN	'Mensal'

				WHEN	COD_PERIODICIDADE_PGTO = 'M'
				THEN	'Mensal'
				ELSE	''	

				END		AS	DES_PERIOD_PAGAMENTO ,  

		CONVERT(FLOAT, A.VLR_PREMIO) AS	VLR_PREMIO_EMITIDO,

		CONVERT(FLOAT,  CASE	WHEN 	A065.NUM_PROPOSTA IS NOT NULL 
								THEN	A.VLR_PREMIO
								WHEN (IIF(CASE	WHEN DTA_VENDA <> CONVERT(DATE, GETDATE()) 
												THEN FLG_PAGO_MJUNMOV 
												ELSE FLG_PAGO_RAJADA 
												END = 'S', A.VLR_PREMIO, 0)) = 0  
								THEN	0
								ELSE	A.VLR_
GO
 
IF OBJECT_ID('[dbo].[VW_VENDA_PREV]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_VENDA_PREV];
GO


CREATE VIEW [dbo].[VW_VENDA_PREV] AS


------------------------------------------------------------------------------------------
--		PROCEDURE VW_VENDA_PREV
------------------------------------------------------------------------------------------
--
--		Objetivo :	Recupera as vendas pelo AIC e internas do KIPREV
--		
--					View recuperaas vendas pelo AIC e internas do KIPREV
--		
------------------------------------------------------------------------------------------
--		22/09/2024	Jr® / Ítalo Naves / Walmir Oliveira		:	V1	-	INCLUSÃO DO CPF		
------------------------------------------------------------------------------------------

SELECT MOVIMENTO,
	   B.DTA_VENDA,
       B.DTH_VENDA,
       B.NUM_CPF AS NUM_CPF_CNPJ,
	   B.NUM_PROPOSTA,
       B.IND_PAGO,
       B.COD_AGENCIA,
       B.MATRICULA_INDICADOR,
	   E.NOM_FUNC AS NOM_INDICADOR,
	   cast(E.COD_UNIDADE as smallint) AS COD_AGENCIA_INDICADOR,
	   B.DTA_PAGAMENTO,
       B.DTA_BAIXA,
	   B.VALOR AS VLR_GERADO,
	   CASE WHEN B.IND_PAGO = 'S' THEN B.VALOR ELSE 0 END AS VLR_PAGO,
	   IsNull(S.VLR_MOVIMENTO,0) AS VLR_SAP	 
	   ,B.DES_FORMA_PGTO
FROM (
      select 'AIC' MOVIMENTO, 
			a.DTA_VENDA,
	         a.DTH_VENDA,
             A.NUM_CPF,
			 a.COD_PROPOSTA AS NUM_PROPOSTA,
			 a.FLG_PAGO_MJUNMOV AS IND_PAGO,
      	     CAST(Replace(a.COD_AGENCIA,'-','') AS SMALLINT) AS COD_AGENCIA,
      	     CAST(Replace(CASE WHEN A.COD_MATRICULA LIKE '%-%' THEN LEFT(REPLACE(A.COD_MATRICULA,'c',''), CHARINDEX('-', REPLACE(A.COD_MATRICULA,'c','')) - 1) ELSE REPLACE(A.COD_MATRICULA,'c','') END, 'p','') AS INT) AS MATRICULA_INDICADOR,
      	     A.VLR_PREMIO AS VALOR,
			 P.DTA_AUTENTICACAO AS DTA_PAGAMENTO,
			 P.DTA_CRED_FEDERALPREV AS DTA_BAIXA,
			 A.DES_FORMA_PGTO
      from DM_AIC_PROPOSTA A WITH(NOLOCK)
      left join DM_ARQ_PROPOSTA_MJUNMOV_PREV P WITH(NOLOCK) ON P.NUM_PROPOSTA = a.COD_PROPOSTA
	  	                                                   AND P.SIT_COBRANCA = 'PAG'
														   AND P.VLR_PAGO_SICOB > 0
      where a.NOM_SEGMENTO = 'Previdência'
	  and   a.dta_venda >= '2024-07-01'
	  --and   a.COD_PROPOSTA = '80290180325081'
) B
LEFT JOIN DM_SAP_PAGAMENTO_BAIXADO S WITH(NOLOCK) ON S.NUM_PROPOSTA = B.NUM_PROPOSTA
                                                 AND S.VLR_MOVIMENTO = B.VALOR
												 AND S.NUM_CERTIFICADO = 0
                                                 AND S.DTA_PAGAMENTO >= B.DTA_VENDA
--select * from DM_SAP_PAGAMENTO_BAIXADO where NUM_PROPOSTA = 80290180325081
LEFT JOIN DM_ECONOMIARIO E WITH(NOLOCK) ON E.MATR_FUNC = B.MATRICULA_INDICADOR
                          AND E.SEQ_REGISTRO = (SELECT MAX(E2.SEQ_REGISTRO) FROM DM_ECONOMIARIO E2 WITH(NOLOCK) WHERE E.MATR_FUNC = E2.MATR_FUNC)

UNION

SELECT 'INTERNA' AS MOVIMENTO,
	   cast(B.DTA_VENDA AS DATE) AS DTA_VENDA,
       CAST(B.DTH_VENDA AS DATETIME) AS DTH_VENDA,
       B.NUM_CPF_CNPJ,
       CAST(B.NUM_PROPOSTA AS BIGINT) AS NUM_PROPOSTA,
       B.IND_PAGO,
       CAST(B.COD_AGENCIA AS SMALLINT) AS COD_AGENCIA,
       CAST(B.MATRICULA_INDICADOR AS INT) AS MATRICULA_INDICADOR,
       B.NOM_INDICADOR,
       B.COD_AGENCIA_INDICADOR,
       B.DTA_PAGAMENTO,
       B.DTA_BAIXA,
       B.VLR_GERADO,
	   B.VLR_PAGO,
       IsNull(S.VLR_MOVIMENTO,0) AS VLR_SAP 
	   ,'' DES_FORMA_PGTO
FROM   OPENQUERY(KIPRD,'SELECT 
  ES.FEC_SOLICITUD AS DTA_VENDA
 ,ES.FEC_SOLICITUD AS DTH_VENDA
-- ,ES.DATA_PROTOCOLO
 ,I.NUM_ID AS NUM_CPF_CNPJ 
 ,ES.NUM_FORMULARIO AS NUM_PROPOSTA 
 ,CASE WHEN FCC.APORTE_ESPERADO IS NULL THEN ''N'' ELSE ''S'' END  IND_PAGO
 ,ES.COD_OFICINA AS COD_AGENCIA --AGENCIA VENDA
 ,ES.COD_AGENTE_VENDA AS MATRICULA_INDICADOR
 ,FUNC.NM_FUNC AS NOM_INDICADOR
 ,FUNC.CD_UNIDADE AS COD_AGENCIA_INDICADOR
--, FCC.DATA_COMPETENCIA DTA_PAGAMENTO --DATA PREVISTA PARA PAGAMENT

,PB.FECHA_DEPOSITO AS DTA_PAGAMENTO  --DATA DE DEPOSITO NO KIPREV.
--,ES.DATA_PAGAMENTO_INI  DTA_PAGAMENTO
--, PB.DATA_BA
GO
 
IF OBJECT_ID('[dbo].[VW_VIDA_VENDA]', 'V') IS NOT NULL DROP VIEW [dbo].[VW_VIDA_VENDA];
GO
CREATE VIEW [dbo].[VW_VIDA_VENDA] AS

---------------------------------------------------------------------------------------------------
--		1.	CONTROLE DO MJUNMOV
---------------------------------------------------------------------------------------------------
WITH ECONOMIARIO_HIST AS (
SELECT CAST(ANO_MES AS VARCHAR(6)) AS ANO_MES,
        MATR_FUNC,
		COD_UNIDADE,
		DES_TIPO_REDE
FROM DMDB41..TB_ECONOMIARIO_HIST	EH (NOLOCK)
WHERE ANO_MES >= 202501
),

ESTRUTURA_HIST AS (
SELECT CAST(ANOMES AS VARCHAR(6)) AS ANOMES,
        NU_UNIDADE,
		NO_UNIDADE
FROM DMDB41..TB_ESTRUTURA_HIST		AG_FUNC With(nolock)
WHERE ANOMES >= 202501
),

MJUNMOV AS ( 	

SELECT	CASE	WHEN	 CONVERT(DATE,B.DTA_PROX_DATA_UTIL) = CONVERT(DATE,GETDATE())
				THEN	'S'
				ELSE	'N'
				END		AS	FLG_PROC_MJUNMOV
from	DMDB42..DM_DIM_TEMPO B
where	B.DTA_DATA = (SELECT	CONVERT(DATE,MAX(DTH_CADASTRAMENTO))
						FROM	DMDB41.[DBO].[DM_ARQ_PROPOSTA_MJUNMOV_VIDA_PREST] (NOLOCK) )
) 

---------------------------------------------------------------------------------------------------
--		2.	CANCELAMENTO
---------------------------------------------------------------------------------------------------
,CANCELAMENTO AS ( 	

SELECT	SUK_PROPOSTA_VIDA, 
		DTH_VENDA, 
		DTH_CANCELAMENTO, 
		DATEDIFF(DAY, DTH_VENDA, DTH_CANCELAMENTO) AS QT_DIAS_CANCEL  
FROM	DMDB05..DM_002_CANCELAMENTO WITH ( NOLOCK )
WHERE	DTH_VENDA >= '2024-01-01' 
) 

---------------------------------------------------------------------------------------------------
--		3.	TDV
--
--		DM_076_RESPONSAVEL_VENDA
--			1	Loterico
--			2	Correspondente
--			3	Funcionario
---------------------------------------------------------------------------------------------------
,TDV AS ( 	

SELECT 	MAX(ANOMES)	ANOMES
					,NOM_PARCEIRO
					,COD_MATRICULA
					,TIP_PARCEIRO 
					,CASE	WHEN	TIP_PARCEIRO       =   'UL'
							THEN	1	
							WHEN	TIP_PARCEIRO       =   'CCA'
							THEN	2 
							ELSE	NULL
							END		AS	 COD_TIPO_VENDEDOR

					,COD_UNIDADE				
					,COD_SR
			FROM	[DMDB41].[dbo].[DM_TDV_CLASSIF_PARCEIRO]  A 	WITH ( NOLOCK )
			WHERE	ANOMES = ( SELECT MAX(ANOMES) ANOMES
								FROM [DMDB41].[dbo].[DM_TDV_CLASSIF_PARCEIRO]  B 	WITH ( NOLOCK )
								WHERE	B.COD_MATRICULA = A.COD_MATRICULA)
			GROUP BY NOM_PARCEIRO
					,COD_MATRICULA
					,TIP_PARCEIRO 
					,COD_UNIDADE				
					,COD_SR
),

---------------------------------------------------------------------------------------------------
--		5.	LE AGENCIAS 
---------------------------------------------------------------------------------------------------
AGENCIA AS (

SELECT	DISTINCT 
		CONVERT(VARCHAR(6),A.DTA_REFERENCIA,112)AS	ANOMES_REF
		,COD_SEV
		,NOM_SEV
		,COD_SR
		,NOM_SR
		,NOM_REGIAO_SR							AS	COD_REGIAO
		,CONVERT(BIGINT, COD_AGENCIA)			AS	COD_AGENCIA_ESTRUTURA -- select top 8 * 
		,NOM_AGENCIA
		,NUM_MATRICULA_CONSULTOR				AS	COD_CARTEIRA	
		,NOM_CONSULTOR_CVP

FROM	DMDB41.[dbo].[DM_AGENCIA_HIST]	A  ( NOLOCK )  
WHERE	A.STA_AGENCIA	=	'A'
AND		CONVERT(VARCHAR(6),A.DTA_REFERENCIA,112)	BETWEEN CONVERT(VARCHAR(6), '2025-01-01',112)  
													AND		CONVERT(VARCHAR(6), GETDATE(), 112)

UNION ALL	--	CRIANDO PARA O MES ATUAL POIS SÓ TEM NO FINAL DO MES
SELECT	DISTINCT 
		CONVERT(VARCHAR(6),GETDATE(),112)		AS	ANOMES_REF
		,COD_SEV
		,NOM_SEV
		,COD_SR
		,NOM_SR
		,NOM_REGIAO_SR							AS	COD_REGIAO
		,CONVERT(BIGINT, COD_AGENCIA)			AS	COD_AGENCIA_ESTRUTURA 
		,NOM_AGENCIA
		,NUM_MATRICULA_CONSULTOR				AS	COD_CARTEIRA	
		,NOM_CONSULTOR_CVP 
FROM	DMDB41.[dbo].[DM_AGENCIA]	A ( NOLOCK )  
WHERE	A.STA_AGENCIA	=	'A'

UNION ALL	--	ETAPA PARA O DELAY DA TABELA HIST É CARREGADA SOMENTE NO DIA 2
SELECT	DISTINCT 
		CONVERT(VARCHAR(6),DATEADD(MONTH,-1,GETDATE()),112)		AS	ANOMES_REF
		,COD_SEV
		,NOM_SEV
		,COD_SR
		,NOM_SR
		,NOM_REGIAO_SR							AS	COD_REGIAO
		,CONVERT(BIGINT, COD_AGENCIA)			AS	COD_AGENCIA_ESTRUTURA 
		,NOM_AGENC
GO
 
 
